# -----------------------------------------------------------------------------
# NEVIS optional performance profiling (disabled by default)
# -----------------------------------------------------------------------------
NEVIS_PROFILE_ENV = "NEVIS_PROFILE"
NEVIS_PROFILE_LOG_NAME = "nevis_perf_profile.log"


def nevis_perf_enabled() -> bool:
    return str(os.environ.get(NEVIS_PROFILE_ENV, "")).strip().lower() in {"1", "true", "yes", "on"}


def nevis_perf_log(name: str, elapsed_ms: float) -> None:
    if not nevis_perf_enabled():
        return
    try:
        log_path = Path(__file__).resolve().parent / NEVIS_PROFILE_LOG_NAME
        stamp = time.strftime("%Y-%m-%d %H:%M:%S")
        with log_path.open("a", encoding="utf-8") as f:
            f.write(f"{stamp}.{int((time.time() % 1) * 1000):03d} {name} {elapsed_ms:.2f} ms\n")
    except Exception as log_error:
        # Profiling must never affect engineering behavior or mask original errors.
        print(f"NEVIS_PROFILE_LOG_ERROR: {log_error}", file=sys.stderr)


class nevis_perf_scope:
    def __init__(self, name: str):
        self.name = name
        self.enabled = False
        self.start = 0.0

    def __enter__(self):
        self.enabled = nevis_perf_enabled()
        if self.enabled:
            self.start = time.perf_counter()
        return self

    def __exit__(self, exc_type, exc, tb):
        if self.enabled:
            nevis_perf_log(self.name, (time.perf_counter() - self.start) * 1000.0)
        return False


# -----------------------------------------------------------------------------
# NEVIS machine license (portable folder, one machine)
# -----------------------------------------------------------------------------
# Ghi chú: khóa này dùng để chặn copy nguyên thư mục sang máy khác ở mức ứng dụng.
# Nếu cần bảo vệ thương mại rất cao thì nên chuyển phần kiểm tra license sang server
# hoặc module native. Với NEVIS nội bộ/portable, cách này đủ gọn và dễ vận hành.
NEVIS_LICENSE_SECRET = b"NEVIS-MEP-NewVision-Integrated-System-2026"


def app_base_dir() -> Path:
    """Folder beside EXE when frozen, or beside .py when running source."""
    try:
        if getattr(sys, "frozen", False):
            return Path(sys.executable).resolve().parent
    except Exception:
        pass
    return Path(__file__).resolve().parent


def _run_cmd_text(cmd: List[str]) -> str:
    try:
        out = subprocess.check_output(cmd, stderr=subprocess.DEVNULL, stdin=subprocess.DEVNULL, timeout=2)
        return out.decode("utf-8", errors="ignore").strip()
    except Exception:
        return ""


def _first_wmic_value(alias: str, prop: str) -> str:
    txt = _run_cmd_text(["wmic", alias, "get", prop])
    lines = [x.strip() for x in txt.splitlines() if x.strip()]
    vals = [x for x in lines if x.lower() != prop.lower()]
    return vals[0] if vals else ""


def nevis_machine_fingerprint() -> str:
    """Return stable-ish Windows hardware identity parts, without exposing raw serials."""
    parts: List[str] = []
    # Windows MachineGuid is stable for the installed OS.
    if os.name == "nt":
        try:
            import winreg  # type: ignore
            with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Microsoft\Cryptography") as k:
                parts.append(str(winreg.QueryValueEx(k, "MachineGuid")[0]))
        except Exception:
            pass
    # Hardware serials. WMIC exists on many Windows 10/11 machines; if absent, other parts remain.
    for alias, prop in (("bios", "SerialNumber"), ("baseboard", "SerialNumber"), ("cpu", "ProcessorId"), ("diskdrive", "SerialNumber")):
        v = _first_wmic_value(alias, prop)
        if v:
            parts.append(v)
    # Last fallback prevents empty code when testing, but is weaker than Windows identifiers.
    if not parts:
        parts.append(str(uuid.getnode()))
        parts.append(os.environ.get("COMPUTERNAME", ""))
        parts.append(os.environ.get("USERNAME", ""))
    raw = "|".join(x.strip().upper() for x in parts if str(x).strip())
    return hashlib.sha256(raw.encode("utf-8", errors="ignore")).hexdigest().upper()


def nevis_machine_code() -> str:
    h = nevis_machine_fingerprint()
    return "NEVIS-" + "-".join([h[i:i+4] for i in range(0, 16, 4)])


def nevis_expected_license(machine_code: Optional[str] = None) -> str:
    code = machine_code or nevis_machine_code()
    digest = hmac.new(NEVIS_LICENSE_SECRET, code.encode("utf-8"), hashlib.sha256).hexdigest().upper()
    return "LIC-" + "-".join([digest[i:i+5] for i in range(0, 25, 5)])


def nevis_license_path() -> Path:
    return app_base_dir() / "license.dat"


def nevis_read_license() -> str:
    try:
        return nevis_license_path().read_text(encoding="utf-8-sig").strip().upper()
    except Exception:
        return ""


def nevis_license_valid() -> bool:
    # Dev escape hatch for source-code debugging only. Do not set this in the release BAT.
    if os.environ.get("NEVIS_SKIP_LICENSE") == "1":
        return True
    lic = nevis_read_license()
    return bool(lic and hmac.compare_digest(lic, nevis_expected_license()))


