# ============================================================
# NEVIS PIPE GRAPHIC STANDARD (LOCKED 2026-06)
# Đại ca chốt tiêu chuẩn nét ống chính thức. Không tự ý sửa khi
# vá các thuật toán khác (Y/LT/LL/集合管/JWW/library...).
#
# VP/DV/HTVP/VU/耐火VP:
#   5 nét tổng: 2 nét biên liền + 2 nét trong đứt + 1 nét tim gạch-chấm.
#
# TMP/トミジ:
#   7 nét tổng:
#     - mỗi bên tim ống có 3 nét
#     - 2 nét ngoài mỗi bên là nét liền  => 4 nét liền
#     - 1 nét trong gần tim mỗi bên là nét đứt => 2 nét đứt
#     - tim ống ở giữa là nét gạch-chấm
#
# Quy tắc này phải dùng chung cho preview và xuất JWW.
# ============================================================
NEVIS_PIPE_STYLE_LOCKED_VERSION = "NEVIS_PIPE_STYLE_LOCKED_2026_06_TMP_7_LINES_VP_DV_5_LINES_NORMAL_TRIM_NO_OVERCUT"
NEVIS_FIRE_BOUNDARY_NO_EXTRA_CAP_2026_06_12 = True  # Không vẽ nét ngang thừa tại điểm giáp ranh chống cháy lan
# Tim ống dùng kiểu JWW dễ đọc: 1 gạch ngắn + 1 gạch dài, không dùng chấm vì rối mắt.
# Qt không có sẵn kiểu này nên preview dùng CustomDashLine. JWW vẫn dùng LT5 (一点鎖1)
# vì khi xuất sang JWW nó hiển thị đúng dạng gạch ngắn/gạch dài theo thiết lập JWW.
NEVIS_PREVIEW_CENTERLINE_STYLE = Qt.CustomDashLine
NEVIS_PREVIEW_CENTERLINE_DASH_PATTERN = [4.0, 3.0, 12.0, 3.0]  # short-gap-long-gap
NEVIS_PREVIEW_INNER_DASH_STYLE = Qt.DashLine
NEVIS_JWW_CENTERLINE_LT = "5"   # JWW 一点鎖1 / short-long centerline
NEVIS_JWW_INNER_DASH_LT = "4"   # nét đứt trong thân ống TMP/DV/VP/HTVP/TaikaVP
NEVIS_CENTERLINE_LT_SET = {"5", "6", "49"}  # 49 = JSON editor centerline marker


def nevis_is_centerline_lt(lt: object) -> bool:
    """True for library/JWW line types that represent fitting or pipe centerlines."""
    s = str(lt or "").strip().lower().replace("lt", "")
    return s in NEVIS_CENTERLINE_LT_SET

def nevis_make_centerline_pen(color: QColor, width: float = 0.85) -> QPen:
    """Locked NEVIS centerline pen: short dash + long dash, no dot."""
    pen = QPen(color, width)
    pen.setCosmetic(True)
    pen.setStyle(Qt.CustomDashLine)
    pen.setDashPattern(NEVIS_PREVIEW_CENTERLINE_DASH_PATTERN)
    return pen


# Preview orientation only. Model/JWW coordinates stay untouched.
# Default is original TXT direction. Use the preview buttons when a drawing needs flipping.
PREVIEW_ROTATE_180 = False
PREVIEW_FLIP_X = False
PREVIEW_FLIP_Y = True  # Match old AHK/JWW screen direction by default

# JWW TXT library local coordinate correction.
# General fittings: keep local X, invert local Y.
# Axis-right correction: after the Y inversion, reverse local X ONLY for collection symbols.
# Do NOT apply this to LL/DL/L, because it rotates normal elbows/terminal U by 180°.
# Y and 45° are also excluded.
LIBRARY_TXT_INVERT_Y = True
AXIS_RIGHT_REVERSE_X_AFTER_Y_INVERT = True

def display_point(x: float, y: float) -> Tuple[float, float]:
    if PREVIEW_ROTATE_180:
        x, y = -x, -y
    if PREVIEW_FLIP_X:
        x = -x
    if PREVIEW_FLIP_Y:
        y = -y
    return (x, y)


def model_point_from_display(x: float, y: float) -> Tuple[float, float]:
    """Inverse of display_point(). Used for safe node dragging in preview."""
    if PREVIEW_FLIP_Y:
        y = -y
    if PREVIEW_FLIP_X:
        x = -x
    if PREVIEW_ROTATE_180:
        x, y = -x, -y
    return (x, y)


def is_collection_library_name(path_or_name: str) -> bool:
    """True for 集合管 library symbols: S_ / SV_ / S3_ / Japanese collection names."""
    stem = Path(str(path_or_name)).stem.upper() if path_or_name else ""
    return stem.startswith("S") or stem.startswith("SV") or stem.startswith("S3") or "集合" in stem


def is_y_library_name(path_or_name: str) -> bool:
    """True for Y fitting library symbols, including names like Y_65_50 and DV_Y_65_50."""
    stem = Path(str(path_or_name)).stem.upper() if path_or_name else ""
    return stem.startswith("Y_") or "_Y_" in stem or stem == "Y"


def is_ahk_raw_transform_library_name(path_or_name: str) -> bool:
    """Libraries now oriented by the old AHK raw-coordinate transform.

    AHK's AppendLibraryFileAt() mirrors/rotates the TXT coordinates directly; it
    does not apply NEVIS' later global local-Y inversion.  Keep this behavior for
    junction/reducer fittings whose angle rules are copied from AHK: Y, LT, DT, T,
    HTVP_T and IN.  LL/DL/45/S keep their existing Python-specific corrections.
    """
    stem = Path(str(path_or_name)).stem.upper() if path_or_name else ""
    return (
        is_y_library_name(stem)
        or stem.startswith("LT") or "_LT" in stem
        or stem.startswith("DT") or "_DT" in stem
        or stem.startswith("T_") or re.match(r"^T\d", stem) is not None or "_T_" in stem
        or stem.startswith("HTVP_T")
        or stem.startswith("IN") or "異径" in stem
    )


def is_axis_right_library_name(path_or_name: str) -> bool:
    """Libraries whose local socket axis needs X reversal after Y inversion.

    v34: apply ONLY to collection fittings (S / SV / S3 / 集合管).
    LL/DL/L must stay on the normal elbow transform; otherwise terminal U and
    normal elbows flip by 180 degrees.
    """
    stem = Path(str(path_or_name)).stem.upper() if path_or_name else ""
    return is_collection_library_name(stem)

def is_up_library_name(path_or_name: str) -> bool:
    """True for U / up type terminal elbow libraries.

    These TXT files are drawn in the opposite direction compared with normal
    LL/DL.  Apply only an extra 180-degree rotation to the final transform; do
    not change the global library axis rule or normal LL/DL will break again.
    """
    stem = Path(str(path_or_name)).stem.upper() if path_or_name else ""
    # Match common names: DL_65_U, LL_50_U, *_UP, *_U, *_N_U, etc.
    return bool(re.search(r"(^|[_\-])U($|[_\-])", stem) or re.search(r"(^|[_\-])UP($|[_\-])", stem))


@dataclass
class Node:
    id: int
    x: float
    y: float
    z: float = 0.0
    level_id: str = ""


@dataclass
class Edge:
    a: int
    b: int
    size: str = ""
    material_override: str = ""  # e.g. branch forced to HTVP from a selected fitting
    slope: float = 0.0
    vertical_type: str = "unknown"
    elevation_mode: str = "unknown"
    system_type: str = ""
    start_level_id: Optional[str] = None
    end_level_id: Optional[str] = None
    start_z: Optional[float] = None
    end_z: Optional[float] = None
    slope_percent: Optional[float] = None
    elevation_locked: bool = False

    @property
    def key(self) -> str:
        return edge_key(self.a, self.b)


def node_from_project_data(node_id: int, data: Dict[str, object]) -> Node:
    z = data.get("z", 0.0)
    return Node(
        int(node_id),
        float(data["x"]),
        float(data["y"]),
        0.0 if z in (None, "") else float(z),
        str(data.get("level_id", "")),
    )


def edge_from_project_data(data: Dict[str, object]) -> Edge:
    slope = data.get("slope", 0.0)
    start_z = data.get("start_z", None)
    end_z = data.get("end_z", None)
    slope_percent = data.get("slope_percent", None)
    return Edge(
        int(data["a"]),
        int(data["b"]),
        str(data.get("size", "65")),
        str(data.get("material_override", "")),
        0.0 if slope in (None, "") else float(slope),
        str(data.get("vertical_type", "unknown")),
        str(data.get("elevation_mode", "unknown")),
        str(data.get("system_type", "")),
        None if data.get("start_level_id", None) in (None, "") else str(data.get("start_level_id", "")),
        None if data.get("end_level_id", None) in (None, "") else str(data.get("end_level_id", "")),
        None if start_z in (None, "") else float(start_z),
        None if end_z in (None, "") else float(end_z),
        None if slope_percent in (None, "") else float(slope_percent),
        bool(data.get("elevation_locked", False)),
    )


