@dataclass
class PipeModel:
    nodes: Dict[int, Node] = field(default_factory=dict)
    edges: List[Edge] = field(default_factory=list)
    fittings: Dict[int, Fitting] = field(default_factory=dict)
    # ブッシング: IN reducer absorbed into a large fitting mouth.
    # Stored as dicts to keep project files simple/backward compatible.
    bushings: List[Dict[str, object]] = field(default_factory=list)
    base_node: Optional[int] = None
    # Multi-source support: one drawing can contain many independent pipe clusters.
    # base_nodes are the true start/collection points for flow calculation.
    # base_node is kept for backward compatibility with old project files.
    base_nodes: Set[int] = field(default_factory=set)
    dist: Dict[int, float] = field(default_factory=dict)
    parent: Dict[int, int] = field(default_factory=dict)
    model_schema_version: int = 1
    level_datums: Dict[str, LevelDatum] = field(default_factory=dict)
    structural_elements: List[object] = field(default_factory=list)
    grid_axes: List[object] = field(default_factory=list)
    drawing_scale: float = 1.0
    scale_origin: Tuple[float, float] = (0.0, 0.0)

    def neighbors(self, nid: int) -> List[int]:
        out = []
        for e in self.edges:
            if e.a == nid:
                out.append(e.b)
            elif e.b == nid:
                out.append(e.a)
        return out

    def degree(self, nid: int) -> int:
        return len(self.neighbors(nid))

    def edge_length(self, e: Edge) -> float:
        n1, n2 = self.nodes[e.a], self.nodes[e.b]
        return math.hypot(n2.x - n1.x, n2.y - n1.y)

    def bounds(self) -> QRectF:
        if not self.nodes:
            return QRectF(-100, -100, 200, 200)
        pts = [display_point(n.x, n.y) for n in self.nodes.values()]
        xs = [p[0] for p in pts]
        ys = [p[1] for p in pts]
        return QRectF(min(xs), min(ys), max(xs)-min(xs), max(ys)-min(ys)).adjusted(-100, -100, 100, 100)


def edge_key(a: int, b: int) -> str:
    return f"{min(a,b)}-{max(a,b)}"


def dist_point_to_segment(px, py, ax, ay, bx, by) -> Tuple[float, float, float, float]:
    dx, dy = bx-ax, by-ay
    l2 = dx*dx + dy*dy
    if l2 <= EPS:
        return math.hypot(px-ax, py-ay), 0.0, ax, ay
    t = ((px-ax)*dx + (py-ay)*dy) / l2
    t = max(0.0, min(1.0, t))
    qx, qy = ax + t*dx, ay + t*dy
    return math.hypot(px-qx, py-qy), t, qx, qy


def point_on_segment_param(px, py, ax, ay, bx, by, tol=NODE_TOL) -> float:
    d, t, qx, qy = dist_point_to_segment(px, py, ax, ay, bx, by)
    if d <= tol and 0.001 < t < 0.999:
        return t
    return -1.0


def split_lines_at_touch_points(lines: List[Tuple[float,float,float,float]], tol=NODE_TOL):
    pts = []
    for x1,y1,x2,y2 in lines:
        pts.append((x1,y1)); pts.append((x2,y2))
    out = []
    for x1,y1,x2,y2 in lines:
        cuts = [0.0, 1.0]
        for px,py in pts:
            t = point_on_segment_param(px, py, x1, y1, x2, y2, tol)
            if t > 0 and all(abs(t-c) > 0.001 for c in cuts):
                cuts.append(t)
        cuts.sort()
        for c1, c2 in zip(cuts, cuts[1:]):
            if abs(c2-c1) < 0.001:
                continue
            ax, ay = x1+(x2-x1)*c1, y1+(y2-y1)*c1
            bx, by = x1+(x2-x1)*c2, y1+(y2-y1)*c2
            if math.hypot(bx-ax, by-ay) > 0.5:
                out.append((ax,ay,bx,by))
    return out


def _jww_attr_key(attr: Dict[str, str]) -> Tuple[str, str, str]:
    return (str(attr.get("ly", "")).strip().lower(), str(attr.get("lc", "")).strip().lower(), str(attr.get("lt", "")).strip().lower())


def _read_jww_temp_entities(path: str) -> Tuple[List[Dict[str, object]], List[Tuple[float, float]]]:
    """Read every drawable entity selected by JWW 外変, preserving layer/color/line type.

    V41 safety rule:
    - Only hp* lines are user/base points.  Do NOT treat hch/hcw/hcd/hcc as
      points; those are JWW header/settings lines and caused fake points like
      (1, 2.5).
    - If JWW writes a 基準点 at the center of the selection rectangle (hn),
      remove only that center point.  hp1/hp2/... are otherwise kept, so many
      pipe groups still work.
    """
    ents: List[Dict[str, object]] = []
    base_points: List[Tuple[float, float]] = []
    selection_center: Optional[Tuple[float, float]] = None
    current = {"ly": "", "lc": "", "lt": ""}
    num = r"-?\d+(?:\.\d+)?"
    numline = re.compile(rf"^\s*({num})\s+({num})\s+({num})\s+({num})\s*$")
    hnline = re.compile(rf"^\s*hn\s+({num})\s+({num})\s+({num})\s+({num})(?:\s|$)", re.IGNORECASE)
    ciline = re.compile(r"^\s*ci\s+(.+)$", re.IGNORECASE)
    pointline = re.compile(rf"^\s*hp\d+\s+({num})\s+({num})(?:\s|$)", re.IGNORECASE)
    nums_re = re.compile(num)
    with open(path, "r", encoding="cp932", errors="ignore") as f:
        for raw in f:
            line = raw.strip()
            if not line:
                continue
            low = line.lower()
            m = hnline.match(line)
            if m:
                x1, y1, x2, y2 = map(float, m.groups())
                selection_center = ((x1 + x2) / 2.0, (y1 + y2) / 2.0)
                continue
            if low.startswith("ly"):
                current["ly"] = line[2:].strip().lower(); continue
            if low.startswith("lc"):
                current["lc"] = line[2:].strip().lower(); continue
            if low.startswith("lt"):
                current["lt"] = line[2:].strip().lower(); continue
            m = pointline.match(line)
            if m:
                base_points.append((float(m.group(1)), float(m.group(2))))
                continue
            common = {"ly": current.get("ly", ""), "lc": current.get("lc", ""), "lt": current.get("lt", "")}
            m = numline.match(line)
            if m:
                x1, y1, x2, y2 = map(float, m.groups())
                if math.hypot(x2 - x1, y2 - y1) > 0.01:
                    d = {"type": "line", "x1": x1, "y1": y1, "x2": x2, "y2": y2}
                    d.update(common); ents.append(d)
                continue
            m = ciline.match(line)
            if m:
                vals = [float(x) for x in nums_re.findall(m.group(1))]
                if len(vals) >= 3 and vals[2] > 0.001:
                    if len(vals) >= 5:
                        rot = vals[-1] if len(vals) >= 7 else 0.0
                        d = {"type": "arc", "cx": vals[0], "cy": vals[1], "r": vals[2], "a1": vals[3], "a2": vals[4], "rot": rot}
                    else:
                        d = {"type": "circle", "cx": vals[0], "cy": vals[1], "r": vals[2]}
                    d.update(common); ents.append(d)
                continue

    if selection_center is not None and base_points:
        cx, cy = selection_center
        # 基準点 is normally exactly the hn center.  Keep tolerance small so a
        # real selected pipe start near the middle is not accidentally removed.
        tol = max(1.0, NODE_TOL * 0.5)
        kept: List[Tuple[float, float]] = []
        for bx, by in base_points:
            if math.hypot(bx - cx, by - cy) <= tol:
                print(f"⚠ Bỏ qua 基準点/tâm vùng quét JWW: ({bx:.3f}, {by:.3f})")
                continue
            kept.append((bx, by))
        base_points = kept
    return ents, base_points


def _detect_centerline_attr_from_base(ents: List[Dict[str, object]], base_points: List[Tuple[float, float]]) -> Optional[Tuple[str, str, str]]:
    if not ents or not base_points:
        return None
    best = None; best_d = 1e100
    for bx, by in base_points:
        for ent in ents:
            if ent.get("type") != "line":
                continue
            x1, y1 = float(ent.get("x1", 0.0)), float(ent.get("y1", 0.0))
            x2, y2 = float(ent.get("x2", 0.0)), float(ent.get("y2", 0.0))
            d, t, _, _ = dist_point_to_segment(bx, by, x1, y1, x2, y2)
            if d < best_d:
                best_d = d; best = _jww_attr_key(ent)  # type: ignore[arg-type]
    if best is not None and best_d <= max(NODE_TOL * 2.0, 8.0):
        return best
    return None


def parse_jww_temp(path: str) -> Tuple[List[Tuple[float,float,float,float]], List[Tuple[float,float]]]:
    """Read JWW 外変 temp file.

    V39: whole selected range becomes reference background, but only lines with
    the same layer/color/line type as the line under the selected start point
    become NEVIS pipe center lines.  This avoids hardcoding layer B.
    """
    ents, base_points = _read_jww_temp_entities(path)
    line_ents = [e for e in ents if e.get("type") == "line"]
    center_attr = _detect_centerline_attr_from_base(line_ents, base_points)
    center_lines: List[Tuple[float,float,float,float]] = []
    if center_attr is not None:
        for e in line_ents:
            if _jww_attr_key(e) == center_attr:  # type: ignore[arg-type]
                x1, y1 = float(e.get("x1", 0.0)), float(e.get("y1", 0.0))
                x2, y2 = float(e.get("x2", 0.0)), float(e.get("y2", 0.0))
                if math.hypot(x2-x1, y2-y1) > 0.5:
                    center_lines.append((x1, y1, x2, y2))
    if not center_lines:
        for e in line_ents:
            ly, lc, lt = _jww_attr_key(e)  # type: ignore[arg-type]
            if ly == "b" and lc in {"6", "2"} and lt in {"5", "1"}:
                x1, y1 = float(e.get("x1", 0.0)), float(e.get("y1", 0.0))
                x2, y2 = float(e.get("x2", 0.0)), float(e.get("y2", 0.0))
                if math.hypot(x2-x1, y2-y1) > 0.5:
                    center_lines.append((x1, y1, x2, y2))
    return center_lines, list(base_points)


def parse_jww_background_geometry(path: str, max_entities: int = 30000) -> List[Dict[str, object]]:
    try:
        ents, _ = _read_jww_temp_entities(path)
        return ents[:max_entities]
    except Exception:
        return []


def jww_background_bounds(ents: List[Dict[str, object]]) -> Optional[QRectF]:
    xs: List[float] = []; ys: List[float] = []
    for e in ents or []:
        try:
            typ = e.get("type")
            if typ == "line":
                p1 = display_point(float(e.get("x1", 0.0)), float(e.get("y1", 0.0)))
                p2 = display_point(float(e.get("x2", 0.0)), float(e.get("y2", 0.0)))
                xs += [p1[0], p2[0]]; ys += [p1[1], p2[1]]
            elif typ in ("circle", "arc"):
                cx, cy = display_point(float(e.get("cx", 0.0)), float(e.get("cy", 0.0)))
                r = abs(float(e.get("r", 0.0)))
                xs += [cx-r, cx+r]; ys += [cy-r, cy+r]
        except Exception:
            continue
    if not xs or not ys:
        return None
    return QRectF(min(xs), min(ys), max(xs)-min(xs), max(ys)-min(ys)).adjusted(-100, -100, 100, 100)

def split_lines_at_points(lines: List[Tuple[float,float,float,float]], points: List[Tuple[float,float]], tol=NODE_TOL):
    """Force selected 集合管 point to become a graph node when it lies on a pipe line."""
    if not points:
        return lines
    out = []
    for x1,y1,x2,y2 in lines:
        cuts = [0.0, 1.0]
        for px, py in points:
            t = point_on_segment_param(px, py, x1, y1, x2, y2, tol)
            if t > 0 and all(abs(t-c) > 0.001 for c in cuts):
                cuts.append(t)
        cuts.sort()
        for c1, c2 in zip(cuts, cuts[1:]):
            if abs(c2-c1) < 0.001:
                continue
            ax, ay = x1+(x2-x1)*c1, y1+(y2-y1)*c1
            bx, by = x1+(x2-x1)*c2, y1+(y2-y1)*c2
            if math.hypot(bx-ax, by-ay) > 0.5:
                out.append((ax,ay,bx,by))
    return out


def build_graph(lines: List[Tuple[float,float,float,float]], base_points: List[Tuple[float,float]]) -> PipeModel:
    model = PipeModel()
    # V15 STRICT SELECTED BASE:
    # Keep the original selected centerlines so JWW temporary selection-center points
    # can be rejected if they are not on a real centerline.
    source_lines_for_base_check = list(lines)
    # First split normal line intersections/endpoints, then split once more by #1 集合管 point.
    # This prevents the base point from snapping to the wrong nearby endpoint when the user
    # right-clicks on the middle of a center line.
    lines = split_lines_at_touch_points(lines)
    lines = split_lines_at_points(lines, base_points)
    next_id = 1

    def get_node(x, y):
        nonlocal next_id
        for nid, n in model.nodes.items():
            if math.hypot(n.x-x, n.y-y) <= NODE_TOL:
                return nid
        nid = next_id; next_id += 1
        model.nodes[nid] = Node(nid, x, y)
        return nid

    seen_edges: Set[str] = set()
    for x1,y1,x2,y2 in lines:
        a, b = get_node(x1,y1), get_node(x2,y2)
        if a == b:
            continue
        k = edge_key(a,b)
        if k not in seen_edges:
            seen_edges.add(k)
            model.edges.append(Edge(a,b))

    # V12: support many indicated start/collection points.
    # Old code kept only base_points[0], so after scanning multiple start points
    # only one cluster was controlled.  Here every indicated point becomes a base.
    if base_points:
        bases = set()
        for bx, by in base_points:
            # V15 STRICT SELECTED BASE:
            # JWW may write a temporary selection-center point before the user picks a real start.
            # Accept a base point only when it lies on/near a selected centerline AND resolves
            # to a real graph node after splitting. Never snap a far temporary point to
            # the nearest intersection.
            if source_lines_for_base_check:
                best_seg_dist = min(
                    dist_point_to_segment(bx, by, x1, y1, x2, y2)[0]
                    for x1, y1, x2, y2 in source_lines_for_base_check
                )
                if best_seg_dist > max(NODE_TOL * 2.0, 5.0):
                    print(f"⚠ Bỏ qua điểm tạm JWW không nằm trên tim ống: ({bx:.3f}, {by:.3f})")
                    continue

            nid = nearest_node(model, bx, by)
            if nid is not None:
                n = model.nodes[nid]
                if math.hypot(n.x - bx, n.y - by) <= max(NODE_TOL * 2.0, 5.0):
                    bases.add(nid)
                else:
                    print(f"⚠ Bỏ qua điểm tạm JWW không trùng node thật: ({bx:.3f}, {by:.3f})")
        model.base_nodes = bases
        model.base_node = sorted(bases)[0] if bases else None
        if not bases:
            print("⚠ Chưa có điểm đầu nhánh")
    elif model.nodes:
        # V15 STRICT SELECTED BASE:
        # No user-selected base point. Do not choose the first node automatically.
        model.base_node = None
        model.base_nodes = set()
        print("⚠ Chưa có điểm đầu nhánh")
    else:
        model.base_node = None
        model.base_nodes = set()

    classify_fittings(model)
    rebuild_flow(model)
    return model


def graph_diagnostic_summary(model: PipeModel) -> Dict[str, int]:
    """Small safety report for large pipe networks.

    This does not change drawing. It only helps detect graph mistakes early:
    split nodes, over-merged nodes, and unsupported 4+ branch nodes.
    """
    degs = [model.degree(nid) for nid in model.nodes]
    return {
        "nodes": len(model.nodes),
        "edges": len(model.edges),
        "end_nodes": sum(1 for d in degs if d == 1),
        "straight_or_bend_nodes": sum(1 for d in degs if d == 2),
        "junction_3_nodes": sum(1 for d in degs if d == 3),
        "check_nodes_4plus": sum(1 for d in degs if d >= 4),
        "disconnected_nodes": sum(1 for nid in model.nodes if model.dist.get(nid, 1e100) >= 1e99),
        "base_nodes": len(getattr(model, "base_nodes", set()) or ({model.base_node} if model.base_node is not None else set())),
    }


def write_graph_diagnostic(model: PipeModel, path: Optional[Path] = None) -> None:
    try:
        path = path or (app_base_dir() / "nevis_graph_debug.txt")
        info = graph_diagnostic_summary(model)
        lines = [
            "NEVIS GRAPH DEBUG",
            f"nodes={info['nodes']}",
            f"edges={info['edges']}",
            f"base_nodes={info.get('base_nodes', 0)}",
            f"end_nodes={info['end_nodes']}",
            f"straight_or_bend_nodes={info['straight_or_bend_nodes']}",
            f"junction_3_nodes={info['junction_3_nodes']}",
            f"check_nodes_4plus={info['check_nodes_4plus']}",
            f"disconnected_nodes={info['disconnected_nodes']}",
            "",
            "NODE_DETAIL id x y degree fitting size",
        ]
        for nid in sorted(model.nodes):
            n = model.nodes[nid]
            fit = model.fittings.get(nid)
            lines.append(f"{nid}	{n.x:.3f}	{n.y:.3f}	{model.degree(nid)}	{getattr(fit,'ftype','')}	{getattr(fit,'size','')}")
        path.write_text("\n".join(lines), encoding="utf-8")
    except Exception:
        pass


def nearest_node(model: PipeModel, x: float, y: float) -> Optional[int]:
    best = None; bd = 1e100
    for nid,n in model.nodes.items():
        d = (n.x-x)**2 + (n.y-y)**2
        if d < bd:
            bd = d; best = nid
    return best


def angle_between(v1, v2):
    x1,y1 = v1; x2,y2 = v2
    l1 = math.hypot(x1,y1); l2 = math.hypot(x2,y2)
    if l1 <= EPS or l2 <= EPS:
        return 0.0
    c = max(-1.0, min(1.0, (x1*x2+y1*y2)/(l1*l2)))
    return math.degrees(math.acos(c))


PIPE_SIZE_ORDER = ["20", "25", "30", "40", "50", "65", "75", "80", "100", "125", "150", "200", "250"]

def lower_pipe_size(size: str) -> str:
    s = str(size).split("x")[0].strip()
    if s in PIPE_SIZE_ORDER:
        i = PIPE_SIZE_ORDER.index(s)
        return PIPE_SIZE_ORDER[max(0, i-1)]
    try:
        v = int(float(s))
    except Exception:
        return s
    # safe fallback for unknown Japanese pipe sizes
    candidates = [int(x) for x in PIPE_SIZE_ORDER]
    smaller = [x for x in candidates if x < v]
    return str(smaller[-1] if smaller else v)

def edge_obj(model: PipeModel, a: int, b: int) -> Optional[Edge]:
    k = edge_key(a, b)
    for e in model.edges:
        if e.key == k:
            return e
    return None

def parse_fitting_size_pair(size: str, default_main: str) -> Tuple[str, str]:
    nums = re.findall(r"\d+", str(size))
    if len(nums) >= 2:
        return nums[0], nums[1]
    if len(nums) == 1:
        return nums[0], lower_pipe_size(nums[0])
    return default_main, lower_pipe_size(default_main)

def junction_axis_info(model: PipeModel, nid: int) -> Optional[Dict[str, object]]:
    """AHK-compatible Y/LT/T axis detector.

    This intentionally mirrors the old AutoHotkey `GetYAxisInfo` logic:
    1. Pick the pair of connected pipes whose vectors have the smallest cosine
       value (closest to -1), i.e. the most straight/collinear pair.
    2. The remaining connection is the branch. If there are more than three
       connections, prefer the candidate closest to 135° from axisA, exactly as
       the AHK code did.

    Previous Python versions selected the branch by proximity to 90°.  That is
    fine for LT/T, but it is wrong for drainage Y where the branch is typically
    45°/135° to the main axis.  It made the Y orientation look unchanged even
    after fixing the TXT centerline rules.
    """
    ns = model.neighbors(nid)
    if len(ns) < 3 or nid not in model.nodes:
        return None
    n0 = model.nodes[nid]

    best_pair = None
    best_cos = 1e100
    best_straight_error = 1e100

    def cos_score(v1, v2):
        x1, y1 = v1; x2, y2 = v2
        l1 = math.hypot(x1, y1); l2 = math.hypot(x2, y2)
        if l1 <= EPS or l2 <= EPS:
            return 1.0
        return max(-1.0, min(1.0, (x1*x2 + y1*y2) / (l1*l2)))

    for i in range(len(ns)):
        for j in range(i + 1, len(ns)):
            ni, nj = ns[i], ns[j]
            vi = (model.nodes[ni].x - n0.x, model.nodes[ni].y - n0.y)
            vj = (model.nodes[nj].x - n0.x, model.nodes[nj].y - n0.y)
            c = cos_score(vi, vj)
            err = abs(180.0 - angle_between(vi, vj))
            if c < best_cos:
                best_cos = c
                best_straight_error = err
                best_pair = (ni, nj)

    if not best_pair:
        return None

    axis = set(best_pair)
    axis_a = best_pair[0]
    va = (model.nodes[axis_a].x - n0.x, model.nodes[axis_a].y - n0.y)

    branch = None
    best_branch_score = 1e100
    branch_angle_from_axis = 0.0
    for nb in ns:
        if nb in axis:
            continue
        vb = (model.nodes[nb].x - n0.x, model.nodes[nb].y - n0.y)
        deg = angle_between(vb, va)
        # AHK: score := Abs(deg2 - 135)
        score = abs(deg - 135.0)
        if score < best_branch_score:
            best_branch_score = score
            branch = nb
            branch_angle_from_axis = deg

    if branch is None:
        return None

    # For classifying LT/DT vs Y, use the actual angle between branch and the
    # undirected main axis.  Y is around 45/135; LT/T is around 90.
    axis_line_angle = min(branch_angle_from_axis, 180.0 - branch_angle_from_axis)
    is_right_angle = abs(axis_line_angle - 90.0) <= 20.0
    return {
        "axis": best_pair,
        "branch": branch,
        "right_angle": is_right_angle,
        "straight_error": best_straight_error,
        "axis_cos": best_cos,
        "branch_score_135": best_branch_score,
    }

def classify_junction_type(model: PipeModel, nid: int, main_size: str = "") -> str:
    info = junction_axis_info(model, nid)
    if not info:
        return "Y"
    if info["right_angle"]:
        try:
            return "DT" if float(str(main_size).split("x")[0]) <= 50 else "LT"
        except Exception:
            return "LT"
    return "Y"

def classify_fittings(model: PipeModel, default_size=""):
    for nid in model.nodes:
        deg = model.degree(nid)
        if (nid == model.base_node) or (nid in getattr(model, "base_nodes", set())):
            model.fittings[nid] = Fitting(nid, "集合管", "")
        elif deg == 1:
            model.fittings[nid] = Fitting(nid, "DL", default_size)
        elif deg == 2:
            ns = model.neighbors(nid)
            n0 = model.nodes[nid]
            v1 = (model.nodes[ns[0]].x-n0.x, model.nodes[ns[0]].y-n0.y)
            v2 = (model.nodes[ns[1]].x-n0.x, model.nodes[ns[1]].y-n0.y)
            bend = abs(180 - angle_between(v1, v2))
            if bend < 20:
                continue
            elif bend < 60:
                model.fittings[nid] = Fitting(nid, "45°", default_size)
            else:
                model.fittings[nid] = Fitting(nid, "LL", default_size)
        elif deg == 3:
            t = classify_junction_type(model, nid, default_size)
            if default_size:
                model.fittings[nid] = Fitting(nid, t, f"{default_size}x{lower_pipe_size(default_size)}")
            else:
                model.fittings[nid] = Fitting(nid, t, "")
        elif deg >= 4:
            # Drainage pipe does not use a 4-way cross fitting.
            # Keep it as a check node instead of forcing Y/T/LT.
            model.fittings[nid] = Fitting(nid, "要確認", "")


def rebuild_flow(model: PipeModel):
    """Calculate flow distance/parent from one or many start nodes.

    Old NEVIS had only one base_node.  Large projects can have many independent
    clusters (kitchen stack, toilet stack, ventilation branches, etc.).  This
    multi-source Dijkstra keeps every selected start node at distance 0 and
    gives each cluster its own flow tree.
    """
    model.dist = {nid: 1e100 for nid in model.nodes}
    model.parent = {}
    bases = set(getattr(model, "base_nodes", set()) or [])
    if getattr(model, "base_node", None) is not None:
        bases.add(model.base_node)
    bases = {b for b in bases if b in model.nodes}
    if not bases:
        return
    model.base_nodes = set(bases)
    # Keep base_node for old code paths, but do not limit flow to only it.
    if model.base_node not in bases:
        model.base_node = sorted(bases)[0]
    for b in bases:
        model.dist[b] = 0.0
    visited = set()
    while len(visited) < len(model.nodes):
        u = None; bd = 1e100
        for nid,d in model.dist.items():
            if nid not in visited and d < bd:
                u = nid; bd = d
        if u is None or bd >= 1e99:
            break
        visited.add(u)
        for nb in model.neighbors(u):
            e_len = math.hypot(model.nodes[nb].x-model.nodes[u].x, model.nodes[nb].y-model.nodes[u].y)
            nd = model.dist[u] + e_len
            if nd + 0.001 < model.dist[nb]:
                model.dist[nb] = nd
                model.parent[nb] = u


def edge_fire_fraction(model: PipeModel, e: Edge, fire_len: float) -> float:
    da = model.dist.get(e.a, 1e100)
    db = model.dist.get(e.b, 1e100)
    if da >= 1e99 or db >= 1e99:
        return 0.0
    mn, mx = min(da, db), max(da, db)
    length = max(model.edge_length(e), EPS)
    overlap = max(0.0, min(mx, fire_len) - mn)
    return max(0.0, min(1.0, overlap / length))



