def _nums_from_text(s: str) -> List[float]:
    return [float(x) for x in re.findall(r"-?\d+(?:\.\d+)?", s or "")]



def _fmt_jww_num(v: float) -> str:
    """Compact number formatter for rebuilt JWW text from JSON geometry."""
    try:
        v = float(v)
    except Exception:
        v = 0.0
    if abs(v) < 1e-9:
        v = 0.0
    s = f"{v:.10f}".rstrip("0").rstrip(".")
    return s if s else "0"


def _read_nevis_json(path: str) -> dict:
    """Read a NEVIS standalone library JSON safely."""
    try:
        return json.loads(Path(path).read_text(encoding="utf-8-sig"))
    except Exception:
        try:
            return json.loads(Path(path).read_text(encoding="utf-8"))
        except Exception:
            return {}




def _as_float(v, default=0.0):
    try:
        return float(v)
    except Exception:
        return default


def _json_geometry_root(data):
    if not isinstance(data, dict):
        return {}
    g = data.get("geometry")
    return g if isinstance(g, dict) else data


def _json_list_any(d: dict, names: List[str]) -> list:
    if not isinstance(d, dict):
        return []
    for name in names:
        v = d.get(name)
        if isinstance(v, list):
            return v
    return []


def _json_xy(obj) -> Optional[Tuple[float, float]]:
    if isinstance(obj, dict):
        if "x" in obj and "y" in obj:
            return (_as_float(obj.get("x")), _as_float(obj.get("y")))
        if "cx" in obj and "cy" in obj:
            return (_as_float(obj.get("cx")), _as_float(obj.get("cy")))
        if "px" in obj and "py" in obj:
            return (_as_float(obj.get("px")), _as_float(obj.get("py")))
        p = obj.get("point") or obj.get("pos") or obj.get("center") or obj.get("origin")
        if isinstance(p, (list, tuple)) and len(p) >= 2:
            return (_as_float(p[0]), _as_float(p[1]))
        if isinstance(p, dict):
            return _json_xy(p)
    if isinstance(obj, (list, tuple)) and len(obj) >= 2:
        return (_as_float(obj[0]), _as_float(obj[1]))
    return None


def _json_port_cut_xy(obj) -> Optional[Tuple[float, float]]:
    """Return the real pipe-contact/cut point of a JSON port when available.

    P1/P2/P3 in the NEVIS JSON library must be treated as socket/mouth contact
    points for trimming.  Older helper _json_xy() was also used for orientation,
    so it intentionally stays conservative.  This helper only serves trimming
    and accepts the extra explicit cut/contact key names produced by different
    library-editor generations.
    """
    if not isinstance(obj, dict):
        return _json_xy(obj)
    for kx, ky in (("cut_x", "cut_y"), ("trim_x", "trim_y"), ("contact_x", "contact_y"), ("mouth_x", "mouth_y"), ("socket_x", "socket_y")):
        if kx in obj and ky in obj:
            return (_as_float(obj.get(kx)), _as_float(obj.get(ky)))
    for k in (
        "cut_point", "cutpoint", "trim_point", "trimming_point",
        "contact_point", "pipe_contact_point", "mouth_point",
        "socket_point", "connection_point", "end_point", "endpoint",
    ):
        if k in obj:
            xy = _json_xy(obj.get(k))
            if xy is not None:
                return xy
    return _json_xy(obj)


def _json_port_axis(obj, anchor: Tuple[float, float] = (0.0, 0.0)) -> Optional[float]:
    """Return local connection direction from a JSON connector/port object.

    The editor versions used during NEVIS development are not all identical, so
    this accepts several common key names: angle/deg/rad, dx/dy, vector, dir,
    direction, axis.  If no vector exists, it falls back to the ray from anchor to
    the port point.
    """
    if not isinstance(obj, dict):
        pt = _json_xy(obj)
        if pt:
            return math.atan2(pt[1] - anchor[1], pt[0] - anchor[0])
        return None
    for k in ("angle", "angle_deg", "ang", "theta", "deg", "degree", "rotation"):
        if k in obj:
            val = _as_float(obj.get(k))
            return math.radians(val) if abs(val) > math.tau else val
    for k in ("rad", "radian"):
        if k in obj:
            return _as_float(obj.get(k))
    for kx, ky in (("dx","dy"), ("vx","vy"), ("nx","ny")):
        if kx in obj and ky in obj:
            dx, dy = _as_float(obj.get(kx)), _as_float(obj.get(ky))
            if abs(dx) + abs(dy) > 1e-9:
                return math.atan2(dy, dx)
    for k in ("vector", "vec", "dir", "direction", "axis"):
        v = obj.get(k)
        if isinstance(v, dict):
            a = _json_port_axis(v, anchor)
            if a is not None:
                return a
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            dx, dy = _as_float(v[0]), _as_float(v[1])
            if abs(dx) + abs(dy) > 1e-9:
                return math.atan2(dy, dx)
        if isinstance(v, str):
            nums = [float(x) for x in re.findall(r"-?\d+(?:\.\d+)?", v)]
            if len(nums) == 1:
                return math.radians(nums[0]) if abs(nums[0]) > math.tau else nums[0]
            if len(nums) >= 2 and abs(nums[0]) + abs(nums[1]) > 1e-9:
                return math.atan2(nums[1], nums[0])
    pt = _json_xy(obj)
    if pt:
        vx, vy = pt[0] - anchor[0], pt[1] - anchor[1]
        if abs(vx) + abs(vy) > 1e-9:
            return math.atan2(vy, vx)
    return None


def _json_connector_data(path: str) -> Tuple[Optional[Tuple[float, float]], List[float], List[Tuple[float, float]]]:
    """Read explicit connector metadata from a NEVIS JSON library.

    Returns (anchor, port_axes, port_points).  It is deliberately tolerant of key
    names so older JSON libraries and the new editor output can both work.
    """
    try:
        if Path(path).suffix.lower() != ".json":
            return None, [], []
    except Exception:
        return None, [], []
    data = _read_nevis_json(path)
    if not isinstance(data, dict):
        return None, [], []
    g = _json_geometry_root(data)
    anchor = None
    for key in ("anchor", "origin", "center", "base", "insert", "insertion_point", "insertion", "node"):
        if key in data:
            anchor = _json_xy(data.get(key));
            if anchor: break
        if isinstance(g, dict) and key in g:
            anchor = _json_xy(g.get(key));
            if anchor: break
    ports = []
    for src in (data, g):
        if not isinstance(src, dict):
            continue
        ports += _json_list_any(src, ["connectors", "connector", "ports", "port", "mouths", "mouth", "joints", "sockets", "connections"])
    # de-duplicate by point/axis-ish string
    uniq = []
    seen = set()
    for p in ports:
        key = repr(p)[:250]
        if key not in seen:
            uniq.append(p); seen.add(key)
    ports = uniq
    pts = []
    for p in ports:
        xy = _json_xy(p)
        if xy is not None:
            pts.append(xy)
    if anchor is None and len(pts) == 1:
        # One-door UP/DOWN terminal: the connector point is the insertion point.
        anchor = pts[0]
    if anchor is None:
        anchor = (0.0, 0.0)
    axes = []
    for p in ports:
        a = _json_port_axis(p, anchor)
        if a is not None:
            axes.append(a)
    # Avoid duplicated layer/same connector axes.
    axes2 = []
    for a in axes:
        if all(abs(((a-b+math.pi)%(2*math.pi))-math.pi) > math.radians(8) for b in axes2):
            axes2.append(a)
    return anchor, axes2, pts



def _json_connector_objects(path: str) -> Tuple[Tuple[float, float], List[Dict[str, object]], Dict[str, object]]:
    """Return JSON connector objects with name/role/point/axis for deterministic orientation and preview.

    The new JSON database is the source of truth.  This helper keeps the port
    labels (P1/P2/P3) and roles instead of returning only angles; losing these
    labels was the reason identical LL libraries could be rotated in different
    ways depending on neighbor order.
    """
    try:
        if Path(path).suffix.lower() != ".json":
            return (0.0, 0.0), [], {}
    except Exception:
        return (0.0, 0.0), [], {}
    data = _read_nevis_json(path)
    if not isinstance(data, dict):
        return (0.0, 0.0), [], {}
    g = _json_geometry_root(data)
    anchor = None
    for key in ("anchor", "origin", "center", "base", "insert", "insertion_point", "insertion", "node"):
        if key in data:
            anchor = _json_xy(data.get(key))
            if anchor: break
        if isinstance(g, dict) and key in g:
            anchor = _json_xy(g.get(key))
            if anchor: break
    raw_ports = []
    for src in (data, g):
        if isinstance(src, dict):
            raw_ports += _json_list_any(src, ["connectors", "connector", "ports", "port", "mouths", "mouth", "joints", "sockets", "connections"])
    pts = []
    for rp in raw_ports:
        xy = _json_xy(rp)
        if xy: pts.append(xy)
    if anchor is None and len(pts) == 1:
        anchor = pts[0]
    if anchor is None:
        anchor = (0.0, 0.0)
    ports = []
    seen = set()
    for i, rp in enumerate(raw_ports, start=1):
        if not isinstance(rp, dict):
            rp = {"point": rp}
        axis = _json_port_axis(rp, anchor)
        xy = _json_xy(rp)
        cut_xy = _json_port_cut_xy(rp)
        name = str(rp.get("name") or rp.get("id") or rp.get("label") or rp.get("port") or f"P{i}")
        role = str(rp.get("role") or rp.get("kind") or rp.get("type") or "")
        if axis is None and xy is not None:
            axis = math.atan2(xy[1] - anchor[1], xy[0] - anchor[0])
        if axis is None:
            continue
        key = (round(axis, 6), round((xy or (999999,999999))[0], 3), round((xy or (999999,999999))[1], 3), name)
        if key in seen:
            continue
        seen.add(key)
        ports.append({"name": name.upper(), "role": role.lower(), "point": xy, "cut_point": cut_xy, "axis": axis, "raw": rp})
    meta = {}
    for src in (data, g):
        if isinstance(src, dict):
            for k in ("flow", "flow_type", "standard_port", "base_port", "main_port", "downstream_port", "out_port"):
                if k in src:
                    meta[k] = src.get(k)
    return tuple(anchor), ports, meta


def _json_terminal_ud_scale_factor(path: str) -> float:
    """JSON library geometry must be used at its own real size.

    Do NOT enlarge/shrink by file name (DV/TMP/U/D/size).  The JSON editor is now
    the single source of truth: every line/circle/arc coordinate and every port
    coordinate is already real local mm.  Earlier hotfixes multiplied terminal
    U/D files by 2.0, which made some sizes correct by accident but broke other
    normal libraries such as 40 and TMP.
    """
    return 1.0

def _scale_library_entities_about_anchor(ents, path: str):
    """Return JSON/TXT entities without artificial scaling.

    A fitting must be drawn exactly as stored in the library JSON.  Any size
    mismatch should be fixed in the JSON generation/normalization, not by NEVIS
    guessing from DV/TMP/U/D file names.
    """
    return ents

def _library_json_to_jww_lines(path: str) -> List[str]:
    """Convert standalone NEVIS JSON V2 into JWW-like text records.

    Supports the current JSON made by Nevis_JSON_Library_Editor_FINAL:
      geometry.raw_lines
      geometry.entities.centerlines / outlines / circles
    raw_lines are preferred.  If absent, entities are rebuilt directly.
    """
    data = _read_nevis_json(path)
    if not isinstance(data, dict):
        return []

    geo = data.get("geometry", data)
    roots = []
    if isinstance(geo, dict):
        roots.append(geo)
    roots.append(data)

    for r in roots:
        if not isinstance(r, dict):
            continue
        raw = r.get("raw_lines")
        if isinstance(raw, list) and raw:
            return [str(x).rstrip("\r\n") for x in raw]
        for k in ("jww_lines", "txt_lines", "source_lines"):
            v = r.get(k)
            if isinstance(v, list) and v:
                return [str(x).rstrip("\r\n") for x in v]
            if isinstance(v, str) and v.strip():
                return v.replace("\r\n", "\n").replace("\r", "\n").split("\n")

    out: List[str] = []

    def add_seg(d, default_lt="1"):
        if not isinstance(d, dict):
            return
        try:
            lt = str(d.get("lt", default_lt))
            lc = str(d.get("lc", ""))
            ly = str(d.get("ly", ""))
            if ly: out.append("ly" + ly)
            if lc: out.append("lc" + lc)
            if lt: out.append("lt" + lt)
            out.append(f"{_fmt_jww_num(d.get('x1',0))} {_fmt_jww_num(d.get('y1',0))} {_fmt_jww_num(d.get('x2',0))} {_fmt_jww_num(d.get('y2',0))}")
        except Exception:
            pass

    def add_circle(d, default_lt="1"):
        if not isinstance(d, dict):
            return
        try:
            lt = str(d.get("lt", default_lt))
            lc = str(d.get("lc", ""))
            ly = str(d.get("ly", ""))
            if ly: out.append("ly" + ly)
            if lc: out.append("lc" + lc)
            if lt: out.append("lt" + lt)
            raw = str(d.get("raw", "")).strip()
            if raw.lower().startswith("ci"):
                out.append(raw); return
            rest = str(d.get("rest", "")).strip()
            cx, cy, rr = _fmt_jww_num(d.get('cx',0)), _fmt_jww_num(d.get('cy',0)), _fmt_jww_num(d.get('r',0))
            if rest:
                out.append(f"ci {cx} {cy} {rr} {rest}")
            elif d.get("is_arc") or any(k in d for k in ("a1","a2","start_angle","end_angle")):
                a1 = d.get("a1", d.get("start_angle", 0))
                a2 = d.get("a2", d.get("end_angle", 360))
                rot = d.get("rot", d.get("rotation", 0))
                out.append(f"ci {cx} {cy} {rr} {_fmt_jww_num(a1)} {_fmt_jww_num(a2)} 1 {_fmt_jww_num(rot)}")
            else:
                out.append(f"ci {cx} {cy} {rr}")
        except Exception:
            pass

    entities = geo.get("entities", {}) if isinstance(geo, dict) else {}
    if isinstance(entities, dict):
        for d in entities.get("centerlines", []) or []:
            add_seg(d, "49")
        for d in entities.get("outlines", []) or []:
            add_seg(d, "1")
        for d in entities.get("segments", []) or []:
            add_seg(d, str(d.get("lt", "1")) if isinstance(d, dict) else "1")
        for d in entities.get("circles", []) or []:
            add_circle(d, str(d.get("lt", "1")) if isinstance(d, dict) else "1")

    # Older JSON shape fallback.
    if not out and isinstance(geo, dict):
        for seg in geo.get("segments", []) or []:
            add_seg(seg, "1")
        for c in geo.get("circles", []) or []:
            add_circle(c, "1")

    # Last tolerant fallback: recursive drawable records, but skip metadata/ports.
    if not out:
        def emit_line(a,b):
            if a and b:
                out.append(f"{_fmt_jww_num(a[0])} {_fmt_jww_num(a[1])} {_fmt_jww_num(b[0])} {_fmt_jww_num(b[1])}")
        def walk(obj):
            if isinstance(obj, dict):
                if {"x1","y1","x2","y2"}.issubset(obj.keys()):
                    add_seg(obj, str(obj.get("lt","1"))); return
                for akey,bkey in (("p1","p2"),("start","end"),("from","to"),("a","b")):
                    if akey in obj and bkey in obj:
                        emit_line(_json_xy(obj.get(akey)), _json_xy(obj.get(bkey))); return
                pts = obj.get("points") or obj.get("pts") or obj.get("vertices") or obj.get("polyline")
                if isinstance(pts, list) and len(pts) >= 2:
                    for a,b in zip(pts, pts[1:]): emit_line(_json_xy(a), _json_xy(b))
                    return
                if (("cx" in obj and "cy" in obj) or "center" in obj) and ("r" in obj or "radius" in obj):
                    add_circle(obj, str(obj.get("lt","1"))); return
                for k,v in obj.items():
                    if k in ("ports","port","connectors","connector","mouths","mouth","joints","sockets","connections","metadata","name_rule","flow","port_convention_status","name_rule_status","auto_detect"):
                        continue
                    if isinstance(v,(dict,list)): walk(v)
            elif isinstance(obj, list):
                for it in obj: walk(it)
        walk(geo)

    # De-duplicate only adjacent attribute duplicates, keep attribute order otherwise.
    clean=[]
    for line in out:
        if line is None: continue
        line=str(line).strip()
        if not line: continue
        if clean and clean[-1]==line and re.match(r"^(lt|lc|ly)", line, re.I):
            continue
        clean.append(line)
    return clean

def _read_library_lines(path: str) -> List[str]:
    """Read TXT library or the new JSON library as JWW-like text lines."""
    if not path:
        return []
    try:
        if Path(path).suffix.lower() == ".json":
            return _library_json_to_jww_lines(path)
    except Exception:
        return []
    for enc in ("cp932", "utf-8-sig", "utf-8"):
        try:
            return Path(path).read_text(encoding=enc).replace("\r\n", "\n").replace("\r", "\n").split("\n")
        except Exception:
            pass
    try:
        return Path(path).read_text(encoding="cp932", errors="ignore").replace("\r\n", "\n").replace("\r", "\n").split("\n")
    except Exception:
        return []

def parse_jww_library_geometry(path: str):
    """Read JWW TXT/JSON library geometry for preview/JWW output.

    Performance note: the same JSON fitting can be drawn dozens of times in one
    preview refresh.  Re-reading JSON and expanding arcs every click caused the
    UI to freeze.  Cache by path + mtime + size, so edited libraries refresh
    automatically but normal selection/redraw is fast.
    """
    if not path:
        return []
    try:
        pp = Path(path)
        st = pp.stat()
        key = (str(pp.resolve()).lower(), float(st.st_mtime), int(st.st_size))
        cached = _LIB_GEOM_CACHE.get(key)
        if cached is not None:
            # Shallow copy is enough because entity dicts are not mutated during drawing.
            return list(cached)
    except Exception:
        key = None

    ents = []
    numline = re.compile(r"^\s*(-?\d+(?:\.\d+)?)\s+(-?\d+(?:\.\d+)?)\s+(-?\d+(?:\.\d+)?)\s+(-?\d+(?:\.\d+)?)\s*$")
    ci_line = re.compile(r"^ci\s+(.+)$", re.IGNORECASE)
    nums_re = re.compile(r"-?\d+(?:\.\d+)?")
    current = {"ly":"", "lc":"", "lt":"1"}
    for raw in _read_library_lines(path):
        ss = str(raw).strip()
        if not ss or ss.startswith("#") or ss.startswith("cn"):
            continue
        low = ss.lower()
        if low.startswith("ly"):
            current["ly"] = ss[2:].strip().lower(); continue
        if low.startswith("lc"):
            current["lc"] = ss[2:].strip().lower(); continue
        if low.startswith("lt"):
            current["lt"] = ss[2:].strip().lower(); continue
        m = numline.match(ss)
        if m:
            x1, y1, x2, y2 = map(float, m.groups())
            if math.hypot(x2-x1, y2-y1) > 0.01:
                ents.append({"type":"line", "x1":x1, "y1":y1, "x2":x2, "y2":y2,
                             "ly":current.get("ly",""), "lc":current.get("lc",""), "lt":current.get("lt","1")})
            continue
        m = ci_line.match(ss)
        if m:
            vals = [float(x) for x in nums_re.findall(m.group(1))]
            if len(vals) >= 3 and vals[2] > 0.001:
                cx, cy, r = vals[0], vals[1], vals[2]
                common = {"ly":current.get("ly",""), "lc":current.get("lc",""), "lt":current.get("lt","1")}
                if len(vals) >= 5:
                    rot = vals[-1] if len(vals) >= 7 else 0.0
                    d={"type":"arc", "cx":cx, "cy":cy, "r":r, "a1":vals[3], "a2":vals[4], "rot":rot}; d.update(common); ents.append(d)
                else:
                    d={"type":"circle", "cx":cx, "cy":cy, "r":r}; d.update(common); ents.append(d)
    ents = _scale_library_entities_about_anchor(ents, path)
    if key is not None:
        _LIB_GEOM_CACHE[key] = list(ents)
        _LIB_GEOM_CACHE_ORDER.append(key)
        # keep memory bounded
        while len(_LIB_GEOM_CACHE_ORDER) > 512:
            old_key = _LIB_GEOM_CACHE_ORDER.pop(0)
            _LIB_GEOM_CACHE.pop(old_key, None)
    return ents

def library_geometry_bounds(ents) -> QRectF:
    xs, ys = [], []
    for e in ents:
        if e["type"] == "line":
            xs += [e["x1"], e["x2"]]; ys += [e["y1"], e["y2"]]
        elif e["type"] in ("circle", "arc"):
            xs += [e["cx"] - e["r"], e["cx"] + e["r"]]
            ys += [e["cy"] - e["r"], e["cy"] + e["r"]]
    if not xs:
        return QRectF(-100, -100, 200, 200)
    return QRectF(min(xs), min(ys), max(xs)-min(xs), max(ys)-min(ys))


def arc_points(cx, cy, r, a1, a2, rot=0.0, steps=48):
    """Return points for a JWW `ci` arc.

    In the VP/DV and TMP fitting TXT samples, `ci` arcs often have a final
    rotation value, e.g. `... 1 90` or `... 1 135`.  The start/end angles are
    local to that rotated system, so the preview must add this rotation before
    drawing.  This is especially important for LL and 45° elbows.
    """
    # JWW TXT normally gives degrees. Convert the local angles plus rotation.
    if abs(a1) > math.tau or abs(a2) > math.tau or abs(rot) > math.tau:
        a1 = math.radians(a1 + rot)
        a2 = math.radians(a2 + rot)
    else:
        a1 = a1 + rot
        a2 = a2 + rot

    span = a2 - a1
    if abs(span) < 1e-9:
        span = math.tau

    # Keep the intended short arc. Many JWW arcs cross 0°, so normalize to
    # the equivalent short span instead of drawing the long reverse side.
    while span > math.pi:
        span -= math.tau
    while span < -math.pi:
        span += math.tau

    n = max(8, min(120, int(abs(span) / math.tau * steps) + 2))
    return [(cx + r*math.cos(a1 + span*i/n), cy + r*math.sin(a1 + span*i/n)) for i in range(n+1)]

class VerticalTabButton(QPushButton):
    """Slim auto-hide tab with rotated text, readable when the right panel is collapsed."""
    def __init__(self, text="", parent=None):
        super().__init__(text, parent)
        self.setFixedWidth(38)
        self.setMinimumHeight(150)
        self.setCursor(Qt.PointingHandCursor)
        self.setToolTip(text.replace("\n", " / "))

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing)
        rect = self.rect().adjusted(3, 6, -3, -6)
        base = QColor("#E4E9F0")
        border = QColor("#88B7EE")
        hover = self.underMouse()
        if hover:
            base = QColor("#CFE0F6")
        painter.setPen(QPen(border, 1))
        painter.setBrush(QBrush(base))
        painter.drawRoundedRect(rect, 9, 9)
        painter.save()
        painter.translate(self.width()/2, self.height()/2)
        painter.rotate(-90)
        painter.setPen(QColor("#155CA8"))
        font = painter.font()
        font.setBold(True)
        font.setPointSize(9)
        painter.setFont(font)
        text = self.text().replace("\n", " / ")
        painter.drawText(QRectF(-self.height()/2 + 8, -self.width()/2, self.height()-16, self.width()), Qt.AlignCenter, text)
        painter.restore()

class PreviewView(QGraphicsView):
    def __init__(self, mainwin):
        super().__init__()
        self.mainwin = mainwin
        self.scene = QGraphicsScene(self)
        self.setScene(self.scene)
        self.setRenderHint(QPainter.Antialiasing)
        self.setBackgroundBrush(QColor(250, 253, 255))
        self.setDragMode(QGraphicsView.ScrollHandDrag)
        self.setMouseTracking(True)
        self.setFocusPolicy(Qt.StrongFocus)
        self._item_map = {}
        self._move_node_id = None
        self._move_edge_key = None
        self._move_group_nodes = set()
        self._move_start_scene = None
        self._move_start_model = None
        self._move_start_positions = {}
        self._move_undo_saved = False
        self._pending_danger_move = None
        self._slide_pipe_data = None  # V18: pipe slide constraint data
        # NEVIS perf: background JWW cache – tránh vẽ lại 30K đối tượng khi chỉ model thay đổi.
        self._bg_sig: object = None
        self._bg_items: list = []

    def wheelEvent(self, event):
        factor = 1.15 if event.angleDelta().y() > 0 else 1/1.15
        self.scale(factor, factor)

    def draw_model(self):
        m = self.mainwin.model
        bg_items = getattr(self.mainwin, "jww_background_items", []) or []
        _sig_now = (id(bg_items), len(bg_items))
        if _sig_now != self._bg_sig:
            # Background thay đổi hoặc lần đầu vẽ: xóa toàn bộ rồi rebuild.
            _nevis_runtime_timed_scene_clear(self.scene); self._item_map.clear()
            self._bg_items = []
            if not m.nodes and not bg_items:
                self._bg_sig = _sig_now
                return
            rect = m.bounds() if m.nodes else QRectF(-100, -100, 200, 200)
            bg_rect = jww_background_bounds(bg_items)
            if bg_rect is not None:
                rect = rect.united(bg_rect)
            self.scene.setSceneRect(rect)
            _before_ids = {id(it) for it in self.scene.items()}
            self._draw_jww_background()
            self._bg_items = [it for it in self.scene.items() if id(it) not in _before_ids]
            self._bg_sig = _sig_now
        else:
            # Background không đổi: chỉ xóa các item model/fitting, giữ lại JWW nền.
            _bg_ids = {id(it) for it in self._bg_items}
            for it in list(self.scene.items()):
                if id(it) not in _bg_ids:
                    self.scene.removeItem(it)
            self._item_map.clear()
            if not m.nodes:
                return
            rect = m.bounds()
            bg_rect = jww_background_bounds(bg_items)
            if bg_rect is not None:
                rect = rect.united(bg_rect)
            self.scene.setSceneRect(rect)
        if not m.nodes:
            return
        use_fire = self.mainwin.chk_fire.isChecked()
        fire_len = self.mainwin.edit_fire_len.text().strip()
        try:
            fire_len = float(fire_len)
        except Exception:
            fire_len = 0.0
        normal_mat = self.mainwin.cmb_normal_mat.currentText()
        fire_mat = self.mainwin.cmb_fire_mat.currentText()

        # draw edges with fire split according network distance
        detail_mode = bool(getattr(self.mainwin, "preview_detail_mode", False))
        for e in m.edges:
            n1,n2 = m.nodes[e.a], m.nodes[e.b]
            x1,y1 = display_point(n1.x, n1.y)
            x2,y2 = display_point(n2.x, n2.y)
            edge_mat = self.mainwin.edge_material(e)
            forced_mat = bool(getattr(e, "material_override", ""))
            frac = 0.0 if forced_mat else (self.mainwin.edge_fire_fraction_by_mouth(e, fire_len) if use_fire else 0.0)

            # Invisible wide hit area.  This makes pipe selection easy without drawing pipes thicker.
            self._add_pipe_hit_line(x1, y1, x2, y2, ("edge", e.key))

            if detail_mode:
                # Finished preview: draw the locked NEVIS pipe graphic standard.
                # Fire-protection range is split at the exact boundary so one edge can
                # show normal pipe on one side and fire pipe on the other side.
                # Centerline is included inside _draw_detailed_pipe_edge_range().
                # Do not draw an extra reference centerline here, otherwise TMP would become 8 nét.
                if forced_mat or (not use_fire):
                    self._draw_detailed_pipe_edge_range(e, edge_mat, 0.0, 1.0)
                else:
                    frac_detail = max(0.0, min(1.0, frac))
                    if frac_detail <= 0.001:
                        self._draw_detailed_pipe_edge_range(e, normal_mat, 0.0, 1.0)
                    elif frac_detail >= 0.999:
                        self._draw_detailed_pipe_edge_range(e, fire_mat, 0.0, 1.0)
                    else:
                        fire_t0, fire_t1 = self.mainwin.edge_fire_interval_by_mouth(e, fire_len)
                        if fire_t1 <= fire_t0 + 0.001:
                            self._draw_detailed_pipe_edge_range(e, normal_mat, 0.0, 1.0)
                        else:
                            if fire_t0 > 0.001:
                                self._draw_detailed_pipe_edge_range(e, normal_mat, 0.0, fire_t0)
                                if self.mainwin.should_draw_fire_boundary_cap(e, fire_t0):
                                    self._draw_fire_boundary_cap(e, fire_t0, normal_mat, fire_mat)
                            self._draw_detailed_pipe_edge_range(e, fire_mat, fire_t0, fire_t1)
                            if fire_t1 < 0.999:
                                if self.mainwin.should_draw_fire_boundary_cap(e, fire_t1):
                                    self._draw_fire_boundary_cap(e, fire_t1, normal_mat, fire_mat)
                                self._draw_detailed_pipe_edge_range(e, normal_mat, fire_t1, 1.0)
            else:
                # Centerline planning view.
                self._add_pipe_line(x1,y1,x2,y2, PIPE_COLORS.get(edge_mat, DEFAULT_DARK), 6, ("edge", e.key), cosmetic=True)
                if (not forced_mat) and use_fire and frac > 0:
                    fire_t0, fire_t1 = self.mainwin.edge_fire_interval_by_mouth(e, fire_len)
                    sx, sy = x1 + (x2 - x1) * fire_t0, y1 + (y2 - y1) * fire_t0
                    mx, my = x1 + (x2 - x1) * fire_t1, y1 + (y2 - y1) * fire_t1
                    self._add_pipe_line(sx,sy,mx,my, PIPE_COLORS.get(fire_mat, DEFAULT_DARK), 10, ("edge", e.key), cosmetic=True)
                # center line
                self._add_pipe_line(x1,y1,x2,y2, QColor(20,20,20), 2, ("edge", e.key), cosmetic=True)

            # Selected pipe highlight is drawn last but still below fittings.
            if getattr(self.mainwin, "selected_edge", None) == e.key:
                self._add_pipe_line(x1, y1, x2, y2, QColor(255, 185, 55, 180), 13, ("edge", e.key), cosmetic=True, z=14)
                self._add_pipe_line(x1, y1, x2, y2, QColor(255, 245, 120), 3, ("edge", e.key), cosmetic=True, z=15)

            # Clash highlight: red overlay when pipe key is in clash results.
            if e.key in getattr(self.mainwin, "_clash_pipe_keys", set()):
                self._add_pipe_line(x1, y1, x2, y2, QColor(220, 30, 30, 160), 14, ("edge", e.key), cosmetic=True, z=16)
                self._add_pipe_line(x1, y1, x2, y2, QColor(255, 80, 80), 3, ("edge", e.key), cosmetic=True, z=17)

        # 支持バンド / pipe support bands.  Draw after pipes and before fittings.
        if getattr(self.mainwin, "support_enabled", False) and getattr(self.mainwin, "support_visible", False):
            self._draw_support_bands()

        # In finished-detail preview, draw actual fitting TXT blocks from the library
        # before drawing the fixed-size selectable node markers.
        if detail_mode:
            self._draw_detailed_fittings()
            # NEVIS locked terminal axis marks: at branch start/end equipment and terminal fittings,
            # draw the pipe axis through the fitting center and a perpendicular axis mark.
            self._draw_terminal_axis_marks()
            # Clearance check: warn when two neighboring fittings consume the whole pipe.
            # Japanese drainage work should not leave fittings touching each other;
            # NEVIS uses 10mm as the default minimum straight pipe between sockets.
            self._draw_fitting_clearance_warnings(min_gap=10.0)

        # Ghost/live preview while placing IN.  When the IN reaches a large
        # fitting mouth, it is previewed as a generated ブッシング sleeve instead of
        # a normal IN body.
        pending = getattr(self.mainwin, "pending_reducer", None)
        if pending:
            pe = next((x for x in m.edges if x.key == str(pending.get("edge_key", ""))), None)
            if pe:
                near_info = pending.get("bushing_preview") if isinstance(pending.get("bushing_preview"), dict) else None
                if near_info:
                    self._draw_bushing_socket_preview(pe, near_info)
                else:
                    try:
                        t = float(pending.get("t", 0.5))
                    except Exception:
                        t = 0.5
                    t = max(0.02, min(0.98, t))
                    n1, n2 = m.nodes[pe.a], m.nodes[pe.b]
                    gx = n1.x + (n2.x - n1.x) * t
                    gy = n1.y + (n2.y - n1.y) * t
                    dx, dy = display_point(gx, gy)
                    rr = 15
                    ghost_pen = QPen(QColor(255, 120, 0), 3)
                    ghost_brush = QBrush(QColor(255, 235, 170, 210))
                    item = self.scene.addEllipse(-rr, -rr, rr*2, rr*2, ghost_pen, ghost_brush)
                    item.setPos(dx, dy)
                    item.setFlag(QGraphicsItem.ItemIgnoresTransformations, True)
                    item.setZValue(24)
                    txt = self.scene.addText(f"IN {pending.get('size','')}", QFont("Segoe UI", 7, QFont.Bold))
                    c = QColor(180, 80, 0); c.setAlpha(150)
                    txt.setDefaultTextColor(c)
                    txt.setPos(dx + 24, dy - 22)
                    txt.setFlag(QGraphicsItem.ItemIgnoresTransformations, True)
                    txt.setZValue(31)
                    txt.setAcceptedMouseButtons(Qt.NoButton)

        # ブッシング markers: IN absorbed into the large fitting mouth.
        # In simplified view it is a small round symbol beside the host fitting.
        for b in getattr(m, "bushings", []):
            try:
                host = int(b.get("host_node")); other = int(b.get("other_node"))
                if host not in m.nodes or other not in m.nodes:
                    continue
                nh, no = m.nodes[host], m.nodes[other]
                vx, vy = no.x - nh.x, no.y - nh.y
                ln = math.hypot(vx, vy) or 1.0
                # Place just beside the large fitting along the pipe, but keep it fixed-size on screen.
                px = nh.x + vx / ln * 28.0
                py = nh.y + vy / ln * 28.0
                dx, dy = display_point(px, py)
                selected = (getattr(self.mainwin, "selected_bushing_id", None) == int(b.get("id", -1)))
                r = 7 if selected else 5
                pen = QPen(QColor(210, 30, 20) if selected else QColor(170, 70, 20), 2.6 if selected else 1.7)
                brush = QBrush(QColor(255, 120, 95, 245) if selected else QColor(255, 205, 105, 230))
                item = self.scene.addEllipse(-r, -r, r*2, r*2, pen, brush)
                item.setPos(dx, dy)
                item.setFlag(QGraphicsItem.ItemIgnoresTransformations, True)
                item.setZValue(26 if selected else 23)
                item.setData(0, ("bushing", int(b.get("id", -1))))
                item.setAcceptHoverEvents(True)
                txt = self.scene.addText("B", QFont("Segoe UI", 5, QFont.Bold))
                txt.setDefaultTextColor(QColor(135, 55, 15))
                txt.setParentItem(item)
                txt.setPos(-3.2, -5.5)
                txt.setAcceptedMouseButtons(Qt.NoButton)
            except Exception:
                continue

        for nid,n in m.nodes.items():
            fit = m.fittings.get(nid)
            if not fit:
                continue
            is_base = (nid == m.base_node) or (nid in getattr(m, "base_nodes", set()))
            ftype = fit.ftype
            # Visual marker kept small for large drawings.  Selection still uses the item,
            # but the symbol no longer hides dense pipe networks.
            r = 10 if is_base else 6
            fill, border = self._node_colors(ftype, is_base)
            pen = QPen(border, 2 if is_base else 1.8)

            # Marker size is fixed on screen: it does not shrink when the drawing is fit/zoomed.
            item = self.scene.addEllipse(-r, -r, r*2, r*2, pen, QBrush(fill))
            dx, dy = display_point(n.x, n.y)
            item.setPos(dx, dy)
            item.setFlag(QGraphicsItem.ItemIgnoresTransformations, True)
            item.setZValue(20)
            item.setData(0, ("node", nid))
            item.setAcceptHoverEvents(True)
            self._item_map[item] = ("node", nid)

            if is_base:
                outer = self.scene.addEllipse(-(r+4), -(r+4), (r+4)*2, (r+4)*2, QPen(QColor(190,90,20), 1.5), QBrush(Qt.NoBrush))
                outer.setPos(dx, dy)
                outer.setFlag(QGraphicsItem.ItemIgnoresTransformations, True)
                outer.setZValue(19)
                outer.setData(0, ("node", nid))
                outer.setAcceptHoverEvents(True)

            label = self.mainwin.make_fitting_label(nid)
            # Fitting labels are visual only.  Put them diagonally away from the
            # marker (about 2.5 o'clock) so horizontal pipes do not hide them.
            # The label is parented to the fixed-size marker, so the offset stays
            # visually stable while zooming/panning.
            # NEVIS 2.02 V90: fitting labels must stay readable above the pipe.
            # - Font is ~1.2x larger than the old 6pt.
            # - Label is lifted farther from the pipe centerline.
            # - A small white halo is drawn behind the text so blue/red pipe lines
            #   or JWW background lines do not hide the fitting name.
            label_font = QFont("Segoe UI", 7, QFont.Bold)
            label_dx = 24 if is_base else 18
            label_dy = -28 if is_base else -22

            halo_color = QColor(255, 255, 255, 235)
            halo_offsets = [(-1, 0), (1, 0), (0, -1), (0, 1)]
            for ox, oy in halo_offsets:
                halo = self.scene.addText(label, label_font)
                halo.setDefaultTextColor(halo_color)
                halo.setParentItem(item)
                halo.setPos(label_dx + ox, label_dy + oy)
                halo.setZValue(9)
                halo.setAcceptedMouseButtons(Qt.NoButton)
                halo.setAcceptHoverEvents(False)

            txt = self.scene.addText(label, label_font)
            soft = QColor(border)
            soft.setAlpha(225)
            txt.setDefaultTextColor(soft)
            txt.setParentItem(item)
            txt.setPos(label_dx, label_dy)
            txt.setZValue(10)
            txt.setAcceptedMouseButtons(Qt.NoButton)
            txt.setAcceptHoverEvents(False)
            # Text labels are for reading only. Do not make them clickable,
            # otherwise pipe/fitting selection becomes noisy around crowded labels.

        elevation_dialog = getattr(self.mainwin, "elevation_preview_dialog", None)
        if elevation_dialog is not None and elevation_dialog.isVisible():
            elevation_dialog.refresh_highlight_after_canvas_redraw()

    def _draw_fitting_clearance_warnings(self, min_gap: float = 10.0):
        """Show warning marks when the straight pipe between two fittings is too short.

        Rule:
            edge length - trim_from_fitting_A - trim_from_fitting_B >= min_gap

        trim_from_fitting_* is already calculated from JSON port/cut_point when
        JSON exists, so this check follows the standardized library database.
        The warning is visual only; it does not block JWW output.
        """
        m = self.mainwin.model
        if not m.nodes:
            return
        issues = []
        for e in m.edges:
            if e.a not in m.nodes or e.b not in m.nodes:
                continue
            # Only judge when both ends are actual fittings.  A raw pipe endpoint
            # without a fitting should not trigger this warning.
            fa = m.fittings.get(e.a)
            fb = m.fittings.get(e.b)
            if not fa or not fb or fa.excluded or fb.excluded:
                continue
            length = m.edge_length(e)
            if length <= EPS:
                continue
            mat = self.mainwin.edge_material(e)
            try:
                trim_a = max(0.0, float(self.mainwin.ruby_trim_for_fitting_side(e.a, e.b, e.size, mat)))
                trim_b = max(0.0, float(self.mainwin.ruby_trim_for_fitting_side(e.b, e.a, e.size, mat)))
            except Exception:
                continue
            clear_len = length - trim_a - trim_b
            if clear_len + 1e-6 < min_gap:
                n1, n2 = m.nodes[e.a], m.nodes[e.b]
                # Put the mark near the middle of the problematic remaining straight run.
                # If the trim values overlap, the edge midpoint is the safest visual position.
                t1 = min(0.49, trim_a / length)
                t2 = max(0.51, 1.0 - trim_b / length)
                tm = 0.5 if t2 <= t1 else (t1 + t2) / 2.0
                wx = n1.x + (n2.x - n1.x) * tm
                wy = n1.y + (n2.y - n1.y) * tm
                issues.append((wx, wy, clear_len, length, trim_a, trim_b, e.key))

        if issues:
            try:
                self.mainwin.clearance_issue_count = len(issues)
            except Exception:
                pass
        else:
            try:
                self.mainwin.clearance_issue_count = 0
            except Exception:
                pass

        for wx, wy, clear_len, length, trim_a, trim_b, key in issues:
            x, y = display_point(wx, wy)

            # Soft red halo to make collision area visible without hiding geometry.
            halo_pen = QPen(QColor(230, 40, 40, 190), 2)
            halo_pen.setCosmetic(True)
            halo = self.scene.addEllipse(-20, -20, 40, 40, halo_pen, QBrush(QColor(255, 90, 90, 45)))
            halo.setPos(x, y)
            halo.setFlag(QGraphicsItem.ItemIgnoresTransformations, True)
            halo.setZValue(60)
            halo.setData(0, ("edge", key))

            # Yellow warning triangle with red exclamation mark.
            tri_pen = QPen(QColor(210, 60, 20), 1.4)
            tri_pen.setCosmetic(True)
            tri = self.scene.addPolygon(
                QPolygonF([QPointF(0, -16), QPointF(15, 12), QPointF(-15, 12)]),
                tri_pen,
                QBrush(QColor(255, 225, 80, 235))
            )
            tri.setPos(x + 26, y - 22)
            tri.setFlag(QGraphicsItem.ItemIgnoresTransformations, True)
            tri.setZValue(70)
            tri.setData(0, ("edge", key))

            mark = self.scene.addText("!", QFont("Segoe UI", 13, QFont.Bold))
            mark.setDefaultTextColor(QColor(190, 30, 20))
            mark.setPos(x + 21, y - 40)
            mark.setFlag(QGraphicsItem.ItemIgnoresTransformations, True)
            mark.setAcceptedMouseButtons(Qt.NoButton)
            mark.setZValue(71)

            msg = f"隙間不足 / Khe hở thiếu: {clear_len:.1f}mm < 10mm"
            txt = self.scene.addText(msg, QFont("Segoe UI", 7, QFont.Bold))
            txt.setDefaultTextColor(QColor(190, 35, 20))
            txt.setPos(x + 44, y - 24)
            txt.setFlag(QGraphicsItem.ItemIgnoresTransformations, True)
            txt.setAcceptedMouseButtons(Qt.NoButton)
            txt.setZValue(71)

    def _draw_bushing_socket_preview(self, e: Edge, info: Dict[str, object]):
        """Live preview when a pending IN reaches the large fitting mouth.

        No separate bushing library is required: the symbol is generated from the
        host fitting socket.  It shows a short small-size pipe sleeved into the
        large fitting mouth, matching the requested geometry concept.
        """
        try:
            m = self.mainwin.model
            host = int(info.get("host")); other = int(info.get("other"))
            if host not in m.nodes or other not in m.nodes:
                return
            nh, no = m.nodes[host], m.nodes[other]
            vx, vy = no.x - nh.x, no.y - nh.y
            ln = math.hypot(vx, vy)
            if ln <= EPS:
                return
            ux, uy = vx / ln, vy / ln
            nx, ny = -uy, ux
            size = str(info.get("size", ""))
            nums = re.findall(r"\d+", size)
            big = nums[0] if nums else str(e.size or "")
            small = nums[1] if len(nums) >= 2 else self.mainwin.dynamic_lower_pipe_size(big)
            mat = self.mainwin.edge_material(e)
            big_d = self.mainwin.pipe_outer_diameter(mat, big) if big else 80.0
            small_d = self.mainwin.pipe_outer_diameter(mat, small) if small else max(20.0, big_d * 0.72)
            sleeve_len = max(55.0, min(max(big_d * 1.15, small_d * 1.55), max(65.0, ln * 0.42)))
            inset = min(14.0, sleeve_len * 0.20)
            start = (nh.x + ux * inset, nh.y + uy * inset)
            end = (nh.x + ux * sleeve_len, nh.y + uy * sleeve_len)
            half = small_d / 2.0

            # yellow halo around the large socket so the user notices the live candidate
            hx, hy = display_point(nh.x + ux * 22.0, nh.y + uy * 22.0)
            halo_pen = QPen(QColor(245, 170, 0, 210), 1.5)
            halo_pen.setCosmetic(True)
            halo_pen.setStyle(Qt.DashLine)
            halo = self.scene.addEllipse(-24, -24, 48, 48, halo_pen, QBrush(QColor(255, 230, 90, 45)))
            halo.setPos(hx, hy)
            halo.setFlag(QGraphicsItem.ItemIgnoresTransformations, True)
            halo.setZValue(52)

            pen = QPen(QColor(0, 0, 255), 1.6)
            pen.setCosmetic(True)
            dash_pen = QPen(QColor(0, 0, 255, 180), 1.0)
            dash_pen.setCosmetic(True)
            dash_pen.setStyle(Qt.DotLine)
            for sign in (1, -1):
                p1 = display_point(start[0] + nx * half * sign, start[1] + ny * half * sign)
                p2 = display_point(end[0] + nx * half * sign, end[1] + ny * half * sign)
                line = self.scene.addLine(p1[0], p1[1], p2[0], p2[1], pen)
                line.setZValue(54)
                line.setData(0, ("edge", e.key))

            # two cross-mouth lines make the small pipe look nested inside the large socket
            for base_pt, z, qpen in ((start, 55, dash_pen), (end, 55, pen)):
                p1 = display_point(base_pt[0] + nx * half, base_pt[1] + ny * half)
                p2 = display_point(base_pt[0] - nx * half, base_pt[1] - ny * half)
                line = self.scene.addLine(p1[0], p1[1], p2[0], p2[1], qpen)
                line.setZValue(z)
                line.setData(0, ("edge", e.key))

            # centerline of the new small pipe right from the socket
            c1 = display_point(nh.x, nh.y)
            c2 = display_point(end[0], end[1])
            cpen = nevis_make_centerline_pen(QColor(70, 70, 70, 185), 1.0)
            cl = self.scene.addLine(c1[0], c1[1], c2[0], c2[1], cpen)
            cl.setZValue(53)

            # round bushing marker at the mouth
            r = 6
            mp = display_point(nh.x + ux * 24.0, nh.y + uy * 24.0)
            mark = self.scene.addEllipse(-r, -r, r*2, r*2, QPen(QColor(20, 20, 20), 1.7), QBrush(QColor(255, 255, 255, 245)))
            mark.setPos(mp[0], mp[1])
            mark.setFlag(QGraphicsItem.ItemIgnoresTransformations, True)
            mark.setZValue(60)
            mark.setData(0, ("node", host))

            txt = self.scene.addText(f"{big}x{small}_ブッシング\n(preview)", QFont("Segoe UI", 7, QFont.Bold))
            txt.setDefaultTextColor(QColor(220, 30, 30))
            tx, ty = display_point(nh.x + ux * (sleeve_len + 22.0) + nx * 18.0, nh.y + uy * (sleeve_len + 22.0) + ny * 18.0)
            txt.setPos(tx, ty)
            txt.setFlag(QGraphicsItem.ItemIgnoresTransformations, True)
            txt.setAcceptedMouseButtons(Qt.NoButton)
            txt.setZValue(61)
        except Exception:
            return

    def _draw_detailed_pipe_edge(self, e: Edge, mat: str):
        # Backward-compatible wrapper.  New code should call
        # _draw_detailed_pipe_edge_range() so fire-protection split can be shown exactly.
        self._draw_detailed_pipe_edge_range(e, mat, 0.0, 1.0)

    def _draw_detailed_pipe_edge_range(self, e: Edge, mat: str, t0: float = 0.0, t1: float = 1.0):
        """Draw pipe body range using the LOCKED NEVIS pipe graphic standard.

        LOCKED 2026-06:
        - VP/DV/HTVP/VU/耐火VP: 5 nét = 2 solid outer lines + 2 inner dashed lines + 1 short-long centerline.
        - TMP/トミジ: 7 nét = 4 solid wall lines + 2 inner dashed lines + 1 short-long centerline.

        Fire-protection split rule locked:
        - when one pipe edge crosses the fire boundary, draw two real pipe ranges
          with their own material families; do not color the whole pipe as one type.
        - boundary is drawn by _draw_fire_boundary_cap() at the exact split point.

        This function is intentionally shared in concept with JWW export helpers
        append_vp_pipe_segment() / append_tmp_pipe_segment().  Do not change one
        side without changing the other.
        """
        if t1 - t0 <= 0.001:
            return
        m = self.mainwin.model
        if e.a not in m.nodes or e.b not in m.nodes:
            return
        n1, n2 = m.nodes[e.a], m.nodes[e.b]
        x1, y1, x2, y2 = n1.x, n1.y, n2.x, n2.y
        length = math.hypot(x2-x1, y2-y1)
        if length <= EPS:
            return

        trim_a = self.mainwin.ruby_trim_for_fitting_side(e.a, e.b, e.size, mat) / length
        trim_b = self.mainwin.ruby_trim_for_fitting_side(e.b, e.a, e.size, mat) / length
        ta = max(t0, min(0.49, trim_a))
        tb = min(t1, 1.0 - min(0.49, trim_b))
        if tb - ta <= 0.001:
            # V6 clean detail rule:
            # When fitting trims consume the whole edge, this edge is inside fitting bodies.
            # Do NOT draw a short fallback pipe stub in the middle of a fitting.
            return

        ax, ay = x1 + (x2-x1)*ta, y1 + (y2-y1)*ta
        bx, by = x1 + (x2-x1)*tb, y1 + (y2-y1)*tb
        dx, dy = bx-ax, by-ay
        ll = math.hypot(dx, dy) or 1.0
        nx, ny = -dy/ll, dx/ll

        fam = self.mainwin.pipe_geometry_family(mat)
        base = re.findall(r"\d+", str(e.size or ""))
        base = base[0] if base else "65"
        blue = QColor(0, 0, 255)

        def add_offset_line(offset: float, style, width: float, z: float):
            if style == NEVIS_PREVIEW_CENTERLINE_STYLE:
                pen = nevis_make_centerline_pen(blue, width)
            else:
                pen = QPen(blue, width)
                pen.setCosmetic(True)
                pen.setStyle(style)
            if abs(offset) <= 1e-9:
                p1 = display_point(ax, ay)
                p2 = display_point(bx, by)
                item = self.scene.addLine(p1[0], p1[1], p2[0], p2[1], pen)
                item.setZValue(z)
                item.setData(0, ("edge", e.key))
                item.setAcceptHoverEvents(True)
                return
            for sign in (1, -1):
                h = offset * sign
                p1 = display_point(ax + nx*h, ay + ny*h)
                p2 = display_point(bx + nx*h, by + ny*h)
                item = self.scene.addLine(p1[0], p1[1], p2[0], p2[1], pen)
                item.setZValue(z)
                item.setData(0, ("edge", e.key))
                item.setAcceptHoverEvents(True)

        if fam == "TMP":
            # Half-widths from TMP/DV/core pipe geometry tables.
            tmp_h  = {"30":21.85,"40":27.6,"50":34.5,"65":43.7,"75":51.1,"100":65.5,"125":80.5,"150":94.8,"200":108.0}
            dv_h   = {"30":19.0, "40":24.0,"50":30.0,"65":38.0,"75":44.5,"100":57.0,"125":70.0,"150":82.5,"200":94.0}
            core_h = {"30":16.8, "40":21.1,"50":26.3,"65":33.3,"75":39.0,"100":50.0,"125":61.4,"150":72.4,"200":82.0}

            # 7 nét locked:
            #   outer solid pair + inner solid pair + inner dashed pair + center dash-dot.
            add_offset_line(tmp_h.get(base, self.mainwin.pipe_outer_diameter(mat, base)/2.0),
                            Qt.SolidLine, 1.15, 6.35)
            add_offset_line(dv_h.get(base, self.mainwin.pipe_outer_diameter("DV", base)/2.0),
                            Qt.SolidLine, 1.00, 6.34)
            add_offset_line(core_h.get(base, max(1.0, self.mainwin.pipe_outer_diameter("DV", base)*0.44)),
                            NEVIS_PREVIEW_INNER_DASH_STYLE, 0.90, 6.33)
            add_offset_line(0.0, NEVIS_PREVIEW_CENTERLINE_STYLE, 0.85, 6.32)
        else:
            # 5 nét locked for DV/VP/HTVP/TaikaVP:
            #   outer solid pair + inner dashed pair + center dash-dot.
            # Inner dashed position MUST match TMP core dashed position, not a
            # separate proportional value. This keeps the visual section consistent
            # when normal pipe changes to fire-protection pipe.
            h = self.mainwin.pipe_outer_diameter(mat, base) / 2.0
            core_h = {"30":16.8, "40":21.1,"50":26.3,"65":33.3,"75":39.0,"100":50.0,"125":61.4,"150":72.4,"200":82.0}
            inner_h = min(max(1.0, core_h.get(base, max(1.0, self.mainwin.pipe_outer_diameter("DV", base) * 0.44))), max(1.0, h - 1.0))
            add_offset_line(h, Qt.SolidLine, 1.15, 6.30)
            add_offset_line(inner_h, NEVIS_PREVIEW_INNER_DASH_STYLE, 0.90, 6.295)
            add_offset_line(0.0, NEVIS_PREVIEW_CENTERLINE_STYLE, 0.85, 6.29)

    def _draw_fire_boundary_cap(self, e: Edge, t: float, normal_mat: str, fire_mat: str):
        """Draw one clear transverse cut line at the fire/normal boundary.

        Rule: the cap length equals pipe outside diameter and uses the material
        color of the fire-protection side. TaikaVP/耐火VP is green. The cap is
        suppressed when the boundary is already at a real fitting center.
        """
        try:
            if t <= 0.001 or t >= 0.999:
                return
            m = self.mainwin.model
            if e.a not in m.nodes or e.b not in m.nodes:
                return
            n1, n2 = m.nodes[e.a], m.nodes[e.b]
            dx, dy = n2.x - n1.x, n2.y - n1.y
            ln = math.hypot(dx, dy)
            if ln <= EPS:
                return
            x = n1.x + dx * t
            y = n1.y + dy * t
            nx, ny = -dy / ln, dx / ln
            dia = self.mainwin.pipe_outer_diameter(fire_mat, e.size)
            h = dia / 2.0
            p1 = display_point(x + nx * h, y + ny * h)
            p2 = display_point(x - nx * h, y - ny * h)
            cap_color = PIPE_COLORS.get(str(fire_mat), PIPE_COLORS.get(self.mainwin.pipe_geometry_family(fire_mat), QColor(0, 0, 255)))
            pen = QPen(cap_color, 1.25)
            pen.setCosmetic(True)
            pen.setStyle(Qt.SolidLine)
            item = self.scene.addLine(p1[0], p1[1], p2[0], p2[1], pen)
            item.setZValue(7.8)
            item.setData(0, ("edge", e.key))
        except Exception:
            return

    def _transform_local_point_for_preview(self, x, y, cx, cy, ang, fx, fy):
        ca, sa = math.cos(ang), math.sin(ang)
        wx, wy = self.mainwin.transform_fitting_point(x, y, cx, cy, ca, sa, fx, fy)
        return display_point(wx, wy)

    def _fitting_centerline_overlaps_pipe_preview(self, nid: int, x1: float, y1: float, x2: float, y2: float) -> bool:
        """Skip fitting centerline only where an actual pipe centerline is already drawn.

        Important: do NOT compare with the full graph edge from node-to-node.
        Detail pipes are trimmed back from fittings, so the pipe centerline is drawn
        only on the remaining straight pipe body.  If we skip a fitting centerline
        merely because it lies on the original full graph edge, some sockets/elbows
        lose their centerline completely.

        Rule locked:
        - if the fitting centerline segment is fully covered by the already-drawn
          trimmed pipe centerline -> skip it to avoid double centerlines;
        - otherwise keep the fitting centerline so every fitting still has a visible
          centerline where the pipe body has been trimmed away.
        """
        try:
            m = self.mainwin.model
            if nid not in m.nodes or math.hypot(x2-x1, y2-y1) <= 1e-6:
                return False
            host = m.nodes[nid]
            for nb in m.neighbors(nid):
                if nb not in m.nodes:
                    continue
                e = edge_obj(m, nid, nb)
                if e is None:
                    continue
                other = m.nodes[nb]
                full_len = math.hypot(other.x - host.x, other.y - host.y)
                if full_len <= 1e-6:
                    continue

                mat = self.mainwin.edge_material(e)
                trim_host = self.mainwin.ruby_trim_for_fitting_side(nid, nb, e.size, mat)
                trim_other = self.mainwin.ruby_trim_for_fitting_side(nb, nid, e.size, mat)
                ta = max(0.0, min(0.49, trim_host / full_len))
                tb = min(1.0, max(0.51, 1.0 - trim_other / full_len))
                if tb - ta <= 0.001:
                    continue

                ax = host.x + (other.x - host.x) * ta
                ay = host.y + (other.y - host.y) * ta
                bx = host.x + (other.x - host.x) * tb
                by = host.y + (other.y - host.y) * tb
                a = display_point(ax, ay)
                b = display_point(bx, by)
                d1, t1, _, _ = dist_point_to_segment(x1, y1, a[0], a[1], b[0], b[1])
                d2, t2, _, _ = dist_point_to_segment(x2, y2, a[0], a[1], b[0], b[1])
                if d1 <= 2.0 and d2 <= 2.0 and max(t1, t2) - min(t1, t2) > 0.01:
                    return True
        except Exception:
            return False
        return False


    def _terminal_axis_mark_info(self, nid: int):
        """Return centerline mark geometry for branch start/end terminal nodes.

        NEVIS LOCKED CENTERLINE STANDARD 2026-06:
        - Apply only to terminal nodes (degree 1): branch start/end device, DL/LL terminal,
          one-port collection symbol, and similar endpoint fittings.
        - Draw one axis line through the fitting/device center along the pipe direction.
          From the center to each end is 1D, which means it passes the assumed outside
          radius (0.5D) by another 0.5D.
        - Draw a perpendicular axis line at the fitting/device center; total length = 2D.
        - D is the nominal/outer pipe diameter used by NEVIS for that connected pipe.

        Do not remove or simplify this when editing fitting preview/export; it keeps
        pipe centerlines continuous without double-drawing fitting centerlines on pipe bodies.
        """
        try:
            m = self.mainwin.model
            if nid not in m.nodes or m.degree(nid) != 1:
                return None
            ns = m.neighbors(nid)
            if not ns:
                return None
            nb = ns[0]
            if nb not in m.nodes:
                return None
            e = edge_obj(m, nid, nb)
            if e is None:
                return None
            n = m.nodes[nid]
            other = m.nodes[nb]
            dx, dy = other.x - n.x, other.y - n.y
            ln = math.hypot(dx, dy)
            if ln <= EPS:
                return None
            ux, uy = dx / ln, dy / ln
            nx, ny = -uy, ux
            mat = self.mainwin.edge_material(e)
            nums = re.findall(r"\d+", str(e.size or ""))
            size = nums[0] if nums else str(e.size or "65")
            try:
                D = float(self.mainwin.pipe_outer_diameter(mat, size))
            except Exception:
                try:
                    D = float(size)
                except Exception:
                    D = 65.0
            D = max(20.0, D)
            return n.x, n.y, ux, uy, nx, ny, D, e.key
        except Exception:
            return None

    def _draw_terminal_axis_marks(self):
        """Draw endpoint fitting/device center marks in preview.

        This adds the short-long centerline axes for terminal nodes after library
        fittings are drawn, so device centers remain readable and all endpoints
        have a proper centerline even where pipe bodies were trimmed.
        """
        m = self.mainwin.model
        pen = nevis_make_centerline_pen(QColor(0, 0, 255), 0.9)
        for nid, fit in m.fittings.items():
            if getattr(fit, "excluded", False):
                continue
            info = self._terminal_axis_mark_info(nid)
            if not info:
                continue
            x, y, ux, uy, nx, ny, D, ekey = info
            # Axis along pipe direction: center -> assumed outside radius 0.5D + extra 0.5D = 1D each side.
            for ax1, ay1, ax2, ay2 in (
                (x - ux * D, y - uy * D, x + ux * D, y + uy * D),
                (x - nx * D, y - ny * D, x + nx * D, y + ny * D),
            ):
                p1 = display_point(ax1, ay1)
                p2 = display_point(ax2, ay2)
                item = self.scene.addLine(p1[0], p1[1], p2[0], p2[1], pen)
                item.setZValue(19)
                item.setData(0, ("node", nid))

    def _draw_detailed_fittings(self):
        _perf_enabled = nevis_perf_enabled()
        _perf_iter_ms = 0.0
        _perf_match_ms = 0.0
        _perf_parse_ms = 0.0
        _perf_transform_ms = 0.0
        _perf_add_ms = 0.0
        _perf_count = 0
        _perf_item_count = 0
        _perf_missing_count = 0

        def _perf_start():
            return time.perf_counter() if _perf_enabled else 0.0

        def _perf_elapsed_ms(start):
            return (time.perf_counter() - start) * 1000.0 if _perf_enabled else 0.0

        from PySide6.QtGui import QPainterPath

        m = self.mainwin.model
        pen = QPen(QColor(0, 0, 255), 1.1)
        pen.setCosmetic(True)
        missing = []
        try:
            for nid, fit in m.fittings.items():
                _t = _perf_start()
                try:
                    if fit.excluded or nid not in m.nodes:
                        continue
                    n = m.nodes[nid]
                    _perf_count += 1
                finally:
                    _perf_iter_ms += _perf_elapsed_ms(_t)
                _t = _perf_start()
                path = self.mainwin.resolve_fitting_library_path_for_jww(nid, fit)
                _perf_match_ms += _perf_elapsed_ms(_t)
                if not path or not Path(path).exists():
                    missing.append(f"{nid}:{fit.ftype}{fit.size}")
                    _perf_missing_count += 1
                    continue
                try:
                    _t = _perf_start()
                    ents = parse_jww_library_geometry(path)
                    _perf_parse_ms += _perf_elapsed_ms(_t)
                except Exception:
                    _perf_parse_ms += _perf_elapsed_ms(_t)
                    missing.append(f"{nid}:{Path(path).name}")
                    _perf_missing_count += 1
                    continue
                _t = _perf_start()
                ftype_norm = self.mainwin.normalize_lib_type(getattr(fit, "ftype", ""))
                is_json_lib = Path(path).suffix.lower() == ".json"
                # JSON libraries are already normalized by the editor.  TXT legacy
                # correction flags are never applied to JSON preview geometry.
                self.mainwin._active_fitting_axis_right = (False if is_json_lib else (
                    is_axis_right_library_name(path)
                    or ftype_norm in ["集合管", "S", "SV"]
                ))
                self.mainwin._active_fitting_skip_y_invert = (True if is_json_lib else (
                    ftype_norm in ["Y", "LT", "DT", "T", "IN", "HTVP"]
                    or is_ahk_raw_transform_library_name(path)
                ))
                # parse_jww_library_geometry() already expands terminal JSON U/D to
                # true size, so do not scale again in preview transform.
                self.mainwin._active_fitting_local_scale = 1.0
                ang, fx, fy = self.mainwin.fitting_transform(nid, fit)
                expected = self.mainwin.fitting_expected_mouth_count(nid, fit)
                # v30 SmartMatcher: use the exact anchor chosen during fitting_transform.
                # Do not recalculate here, because Y/45 use mouth-intersection anchor
                # while 集合管/S/SV usually use the TXT origin as the collection point.
                anchors = getattr(self.mainwin, "_last_fit_anchor_by_node", {})
                self.mainwin._active_fitting_anchor = anchors.get(nid, self.mainwin.fitting_local_anchor(path, expected=expected))
                _perf_transform_ms += _perf_elapsed_ms(_t)
                _t = _perf_start()
                normal_path = QPainterPath()
                center_path = QPainterPath()
                for ent in ents[:2500]:
                    typ = ent.get("type")
                    if typ == "line":
                        x1, y1 = self._transform_local_point_for_preview(ent["x1"], ent["y1"], n.x, n.y, ang, fx, fy)
                        x2, y2 = self._transform_local_point_for_preview(ent["x2"], ent["y2"], n.x, n.y, ang, fx, fy)
                        is_center = nevis_is_centerline_lt(ent.get("lt"))
                        if is_center and self._fitting_centerline_overlaps_pipe_preview(nid, x1, y1, x2, y2):
                            continue
                        path_obj = center_path if is_center else normal_path
                        path_obj.moveTo(x1, y1)
                        path_obj.lineTo(x2, y2)
                    elif typ == "circle":
                        cx, cy = self._transform_local_point_for_preview(ent["cx"], ent["cy"], n.x, n.y, ang, fx, fy)
                        r = float(ent["r"])
                        item = self.scene.addEllipse(cx-r, cy-r, r*2, r*2, pen)
                        item.setZValue(18)
                        item.setData(0, ("node", nid))
                        _perf_item_count += 1
                    elif typ == "arc":
                        pts = arc_points(ent["cx"], ent["cy"], ent["r"], ent["a1"], ent["a2"], ent.get("rot", 0.0))
                        pts2 = [self._transform_local_point_for_preview(x, y, n.x, n.y, ang, fx, fy) for x, y in pts]
                        path_obj = center_path if nevis_is_centerline_lt(ent.get("lt")) else normal_path
                        for (x1,y1),(x2,y2) in zip(pts2, pts2[1:]):
                            path_obj.moveTo(x1, y1)
                            path_obj.lineTo(x2, y2)
                if not normal_path.isEmpty():
                    item = self.scene.addPath(normal_path, pen)
                    item.setZValue(18)
                    item.setData(0, ("node", nid))
                    _perf_item_count += 1
                if not center_path.isEmpty():
                    item = self.scene.addPath(center_path, nevis_make_centerline_pen(QColor(0, 0, 255), 0.9))
                    item.setZValue(18)
                    item.setData(0, ("node", nid))
                    _perf_item_count += 1
                _perf_add_ms += _perf_elapsed_ms(_t)
                self.mainwin._active_fitting_axis_right = False
        finally:
            if _perf_enabled:
                prefix = "PreviewView._draw_detailed_fittings"
                nevis_perf_log(f"{prefix}.iterate_fitting_node count={_perf_count}", _perf_iter_ms)
                nevis_perf_log(f"{prefix}.matching_library_path missing={_perf_missing_count}", _perf_match_ms)
                nevis_perf_log(f"{prefix}.parse_geometry", _perf_parse_ms)
                nevis_perf_log(f"{prefix}.transform_geometry", _perf_transform_ms)
                nevis_perf_log(f"{prefix}.add_scene_items count={_perf_item_count}", _perf_add_ms)
        # Debug file writing on every preview refresh made the UI feel frozen on
        # Windows/OneDrive/network folders.  Enable only when needed:
        #   set NEVIS_DEBUG_PREVIEW=1
        if os.environ.get("NEVIS_DEBUG_PREVIEW") == "1":
            try:
                Path("nevis_preview_fitting_debug.txt").write_text("missing=" + ", ".join(missing), encoding="utf-8")
                Path("nevis_preview_orient_debug.txt").write_text("\n".join(getattr(self.mainwin, "_orient_debug", [])), encoding="utf-8")
            except Exception:
                pass

    def _draw_support_bands(self):
        """Draw orange support bands perpendicular to pipe centerlines.

        This is visual-only for now: one band at every fitting/node, plus
        intermediate bands so that the interval never exceeds the user setting.
        """
        entries = self.mainwin.compute_support_bands()
        pen = QPen(QColor(235, 135, 35), 4)
        pen.setCosmetic(True)
        for ent in entries:
            x, y = display_point(ent["x"], ent["y"])
            nx, ny = ent.get("nx", 0.0), ent.get("ny", 1.0)
            # Preview flip changes the drawing coordinate handedness; apply same display transform to direction.
            x2d, y2d = display_point(ent["x"] + nx, ent["y"] + ny)
            vx, vy = x2d - x, y2d - y
            l = math.hypot(vx, vy) or 1.0
            vx, vy = vx / l, vy / l
            half = float(ent.get("half", 45.0))
            item = self.scene.addLine(x - vx*half, y - vy*half, x + vx*half, y + vy*half, pen)
            item.setZValue(16)
            item.setAcceptedMouseButtons(Qt.NoButton)

    def _node_colors(self, ftype: str, is_base: bool):
        if is_base or ftype == "集合管":
            return QColor(255, 220, 95), QColor(180, 85, 0)
        if ftype in ("Y", "LT", "DT", "T"):
            return QColor(205, 232, 255), QColor(0, 95, 180)
        if ftype in ("SV", "S"):
            return QColor(225, 210, 255), QColor(105, 55, 180)
        if ftype in ("LL", "DL"):
            return QColor(215, 255, 220), QColor(20, 135, 50)
        if ftype == "45°":
            return QColor(255, 225, 210), QColor(210, 85, 35)
        if ftype == "IN":
            return QColor(230, 230, 230), QColor(80, 80, 80)
        if ftype == "脚部":
            return QColor(255, 240, 200), QColor(150, 105, 20)
        return QColor(238, 238, 238), QColor(70, 70, 70)

    def _draw_jww_background(self):
        """Draw all selected JWW background objects, below NEVIS pipes."""
        ents = getattr(self.mainwin, "jww_background_items", []) or []
        if not ents:
            return
        base_pen = QPen(QColor(0, 185, 190, 150), 1.0)
        base_pen.setCosmetic(True)
        dash_pen = QPen(QColor(0, 140, 170, 130), 1.0)
        dash_pen.setCosmetic(True)
        dash_pen.setStyle(Qt.DashLine)
        center_pen = QPen(QColor(40, 70, 210, 110), 1.0)
        center_pen.setCosmetic(True)
        center_pen.setStyle(Qt.DashLine)
        for ent in ents[:30000]:
            try:
                typ = ent.get("type")
                lt = str(ent.get("lt", "")).strip().lower().replace("lt", "")
                lc = str(ent.get("lc", "")).strip().lower()
                pen = center_pen if lc in {"6", "2"} and lt in {"5", "1", "6", "49"} else (dash_pen if lt not in {"", "1"} else base_pen)
                if typ == "line":
                    x1, y1 = display_point(float(ent.get("x1", 0.0)), float(ent.get("y1", 0.0)))
                    x2, y2 = display_point(float(ent.get("x2", 0.0)), float(ent.get("y2", 0.0)))
                    item = self.scene.addLine(x1, y1, x2, y2, pen)
                    item.setZValue(-100); item.setAcceptedMouseButtons(Qt.NoButton)
                elif typ == "circle":
                    cx, cy = display_point(float(ent.get("cx", 0.0)), float(ent.get("cy", 0.0)))
                    r = abs(float(ent.get("r", 0.0)))
                    item = self.scene.addEllipse(cx-r, cy-r, r*2, r*2, pen)
                    item.setZValue(-100); item.setAcceptedMouseButtons(Qt.NoButton)
                elif typ == "arc":
                    pts = arc_points(float(ent.get("cx", 0.0)), float(ent.get("cy", 0.0)), abs(float(ent.get("r", 0.0))),
                                     float(ent.get("a1", 0.0)), float(ent.get("a2", 0.0)), float(ent.get("rot", 0.0)))
                    pts2 = [display_point(x, y) for x, y in pts]
                    for (x1, y1), (x2, y2) in zip(pts2, pts2[1:]):
                        item = self.scene.addLine(x1, y1, x2, y2, pen)
                        item.setZValue(-100); item.setAcceptedMouseButtons(Qt.NoButton)
            except Exception:
                continue

    def _add_pipe_line(self, x1,y1,x2,y2,color,width,data,cosmetic=True,z=5):
        pen = QPen(color, width)
        # Keep pipe strokes visible after fit/zoom. Geometry scale stays real, line thickness stays readable.
        pen.setCosmetic(cosmetic)
        item = self.scene.addLine(x1,y1,x2,y2,pen)
        item.setZValue(z)
        item.setData(0, data)
        item.setAcceptHoverEvents(True)
        return item

    def _add_pipe_hit_line(self, x1, y1, x2, y2, data):
        """Wide invisible clickable line for pipe selection.

        The visible pipe remains thin, but the hit area is much wider so it feels
        closer to CAD object selection.
        """
        pen = QPen(QColor(0, 0, 0, 1), 22)
        pen.setCosmetic(True)
        item = self.scene.addLine(x1, y1, x2, y2, pen)
        item.setZValue(13)
        item.setData(0, data)
        item.setAcceptHoverEvents(True)
        return item

    def _move_pending_reducer_from_view_pos(self, pos) -> bool:
        """Move pending IN to the closest point on its selected pipe."""
        data = getattr(self.mainwin, "pending_reducer", None)
        if not data:
            return False
        key = str(data.get("edge_key", ""))
        e = next((x for x in self.mainwin.model.edges if x.key == key), None)
        if not e:
            return False
        n1, n2 = self.mainwin.model.nodes[e.a], self.mainwin.model.nodes[e.b]
        x1, y1 = display_point(n1.x, n1.y)
        x2, y2 = display_point(n2.x, n2.y)
        sp = self.mapToScene(pos)
        _, t, _, _ = dist_point_to_segment(sp.x(), sp.y(), x1, y1, x2, y2)
        # Allow moving very close to the end.  When it reaches a fitting mouth,
        # confirm_insert_reducer() can convert it to ブッシング instead of drawing an IN body.
        t = max(0.01, min(0.99, t))
        data["t"] = t
        near = self.mainwin.reducer_near_bushing_end(e, t, str(data.get("size", "")))
        if near:
            data["bushing_preview"] = dict(near)
            offer_key = f"{near.get('host')}-{near.get('other')}-{near.get('size')}"
            self.mainwin.pending_reducer = data
            # Live preview must be real, not only a symbol: temporarily shrink
            # the pipe/fittings on the small side while the mouse is inside the mouth zone.
            self.mainwin._preview_apply_bushing_small_side(dict(near))
            self.mainwin.lbl_reducer_hint.setText(self.mainwin.tr("bushing_live_hint"))
            self.mainwin.preview.draw_model()
            # Ask immediately when entering the mouth zone.  Guard keys prevent
            # repeated popups while the mouse is still inside the same socket.
            if data.get("bushing_declined_key") != offer_key and data.get("bushing_offer_key") != offer_key:
                data["bushing_offer_key"] = offer_key
                self.mainwin.pending_reducer = data
                QTimer.singleShot(0, lambda k=e.key, ok=offer_key: self.mainwin.ask_live_bushing_conversion(k, ok))
            return True
        else:
            # Leaving the mouth zone cancels only the live preview, so restore
            # original sizes before drawing IN normally again.
            self.mainwin.pending_reducer = data
            self.mainwin._preview_restore_bushing_small_side()
            data = getattr(self.mainwin, "pending_reducer", data)
            data.pop("bushing_preview", None)
            data.pop("bushing_offer_key", None)
            data.pop("bushing_declined_key", None)
            self.mainwin.pending_reducer = data
            self.mainwin.lbl_reducer_hint.setText(f"IN {data.get('size','')} 位置 {t*100:.0f}% → 確定")
            self.mainwin.preview.draw_model()
            return True

    def _node_is_danger_for_move(self, nid: int) -> Tuple[bool, str]:
        m = self.mainwin.model
        is_base = (nid == getattr(m, "base_node", None)) or (nid in getattr(m, "base_nodes", set()))
        is_end = (m.degree(nid) == 1)
        if is_base and is_end:
            return True, "⚠ Đây là điểm đầu đồng thời là điểm cuối. Nhấn Space để xác nhận di chuyển."
        if is_base:
            return True, "⚠ Đây là điểm đầu nhánh. Nhấn Space để xác nhận di chuyển."
        if is_end:
            return True, "⚠ Đây là điểm cuối nhánh. Nhấn Space để xác nhận di chuyển."
        return False, ""

    def _edge_by_key(self, key: str):
        return next((e for e in self.mainwin.model.edges if e.key == key), None)

    def _edge_unit_angle180(self, a: int, b: int) -> float:
        m = self.mainwin.model
        na, nb = m.nodes[a], m.nodes[b]
        return math.degrees(math.atan2(nb.y - na.y, nb.x - na.x)) % 180.0

    def _angle180_diff(self, a: float, b: float) -> float:
        d = abs((a - b) % 180.0)
        return min(d, 180.0 - d)

    def _edge_parallel_to(self, e, target_angle: float, tol_deg: float = 3.0) -> bool:
        if e.a not in self.mainwin.model.nodes or e.b not in self.mainwin.model.nodes:
            return False
        ang = self._edge_unit_angle180(e.a, e.b)
        return self._angle180_diff(ang, target_angle) <= tol_deg

    def _build_pipe_move_group(self, edge_key_value: str) -> Set[int]:
        """Return all nodes on the selected straight/45° pipe run.

        Kéo ống kiểu BIM: chọn một đoạn ống nhỏ bất kỳ, NEVIS gom toàn bộ
        các đoạn cùng phương nối tiếp nhau thành một tuyến.  Khi kéo, mọi cút
        trên tuyến đó đi theo; các nhánh ngoài chỉ thay đổi dài/ngắn.
        """
        m = self.mainwin.model
        e0 = self._edge_by_key(edge_key_value)
        if not e0 or e0.a not in m.nodes or e0.b not in m.nodes:
            return set()
        target = self._edge_unit_angle180(e0.a, e0.b)
        group = {e0.a, e0.b}
        stack = [e0.a, e0.b]
        while stack:
            u = stack.pop()
            for e in m.edges:
                if e.a == u:
                    v = e.b
                elif e.b == u:
                    v = e.a
                else:
                    continue
                if v in group:
                    continue
                if self._edge_parallel_to(e, target):
                    group.add(v)
                    stack.append(v)
        return group

    def _unit_vec(self, x: float, y: float) -> Tuple[float, float]:
        l = math.hypot(x, y)
        if l <= EPS:
            return (0.0, 0.0)
        return (x / l, y / l)

    def _cross2(self, ax: float, ay: float, bx: float, by: float) -> float:
        return ax * by - ay * bx

    def _dot2(self, ax: float, ay: float, bx: float, by: float) -> float:
        return ax * bx + ay * by

    def _external_slide_unit(self, nid: int, group: Set[int], run_ux: float, run_uy: float):
        """Return direction unit of the fixed outside pipe on which this run endpoint can slide."""
        m = self.mainwin.model
        n0 = m.nodes.get(nid)
        if not n0:
            return None
        best = None
        best_score = 1e100
        for e in m.edges:
            if e.a == nid:
                other = e.b
            elif e.b == nid:
                other = e.a
            else:
                continue
            if other in group or other not in m.nodes:
                continue
            no = m.nodes[other]
            ux, uy = self._unit_vec(no.x - n0.x, no.y - n0.y)
            if abs(ux) + abs(uy) <= EPS:
                continue
            # Prefer a non-parallel outside pipe.  A parallel outside pipe would
            # not define a useful slide rail for offsetting this run.
            parallel_score = abs(self._cross2(run_ux, run_uy, ux, uy))
            score = -parallel_score
            if score < best_score:
                best_score = score
                best = (ux, uy, other, e.key)
        return best

    def _prepare_pipe_slide_data(self, edge_key_value: str):
        """V18 BIM-style pipe move.

        The selected yellow pipe/run keeps its angle.  Its two end fittings slide
        on the blue outside pipes connected to the run ends.  Therefore the
        selected pipe/run only changes length/position; it never becomes a random
        odd angle.
        """
        m = self.mainwin.model
        e0 = self._edge_by_key(edge_key_value)
        if not e0 or e0.a not in m.nodes or e0.b not in m.nodes:
            return None
        group = self._build_pipe_move_group(edge_key_value)
        if len(group) < 2:
            group = {e0.a, e0.b}
        starts = {nid: (float(m.nodes[nid].x), float(m.nodes[nid].y)) for nid in group if nid in m.nodes}
        ax0, ay0 = starts.get(e0.a, (m.nodes[e0.a].x, m.nodes[e0.a].y))
        bx0, by0 = starts.get(e0.b, (m.nodes[e0.b].x, m.nodes[e0.b].y))
        run_ux, run_uy = self._unit_vec(bx0 - ax0, by0 - ay0)
        if abs(run_ux) + abs(run_uy) <= EPS:
            return None

        # Find the two extreme nodes on this pipe run along the selected pipe direction.
        projs = []
        for nid, (x, y) in starts.items():
            projs.append((self._dot2(x, y, run_ux, run_uy), nid))
        projs.sort()
        end_a = projs[0][1]
        end_b = projs[-1][1]
        if end_a == end_b:
            return None
        A = starts[end_a]
        B = starts[end_b]
        L = math.hypot(B[0] - A[0], B[1] - A[1])
        if L <= NODE_TOL:
            return None
        # Re-orient the run unit from A to B for stable interpolation.
        run_ux, run_uy = self._unit_vec(B[0] - A[0], B[1] - A[1])

        rail_a = self._external_slide_unit(end_a, group, run_ux, run_uy)
        rail_b = self._external_slide_unit(end_b, group, run_ux, run_uy)
        if not rail_a or not rail_b:
            self.mainwin.lbl_status.setText("⚠ Tuyến ống này thiếu ống xanh ở một đầu để cút trượt. Chọn đoạn khác hoặc dùng chỉnh thủ công.")
            return None
        ua_x, ua_y, outside_a, edge_a = rail_a
        ub_x, ub_y, outside_b, edge_b = rail_b
        ca = self._cross2(run_ux, run_uy, ua_x, ua_y)
        cb = self._cross2(run_ux, run_uy, ub_x, ub_y)
        if abs(cb) <= 1e-6 or abs(ca) <= 1e-6:
            self.mainwin.lbl_status.setText("⚠ Không tạo được ràng buộc trượt: ống ngoài gần như song song với ống đang kéo.")
            return None
        k = ca / cb
        # Allowable midpoint move direction. Mouse movement is projected to this direction.
        w_x = (ua_x + k * ub_x) * 0.5
        w_y = (ua_y + k * ub_y) * 0.5
        ww = w_x * w_x + w_y * w_y
        if ww <= 1e-8:
            self.mainwin.lbl_status.setText("⚠ Hai ray trượt triệt tiêu nhau, không kéo mượt được đoạn này.")
            return None

        node_param = {}
        for nid, (x, y) in starts.items():
            t = self._dot2(x - A[0], y - A[1], run_ux, run_uy) / L
            # Keep only tiny perpendicular offset to avoid numerical drift.
            node_param[nid] = max(0.0, min(1.0, t))

        return {
            "mode": "slide_pipe_run",
            "edge_key": edge_key_value,
            "group": set(group),
            "starts": starts,
            "end_a": end_a,
            "end_b": end_b,
            "A": A,
            "B": B,
            "run_u": (run_ux, run_uy),
            "rail_a": (ua_x, ua_y, outside_a, edge_a),
            "rail_b": (ub_x, ub_y, outside_b, edge_b),
            "k": k,
            "w": (w_x, w_y),
            "ww": ww,
            "node_param": node_param,
            "min_len": max(NODE_TOL * 2.0, 5.0),
        }

    def _calc_slide_positions(self, dx_model: float, dy_model: float):
        data = getattr(self, "_slide_pipe_data", None)
        if not data or data.get("mode") != "slide_pipe_run":
            return None
        A = data["A"]; B = data["B"]
        ua_x, ua_y, _, _ = data["rail_a"]
        ub_x, ub_y, _, _ = data["rail_b"]
        k = float(data["k"])
        w_x, w_y = data["w"]
        ww = float(data["ww"])
        # Project free mouse movement onto the only geometrically valid move vector.
        s = (dx_model * w_x + dy_model * w_y) / ww
        A2 = (A[0] + s * ua_x, A[1] + s * ua_y)
        B2 = (B[0] + k * s * ub_x, B[1] + k * s * ub_y)
        if math.hypot(B2[0] - A2[0], B2[1] - A2[1]) < float(data.get("min_len", 5.0)):
            return None
        # The yellow pipe/run must keep exactly the same direction.
        ru_x, ru_y = data["run_u"]
        if abs(self._cross2(ru_x, ru_y, B2[0] - A2[0], B2[1] - A2[1])) > 1.0:
            return None
        positions = {}
        for nid, t in data["node_param"].items():
            positions[nid] = (A2[0] + t * (B2[0] - A2[0]), A2[1] + t * (B2[1] - A2[1]))
        return positions

    def _slide_positions_ok(self, positions: Dict[int, Tuple[float, float]]) -> bool:
        m = self.mainwin.model
        for e in m.edges:
            if e.a not in m.nodes or e.b not in m.nodes:
                continue
            ax, ay = positions.get(e.a, (m.nodes[e.a].x, m.nodes[e.a].y))
            bx, by = positions.get(e.b, (m.nodes[e.b].x, m.nodes[e.b].y))
            if e.a in positions or e.b in positions:
                if not self._edge_angle_is_canonical(ax, ay, bx, by, tol_deg=2.25):
                    return False
        return True

    def _start_pipe_run_move(self, edge_key_value: str, scene_pos):
        if getattr(self.mainwin, "preview_detail_mode", False):
            self.mainwin.lbl_status.setText("Đang xem chi tiết: không cho di chuyển ống.")
            return False
        e = self._edge_by_key(edge_key_value)
        if not e:
            return False
        data = self._prepare_pipe_slide_data(edge_key_value)
        if not data:
            return False
        self.mainwin.select_edge(edge_key_value)
        self._move_node_id = None
        self._move_edge_key = edge_key_value
        self._move_group_nodes = set(data["group"])
        self._move_start_scene = QPointF(scene_pos)
        self._move_start_model = None
        self._move_start_positions = dict(data["starts"])
        self._slide_pipe_data = data
        self._move_undo_saved = False
        self._pending_danger_move = None
        self.viewport().setCursor(Qt.ClosedHandCursor)
        self.mainwin.lbl_status.setText(
            "Đang kéo ống kiểu trượt: 2 đầu cút chạy trên ống xanh, ống đang kéo giữ nguyên góc, chỉ dài/ngắn."
        )
        return True

    def _start_safe_node_move(self, nid: int, scene_pos):
        """Fallback: kéo một cút đơn lẻ. Ưu tiên mới là kéo tuyến ống."""
        if nid not in self.mainwin.model.nodes:
            return False
        if getattr(self.mainwin, "preview_detail_mode", False):
            self.mainwin.lbl_status.setText("Đang xem chi tiết: không cho di chuyển cút.")
            return False
        self.mainwin.select_node(nid)
        n = self.mainwin.model.nodes[nid]
        self._move_node_id = nid
        self._move_edge_key = None
        self._move_group_nodes = {nid}
        self._move_start_scene = QPointF(scene_pos)
        self._move_start_model = (float(n.x), float(n.y))
        self._move_start_positions = {nid: (float(n.x), float(n.y))}
        self._move_undo_saved = False
        self._pending_danger_move = None
        self.viewport().setCursor(Qt.ClosedHandCursor)
        self.mainwin.lbl_status.setText("Đang di chuyển cút: chỉ cho 8 hướng 0°/45°/90°. Thả chuột phải để kết thúc.")
        return True

    def _snap_delta_8dir(self, dx: float, dy: float) -> Tuple[float, float]:
        length = math.hypot(dx, dy)
        if length <= 0.01:
            return 0.0, 0.0
        step = math.pi / 4.0
        ang = round(math.atan2(dy, dx) / step) * step
        return math.cos(ang) * length, math.sin(ang) * length

    def _edge_angle_is_canonical(self, ax: float, ay: float, bx: float, by: float, tol_deg: float = 1.75) -> bool:
        dx, dy = bx - ax, by - ay
        if math.hypot(dx, dy) <= NODE_TOL:
            return False
        ang = (math.degrees(math.atan2(dy, dx)) % 180.0)
        nearest = round(ang / 45.0) * 45.0
        nearest = nearest % 180.0
        diff = abs(ang - nearest)
        diff = min(diff, 180.0 - diff)
        return diff <= tol_deg

    def _candidate_group_move_ok(self, group: Set[int], dx_model: float, dy_model: float) -> bool:
        m = self.mainwin.model
        if not group:
            return False
        starts = self._move_start_positions or {}
        # Validate every edge after the candidate move. Internal edges keep their
        # original direction because both endpoints move together. Boundary edges
        # are the important ones: they may lengthen/shorten, but must stay at
        # 0/45/90/135 only.
        for e in m.edges:
            if e.a not in m.nodes or e.b not in m.nodes:
                continue
            a_in = e.a in group
            b_in = e.b in group
            if not a_in and not b_in:
                continue
            ax, ay = starts.get(e.a, (m.nodes[e.a].x, m.nodes[e.a].y))
            bx, by = starts.get(e.b, (m.nodes[e.b].x, m.nodes[e.b].y))
            if a_in:
                ax += dx_model; ay += dy_model
            if b_in:
                bx += dx_model; by += dy_model
            if not self._edge_angle_is_canonical(ax, ay, bx, by):
                return False
        return True

    def _move_group_from_view_pos(self, pos) -> bool:
        group = set(self._move_group_nodes or [])
        if not group or self._move_start_scene is None:
            return False
        sp = self.mapToScene(pos)
        dx_disp = sp.x() - self._move_start_scene.x()
        dy_disp = sp.y() - self._move_start_scene.y()
        # Convert display delta to model delta. Delta transform has no origin.
        x0, y0 = model_point_from_display(0.0, 0.0)
        x1, y1 = model_point_from_display(dx_disp, dy_disp)
        dx_model, dy_model = x1 - x0, y1 - y0

        # V18 preferred mode: pipe-run slide.  Do not translate the whole group.
        # Instead, both end fittings slide on their connected outside pipes, and
        # the selected pipe/run keeps its original 0/45/90/135 direction.
        if getattr(self, "_slide_pipe_data", None):
            positions = self._calc_slide_positions(dx_model, dy_model)
            if not positions or not self._slide_positions_ok(positions):
                self.mainwin.lbl_status.setText("⚠ Không kéo được: cút không thể trượt mà vẫn giữ toàn bộ ống theo góc 0°/45°/90°/135°.")
                self.viewport().setCursor(Qt.ForbiddenCursor)
                return False
            if not self._move_undo_saved:
                self.mainwin.save_undo_snapshot("slide_pipe_run")
                self._move_undo_saved = True
            for nid, (nx, ny) in positions.items():
                if nid in self.mainwin.model.nodes:
                    self.mainwin.model.nodes[nid].x = nx
                    self.mainwin.model.nodes[nid].y = ny
            self.viewport().setCursor(Qt.ClosedHandCursor)
            self.mainwin.lbl_status.setText(f"Đang trượt ống: {len(positions)} cút/điểm trên tuyến, góc ống giữ nguyên.")
            self.mainwin.preview.draw_model()
            return True

        # Fallback old mode: translate a node/group in one of 8 directions.
        dx_disp, dy_disp = self._snap_delta_8dir(dx_disp, dy_disp)
        x0, y0 = model_point_from_display(0.0, 0.0)
        x1, y1 = model_point_from_display(dx_disp, dy_disp)
        dx_model, dy_model = x1 - x0, y1 - y0
        if abs(dx_model) + abs(dy_model) <= 0.01:
            return True
        if not self._candidate_group_move_ok(group, dx_model, dy_model):
            self.mainwin.lbl_status.setText("⚠ Không kéo được: một nhánh ngoài sẽ thành góc lẻ. Hãy kéo theo hướng làm nhánh dài/ngắn theo 0°/45°/90°.")
            self.viewport().setCursor(Qt.ForbiddenCursor)
            return False
        if not self._move_undo_saved:
            self.mainwin.save_undo_snapshot("move_pipe_run")
            self._move_undo_saved = True
        for nid in group:
            if nid not in self.mainwin.model.nodes or nid not in self._move_start_positions:
                continue
            sx, sy = self._move_start_positions[nid]
            self.mainwin.model.nodes[nid].x = sx + dx_model
            self.mainwin.model.nodes[nid].y = sy + dy_model
        self.viewport().setCursor(Qt.ClosedHandCursor)
        self.mainwin.preview.draw_model()
        return True

    def _move_node_from_view_pos(self, pos) -> bool:
        # Compatibility wrapper for old cút-drag path.
        return self._move_group_from_view_pos(pos)

    def _finish_node_move(self):
        moved = bool(self._move_undo_saved)
        moved_edge = self._move_edge_key
        moved_node = self._move_node_id
        self._move_node_id = None
        self._move_edge_key = None
        self._move_group_nodes = set()
        self._move_start_scene = None
        self._move_start_model = None
        self._move_start_positions = {}
        self._slide_pipe_data = None
        self._move_undo_saved = False
        if moved:
            # Recalculate only once after mouse release for speed.
            self.mainwin.apply_common()
            try:
                self.mainwin.force_bushing_downstream_sizes()
            except Exception:
                pass
            optimized = False
            if moved_edge:
                try:
                    optimized = bool(self.mainwin.smart_drag_optimize_after_pipe_move(moved_edge))
                except Exception as ex:
                    optimized = False
                    try:
                        print("NEVIS smart drag optimize skipped:", ex)
                    except Exception:
                        pass
            if moved_edge and not optimized:
                self.mainwin.select_edge(moved_edge)
                self.mainwin.lbl_status.setText(self.mainwin.tr("smart_drag_moved"))
            elif moved_node and moved_node in self.mainwin.model.nodes and not optimized:
                self.mainwin.select_node(moved_node)
                self.mainwin.lbl_status.setText("Đã di chuyển cút theo hướng an toàn 0°/45°/90°.")
        self.update()

    def keyPressEvent(self, event):
        if event.key() == Qt.Key_Space and self._pending_danger_move:
            nid, scene_pos = self._pending_danger_move
            self._start_safe_node_move(nid, scene_pos)
            event.accept()
            return
        if event.key() == Qt.Key_Escape:
            self._pending_danger_move = None
            self._move_node_id = None
            self._move_edge_key = None
            self._move_group_nodes = set()
            self._move_start_positions = {}
            self._slide_pipe_data = None
            self.mainwin.lbl_status.setText("Đã hủy di chuyển.")
            event.accept()
            return
        super().keyPressEvent(event)

    def mouseMoveEvent(self, event):
        if (self._move_node_id is not None or self._move_edge_key is not None) and (event.buttons() & Qt.RightButton):
            self._move_group_from_view_pos(event.pos())
            return
        if getattr(self.mainwin, "pending_reducer", None) and (event.buttons() & Qt.LeftButton):
            if self._move_pending_reducer_from_view_pos(event.pos()):
                self.viewport().setCursor(Qt.CrossCursor)
                return
        item = self.itemAt(event.pos())
        if getattr(self.mainwin, "pending_reducer", None):
            self.viewport().setCursor(Qt.CrossCursor)
        elif self._interactive_item_data(item) is not None:
            self.viewport().setCursor(Qt.PointingHandCursor)
        elif self.dragMode() == QGraphicsView.ScrollHandDrag:
            self.viewport().setCursor(Qt.OpenHandCursor)
        super().mouseMoveEvent(event)

    @staticmethod
    def _interactive_item_data(item):
        """Return selectable scene metadata without trusting arbitrary item data."""
        if item is None:
            return None
        data = item.data(0)
        if data == "nevis_reference_raster_background":
            return None
        if not isinstance(data, tuple) or len(data) != 2:
            return None
        return data

    def mousePressEvent(self, event):
        if event.button() == Qt.LeftButton and getattr(self.mainwin, "measure_mode", False):
            sp = self.mapToScene(event.pos())
            self.mainwin.add_measure_point(sp.x(), sp.y())
            return
        if event.button() == Qt.LeftButton and getattr(self.mainwin, "pending_reducer", None):
            if self._move_pending_reducer_from_view_pos(event.pos()):
                return
        item = self.itemAt(event.pos())
        item_data = self._interactive_item_data(item)
        if event.button() == Qt.LeftButton and item_data is not None:
            kind, val = item_data
            if kind == "node":
                self.mainwin.select_node(val)
            elif kind == "edge":
                self.mainwin.select_edge(val)
            elif kind == "bushing":
                self.mainwin.select_bushing(val)
            return
        if event.button() == Qt.RightButton:
            item = self.itemAt(event.pos())
            item_data = self._interactive_item_data(item)
            if item_data is not None:
                kind, val = item_data
                self.setFocus()
                if kind == "edge":
                    self._start_pipe_run_move(val, self.mapToScene(event.pos()))
                    return
                if kind == "bushing":
                    self.mainwin.select_bushing(val)
                    return
                if kind == "node":
                    danger, msg = self._node_is_danger_for_move(val)
                    if danger:
                        self._pending_danger_move = (val, self.mapToScene(event.pos()))
                        self.mainwin.select_node(val)
                        self.mainwin.lbl_status.setText(msg + "  Esc: hủy")
                        self.viewport().setCursor(Qt.WhatsThisCursor)
                        return
                    self._start_safe_node_move(val, self.mapToScene(event.pos()))
                    return
            self.viewport().setCursor(Qt.ClosedHandCursor)
        super().mousePressEvent(event)

    def mouseReleaseEvent(self, event):
        if event.button() == Qt.RightButton and (self._move_node_id is not None or self._move_edge_key is not None):
            self._finish_node_move()
            self.viewport().setCursor(Qt.OpenHandCursor)
            event.accept()
            return
        if event.button() == Qt.RightButton and self._pending_danger_move:
            # Người dùng chỉ bấm phải vào điểm nguy hiểm nhưng chưa nhấn Space.
            # Giữ cảnh báo trên status, không tự di chuyển.
            self.viewport().setCursor(Qt.OpenHandCursor)
            event.accept()
            return
        self.viewport().setCursor(Qt.OpenHandCursor)
        super().mouseReleaseEvent(event)

    def fit_view(self):
        if self.scene.items():
            # Smaller padding so the drawing does not look tiny.
            self.fitInView(self.scene.itemsBoundingRect().adjusted(-35,-35,35,35), Qt.KeepAspectRatio)
            self.scale(1.08, 1.08)




