SYSTEM_FOLDER_ALIAS_MAP = {
    "排水": ["Thoat nuoc", "Thoát nước", "排水", "Drain", "Drainage"],
    "給水": ["Cap nuoc", "Cấp nước", "給水", "Water", "Water supply"],
    "SP": ["Cuu hoa", "Cứu hỏa", "消防", "Sprinkler", "Fire"],
    "連結送水管": ["Cuu hoa", "Cứu hỏa", "消防", "連結送水管", "Fire department connection", "FDC"],
    "空調": ["Dieu hoa", "Điều hòa", "空調", "HVAC"],
    "換気": ["Thong khi", "Thông khí", "換気", "Vent", "Ventilation"],
}
SYSTEM_FOLDER_TOKENS = {x.lower(): code for code, arr in SYSTEM_FOLDER_ALIAS_MAP.items() for x in ([code] + arr)}


def infer_system_code_from_folder(name: str) -> str:
    key = str(name or "").strip().lower()
    return SYSTEM_FOLDER_TOKENS.get(key, str(name or "").strip())


def system_folder_aliases_from_code(code: str, item: Optional[dict] = None) -> List[str]:
    out = []
    def add(x):
        x = str(x or "").strip()
        if x and x not in out:
            out.append(x)
    if item:
        add(item.get("folder", "")); add(item.get("name_vi", "")); add(item.get("name_jp", ""))
    add(code)
    for x in SYSTEM_FOLDER_ALIAS_MAP.get(str(code or ""), []): add(x)
    return out


def nevis_app_dir() -> Path:
    try:
        return Path(sys.argv[0]).resolve().parent
    except Exception:
        return Path.cwd()


def make_nevis_material_name(group: str, main_size: str, branch_size: str = "", note: str = "") -> str:
    """Unified material/library stem: group_main_branch_note.

    main_size = ống chính / 主管, branch_size = nhánh phụ / 枝管.
    note is optional and may be U/D or a user-defined suffix.
    """
    parts = [str(group or "").strip(), str(main_size or "").strip()]
    b = str(branch_size or "").strip()
    n = str(note or "").strip()
    if b:
        parts.append(b)
    if n:
        parts.append(n)
    return "_".join([p for p in parts if p])


def parse_nevis_material_name(name: str) -> Dict[str, str]:
    """Parse group_main_branch_note from a JSON/TXT library filename.

    Supports old stems like Y_65x50 by translating 65x50 -> main=65, branch=50.
    """
    stem = Path(str(name or "")).stem
    parts = [p for p in re.split(r"[_\s]+", stem) if p]
    out = {"group": "", "main": "", "branch": "", "note": ""}
    if not parts:
        return out
    out["group"] = parts[0]
    if len(parts) >= 2:
        m = re.match(r"^(\d+)x(\d+)$", parts[1], re.I)
        if m:
            out["main"], out["branch"] = m.group(1), m.group(2)
        else:
            out["main"] = parts[1]
    if len(parts) >= 3:
        out["branch"] = parts[2]
    if len(parts) >= 4:
        out["note"] = "_".join(parts[3:])
    return out


# Fittings whose identity depends on BOTH main pipe size and branch size.
# These must never fall back from 65x50 to 65x65 just because the main size matches.
STRICT_BRANCH_SIZE_FITTINGS = {"Y", "LT", "DT", "T", "SV", "S", "集合管"}


def _nevis_size_identity(text: str) -> Tuple[str, str, str]:
    """Return (main, branch, note) from size/name text.

    Accepts 65x50, 65_50_U, Y_65_50_U, DV_Y_65_50_U.
    note may be U/D/N or any user-created suffix. Numeric tokens are size order.
    """
    txt = str(text or "").strip()
    stem = Path(txt).stem if ("." in txt or "\\" in txt or "/" in txt) else txt
    nums = re.findall(r"\d+", stem)
    if re.search(r"(?i)(^|[_x\-])45(°|度)?($|[_x\-])", stem) and nums and nums[0] == "45":
        nums = nums[1:]
    main = nums[0] if nums else ""
    branch = nums[1] if len(nums) >= 2 else ""
    tokens = [t for t in re.split(r"[_x\-\s]+", stem.upper().replace("°", "")) if t]
    numeric = set(nums)
    notes = []
    for t in tokens:
        if t in numeric:
            continue
        if t in {"DV", "VP", "VU", "TMP", "TS", "HTVP", "TAIKAVP", "耐火VP"}:
            continue
        if t in {"Y", "LT", "DT", "T", "SV", "S", "LL", "DL", "L", "IN", "45", "JSON", "TXT"}:
            continue
        notes.append(t)
    note = notes[-1] if notes else ""
    return main, branch, note




def _collection_requested_single_port(size_text: str) -> bool:
    """True when 集合管 request is one-door/one-port: size is only main size.

    NEVIS uses size like "65" for 集合管 1 cửa.  Names like S_65_50 /
    SV_65_50 are multi-port collection libraries and must not be used for this
    request even though the first size token matches 65.
    """
    nums = re.findall(r"\d+", str(size_text or ""))
    return len(nums) == 1


def _collection_candidate_is_single_port(name_or_path: str) -> bool:
    """Return True for one-door 集合管 library names.

    Accept S_65 / S65 / 集合管_65. Reject SV_* and any name containing two or
    more size numbers such as S_65_50, because those draw two/three mouths.
    """
    stem = Path(str(name_or_path or "")).stem.upper()
    if stem.startswith("SV") or "_SV" in stem:
        return False
    nums = re.findall(r"\d+", stem)
    return len(nums) <= 1

def _strict_fitting_size_match(ftype: str, candidate_name_or_size: str, requested_size: str) -> bool:
    """Exact identity match for branch fittings.

    For Y/LT/DT/T/SV/S, main and branch are both required when requested has two
    sizes.  This prevents Y_65_65 from being selected for a computed 65x50 fitting.
    """
    ft = str(ftype or "").strip()
    r_main, r_branch, r_note = _nevis_size_identity(requested_size)
    c_main, c_branch, c_note = _nevis_size_identity(candidate_name_or_size)
    if not r_main:
        return False
    if c_main != r_main:
        return False
    if ft in STRICT_BRANCH_SIZE_FITTINGS:
        if r_branch:
            if not c_branch:
                return False
            if c_branch != r_branch:
                return False
        # If user requested U/D/custom note, respect it strictly.
        if r_note and c_note and c_note != r_note:
            return False
    return True


class MasterListEditor(QDialog):
    def __init__(self, parent, title: str, fields: List[Tuple[str, str]], item: Optional[dict]=None):
        super().__init__(parent)
        self.setWindowTitle(title)
        self.values: Dict[str, str] = {}
        self.edits: Dict[str, QLineEdit] = {}
        lay = QVBoxLayout(self); lay.setContentsMargins(14,14,14,14); lay.setSpacing(8)
        grid = QGridLayout(); grid.setHorizontalSpacing(8); grid.setVerticalSpacing(8)
        for r, (key, label) in enumerate(fields):
            grid.addWidget(QLabel(label), r, 0)
            ed = QLineEdit(str((item or {}).get(key, "")))
            grid.addWidget(ed, r, 1)
            self.edits[key] = ed
        lay.addLayout(grid)
        btns = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        btns.accepted.connect(self.accept); btns.rejected.connect(self.reject)
        lay.addWidget(btns)
        self.resize(460, 220)
    def accept(self):
        self.values = {k: e.text().strip() for k, e in self.edits.items()}
        super().accept()


class NevisMasterDialog(QDialog):
    """Relational master database manager.

    Data rule:
      System (primary) -> allowed Materials
      Material (sub key) -> allowed Fitting Groups
    """
    def __init__(self, mainwin):
        super().__init__(mainwin)
        self.mainwin = mainwin
        self.lang = getattr(mainwin, 'lang', 'vi')
        self.tr = mainwin.tr
        self.master_path = nevis_app_dir() / 'nevis_master.json'
        self.data = self.load_master()
        self._loading = False
        self.setWindowTitle(self.tr('master_manager_title'))
        self.resize(1120, 680)
        self._build_ui()
        self.refresh_systems()
        self.refresh_materials_for_system()
        self.refresh_groups_for_material()
        self.refresh_start_end_for_material()
        # Không tự đồng bộ kiểu suy đoán khi mở cửa sổ.
        # CSDL phải theo folder thật, chỉ đồng bộ khi người dùng bấm nút.
        # Điều này tránh tự thêm DL/LL/VP... không tồn tại trong cây thư viện.

    def _upgrade_nevis_master_data(self, data: dict):
        """Add new fields to old nevis_master.json without deleting user settings."""
        try:
            default = copy.deepcopy(DEFAULT_NEVIS_MASTER)
            for key in ("systems", "materials", "fitting_groups"):
                by_code = {str(x.get("code", "")): x for x in default.get(key, []) if isinstance(x, dict)}
                for item in data.get(key, []) or []:
                    if not isinstance(item, dict):
                        continue
                    d = by_code.get(str(item.get("code", "")), {})
                    for kk, vv in d.items():
                        item.setdefault(kk, copy.deepcopy(vv))
            for mat in data.get("materials", []) or []:
                if isinstance(mat, dict):
                    for rk in ("start_groups", "end_groups"):
                        mat[rk] = [self.normalize_role_code(x) for x in mat.get(rk, []) or []]
            data.setdefault("version", 3)
            data.setdefault("name_rule", "{group}_{main}_{branch}_{note}")
        except Exception:
            pass

    def load_master(self):
        try:
            if self.master_path.exists():
                data = json.loads(self.master_path.read_text(encoding='utf-8-sig'))
                for k, v in DEFAULT_NEVIS_MASTER.items():
                    # If old/corrupted nevis_master.json has empty lists, restore defaults.
                    if k in ("systems", "materials", "fitting_groups"):
                        if not data.get(k):
                            data[k] = copy.deepcopy(v)
                    else:
                        data.setdefault(k, copy.deepcopy(v))
                self._upgrade_nevis_master_data(data)
                if not data.get("name_rule"):
                    data["name_rule"] = "{group}_{main}_{branch}_{note}"
                return data
        except Exception:
            pass
        return copy.deepcopy(DEFAULT_NEVIS_MASTER)

    def save_master(self, silent: bool = False):
        try:
            self.master_path.write_text(json.dumps(self.data, ensure_ascii=False, indent=2), encoding='utf-8')
            if hasattr(self.mainwin, 'apply_master_to_common_controls'):
                self.mainwin.apply_master_to_common_controls()
            if not silent:
                QMessageBox.information(self, self.tr('master_manager_title'), self.tr('master_saved'))
        except Exception as e:
            QMessageBox.warning(self, self.tr('master_manager_title'), str(e))

    def t(self, vi: str, jp: str) -> str:
        return jp if self.lang == 'jp' else vi

    def name_of(self, item: dict) -> str:
        if self.lang == 'jp':
            return item.get('name_jp') or item.get('name_vi') or item.get('code','')
        return item.get('name_vi') or item.get('name_jp') or item.get('code','')

    def system_label(self, item: dict) -> str:
        name = self.name_of(item); code = item.get('code','')
        return f"{code} — {name}" if name and name != code else code

    def material_label(self, item: dict) -> str:
        name = self.name_of(item); code = item.get('code',''); folder = item.get('folder','')
        return f"{code} — {name}  [{folder}]" if name and name != code else f"{code}  [{folder}]"

    def group_label(self, item: dict) -> str:
        name = self.name_of(item); code = item.get('code',''); ports = item.get('ports','')
        return f"{code} — {name}  ({ports}P)" if name and name != code else f"{code}  ({ports}P)"

    def role_label(self, code: str) -> str:
        code = str(code or '').strip()
        if code in {'PIPE', '配管'}:
            return self.tr('master_pipe_raw')
        if code in {'NONE', 'なし'}:
            return self.tr('master_none')
        for g in self.data.get('fitting_groups', []) or []:
            if str(g.get('code', '')) == code:
                return self.group_label(g)
        for m in self.data.get('materials', []) or []:
            if str(m.get('code', '')) == code:
                return self.material_label(m)
        return code

    def normalize_role_code(self, code: str) -> str:
        code = str(code or '').strip()
        aliases = {
            'PIPE': '配管', 'pipe': '配管', 'Pipe': '配管',
            'NONE': 'なし', 'none': 'なし', 'None': 'なし',
            # Keep UP/Down spelling consistent so DL Up / DL UP do not split lists.
            'DL UP': 'DL Up', 'DL_UP': 'DL Up', 'DL-UP': 'DL Up',
            'LL UP': 'LL Up', 'LL_UP': 'LL Up', 'LL-UP': 'LL Up',
            'DL DOWN': 'DL Down', 'DL_DOWN': 'DL Down', 'DL-DOWN': 'DL Down',
            'LL DOWN': 'LL Down', 'LL_DOWN': 'LL Down', 'LL-DOWN': 'LL Down',
        }
        return aliases.get(code, code)

    def style_check_item(self, item: QListWidgetItem):
        """Make checked master items visually obvious."""
        if item.checkState() == Qt.Checked:
            item.setBackground(QBrush(QColor(215, 246, 235)))
            item.setForeground(QBrush(QColor(0, 105, 92)))
            f = item.font(); f.setBold(True); item.setFont(f)
            txt = item.text()
            if not txt.startswith("✓ "):
                item.setText("✓ " + txt)
        else:
            item.setBackground(QBrush(QColor(255, 255, 255)))
            item.setForeground(QBrush(QColor(31, 41, 55)))
            f = item.font(); f.setBold(False); item.setFont(f)
            txt = item.text()
            if txt.startswith("✓ "):
                item.setText(txt[2:])

    def selected_system(self):
        row = self.lw_systems.currentRow(); arr = self.data.get('systems', [])
        return arr[row] if 0 <= row < len(arr) else None

    def selected_material(self):
        item = self.lw_materials.currentItem()
        return self.find_material(item.data(Qt.UserRole)) if item else None

    def find_material(self, code: str) -> Optional[dict]:
        for m in self.data.get('materials', []):
            if str(m.get('code','')) == str(code):
                return m
        return None


    def load_app_settings(self) -> Dict[str, object]:
        default = {"light_detail_preview": True, "auto_scan_library": True, "show_library_tab": False}
        p = Path("nevis_settings.json")
        if p.exists():
            try:
                data = json.loads(p.read_text(encoding="utf-8"))
                if isinstance(data, dict):
                    default.update({k: data.get(k, v) for k, v in default.items()})
            except Exception:
                pass
        return default

    def save_app_settings(self):
        try:
            Path("nevis_settings.json").write_text(json.dumps(self.app_settings, ensure_ascii=False, indent=2), encoding="utf-8")
        except Exception:
            pass

