        self.cmb_normal_mat = _nevis_control(QComboBox(), 115, 150); self.cmb_normal_mat.addItems(["DV", "VP/VU", "VP", "VU", "HTVP", "TMP", "耐火VP"])
        self.lbl_inside = _nevis_label(self.tr("inside")); self.lbl_outside = _nevis_label(self.tr("outside"))

