        # JWW operation panel is wide, so keep the color/line reference and
        # export settings side-by-side.  This avoids the old narrow left-panel
        # layout where color samples and line patterns overlapped each other.
        jww_top = QHBoxLayout()
        jww_top.setSpacing(6)

        self.g_jww_ref = QGroupBox(self.tr("jww_ref"))
        ref_grid = QGridLayout(self.g_jww_ref)
        ref_grid.setContentsMargins(8, 14, 8, 8)
        ref_grid.setHorizontalSpacing(5)
        ref_grid.setVerticalSpacing(4)
        # Compact 2-column reference: colors 1-4 / 5-8 and line types 1-4 / 5-8.
        # This uses the wide panel efficiently and keeps the drawing canvas taller.
        self.hdr_color = QLabel(self.tr("jww_col_color"))
        self.hdr_line = QLabel(self.tr("jww_col_line"))
        hdr_color = self.hdr_color
        hdr_line = self.hdr_line
        hdr_color.setStyleSheet("font-weight:700; color:#1E2A3A;")
        hdr_line.setStyleSheet("font-weight:700; color:#1E2A3A;")
        ref_grid.addWidget(hdr_color, 0, 0, 1, 5)
        ref_grid.addWidget(hdr_line, 0, 5, 1, 5)
        self.jww_color_boxes = []
        self.jww_line_labels = []
        for i in range(1, 9):
            # Rows 1-4, columns split into left/right blocks.
            row_i = ((i - 1) % 4) + 1
            block = 0 if i <= 4 else 3
            color_box = QLabel(" ")
            color_box.setFixedSize(30, 12)
            color_box.setStyleSheet(f"background: #{self.jww_colors.get(i, 'CCCCCC')}; border:1px solid #777;")
            no_lbl = QLabel(str(i)); no_lbl.setFixedWidth(18)
            ref_grid.addWidget(color_box, row_i, block + 0)
            ref_grid.addWidget(no_lbl, row_i, block + 1)
            self.jww_color_boxes.append(color_box)

            line_block = 5 if i <= 4 else 8
            line_lbl = QLabel(self.jww_line_pattern_text(i))
            line_lbl.setMinimumWidth(56)
            line_lbl.setMaximumHeight(18)
            line_lbl.setStyleSheet("background:#FFFFFF; padding-left:6px; border:1px solid #E1E8F2; border-radius:3px;")
            lt_no_lbl = QLabel(str(i)); lt_no_lbl.setFixedWidth(18)
            ref_grid.addWidget(line_lbl, row_i, line_block + 0)
            ref_grid.addWidget(lt_no_lbl, row_i, line_block + 1)
            self.jww_line_labels.append(line_lbl)
        self.g_jww_ref.setMinimumWidth(260)
        self.g_jww_ref.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        self.g_jww_ref.setMaximumHeight(145)
        jww_top.addWidget(self.g_jww_ref, 1)

        self.g_jww_style = QGroupBox(self.tr("jww_style"))
        style_grid = QGridLayout(self.g_jww_style)
        style_grid.setContentsMargins(8, 14, 8, 8)
        style_grid.setHorizontalSpacing(5)
        style_grid.setVerticalSpacing(6)
        style_grid.setColumnStretch(5, 1)
        self.lbl_jww_blank = QLabel("")
        self.lbl_jww_color = QLabel(self.tr("jww_col_color"))
        self.lbl_jww_line = QLabel(self.tr("jww_col_line"))
        self.lbl_jww_main_layer = QLabel(self.tr("jww_col_main_layer"))
        self.lbl_jww_sub_layer = QLabel(self.tr("jww_col_sub_layer"))
        style_grid.addWidget(self.lbl_jww_blank, 0, 0)
        style_grid.addWidget(self.lbl_jww_color, 0, 1)
        style_grid.addWidget(self.lbl_jww_line, 0, 2)
        style_grid.addWidget(self.lbl_jww_main_layer, 0, 3)
        style_grid.addWidget(self.lbl_jww_sub_layer, 0, 4)
        self.jww_edits = {}
        rows = [
            ("pipe", self.tr("jww_row_pipe"), self.jww_pipe_color, self.jww_pipe_line, self.jww_pipe_lg, self.jww_pipe_ly),
            ("center", self.tr("jww_row_center"), self.jww_center_color, self.jww_center_line, self.jww_center_lg, self.jww_center_ly),
            ("joint", self.tr("jww_row_joint"), self.jww_joint_color, self.jww_joint_line, self.jww_joint_lg, self.jww_joint_ly),
        ]
        self.jww_row_labels = {}
        for r, (key, label, c, lt, lg, ly) in enumerate(rows, start=1):
            row_label = QLabel(label)
            self.jww_row_labels[key] = row_label
            style_grid.addWidget(row_label, r, 0)
            vals = [("color", c), ("line", lt), ("lg", lg), ("ly", ly)]
            for col, (name, val) in enumerate(vals, start=1):
                e = QLineEdit(val)
                e.setAlignment(Qt.AlignCenter)
                e.setMaximumWidth(38)
                e.setMinimumWidth(30)
                style_grid.addWidget(e, r, col)
                self.jww_edits[f"{key}_{name}"] = e

