    def resizeEvent(self, event):
        super().resizeEvent(event)
        try:
            self.apply_responsive_layout()
        except Exception:
            pass

    def set_left_panel_width(self, w: int):
        """Live-update the fixed width of the left task panel (used by Layout Tuner)."""
        w = max(300, int(w))
        try:
            self.left_shell.setFixedWidth(w)
        except Exception:
            pass
        try:
            self.left_scroll.widget().setFixedWidth(w)
        except Exception:
            pass
        try:
            self.apply_responsive_layout()
        except Exception:
            pass

    def apply_responsive_layout(self):
        """Keep left task panel fixed; allow user to drag the right material panel.

        Important: do not force the right panel back to 220-250px on every
        resizeEvent.  That made the right splitter look locked and prevented
        manual adjustment.  Only clamp it to a safe range and give the rest of
        the width to the preview.
        """
        sizes = self.splitter.sizes() if hasattr(self, 'splitter') else []
        if len(sizes) != 3:
            return
        left_w = self.left_shell.width() if hasattr(self, 'left_shell') else sizes[0]
        total = max(1, sum(sizes))
        right_hidden = bool(getattr(self, 'btn_right_tab', None) and self.btn_right_tab.isVisible())
        if right_hidden:
            right_w = 30
        else:
            # User-draggable range for the material panel.
            right_w = max(160, min(420, sizes[2] or 220))
        center_w = max(320, total - left_w - right_w)
        if sizes[0] != left_w or abs(sizes[2] - right_w) > 4 or abs(sizes[1] - center_w) > 4:
            self.splitter.setSizes([left_w, center_w, right_w])
        self._set_preview_toolbar_compact(center_w < 1250, center_w < 560)

    def _set_preview_toolbar_compact(self, compact: bool, narrow: bool = False):
        """Wrap reference-background controls when the preview panel is narrow."""
        layout = getattr(self, "preview_toolbar_layout", None)
        mode = (bool(compact), bool(narrow))
        current_mode = (
            getattr(self, "_preview_toolbar_compact", None),
            getattr(self, "_preview_toolbar_narrow", None),
        )
        if layout is None or current_mode == mode:
            return

        primary = getattr(self, "_preview_primary_widgets", [])
        background = getattr(self, "_preview_background_widgets", [])
        if narrow:
            layout.addWidget(self.lbl_drawing_preview, 0, 0, 1, 3)
            for offset, widget in enumerate(primary[:3]):
                layout.addWidget(widget, 1, offset)
            for offset, widget in enumerate(primary[3:]):
                layout.addWidget(widget, 2, offset)
            for offset, widget in enumerate(background[:2]):
                layout.addWidget(widget, 3, offset)
            for offset, widget in enumerate(background[2:]):
                layout.addWidget(widget, 4, offset)
        elif compact:
            layout.addWidget(self.lbl_drawing_preview, 0, 0, 1, 6)
            for offset, widget in enumerate(primary):
                layout.addWidget(widget, 1, offset)
            for offset, widget in enumerate(background):
                layout.addWidget(widget, 2, offset)
        else:
            layout.addWidget(self.lbl_drawing_preview, 0, 0)
            for column, widget in enumerate(primary, start=2):
                layout.addWidget(widget, 0, column)
            for offset, widget in enumerate(background):
                layout.addWidget(widget, 0, 2 + len(primary) + offset)

        self._preview_toolbar_compact = bool(compact)
        self._preview_toolbar_narrow = bool(narrow)
        layout.invalidate()

    def set_side_panel_visible(self, side: str, visible: bool):
        """Pin/unpin only the right material/library panel.

        The left operation/task area stays visible all the time because hiding it
        makes the workflow unclear.  The right panel keeps a slim vertical tab
        when unpinned so the drawing area can expand.
        """
        if side == 'left':
            return

        if side == 'right':
            content = getattr(self, 'right_shell', None)
            tab = getattr(self, 'btn_right_tab', None)
            pin = getattr(self, 'btn_pin_right', None)
            if content is not None and content.layout() is not None and content.layout().count() >= 2:
                panel = content.layout().itemAt(0).widget()
                panel.setVisible(visible)
                if tab:
                    tab.setVisible(not visible)
                if pin:
                    pin.blockSignals(True)
                    pin.setChecked(bool(visible))
                    pin.blockSignals(False)
                    pin.setToolTip(self.tr("pin_right_hide") if visible else self.tr("pin_right_show"))
                content.setMinimumWidth(160 if visible else 30)
                content.setMaximumWidth(420 if visible else 30)
                sizes = self.splitter.sizes() if hasattr(self, 'splitter') else []
                if len(sizes) == 3:
                    total = max(1, sum(sizes))
                    left_w = self.left_shell.width() if hasattr(self, 'left_shell') else sizes[0]
                    right_w = 220 if visible else 30
                    center_w = max(320, total - left_w - right_w)
                    self.splitter.setSizes([left_w, center_w, right_w])

        if hasattr(self, 'preview'):
            try:
                self.preview.fit_view()
            except Exception:
                pass

    def _library_password_file(self) -> Path:
        """Password file for the library editor lock.

        Stored beside the main script when possible, otherwise in the current folder.
        Default password is 172752266.  The file stores only SHA-256 hash, not plain text.
        """
        try:
            base = Path(__file__).resolve().parent
        except Exception:
            base = Path.cwd()
        return base / "nevis_library_editor_password.json"

    def _library_password_hash(self, text: str) -> str:
        return hashlib.sha256((text or "").encode("utf-8")).hexdigest()

    def _load_library_password_hash(self) -> str:
        default_hash = self._library_password_hash("172752266")
        p = self._library_password_file()
        try:
            if p.exists():
                data = json.loads(p.read_text(encoding="utf-8-sig"))
                h = str(data.get("sha256", "")).strip()
                return h or default_hash
        except Exception:
            pass
        return default_hash

    def _save_library_password_hash(self, h: str):
        p = self._library_password_file()
        try:
            p.write_text(json.dumps({"sha256": h}, ensure_ascii=False, indent=2), encoding="utf-8")
        except Exception as e:
            QMessageBox.warning(self, "NEVIS", str(e))

    def change_library_editor_password(self):
        old, ok = QInputDialog.getText(self, self.tr("library_editor_change_password"), self.tr("library_editor_old_password"), QLineEdit.Password)
        if not ok:
            return
        if self._library_password_hash(old) != self._load_library_password_hash():
            QMessageBox.warning(self, self.tr("library_editor_title"), self.tr("library_editor_wrong_password"))
            return
        new, ok = QInputDialog.getText(self, self.tr("library_editor_change_password"), self.tr("library_editor_new_password"), QLineEdit.Password)
        if not ok or not new:
            return
        self._save_library_password_hash(self._library_password_hash(new))
        QMessageBox.information(self, self.tr("library_editor_change_password"), self.tr("library_editor_password_changed"))

    def open_library_editor_secure(self):
        msg = QMessageBox(self)
        msg.setWindowTitle(self.tr("library_editor_title"))
        msg.setText(self.tr("library_editor_password"))
        btn_open = msg.addButton(self.tr("library_editor"), QMessageBox.AcceptRole)
        btn_change = msg.addButton(self.tr("library_editor_change_password"), QMessageBox.ActionRole)
        msg.addButton(QMessageBox.Cancel)
        msg.exec()
        clicked = msg.clickedButton()
        if clicked == btn_change:
            self.change_library_editor_password()
            return
        if clicked != btn_open:
            return
        pw, ok = QInputDialog.getText(self, self.tr("library_editor_title"), self.tr("library_editor_password"), QLineEdit.Password)
        if not ok:
            return
        if self._library_password_hash(pw) != self._load_library_password_hash():
            QMessageBox.warning(self, self.tr("library_editor_title"), self.tr("library_editor_wrong_password"))
            return
        self.launch_library_editor()

    def launch_library_editor(self):
        try:
            base = Path(__file__).resolve().parent
        except Exception:
            base = Path.cwd()
        candidates = [
            base / "Nevis_JSON_Library_Editor_FINAL_i18n.py",
            base / "Nevis_JSON_Library_Editor_FINAL.py",
            Path.cwd() / "Nevis_JSON_Library_Editor_FINAL_i18n.py",
            Path.cwd() / "Nevis_JSON_Library_Editor_FINAL.py",
        ]
        editor = next((x for x in candidates if x.exists()), None)
        if editor is None:
            QMessageBox.warning(self, "NEVIS", self.tr("library_editor_not_found") + "\nNevis_JSON_Library_Editor_FINAL_i18n.py")
            return
        env = os.environ.copy()
        env["NEVIS_LANG"] = getattr(self, "lang", "vi")
        env["NEVIS_LIBRARY_ROOT"] = str((base / "Library") if (base / "Library").exists() else base)
        try:
            subprocess.Popen([sys.executable, str(editor)], cwd=str(editor.parent), env=env)
        except Exception as e:
            QMessageBox.warning(self, "NEVIS", str(e))


    def resolve_app_icon_path(self) -> Optional[Path]:
        """Find Icon/icon_tan.ico next to the EXE/PY so copying the whole folder keeps the icon working."""
        candidates: List[Path] = []
        try:
            candidates.append(Path(sys.argv[0]).resolve().parent / "Icon" / "icon_tan.ico")
        except Exception:
            pass
        try:
            candidates.append(Path(__file__).resolve().parent / "Icon" / "icon_tan.ico")
        except Exception:
            pass
        candidates.append(Path.cwd() / "Icon" / "icon_tan.ico")
        candidates.append(nevis_app_dir() / "Icon" / "icon_tan.ico")
        for c in candidates:
            if c.exists():
                return c
        # Last fallback: search one level down from app dir. Useful after copying folders.
        try:
            for c in nevis_app_dir().glob("**/icon_tan.ico"):
                if c.name.lower() == "icon_tan.ico":
                    return c
        except Exception:
            pass
        return None

