    def toggle_detail_preview(self, checked: bool = False):
        """Switch between editable design mode and read-only detailed preview.

        Detail preview is only for checking before JWW output.  It must not modify the
        model, export files, or trigger extra recalculation while the user is inspecting.
        """
        self.preview_detail_mode = bool(checked)
        self._set_detail_readonly_state(self.preview_detail_mode)
        if hasattr(self, "btn_detail_preview"):
            try:
                self.btn_detail_preview.setChecked(self.preview_detail_mode)
                self.btn_detail_preview.setText(self.tr("end_detail_preview") if self.preview_detail_mode else self.tr("detail_preview"))
            except Exception:
                pass
        # Redraw once when entering/leaving; after that selection only updates info/preview.
        self.preview.draw_model()
        self.update_reducer_buttons()
        self.update_branch_material_buttons()

