    def load_temp(self, path: str):
        try:
            self.input_path = path
            self.jww_background_items = parse_jww_background_geometry(path)
            lines, hp = parse_jww_temp(path)
            if not lines:
                QMessageBox.warning(self,"NEVIS", "Đã đọc nền JWW nhưng chưa nhận được tim ống.\nHãy quét cả nền + tim ống, rồi chọn điểm đầu nhánh nằm đúng trên tim ống.\nNEVIS sẽ tự lấy layer/màu/nét của đường tại điểm đầu nhánh làm layer tim ống.")
                self.preview.draw_model(); self.preview.fit_view()
                self.lbl_status.setText(f"Đã đọc nền JWW {len(getattr(self, 'jww_background_items', []) or [])} đối tượng | Chưa nhận được tim ống")
                return
            self.model = build_graph(lines, hp)
            write_graph_diagnostic(self.model)
            ginfo = graph_diagnostic_summary(self.model)
            # Do not unlock operation panels automatically after reading temp.txt.
            # User must confirm the common settings first by pressing Apply.
            self.update_workflow_state(False)
            self.preview.draw_model(); self.preview.fit_view()
            warn = ""
            if ginfo.get("check_nodes_4plus", 0):
                warn = f" | CẢNH BÁO: {ginfo['check_nodes_4plus']} node >=4 nhánh cần kiểm tra"
            if ginfo.get("disconnected_nodes", 0):
                warn += f" | {ginfo['disconnected_nodes']} node rời mạng"
            bg_count = len(getattr(self, "jww_background_items", []) or [])
            self.lbl_status.setText(
                f"Đã đọc {len(lines)} đoạn tim ống | Nền JWW {bg_count} đối tượng | Node {ginfo['nodes']} | Edge {ginfo['edges']} | Điểm đầu {ginfo.get('base_nodes',0)} | Đầu mút {ginfo['end_nodes']} | Giao 3 {ginfo['junction_3_nodes']}{warn}. Kiểm tra thiết lập rồi bấm Áp dụng"
            )
        except Exception as e:
            QMessageBox.critical(self,"NEVIS error", str(e))


    def toggle_measure_mode(self, checked: bool = False):
        self.measure_mode = bool(checked)
        self.measure_points = []
        if hasattr(self, "lbl_status"):
            self.lbl_status.setText(self.tr("measure_click1") if checked else self.tr("status_wait"))
        if hasattr(self, "btn_measure"):
            self.btn_measure.setChecked(self.measure_mode)

    def clear_measurements(self):
        for it in list(getattr(self, "measure_items", [])):
            try:
                self.preview.scene.removeItem(it)
            except Exception:
                pass
        self.measure_items = []
        self.measure_points = []
        if hasattr(self, "lbl_status"):
            self.lbl_status.setText(self.tr("status_wait"))

    def _snap_measure_point(self, sx: float, sy: float) -> Tuple[float, float]:
        """Snap measure point to a node or pipe centerline in displayed scene coordinates."""
        best = (sx, sy)
        best_d = 45.0
        m = self.model
        for n in m.nodes.values():
            dx, dy = display_point(n.x, n.y)
            d = math.hypot(sx - dx, sy - dy)
            if d < best_d:
                best_d = d
                best = (dx, dy)
        for e in m.edges:
            if e.a not in m.nodes or e.b not in m.nodes:
                continue
            n1, n2 = m.nodes[e.a], m.nodes[e.b]
            ax, ay = display_point(n1.x, n1.y)
            bx, by = display_point(n2.x, n2.y)
            d, t, qx, qy = dist_point_to_segment(sx, sy, ax, ay, bx, by)
            if d < best_d:
                best_d = d
                best = (qx, qy)
        return best

    def add_measure_point(self, sx: float, sy: float):
        x, y = self._snap_measure_point(sx, sy)
        r = 4.0
        pen = QPen(QColor(220, 70, 20), 1.5); pen.setCosmetic(True)
        brush = QBrush(QColor(255, 240, 160))
        dot = self.preview.scene.addEllipse(x-r, y-r, r*2, r*2, pen, brush)
        dot.setZValue(1000)
        self.measure_items.append(dot)
        self.measure_points.append((x, y))
        if len(self.measure_points) == 1:
            self.lbl_status.setText(self.tr("measure_click2"))
            return
        x1, y1 = self.measure_points[-2]
        x2, y2 = self.measure_points[-1]
        line_pen = QPen(QColor(220, 70, 20), 1.3); line_pen.setCosmetic(True); line_pen.setStyle(Qt.DashLine)
        ln = self.preview.scene.addLine(x1, y1, x2, y2, line_pen)
        ln.setZValue(999)
        dist = math.hypot(x2 - x1, y2 - y1)
        txt = self.preview.scene.addText(f"{dist:.1f} mm", QFont("Segoe UI", 8, QFont.Bold))
        txt.setDefaultTextColor(QColor(190, 60, 20))
        txt.setPos((x1+x2)/2 + 8, (y1+y2)/2 + 8)
        txt.setZValue(1001)
        self.measure_items.extend([ln, txt])
        self.measure_points = []
        self.lbl_status.setText(self.tr("measure_result").format(dist=dist))

    def open_level_manager(self):
        dlg = LevelManagerDialog(getattr(self.model, "level_datums", {}), self)
        if dlg.exec() == QDialog.Accepted:
            self.model.level_datums = dlg.level_datums()
            self.update_node_level_choices()
            msg = self.tr("level_manager_saved")
            self.lbl_status.setText(msg if msg != "level_manager_saved" else "Đã cập nhật LevelDatum")

    def open_elevation_preview(self):
        dialog = getattr(self, "elevation_preview_dialog", None)
        if dialog is None:
            dialog = ElevationPreviewDialog(self)
            self.elevation_preview_dialog = dialog
        dialog.retranslate_ui()
        dialog.show()
        dialog.raise_()
        dialog.activateWindow()

    def update_node_level_choices(self):
        if not hasattr(self, "cmb_node_level"):
            return
        current = ""
        if getattr(self, "selected_node", None) in getattr(self.model, "nodes", {}):
            current = str(getattr(self.model.nodes[self.selected_node], "level_id", "") or "")
        combo = self.cmb_node_level
        combo.blockSignals(True)
        try:
            combo.clear()
            combo.addItem(self.tr("elevation_none"), "")
            ids = sorted(str(k) for k in getattr(self.model, "level_datums", {}).keys() if str(k).strip())
            for datum_id in ids:
                combo.addItem(datum_id, datum_id)
            if current and current not in ids:
                combo.addItem(current, current)
            idx = combo.findData(current)
            combo.setCurrentIndex(idx if idx >= 0 else 0)
            enabled = getattr(self, "selected_node", None) in getattr(self.model, "nodes", {})
            combo.setEnabled(enabled)
            if hasattr(self, "edit_node_z"):
                node_z = None
                if enabled:
                    node_z = getattr(self.model.nodes[self.selected_node], "z", None)
                self.edit_node_z.setText("" if node_z is None else f"{float(node_z):g}")
                self.edit_node_z.setEnabled(enabled)
            if hasattr(self, "btn_apply_node_level"):
                self.btn_apply_node_level.setEnabled(enabled)
        finally:
            combo.blockSignals(False)

    def _level_id_from_combo(self, combo: QComboBox) -> str:
        data = combo.currentData()
        if data not in (None, ""):
            return str(data).strip()
        text = combo.currentText().strip()
        return "" if text in ("None", self.tr("elevation_none")) else text

    def _warn_unknown_level_id(self, level_id: str):
        if level_id and level_id not in getattr(self.model, "level_datums", {}):
            QMessageBox.warning(self, "Elevation Metadata", f"Level ID is not defined in LevelDatum: {level_id}")

    def apply_selected_node_level(self):
        nid = getattr(self, "selected_node", None)
        if nid not in getattr(self.model, "nodes", {}):
            return
        combo = getattr(self, "cmb_node_level", None)
        if combo is None:
            return
        node_z, error = validate_node_z_input(self.edit_node_z.text())
        if error:
            if hasattr(self, "lbl_status"):
                self.lbl_status.setText(error)
            return
        level_id = self._level_id_from_combo(combo)
        self._warn_unknown_level_id(level_id)
        self.model.nodes[nid].level_id = str(level_id or "")
        self.model.nodes[nid].z = 0.0 if node_z is None else node_z
        for edge in getattr(self.model, "edges", []):
            if nid not in (edge.a, edge.b):
                continue
            start_node = self.model.nodes.get(edge.a)
            end_node = self.model.nodes.get(edge.b)
            edge.slope = compute_edge_slope(
                getattr(start_node, "z", None),
                getattr(end_node, "z", None),
                self.model.edge_length(edge),
            )
        self.update_node_level_choices()
        self.update_selected_elevation_summary()
        if hasattr(self, "lbl_status"):
            self.lbl_status.setText(f"Node {nid} elevation metadata updated")

    def _selected_edge_obj(self) -> Optional[Edge]:
        key = getattr(self, "selected_edge", None)
        if not key:
            return None
        return next((e for e in getattr(self.model, "edges", []) if e.key == key), None)

    def get_pipe_start_node(self, pipe: Edge) -> Optional[Node]:
        return getattr(self.model, "nodes", {}).get(pipe.a)

    def get_pipe_end_node(self, pipe: Edge) -> Optional[Node]:
        return getattr(self.model, "nodes", {}).get(pipe.b)

    def _fill_level_combo(self, combo: QComboBox, current: Optional[str]):
        combo.blockSignals(True)
        try:
            combo.clear()
            combo.addItem(self.tr("elevation_none"), "")
            ids = sorted(str(k) for k in getattr(self.model, "level_datums", {}).keys() if str(k).strip())
            for datum_id in ids:
                combo.addItem(datum_id, datum_id)
            current_s = str(current or "")
            if current_s and current_s not in ids:
                combo.addItem(current_s, current_s)
            idx = combo.findData(current_s)
            combo.setCurrentIndex(idx if idx >= 0 else 0)
        finally:
            combo.blockSignals(False)

    def update_pipe_elevation_controls(self):
        if not hasattr(self, "g_pipe_elev"):
            return
        edge = self._selected_edge_obj()
        has_node = getattr(self, "selected_node", None) in getattr(self.model, "nodes", {})
        has_pipe = edge is not None
        enabled = has_pipe or has_node
        self.g_pipe_elev.setVisible(ELEVATION_UI_ENABLED and enabled)
        self.g_pipe_elev.setEnabled(enabled)
        if hasattr(self, "w_node_elev"):
            self.w_node_elev.setVisible(has_node and not has_pipe)
        if hasattr(self, "w_pipe_elev"):
            self.w_pipe_elev.setVisible(has_pipe)
        self._fill_level_combo(self.cmb_pipe_start_level, getattr(edge, "start_level_id", None) if edge else None)
        self._fill_level_combo(self.cmb_pipe_end_level, getattr(edge, "end_level_id", None) if edge else None)
        self.edit_pipe_start_z.setText("" if edge is None or edge.start_z is None else f"{float(edge.start_z):g}")
        self.edit_pipe_end_z.setText("" if edge is None or edge.end_z is None else f"{float(edge.end_z):g}")
        self.edit_pipe_slope_percent.setText("" if edge is None or edge.slope_percent is None else f"{float(edge.slope_percent):g}")
        self.chk_pipe_elevation_locked.setChecked(bool(edge.elevation_locked) if edge else False)

    def _parse_optional_float_field(self, edit: QLineEdit, label: str) -> Optional[float]:
        text = edit.text().strip()
        if not text:
            return None
        try:
            return float(text)
        except Exception:
            QMessageBox.warning(self, "Pipe Elevation", f"{label} must be a number or blank.")
            raise

    def apply_selected_pipe_elevation(self):
        edge = self._selected_edge_obj()
        if edge is None:
            return
        try:
            start_z = self._parse_optional_float_field(self.edit_pipe_start_z, "Start Z")
            end_z = self._parse_optional_float_field(self.edit_pipe_end_z, "End Z")
            slope_percent = self._parse_optional_float_field(self.edit_pipe_slope_percent, "Slope %")
        except Exception:
            return
        start_level_id = self._level_id_from_combo(self.cmb_pipe_start_level)
        end_level_id = self._level_id_from_combo(self.cmb_pipe_end_level)
        self._warn_unknown_level_id(start_level_id)
        self._warn_unknown_level_id(end_level_id)
        edge.start_level_id = start_level_id or None
        edge.end_level_id = end_level_id or None
        edge.start_z = start_z
        edge.end_z = end_z
        edge.slope_percent = slope_percent
        edge.elevation_locked = bool(self.chk_pipe_elevation_locked.isChecked())
        self.update_pipe_elevation_controls()
        if hasattr(self, "lbl_status"):
            self.lbl_status.setText(f"Pipe {edge.key} elevation metadata updated")

    def apply_selected_pipe_elevation_to_nodes(self):
        edge = self._selected_edge_obj()
        if edge is None:
            return
        start_node = self.get_pipe_start_node(edge)
        end_node = self.get_pipe_end_node(edge)
        if start_node is None or end_node is None:
            return
        if edge.start_z is not None:
            start_node.z = float(edge.start_z)
        if edge.end_z is not None:
            end_node.z = float(edge.end_z)
        if edge.start_level_id:
            start_node.level_id = str(edge.start_level_id)
        if edge.end_level_id:
            end_node.level_id = str(edge.end_level_id)
        self.update_node_level_choices()
        self.update_pipe_elevation_controls()
        self.update_selected_elevation_summary()
        self.refresh_elevation_report()
        if hasattr(self, "lbl_status"):
            self.lbl_status.setText(f"Pipe {edge.key} elevation applied to nodes")

    def sync_selected_pipe_elevation_from_nodes(self):
        edge = self._selected_edge_obj()
        if edge is None:
            return
        start_node = self.get_pipe_start_node(edge)
        end_node = self.get_pipe_end_node(edge)
        if start_node is None or end_node is None:
            return
        if start_node.z is not None:
            edge.start_z = float(start_node.z)
        if end_node.z is not None:
            edge.end_z = float(end_node.z)
        if getattr(start_node, "level_id", ""):
            edge.start_level_id = str(start_node.level_id)
        if getattr(end_node, "level_id", ""):
            edge.end_level_id = str(end_node.level_id)
        self.update_pipe_elevation_controls()
        self.update_selected_elevation_summary()
        self.refresh_elevation_report()
        if hasattr(self, "lbl_status"):
            self.lbl_status.setText(f"Pipe {edge.key} elevation synced from nodes")

    def _edge_between_nodes(self, a: int, b: int) -> Optional[Edge]:
        key = edge_key(a, b)
        return next((e for e in getattr(self.model, "edges", []) if e.key == key), None)

    def _set_edge_z_for_direction(self, edge: Edge, from_node: int, current_z: float, next_z: float):
        if edge.a == from_node:
            edge.start_z = float(current_z)
            edge.end_z = float(next_z)
        else:
            edge.start_z = float(next_z)
            edge.end_z = float(current_z)

    def _simple_chain_start(self) -> Tuple[Optional[int], Optional[Edge]]:
        edge = self._selected_edge_obj()
        if edge is not None:
            return edge.a, edge
        nid = getattr(self, "selected_node", None)
        if nid not in getattr(self.model, "nodes", {}):
            return None, None
        neighbors = self.model.neighbors(nid)
        if len(neighbors) != 1:
            return nid, None
        return nid, self._edge_between_nodes(nid, neighbors[0])

    def propagate_simple_chain_elevation(self):
        try:
            start_z = self._parse_optional_float_field(self.edit_pipe_start_z, "Start Z")
            slope_percent = self._parse_optional_float_field(self.edit_pipe_slope_percent, "Slope %")
        except Exception:
            return
        if start_z is None or slope_percent is None:
            QMessageBox.warning(self, "Elevation Propagation", "Start Z and Slope % are required.")
            return
        start_node_id, first_edge = self._simple_chain_start()
        if start_node_id is None or first_edge is None:
            QMessageBox.warning(self, "Elevation Propagation", "Select a start pipe or an end node of a simple chain.")
            return
        if start_node_id not in self.model.nodes:
            return

        warnings = []
        current_node_id = int(start_node_id)
        current_z = float(start_z)
        previous_node_id = None
        next_edge = first_edge
        self.model.nodes[current_node_id].z = current_z

        while next_edge is not None:
            if next_edge.a == current_node_id:
                next_node_id = next_edge.b
            elif next_edge.b == current_node_id:
                next_node_id = next_edge.a
            else:
                break
            length_2d = self.model.edge_length(next_edge)
            if length_2d <= 0:
                warnings.append("zero_length_pipe")
                break
            next_z = current_z - float(length_2d) * float(slope_percent) / 100.0
            self._set_edge_z_for_direction(next_edge, current_node_id, current_z, next_z)
            next_edge.slope_percent = float(slope_percent)
            if current_node_id in self.model.nodes:
                self.model.nodes[current_node_id].z = float(current_z)
            if next_node_id in self.model.nodes:
                self.model.nodes[next_node_id].z = float(next_z)

            degree = self.model.degree(next_node_id)
            if degree > 2:
                warnings.append(f"branch_stopped_at_node_{next_node_id}")
                break

            candidates = [n for n in self.model.neighbors(next_node_id) if n != current_node_id]
            if not candidates:
                break
            previous_node_id = current_node_id
            current_node_id = next_node_id
            current_z = next_z
            next_edge = self._edge_between_nodes(current_node_id, candidates[0])
            if previous_node_id == current_node_id:
                break

        self.update_pipe_elevation_controls()
        self.update_selected_elevation_summary()
        self.refresh_elevation_report()
        if warnings:
            QMessageBox.warning(self, "Elevation Propagation", ", ".join(warnings))
        if hasattr(self, "lbl_status"):
            suffix = f" ({', '.join(warnings)})" if warnings else ""
            self.lbl_status.setText(f"Simple chain elevation propagated{suffix}")

    def _fmt_optional_number(self, value) -> str:
        return "None" if value is None else f"{float(value):g}"

    def _pipe_has_elevation_metadata(self, edge: Edge) -> bool:
        return any([
            bool(getattr(edge, "start_level_id", None)),
            bool(getattr(edge, "end_level_id", None)),
            getattr(edge, "start_z", None) is not None,
            getattr(edge, "end_z", None) is not None,
            getattr(edge, "slope_percent", None) is not None,
            bool(getattr(edge, "elevation_locked", False)),
        ])

    def _set_elevation_report_column_widths(self):
        table = getattr(self, "table_elevation_report", None)
        if table is None:
            return
        for col, width in enumerate([72, 112, 112, 82, 82, 140]):
            table.setColumnWidth(col, width)

    def refresh_elevation_report(self):
        table = getattr(self, "table_elevation_report", None)
        if table is None:
            return
        rows = []
        for edge in getattr(self.model, "edges", []):
            if not self._pipe_has_elevation_metadata(edge):
                continue
            calc = self.calculate_pipe_elevation_preview(edge)
            warnings = self.check_pipe_elevation_consistency(edge)
            start_text = f"{str(getattr(edge, 'start_level_id', '') or '')} / {self._fmt_optional_number(getattr(edge, 'start_z', None))}".strip()
            end_text = f"{str(getattr(edge, 'end_level_id', '') or '')} / {self._fmt_optional_number(getattr(edge, 'end_z', None))}".strip()
            rows.append([
                edge.key,
                start_text,
                end_text,
                self._fmt_optional_number(calc["pipe_length_2d"]),
                self._fmt_optional_number(calc["computed_slope_percent"]),
                ", ".join(warnings) if warnings else "OK",
            ])
        table.setRowCount(len(rows))
        for row, values in enumerate(rows):
            for col, value in enumerate(values):
                item = QTableWidgetItem(str(value))
                item.setFlags(item.flags() & ~Qt.ItemIsEditable)
                table.setItem(row, col, item)
        self._set_elevation_report_column_widths()
        if hasattr(self, "lbl_status"):
            self.lbl_status.setText(f"Elevation report refreshed: {len(rows)} pipes")

    def calculate_pipe_elevation_preview(self, edge: Edge) -> Dict[str, Optional[float]]:
        def _resolve_z(explicit_z, level_id) -> Optional[float]:
            if explicit_z is not None:
                try:
                    return float(explicit_z)
                except Exception:
                    return None
            level_key = str(level_id or "").strip()
            if not level_key:
                return None
            datum = getattr(self.model, "level_datums", {}).get(level_key)
            if datum is None:
                return None
            try:
                return float(datum.elevation_mm)
            except Exception:
                return None

        try:
            length_2d = float(self.model.edge_length(edge))
        except Exception:
            length_2d = None
        start_z = _resolve_z(getattr(edge, "start_z", None), getattr(edge, "start_level_id", None))
        end_z = _resolve_z(getattr(edge, "end_z", None), getattr(edge, "end_level_id", None))
        delta_z = None
        slope_percent = None
        if start_z is not None and end_z is not None:
            delta_z = end_z - start_z
            if length_2d is not None and length_2d > 0:
                slope_percent = delta_z / length_2d * 100.0
        return {
            "resolved_start_z": start_z,
            "resolved_end_z": end_z,
            "delta_z": delta_z,
            "pipe_length_2d": length_2d,
            "computed_slope_percent": slope_percent,
        }

    def check_pipe_elevation_consistency(self, edge: Edge) -> List[str]:
        warnings = []
        level_datums = getattr(self.model, "level_datums", {})
        start_level_id = str(getattr(edge, "start_level_id", None) or "").strip()
        end_level_id = str(getattr(edge, "end_level_id", None) or "").strip()
        has_start_z = getattr(edge, "start_z", None) is not None
        has_end_z = getattr(edge, "end_z", None) is not None

        if not has_start_z and not start_level_id:
            warnings.append("missing_start_elevation")
        if not has_end_z and not end_level_id:
            warnings.append("missing_end_elevation")
        if (start_level_id and start_level_id not in level_datums) or (end_level_id and end_level_id not in level_datums):
            warnings.append("missing_level_datum")

        calc = self.calculate_pipe_elevation_preview(edge)
        if calc["pipe_length_2d"] == 0:
            warnings.append("zero_length_pipe")

        entered_slope = getattr(edge, "slope_percent", None)
        computed_slope = calc["computed_slope_percent"]
        if entered_slope is not None and computed_slope is not None:
            try:
                if abs(float(entered_slope) - float(computed_slope)) > 0.01:
                    warnings.append("slope_mismatch")
            except Exception:
                pass

        if bool(getattr(edge, "elevation_locked", False)) and (
            calc["resolved_start_z"] is None or calc["resolved_end_z"] is None
        ):
            warnings.append("locked_but_incomplete")
        return warnings

    def update_selected_elevation_summary(self):
        if not ELEVATION_UI_ENABLED:
            return
        if not hasattr(self, "lbl_detail"):
            return
        nid = getattr(self, "selected_node", None)
        if nid in getattr(self.model, "nodes", {}):
            n = self.model.nodes[nid]
            level = str(getattr(n, "level_id", "") or "None")
            z = self._fmt_optional_number(getattr(n, "z", None))
            self.lbl_detail.setText(
                self.tr("coord_degree_fmt").format(x=n.x, y=n.y, deg=self.model.degree(nid))
                + f" | Level: {level} | Z: {z}"
            )
            return
        edge = self._selected_edge_obj()
        if edge is not None:
            length = self.model.edge_length(edge) / 1000.0
            mat = self.edge_material(edge)
            pipe_name = f"{edge.size}{self.pipe_prefix(mat)}"
            start_level = str(edge.start_level_id or "None")
            end_level = str(edge.end_level_id or "None")
            start_z = self._fmt_optional_number(edge.start_z)
            end_z = self._fmt_optional_number(edge.end_z)
            slope = self._fmt_optional_number(edge.slope_percent)
            locked = "ON" if bool(edge.elevation_locked) else "OFF"
            calc = self.calculate_pipe_elevation_preview(edge)
            calc_start_z = self._fmt_optional_number(calc["resolved_start_z"])
            calc_end_z = self._fmt_optional_number(calc["resolved_end_z"])
            calc_delta_z = self._fmt_optional_number(calc["delta_z"])
            calc_length = self._fmt_optional_number(calc["pipe_length_2d"])
            calc_slope = self._fmt_optional_number(calc["computed_slope_percent"])
            consistency_warnings = self.check_pipe_elevation_consistency(edge)
            warning_text = ", ".join(consistency_warnings) if consistency_warnings else "none"
            self.lbl_detail.setText(
                f"{pipe_name}   |   {length:.3f} m"
                f" | {self.tr('elevation_report_start')}: {start_level} / Z {start_z}"
                f" | {self.tr('elevation_report_end')}: {end_level} / Z {end_z}"
                f" | {self.tr('elevation_slope')}: {slope}"
                f" | {self.tr('elevation_locked')}: {locked}"
                f" | {self.tr('elevation_calc_preview')}: Z {calc_start_z}->{calc_end_z}, dZ {calc_delta_z}, L2D {calc_length}, {self.tr('elevation_slope')} {calc_slope}%"
                f" | {self.tr('elevation_warnings')}: {warning_text}"
            )

    def _project_payload(self) -> Dict[str, object]:
        return {
            "version": 54,
            "model_schema_version": max(2, int(getattr(self.model, "model_schema_version", 1) or 1)),
            "lang": self.lang,
            "workspace_mode": serialize_workspace_mode(getattr(self, "workspace_mode", get_default_mode()))["workspace_mode"],
            "drawing_scale": float(getattr(self.model, "drawing_scale", 1.0) or 1.0),
            "scale_origin": list(getattr(self.model, "scale_origin", (0.0, 0.0))),
            "nodes": {str(k): {"x": v.x, "y": v.y, "z": v.z, "level_id": v.level_id} for k, v in self.model.nodes.items()},
            "edges": [{"a": e.a, "b": e.b, "size": e.size, "material_override": e.material_override, "slope": e.slope, "vertical_type": e.vertical_type, "elevation_mode": e.elevation_mode, "system_type": e.system_type, "start_level_id": e.start_level_id, "end_level_id": e.end_level_id, "start_z": e.start_z, "end_z": e.end_z, "slope_percent": e.slope_percent, "elevation_locked": bool(e.elevation_locked)} for e in self.model.edges],
            "level_datums": {str(k): {"id": d.id, "name": d.name, "elevation_mm": d.elevation_mm, "datum_type": d.datum_type, "floor_index": d.floor_index, "description": d.description} for k, d in getattr(self.model, "level_datums", {}).items()},
            "fittings": {str(k): {"node_id": f.node_id, "ftype": f.ftype, "size": f.size, "manual": f.manual, "excluded": f.excluded, "material_override": f.material_override} for k, f in self.model.fittings.items()},
            "bushings": list(getattr(self.model, "bushings", [])),
            "structural_elements": [__import__("modules.structural_element", fromlist=["structural_element_to_dict"]).structural_element_to_dict(e) for e in getattr(self.model, "structural_elements", [])],
            "base_node": self.model.base_node,
            "base_nodes": sorted(list(getattr(self.model, "base_nodes", set()))),
            "selected_node": self.selected_node,
            "selected_edge": self.selected_edge,
            "selected_bushing_id": getattr(self, "selected_bushing_id", None),
            "settings": {
                "project": self.edit_project.text() if hasattr(self, "edit_project") else "",
                "system": self.cmb_system.currentText() if hasattr(self, "cmb_system") else "排水 / Thoát nước",
                "main_size": self.cmb_main_size.currentText() if hasattr(self, "cmb_main_size") else "",
                "branch_rule": self.cmb_branch_rule.currentText() if hasattr(self, "cmb_branch_rule") else "Giảm 1 bậc",
                "branch_size": self.cmb_branch_size.currentText() if hasattr(self, "cmb_branch_size") else "",
                "start_fitting": self.cmb_start_fitting.currentText() if hasattr(self, "cmb_start_fitting") else "集合管",
                "system_items": self._combo_items(self.cmb_system) if hasattr(self, "cmb_system") else [],
                "pipe_size_items": self._combo_items(self.cmb_main_size) if hasattr(self, "cmb_main_size") else [],
                "start_fitting_items": self._combo_items(self.cmb_start_fitting) if hasattr(self, "cmb_start_fitting") else [],
                "terminal_items": self._combo_items(self.cmb_terminal) if hasattr(self, "cmb_terminal") else [],
                "fire_len": self.edit_fire_len.text() if hasattr(self, "edit_fire_len") else "1200",
                "fire_mat": self.cmb_fire_mat.currentText() if hasattr(self, "cmb_fire_mat") else "TMP",
                "normal_mat": self.cmb_normal_mat.currentText() if hasattr(self, "cmb_normal_mat") else "VP/VU",
                "support_enabled": bool(getattr(self, "support_enabled", False)),
                "support_spacing": float(getattr(self, "support_spacing", 900.0)),
                "support_kind": getattr(self, "support_kind", "レベル"),
                "support_visible": bool(getattr(self, "support_visible", False)),
                "detail_mode": bool(getattr(self, "preview_detail_mode", False)),
            },
        }

    def save_project(self):
        if self._block_if_detail_readonly():
            return
        default = self.current_project_path or str(Path.home() / "Desktop" / f"{self.edit_project.text().strip() or 'NEVIS_Project'}.nevis.json")
        path, _ = QFileDialog.getSaveFileName(self, self.tr("save_project"), default, "NEVIS Project (*.nevis.json);;JSON (*.json)")
        if not path:
            return
        if not path.lower().endswith((".nevis.json", ".json")):
            path += ".nevis.json"
        Path(path).write_text(json.dumps(self._project_payload(), ensure_ascii=False, indent=2), encoding="utf-8")
        self.current_project_path = path
        self.lbl_status.setText(self.tr("project_saved"))

    def open_project(self):
        if self._block_if_detail_readonly():
            return
        path, _ = QFileDialog.getOpenFileName(self, self.tr("open_project"), "", "NEVIS Project (*.nevis.json *.json);;JSON (*.json);;All files (*.*)")
        if not path:
            return
        data = json.loads(Path(path).read_text(encoding="utf-8"))
        m = PipeModel()
        m.model_schema_version = int(data.get("model_schema_version", 1))
        try:
            m.drawing_scale = max(EPS, float(data.get("drawing_scale", 1.0) or 1.0))
            origin_data = data.get("scale_origin", [0.0, 0.0])
            m.scale_origin = (float(origin_data[0]), float(origin_data[1]))
        except (TypeError, ValueError, IndexError):
            m.drawing_scale = 1.0
            m.scale_origin = (0.0, 0.0)
        for k, v in data.get("nodes", {}).items():
            nid = int(k); m.nodes[nid] = node_from_project_data(nid, v)
        for e in data.get("edges", []):
            m.edges.append(edge_from_project_data(e))
        try:
            from modules.structural_element import structural_element_from_dict
            m.structural_elements = [structural_element_from_dict(d) for d in data.get("structural_elements", [])]
        except Exception:
            m.structural_elements = []
        try:
            m.grid_axes = [grid_axis_from_dict(d) for d in data.get("grid_axes", [])]
        except Exception:
            m.grid_axes = []
        for k, d in data.get("level_datums", {}).items():
            try:
                if not isinstance(d, dict):
                    continue
                datum_id = str(d.get("id", k)).strip()
                if not datum_id:
                    continue
                floor_val = d.get("floor_index", None)
                m.level_datums[datum_id] = LevelDatum(
                    datum_id,
                    str(d.get("name", "")),
                    float(d.get("elevation_mm", 0.0)),
                    str(d.get("datum_type", "FL")),
                    None if floor_val in (None, "") else int(floor_val),
                    str(d.get("description", "")),
                )
            except Exception:
                continue
        for k, f in data.get("fittings", {}).items():
            nid = int(k); m.fittings[nid] = Fitting(nid, str(f.get("ftype", "")), str(f.get("size", "65")), bool(f.get("manual", False)), bool(f.get("excluded", False)), str(f.get("material_override", "")))
        m.bushings = [dict(x) for x in data.get("bushings", []) if isinstance(x, dict)]
        m.base_node = data.get("base_node")
        rebuild_flow(m)
        self.model = m
        self.selected_node = data.get("selected_node")
        self.selected_edge = data.get("selected_edge")
        self.selected_bushing_id = data.get("selected_bushing_id")
        st = data.get("settings", {})
        if hasattr(self, "edit_project") and st.get("project") is not None: self.edit_project.setText(str(st.get("project")))
        if hasattr(self, "cmb_system") and st.get("system") is not None: self.cmb_system.setCurrentText(str(st.get("system")))
        if hasattr(self, "cmb_main_size"): self.cmb_main_size.setCurrentText(str(st.get("main_size", "")))
        if hasattr(self, "cmb_branch_rule"):
            self._set_branch_rule_items(self._branch_rule_code_from_text(str(st.get("branch_rule", ""))))
        def _restore_combo_items(combo, key):
            vals = st.get(key, [])
            if vals and isinstance(vals, list):
                cur = combo.currentText()
                combo.clear(); combo.addItems([str(x) for x in vals if str(x).strip()])
                combo.setCurrentText(cur)
        if hasattr(self, "cmb_system"):
            self._set_combo_items_with_data(self.cmb_system, [("排水", "排水転がし配管")], keep_code="排水")
            self.cmb_system.setCurrentIndex(0)
            self.cmb_system.setVisible(False)
        if hasattr(self, "cmb_main_size"): _restore_combo_items(self.cmb_main_size, "pipe_size_items")
        if hasattr(self, "cmb_branch_size"): _restore_combo_items(self.cmb_branch_size, "pipe_size_items")
        if hasattr(self, "cmb_start_fitting"): _restore_combo_items(self.cmb_start_fitting, "start_fitting_items")
        if hasattr(self, "cmb_terminal"): _restore_combo_items(self.cmb_terminal, "terminal_items")
        if hasattr(self, "cmb_branch_size"): self.cmb_branch_size.setCurrentText(str(st.get("branch_size", "")))
        if hasattr(self, "cmb_start_fitting"): self.cmb_start_fitting.setCurrentText(str(st.get("start_fitting", "集合管")))
        if hasattr(self, "edit_fire_len"): self.edit_fire_len.setText(str(st.get("fire_len", "1200")))
        if hasattr(self, "cmb_fire_mat"): self.cmb_fire_mat.setCurrentText(str(st.get("fire_mat", "TMP")))
        if hasattr(self, "cmb_normal_mat"): self.cmb_normal_mat.setCurrentText(str(st.get("normal_mat", "VP/VU")))
        if hasattr(self, "chk_support_band"): self.chk_support_band.setChecked(bool(st.get("support_enabled", False)))
        if hasattr(self, "edit_support_spacing"): self.edit_support_spacing.setText(str(st.get("support_spacing", 900.0)))
        self.support_enabled = bool(st.get("support_enabled", False))
        self.support_spacing = float(st.get("support_spacing", 900.0))
        self.support_kind = str(st.get("support_kind", "レベル"))
        self.support_visible = bool(st.get("support_visible", False))
        if hasattr(self, "chk_show_support_band"):
            self.chk_show_support_band.setChecked(self.support_visible)
        self.preview_detail_mode = bool(st.get("detail_mode", False))
        if hasattr(self, "btn_detail_preview"):
            self.btn_detail_preview.setChecked(self.preview_detail_mode)
        self.set_workspace_mode(deserialize_workspace_mode(data))
        self.current_project_path = path
        self.clear_measurements()
        self.refresh_all()
        self.lbl_status.setText(self.tr("project_loaded"))

    def open_temp(self):
        p, _ = QFileDialog.getOpenFileName(self,"Open temp.txt", "", "Text (*.txt);;All files (*.*)")
        if p:
            self.load_temp(p)


    def common_config_path(self) -> Path:
        try:
            return Path(__file__).resolve().with_name("system_config.json")
        except Exception:
            return Path("system_config.json")

    def _branch_rule_code_from_text(self, text: str = "") -> str:
        text = str(text or (self.cmb_branch_rule.currentText() if hasattr(self, "cmb_branch_rule") else "")).lower()
        if "cố" in text or "固定" in text or "fixed" in text:
            return "fixed"
        if "bằng" in text or "同" in text or "same" in text:
            return "same"
        return "down"

    def _set_branch_rule_items(self, code: str = "down"):
        if not hasattr(self, "cmb_branch_rule"):
            return
        items = [("down", self.tr("branch_rule_down")), ("same", self.tr("branch_rule_same")), ("fixed", self.tr("branch_rule_fixed"))]
        self.cmb_branch_rule.blockSignals(True)
        self.cmb_branch_rule.clear()
        for c, label in items:
            self.cmb_branch_rule.addItem(label, c)
        idx = max(0, self.cmb_branch_rule.findData(code))
        self.cmb_branch_rule.setCurrentIndex(idx)
        self.cmb_branch_rule.blockSignals(False)

    def _refresh_branch_rule_language(self):
        if not hasattr(self, "cmb_branch_rule"):
            return
        code = self.cmb_branch_rule.currentData() or self._branch_rule_code_from_text()
        self._set_branch_rule_items(str(code))
        self.sync_branch_size_from_rule()


    def _upgrade_nevis_master_data(self, data: dict):
        """Add new fields to old nevis_master.json without deleting user settings."""
        try:
            default = copy.deepcopy(DEFAULT_NEVIS_MASTER)
            for key in ("systems", "materials", "fitting_groups"):
                by_code = {str(x.get("code", "")): x for x in default.get(key, []) if isinstance(x, dict)}
                for item in data.get(key, []) or []:
                    if not isinstance(item, dict):
                        continue
                    d = by_code.get(str(item.get("code", "")), {})
                    for kk, vv in d.items():
                        item.setdefault(kk, copy.deepcopy(vv))
            for mat in data.get("materials", []) or []:
                if isinstance(mat, dict):
                    for rk in ("start_groups", "end_groups"):
                        mat[rk] = [self.normalize_role_code(x) for x in mat.get(rk, []) or []]
            data.setdefault("version", 3)
            data.setdefault("name_rule", "{group}_{main}_{branch}_{note}")
        except Exception:
            pass

    def load_nevis_master_data(self) -> Dict[str, object]:
        """Load relational master DB. Falls back to DEFAULT_NEVIS_MASTER."""
        path = nevis_app_dir() / "nevis_master.json"
        try:
            if path.exists():
                data = json.loads(path.read_text(encoding="utf-8-sig"))
                for k, v in DEFAULT_NEVIS_MASTER.items():
                    # If old/corrupted nevis_master.json has empty lists, restore defaults.
                    if k in ("systems", "materials", "fitting_groups"):
                        if not data.get(k):
                            data[k] = copy.deepcopy(v)
                    else:
                        data.setdefault(k, copy.deepcopy(v))
                self._upgrade_nevis_master_data(data)
                if not data.get("name_rule"):
                    data["name_rule"] = "{group}_{main}_{branch}_{note}"
                return data
        except Exception:
            pass
        return copy.deepcopy(DEFAULT_NEVIS_MASTER)

    def _master_name(self, item: dict) -> str:
        if getattr(self, "lang", "vi") == "jp":
            return item.get("name_jp") or item.get("name_vi") or item.get("code", "")
        return item.get("name_vi") or item.get("name_jp") or item.get("code", "")

    def _find_master_item(self, data: dict, key: str, code: str) -> Optional[dict]:
        code = str(code or "")
        for item in data.get(key, []) or []:
            if str(item.get("code", "")) == code:
                return item
        return None

    def _combo_current_code(self, combo: QComboBox) -> str:
        try:
            data = combo.currentData()
            if data not in (None, ""):
                return str(data)
        except Exception:
            pass
        txt = combo.currentText().strip()
        # Labels may be like "排水 — Thoát nước".
        if " — " in txt:
            return txt.split(" — ", 1)[0].strip()
        return txt

    def _set_combo_items_with_data(self, combo: QComboBox, pairs: List[Tuple[str, str]], keep_code: str = ""):
        """Set combobox items with stable internal codes.

        Important fix: when the previous code is not available in the new system
        (for example switching from 給水/HIVP back to 排水/DV), do NOT keep the old
        text as a free value.  Keeping a stale value made the dependent start/end
        lists and library lookup refresh only after changing the system several
        times.  Instead, select the first valid item immediately.
        """
        old_code = keep_code or self._combo_current_code(combo)
        combo.blockSignals(True)
        combo.clear()
        for code, label in pairs:
            combo.addItem(label, code)
        if pairs:
            idx = combo.findData(old_code) if old_code else -1
            combo.setCurrentIndex(idx if idx >= 0 else 0)
        combo.blockSignals(False)

    def apply_master_to_common_controls(self):
        """Apply System -> Material -> Group relation to main UI comboboxes."""
        data = self.load_nevis_master_data()
        self._nevis_master_data = data
        # Systems: drainage-only mode. Keep internal code as 排水 so library lookup
        # continues to use existing 排水 folders/master data, but do not expose a system selector.
        if hasattr(self, "cmb_system"):
            self._set_combo_items_with_data(self.cmb_system, [("排水", "排水転がし配管")], keep_code="排水")
            self.cmb_system.setCurrentIndex(0)
            self.cmb_system.setVisible(False)
            try:
                with warnings.catch_warnings():
                    warnings.simplefilter("ignore", RuntimeWarning)
                    self.cmb_system.currentTextChanged.disconnect(self.update_master_dependent_combos)
            except Exception:
                pass
            self.cmb_system.currentTextChanged.connect(self.update_master_dependent_combos)
        if hasattr(self, "cmb_normal_mat"):
            try:
                with warnings.catch_warnings():
                    warnings.simplefilter("ignore", RuntimeWarning)
                    self.cmb_normal_mat.currentTextChanged.disconnect(self.update_master_dependent_combos)
            except Exception:
                pass
            self.cmb_normal_mat.currentTextChanged.connect(self.update_master_dependent_combos)
        self.update_master_dependent_combos()

    def update_master_dependent_combos(self):
        self._updating_master_combos = True
        # Library choices depend on system/material.  Clear path cache whenever
        # these comboboxes change, otherwise moved folders can keep resolving to
        # old TMP/DV paths until the app is restarted.
        try:
            _LIB_PATH_CACHE.clear()
        except Exception:
            pass
        data = getattr(self, "_nevis_master_data", None) or self.load_nevis_master_data()
        sys_code = self._combo_current_code(self.cmb_system) if hasattr(self, "cmb_system") else ""
        sys_item = self._find_master_item(data, "systems", sys_code) or (data.get("systems", []) or [{}])[0]
        material_codes = [str(x) for x in sys_item.get("materials", [])]
        materials = [m for m in data.get("materials", []) if str(m.get("code", "")) in material_codes]
        # If the system does not define materials yet, show all as fallback.
        if not materials:
            materials = data.get("materials", []) or []
        mat_pairs = []
        for m in materials:
            code = str(m.get("code", ""))
            name = self._master_name(m)
            mat_pairs.append((code, name if name else code))
        if hasattr(self, "cmb_normal_mat"):
            self._set_combo_items_with_data(self.cmb_normal_mat, mat_pairs)
        if hasattr(self, "cmb_fire_mat"):
            self._set_combo_items_with_data(self.cmb_fire_mat, mat_pairs)
        if hasattr(self, "cmb_branch_material"):
            self._set_combo_items_with_data(self.cmb_branch_material, mat_pairs)

        mat_code = self._combo_current_code(self.cmb_normal_mat) if hasattr(self, "cmb_normal_mat") else ""
        mat_item = self._find_master_item(data, "materials", mat_code)
        if mat_item is None and materials:
            mat_item = materials[0]
        # Sizes follow the selected material.
        sizes = [str(x) for x in (mat_item or {}).get("sizes", []) if str(x).strip()]
        if sizes:
            cur_main = self.cmb_main_size.currentText().strip() if hasattr(self, "cmb_main_size") else ""
            cur_branch = self.cmb_branch_size.currentText().strip() if hasattr(self, "cmb_branch_size") else ""
            if hasattr(self, "cmb_main_size"):
                self.cmb_main_size.blockSignals(True); self.cmb_main_size.clear(); self.cmb_main_size.addItems([""] + sizes); self.cmb_main_size.setCurrentText(cur_main if cur_main in sizes else ""); self.cmb_main_size.blockSignals(False)
            if hasattr(self, "cmb_branch_size"):
                self.cmb_branch_size.blockSignals(True); self.cmb_branch_size.clear(); self.cmb_branch_size.addItems([""] + sizes); self.cmb_branch_size.setCurrentText(cur_branch if cur_branch in sizes else ""); self.cmb_branch_size.blockSignals(False)
            self.sync_branch_size_from_rule()
        # Fitting groups follow the selected material.
        group_codes = [str(x) for x in (mat_item or {}).get("groups", [])]
        groups = [g for g in data.get("fitting_groups", []) if str(g.get("code", "")) in group_codes]
        if not groups:
            groups = data.get("fitting_groups", []) or []
        group_pairs = []
        for g in groups:
            code = str(g.get("code", ""))
            label = self._master_name(g) or code
            group_pairs.append((code, label))
        def set_group_combo(combo, pairs=None):
            cur = self._combo_current_code(combo)
            combo.blockSignals(True); combo.clear()
            for code, label in (pairs or group_pairs):
                combo.addItem(label, code)
            if cur:
                idx = combo.findData(cur)
                if idx >= 0: combo.setCurrentIndex(idx)
                else: combo.setCurrentText(cur)
            combo.blockSignals(False)
        def role_pairs(role_key: str, fallback: List[str]):
            # 排水転がし配管: start/end candidates are fixed and compact.
            allowed = ['集合管', 'DL Down', 'LL Down'] if role_key == 'start_groups' else ['DL Up', 'LL Up']
            codes = [str(x) for x in (mat_item or {}).get(role_key, []) if str(x).strip() and str(x) in allowed]
            if not codes:
                codes = [x for x in fallback[:] if x in allowed]
            out=[]
            for code in codes:
                g = self._find_master_item(data, "fitting_groups", code)
                if g:
                    out.append((code, self._master_name(g) or code))
                else:
                    out.append((code, code))
            return out
        if hasattr(self, "cmb_fit_type"):
            set_group_combo(self.cmb_fit_type, group_pairs)
        if hasattr(self, "cmb_start_fitting"):
            set_group_combo(self.cmb_start_fitting, role_pairs("start_groups", ["集合管", "DL Down", "LL Down"]))
        if hasattr(self, "cmb_terminal"):
            set_group_combo(self.cmb_terminal, role_pairs("end_groups", ["DL Up", "LL Up"]))
        try:
            self.refresh_size_and_terminal_from_library()
        except Exception:
            pass
        self._updating_master_combos = False
        try:
            self.schedule_common_apply()
        except Exception:
            pass

    def save_common_config(self):
        data = {
            "systems": self._combo_items(self.cmb_system) if hasattr(self, "cmb_system") else [],
            "sizes": self._combo_items(self.cmb_main_size) if hasattr(self, "cmb_main_size") else [],
            "branch_start": self._combo_items(self.cmb_start_fitting) if hasattr(self, "cmb_start_fitting") else [],
            "branch_end": self._combo_items(self.cmb_terminal) if hasattr(self, "cmb_terminal") else [],
        }
        try:
            self.common_config_path().write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
        except Exception:
            pass

    def load_common_config(self):
        global PIPE_SIZE_ORDER
        path = self.common_config_path()
        if not path.exists():
            return
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except Exception:
            return
        def reload_combo(combo, vals, keep_current=True):
            vals = [str(x).strip() for x in vals if str(x).strip()]
            if not vals:
                return
            cur = combo.currentText().strip() if keep_current else ""
            combo.blockSignals(True)
            combo.clear(); combo.addItems(vals)
            if cur:
                combo.setCurrentText(cur)
            combo.blockSignals(False)
        if hasattr(self, "cmb_system"): reload_combo(self.cmb_system, data.get("systems", []))
        if hasattr(self, "cmb_main_size"):
            sizes = data.get("sizes", [])
            reload_combo(self.cmb_main_size, sizes)
            if sizes:
                PIPE_SIZE_ORDER = [str(x).strip() for x in sizes if str(x).strip()]
        if hasattr(self, "cmb_branch_size"): reload_combo(self.cmb_branch_size, data.get("sizes", []))
        if hasattr(self, "cmb_start_fitting"): reload_combo(self.cmb_start_fitting, data.get("branch_start", []))
        if hasattr(self, "cmb_terminal"): reload_combo(self.cmb_terminal, data.get("branch_end", []))
        self.sync_branch_size_from_rule()

    def _combo_items(self, combo) -> List[str]:
        out = []
        try:
            for i in range(combo.count()):
                t = combo.itemText(i).strip()
                if t and t not in out:
                    out.append(t)
        except Exception:
            pass
        return out

    def sync_branch_size_from_rule(self):
        """Keep default branch size visible and predictable.

        - Giảm 1 bậc: main 65 -> branch 50.
        - Bằng ống chính: branch follows main exactly.
        - Cố định: user can freely edit branch size; do not overwrite it.
        """
        if not hasattr(self, "cmb_branch_rule") or not hasattr(self, "cmb_branch_size"):
            return
        code = self.cmb_branch_rule.currentData() or self._branch_rule_code_from_text()
        main = self.cmb_main_size.currentText().strip() if hasattr(self, "cmb_main_size") else ""
        fixed = (code == "fixed")
        self.cmb_branch_size.setEnabled(fixed)
        if not main:
            if not fixed:
                self.cmb_branch_size.setCurrentText("")
            return
        if code == "same":
            self.cmb_branch_size.setCurrentText(main)
        elif not fixed:
            self.cmb_branch_size.setCurrentText(self.dynamic_lower_pipe_size(main))

    def open_common_settings_dialog(self):
        global PIPE_SIZE_ORDER
        """Compatibility entry: common lists are now managed by the unified material DB."""
        return self.open_master_manager()
        dlg = QDialog(self)
        dlg.setWindowTitle(self.tr("common_settings_title"))
        dlg.resize(980, 520)
        layout = QVBoxLayout(dlg)
        note = QLabel(self.tr("common_settings_note"))
        note.setWordWrap(True)
        layout.addWidget(note)
        row = QHBoxLayout()
        layout.addLayout(row, 1)

        def unique(vals):
            out = []
            for v in vals:
                t = str(v).strip()
                if t and t not in out:
                    out.append(t)
            return out

        def make_manager(title, values, allow_order=True):
            box = QGroupBox(title)
            v = QVBoxLayout(box)
            lw = QListWidget()
            lw.addItems(unique(values))
            lw.setMinimumWidth(190)
            lw.setMinimumHeight(280)
            v.addWidget(lw, 1)
            btnrow1 = QHBoxLayout()
            b_add = QPushButton(self.tr("add")); b_edit = QPushButton(self.tr("edit")); b_del = QPushButton(self.tr("delete"))
            btnrow1.addWidget(b_add); btnrow1.addWidget(b_edit); btnrow1.addWidget(b_del)
            v.addLayout(btnrow1)
            row.addWidget(box, 1)

            def current_text():
                item = lw.currentItem()
                return item.text().strip() if item else ""

            def add_item():
                text, ok = QInputDialog.getText(dlg, self.tr("add"), self.tr("input_item"))
                text = text.strip()
                if ok and text and text not in [lw.item(i).text().strip() for i in range(lw.count())]:
                    lw.addItem(text)
                    lw.setCurrentRow(lw.count() - 1)

            def edit_item():
                item = lw.currentItem()
                if not item:
                    return
                text, ok = QInputDialog.getText(dlg, self.tr("edit"), self.tr("edit_item"), text=item.text())
                text = text.strip()
                existing = [lw.item(i).text().strip() for i in range(lw.count()) if lw.item(i) is not item]
                if ok and text and text not in existing:
                    item.setText(text)

            def delete_item():
                row_idx = lw.currentRow()
                if row_idx >= 0:
                    lw.takeItem(row_idx)
                    if lw.count():
                        lw.setCurrentRow(min(row_idx, lw.count()-1))

            b_add.clicked.connect(add_item)
            b_edit.clicked.connect(edit_item)
            b_del.clicked.connect(delete_item)
            # Sắp xếp bằng thao tác kéo trong danh sách, không dùng nút Lên/Xuống
            # để cửa sổ gọn hơn.
            try:
                lw.setDragDropMode(QListWidget.InternalMove)
                lw.setDefaultDropAction(Qt.MoveAction)
            except Exception:
                pass
            return lw

        lw_system = make_manager(self.tr("systems"), self._combo_items(self.cmb_system), True)
        lw_sizes = make_manager(self.tr("pipe_sizes"), self._combo_items(self.cmb_main_size), True)
        lw_start = make_manager(self.tr("branch_start"), self._combo_items(self.cmb_start_fitting), True)
        lw_terminal = make_manager(self.tr("branch_end"), self._combo_items(self.cmb_terminal), True)

        buttons = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        buttons.accepted.connect(dlg.accept)
        buttons.rejected.connect(dlg.reject)
        layout.addWidget(buttons)
        if dlg.exec() != QDialog.Accepted:
            return

        def list_items(lw):
            return unique([lw.item(i).text() for i in range(lw.count())])

        current_system = self.cmb_system.currentText().strip()
        current_main = self.cmb_main_size.currentText().strip()
        current_branch = self.cmb_branch_size.currentText().strip()
        current_start = self.cmb_start_fitting.currentText().strip()
        current_terminal = self.cmb_terminal.currentText().strip()
        systems = list_items(lw_system) or [current_system or self.tr("systems")]
        sizes = list_items(lw_sizes) or PIPE_SIZE_ORDER
        starts = list_items(lw_start) or [current_start or "集合管"]
        terms = list_items(lw_terminal) or [current_terminal or "DL"]
        PIPE_SIZE_ORDER = sizes[:]

        def reload_combo(combo, vals, cur):
            combo.blockSignals(True)
            combo.clear()
            combo.addItems(vals)
            if cur and cur in vals:
                combo.setCurrentText(cur)
            elif vals:
                combo.setCurrentIndex(0)
            combo.blockSignals(False)

        reload_combo(self.cmb_system, systems, current_system)
        reload_combo(self.cmb_main_size, sizes, current_main)
        reload_combo(self.cmb_branch_size, sizes, current_branch)
        reload_combo(self.cmb_start_fitting, starts, current_start)
        reload_combo(self.cmb_terminal, terms, current_terminal)
        self.save_common_config()
        self.sync_branch_size_from_rule()
        self.lbl_status.setText(self.tr("config_saved"))

    def _library_files_count(self) -> int:
        roots = []
        for base in [Path.cwd(), Path(__file__).resolve().parent]:
            for libname in ["library", "Library"]:
                d = base / libname
                if d.exists() and d.is_dir():
                    roots.append(d)
        seen = set(); count = 0
        for root in roots:
            for f in list(root.rglob("*.json")) + list(root.rglob("*.txt")):
                try:
                    k = str(f.resolve()).lower()
                except Exception:
                    k = str(f).lower()
                if k not in seen:
                    seen.add(k); count += 1
        return count

    def _ensure_library_index_current(self):
        """Warn/refresh if folder library changed after the last scan.

        This prevents the confusing case where the user reorganizes Library by system/material
        and old cached/indexed paths keep being used until combos are changed several times.
        """
        # NEVIS perf: throttle – tránh rglob mỗi lần bấm Apply. Chỉ kiểm tra 1 lần/20 giây.
        try:
            import time as _tm
            if _tm.monotonic() - getattr(self, '_lib_chk_t', 0.0) < 20.0:
                return
            self._lib_chk_t = _tm.monotonic()
        except Exception:
            pass
        try:
            fs_count = self._library_files_count()
            idx_count = len([it for it in getattr(self, "library_index", []) if isinstance(it, dict) and it.get("path") and Path(it.get("path")).exists()])
            if fs_count and fs_count != idx_count:
                ans = QMessageBox.question(self, "NEVIS", self.tr("library_changed_scan"), QMessageBox.Yes | QMessageBox.No, QMessageBox.Yes)
                if ans == QMessageBox.Yes:
                    self.library_index = []
                    self.auto_scan_default_library_folders(save=True)
                    _LIB_PATH_CACHE.clear(); _LIB_GEOM_CACHE.clear(); _LIB_GEOM_CACHE_ORDER.clear()
                    self._load_library_index()
                    self.refresh_library_tree()
        except Exception:
            pass

    def schedule_common_apply(self, *args):
        """Debounced common-setting apply.

        Thiết lập chung là khóa chính nên mọi thay đổi hệ/size/đầu-cuối nhánh
        phải chạy lại size propagation. Dùng timer để giảm lag khi combo phát nhiều signal.
        """
        try:
            if getattr(self, '_loading_project', False) or getattr(self, '_updating_master_combos', False):
                return
            if hasattr(self, '_common_apply_timer'):
                self._common_apply_timer.start(180)
        except Exception:
            pass

    def _safe_group_code(self, text: str) -> str:
        """Normalize UI/library group name without losing folder variants in DB.

        Runtime fitting logic only needs the base kind: LL Down/LL UP/LL_U -> LL,
        DL Down/DL UP -> DL. Folder names in CSDL are still kept strictly as-is.
        """
        t = str(text or '').strip()
        if not t:
            return ''
        low = t.lower().replace('_', ' ').replace('-', ' ')
        if low.startswith('ll'):
            return 'LL'
        if low.startswith('dl'):
            return 'DL'
        if low.startswith('45') or '45°' in t:
            return '45°'
        return t

    def _auto_default_fitting_for_node(self, nid: int) -> Fitting:
        """Return fitting controlled by current common settings for one node.

        Used by Mặc định and Đặt đầu nhánh. It prevents stale manual values
        like 'LL Down 65x50' staying on a node after common settings changed.
        """
        main_size = self.cmb_main_size.currentText().strip() if hasattr(self, 'cmb_main_size') else ''
        terminal = self.cmb_terminal.currentText().strip() if hasattr(self, 'cmb_terminal') else 'DL'
        start_type = self.cmb_start_fitting.currentText().strip() if hasattr(self, 'cmb_start_fitting') else '集合管'
        deg = self.model.degree(nid) if getattr(self, 'model', None) else 0
        old_fit = self.model.fittings.get(nid) if getattr(self, 'model', None) else None
        old_mat = getattr(old_fit, 'material_override', '') if old_fit else ''
        if (getattr(self.model, 'base_node', None) == nid) or (nid in getattr(self.model, 'base_nodes', set())):
            base_kind = self._safe_group_code(start_type) or start_type or '集合管'
            size = self.auto_base_fitting_size(nid) if base_kind == '集合管' else main_size
            return Fitting(nid, base_kind, size, manual=False, material_override=old_mat)
        if deg <= 0:
            return Fitting(nid, '要確認', '', manual=False, material_override=old_mat)
        if deg == 1:
            ftype, fsize = self.normalize_terminal_type_size(terminal, main_size)
            return Fitting(nid, ftype, fsize, manual=False, material_override=old_mat)
        if deg == 2:
            ns = self.model.neighbors(nid)
            n0 = self.model.nodes[nid]
            v1 = (self.model.nodes[ns[0]].x-n0.x, self.model.nodes[ns[0]].y-n0.y)
            v2 = (self.model.nodes[ns[1]].x-n0.x, self.model.nodes[ns[1]].y-n0.y)
            bend = abs(180 - angle_between(v1, v2))
            if bend < 20:
                return Fitting(nid, 'PASS', main_size, manual=False, material_override=old_mat)
            return Fitting(nid, '45°' if bend < 60 else 'LL', main_size, manual=False, material_override=old_mat)
        if deg == 3:
            ftype = classify_junction_type(self.model, nid, main_size)
            bsize = self.default_branch_size_for(main_size)
            fsize = f'{main_size}x{bsize}' if main_size and bsize else main_size
            return Fitting(nid, ftype, fsize, manual=False, material_override=old_mat)
        return Fitting(nid, '要確認', main_size, manual=False, material_override=old_mat)

    def apply_common(self):
        if self._block_if_detail_readonly():
            return
        self._ensure_library_index_current()
        main_size = self.cmb_main_size.currentText().strip()
        term = self.cmb_terminal.currentText()
        sys_code = self._combo_current_code(self.cmb_system) if hasattr(self, "cmb_system") else ""
        mat_code = self._combo_current_code(self.cmb_normal_mat) if hasattr(self, "cmb_normal_mat") else ""
        if not sys_code or not mat_code or not main_size:
            if not main_size:
                self.require_main_size_for_action()
            missing = []
            if not sys_code: missing.append("Hệ")
            if not mat_code: missing.append("Vật liệu")
            if not main_size: missing.append("Ống chính")
            msg = "Vui lòng nhập kích thước ống chính" if not main_size else "Thiếu thiết lập bắt buộc: " + ", ".join(missing)
            try:
                self.lbl_status.setText("⚠ " + msg)
                self.statusBar().showMessage(msg)
            except Exception:
                pass
            # Do not guess default 65. Keep the graph visible but do not propagate wrong sizes.
            self.update_workflow_state(False)
            self.refresh_all()
            return
        if hasattr(self, "sync_branch_size_from_rule"):
            self.sync_branch_size_from_rule()
        # Thiết lập chung là khóa chính: base fitting luôn ăn theo ô Đầu nhánh,
        # trừ khi người dùng cố tình sửa chi tiết bằng Apply trên node khác.
        if hasattr(self, "cmb_start_fitting"):
            bases = set(getattr(self.model, "base_nodes", set()) or [])
            if getattr(self.model, "base_node", None) in self.model.nodes:
                bases.add(self.model.base_node)
            self.model.base_nodes = {b for b in bases if b in self.model.nodes}
            for b in sorted(self.model.base_nodes):
                self.model.fittings[b] = self._auto_default_fitting_for_node(b)
        rebuild_flow(self.model)
        self.apply_branch_sizing(main_size, term)
        self.update_workflow_state(True)
        self.refresh_all()

    def default_branch_size_for(self, current_size: str) -> str:
        """Return default branch size from the common setting panel.

        - Giảm 1 bậc: old drainage rule, e.g. 65 -> 50.
        - Bằng ống chính: branch keeps the same size as main.
        - Cố định: branch uses the editable branch-size box, e.g. 150 -> 100 or 80 -> 25.
        """
        code = (self.cmb_branch_rule.currentData() if hasattr(self, "cmb_branch_rule") else "down") or self._branch_rule_code_from_text()
        current_size = str(current_size or "").strip()
        if not current_size:
            return ""
        if code == "same":
            return current_size
        if code == "fixed":
            val = self.cmb_branch_size.currentText().strip() if hasattr(self, "cmb_branch_size") else ""
            return val
        return self.dynamic_lower_pipe_size(current_size)

    def normalize_terminal_type_size(self, terminal_type: str, current_size: str) -> Tuple[str, str]:
        t = str(terminal_type or "DL").strip()
        low = t.lower()
        mode = ""
        if "up" in low or t.endswith(" U") or t.endswith("_U") or "上" in t:
            mode = "U"
        elif "down" in low or t.endswith(" D") or t.endswith("_D") or "下" in t:
            mode = "D"
        base = t.replace(" Up", "").replace(" Down", "").replace("_U", "").replace("_D", "").strip()
        if base in ["DL", "LL"] and mode:
            return base, f"{current_size}x{mode}"
        return base or t, (f"{current_size}xU" if base in ["DL", "LL", "脚部"] else current_size)

    def apply_branch_sizing(self, main_size: str, terminal_type: str):
        """
        Size rule for drainage branches:
        - The main axis continues with its current size.
        - At Y/LT/DT/T junctions, the side branch follows the common panel rule:
          one size smaller / same as main / fixed custom size.
        - All pipes and automatic fittings downstream of that side branch inherit the side-branch size.
        - Manual fitting edits are respected: e.g. changing auto 65x50 Y to LT 65x40 will propagate 40 to that side branch.
        """
        if not self.model.nodes:
            return
        main_size = str(main_size or "").strip()
        if not main_size:
            # No hard fallback to 65. Keep blank and let the user pick a size from the current library/material.
            for e in self.model.edges:
                if str(getattr(e, "size", "")) == "65":
                    e.size = ""
            try:
                self.statusBar().showMessage("Chưa chọn size tuyến chính / 主管サイズ未設定")
            except Exception:
                pass
            return
        for e in self.model.edges:
            e.size = main_size

        # Base and terminal defaults first.
        # 集合管 is not a fixed 100x65x50 fitting anymore:
        # its port count/type follows the number and angle of centerlines connected to the base point.
        # Auto priority is 65x75 for a 2-port 集合管, then each outgoing branch inherits its own port size.
        for nid, fit in list(self.model.fittings.items()):
            fbase0 = self._safe_group_code(getattr(fit, 'ftype', ''))
            if (nid == self.model.base_node or nid in getattr(self.model, "base_nodes", set())) and not fit.manual:
                # Keep current common-start type. 集合管 uses auto port size; other start devices use main size.
                start_type = self.cmb_start_fitting.currentText().strip() if hasattr(self, 'cmb_start_fitting') else '集合管'
                fit.ftype = self._safe_group_code(start_type) or start_type or '集合管'
                fit.size = self.auto_base_fitting_size(nid) if fit.ftype == '集合管' else main_size
            elif self.model.degree(nid) == 1 and fbase0 in ["DL", "LL", "脚部"] and not fit.manual:
                fit.ftype, fit.size = self.normalize_terminal_type_size(terminal_type, main_size)
                # Temporary default; the DFS below overwrites it with the actual inherited branch size.

        bases = set(getattr(self.model, "base_nodes", set()) or [])
        if getattr(self.model, "base_node", None) is not None:
            bases.add(self.model.base_node)
        bases = {b for b in bases if b in self.model.nodes}
        if not bases:
            return

        base_child_sizes_by_base = {b: self.base_child_size_map(b, main_size) for b in bases}

        visited_edges = set()

        def visit(nid: int, incoming_size: str):
            fit = self.model.fittings.get(nid)
            if self.model.degree(nid) >= 4:
                if fit and not fit.manual:
                    fit.ftype = "要確認"
                    fit.size = incoming_size or main_size
                info = None
            else:
                info = junction_axis_info(self.model, nid) if self.model.degree(nid) == 3 else None
            branch_nb = info["branch"] if info else None
            current_size = incoming_size
            branch_size = self.default_branch_size_for(current_size)

            fit_base = self._safe_group_code(getattr(fit, 'ftype', '')) if fit else ''
            if fit and fit_base in ["Y", "LT", "DT", "T", "SV", "S"] and self.model.degree(nid) == 3:
                if fit.manual:
                    msz, bsz = parse_fitting_size_pair(fit.size, current_size)
                    current_size = msz or current_size
                    branch_size = bsz or self.dynamic_lower_pipe_size(current_size)
                else:
                    ftype = classify_junction_type(self.model, nid, current_size)
                    fit.ftype = ftype
                    branch_size = self.default_branch_size_for(current_size)
                    fit.size = f"{current_size}x{branch_size}"
            elif fit and fit.ftype == "IN":
                # 異径ソケット / cút thu thẳng trên tuyến.
                # Upstream side keeps incoming_size; only the downstream side away from 集合管 changes.
                nums = re.findall(r"\d+", str(fit.size))
                if len(nums) >= 2:
                    up_size, down_size = nums[0], nums[1]
                    # keep display/library size as up x down, but propagate only down_size to children
                    fit.size = f"{up_size}x{down_size}"
                    current_size = down_size
                    branch_size = down_size
                elif not fit.manual:
                    fit.size = current_size
            elif fit and not fit.manual:
                # Only true pipe endpoints (degree == 1) use the U/UP terminal library.
                # Bends on the route such as LL with degree == 2 must stay normal LL,
                # otherwise every corner becomes 65xU/50xU and the wrong TXT is selected.
                fit_base2 = self._safe_group_code(getattr(fit, 'ftype', ''))
                if fit_base2 in ["LL", "DL", "脚部"]:
                    if self.model.degree(nid) == 1:
                        fit.ftype, fit.size = self.normalize_terminal_type_size(terminal_type, current_size)
                    else:
                        # Up/Down only belongs to true endpoints; route bends stay normal LL/DL.
                        fit.ftype = fit_base2
                        fit.size = current_size
                elif fit_base2 in ["45°", "IN"]:
                    fit.ftype = fit_base2
                    fit.size = current_size

            # Children are nodes farther from 集合管. This keeps the rule following the pipe network, not screen radius.
            for nb in self.model.neighbors(nid):
                if self.model.parent.get(nb) != nid:
                    continue
                e = edge_obj(self.model, nid, nb)
                if e is None or e.key in visited_edges:
                    continue
                base_child_sizes = base_child_sizes_by_base.get(nid, {})
                if (nid in bases) and nb in base_child_sizes:
                    # First sizing comes from each selected start/collection point itself.
                    # Example: auto 65x75 -> one branch inherits 65, the other inherits 75.
                    next_size = base_child_sizes[nb]
                else:
                    next_size = branch_size if (branch_nb is not None and nb == branch_nb) else current_size
                # ブッシング behaves like an IN absorbed into the large fitting mouth:
                # the pipe becomes small immediately from the host fitting and the
                # small size propagates downstream.
                bsmall = self.bushing_small_for_side(nid, nb) if hasattr(self, "bushing_small_for_side") else ""
                if bsmall:
                    next_size = bsmall
                e.size = next_size
                visited_edges.add(e.key)
                visit(nb, next_size)

        # Process every selected start node.  This supports large projects with many independent clusters.
        for b in sorted(bases):
            visit(b, main_size)
        disconnected_count = 0
        for e in self.model.edges:
            if e.key not in visited_edges:
                # Safer than guessing: disconnected/unreachable segments remain blank for user check.
                e.size = ""
                disconnected_count += 1
        if disconnected_count:
            try:
                self.statusBar().showMessage(f"⚠ Có {disconnected_count} đoạn ống chưa nối được về đầu nhánh/集合管 - giữ size trống")
            except Exception:
                pass
        self.force_bushing_downstream_sizes()

    def force_bushing_downstream_sizes(self):
        """Force pipe/fitting sizes after each ブッシング to the small side.

        Strong final pass after normal auto-sizing.  It updates BOTH automatic and
        manual downstream fittings because the physical pipe after a ブッシング is no
        longer the large diameter.
        """
        bs = list(getattr(self.model, "bushings", []) or [])
        if not bs:
            return
        for b in bs:
            try:
                host = int(b.get("host_node")); other = int(b.get("other_node"))
                nums = re.findall(r"\d+", str(b.get("size", "")))
                if len(nums) < 2:
                    continue
                self._apply_bushing_small_side_now(host, other, nums[1])
            except Exception:
                continue

    def bushing_item_name(self, mat: str) -> str:
        """Plastic systems use plastic ブッシング; fire systems use metal threaded type."""
        mat2 = self.material_kind_label(mat)
        sys_code = self._combo_current_code(self.cmb_system) if hasattr(self, "cmb_system") else ""
        if mat2 in {"STPG", "SGP", "SUS", "STEEL"} or sys_code in {"SP", "連結送水管"}:
            return "金属ブッシング"
        return "ブッシング"


    # ------------------------------------------------------------------
    # NEVIS Smart Drag: topology optimization after moving a pipe run
    # ------------------------------------------------------------------
    def _fit_base(self, nid: int) -> str:
        fit = self.model.fittings.get(nid) if getattr(self, "model", None) else None
        return self._safe_group_code(getattr(fit, "ftype", "")) if fit else ""

    def _smart_drag_relevant_nodes(self, moved_edge_key: str) -> Set[int]:
        """Nodes around the moved pipe; keep optimization local and safe."""
        out: Set[int] = set()
        if not moved_edge_key:
            return out
        e0 = next((e for e in self.model.edges if e.key == moved_edge_key), None)
        if not e0:
            return out
        out.update([e0.a, e0.b])
        for nid in list(out):
            for nb in self.model.neighbors(nid):
                out.add(nb)
                for nb2 in self.model.neighbors(nb):
                    out.add(nb2)
        return out

    def _angle_to_main_axis_for_candidate(self, host: int, terminal: int, ignore_mid: int) -> float:
        """Angle between proposed branch host-terminal and host's main axis."""
        if host not in self.model.nodes or terminal not in self.model.nodes:
            return 999.0
        h = self.model.nodes[host]; t = self.model.nodes[terminal]
        bvec = (t.x - h.x, t.y - h.y)
        # Main axis = most opposite pair among host neighbors, excluding the removed 45 node.
        ns = [n for n in self.model.neighbors(host) if n != ignore_mid and n in self.model.nodes]
        if len(ns) < 2:
            return 999.0
        best = None; best_err = 1e100
        for i in range(len(ns)):
            for j in range(i+1, len(ns)):
                n1 = self.model.nodes[ns[i]]; n2 = self.model.nodes[ns[j]]
                v1 = (n1.x - h.x, n1.y - h.y)
                v2 = (n2.x - h.x, n2.y - h.y)
                err = abs(180.0 - angle_between(v1, v2))
                if err < best_err:
                    best_err = err; best = v1
        if best is None:
            return 999.0
        a = angle_between(best, bvec)
        return min(a, 180.0 - a)

    def _find_smart_drag_simplify_candidate(self, moved_edge_key: str):
        """Find a local pattern: junction -- middle bend -- terminal, then propose junction -- terminal.

        v2: Works in both drag directions.  After dragging, apply_common() may
        reclassify the old 45° node into LL/DL/straight depending on the new
        geometry.  Therefore do not require the middle node to still be named
        exactly 45°; require the safer topology instead:
          host = junction node (degree >= 3)
          mid  = removable degree-2 bend/pass node
          terminal = branch end node (degree == 1, DL/LL/脚部)
        """
        if not getattr(self, "model", None) or not self.model.nodes:
            return None
        relevant = self._smart_drag_relevant_nodes(moved_edge_key)
        if not relevant:
            return None
        allowed_mid = {"45°", "LL", "DL", "", "通過", "PASS"}
        for mid in sorted(relevant):
            if mid not in self.model.nodes or self.model.degree(mid) != 2:
                continue
            fit_mid = self.model.fittings.get(mid)
            mid_code = self._safe_group_code(getattr(fit_mid, "ftype", "")) if fit_mid else ""
            # Keep it conservative: remove only normal bend/pass nodes, never reducers, Y/LT/T/S, bushings, etc.
            if mid_code not in allowed_mid:
                continue
            ns = self.model.neighbors(mid)
            if len(ns) != 2:
                continue
            for host, terminal in ((ns[0], ns[1]), (ns[1], ns[0])):
                if host not in self.model.nodes or terminal not in self.model.nodes:
                    continue
                if self.model.degree(host) < 3 or self.model.degree(terminal) != 1:
                    continue
                tbase = self._fit_base(terminal)
                if tbase not in {"DL", "LL", "脚部"}:
                    continue
                hn = self.model.nodes[host]; tn = self.model.nodes[terminal]
                direct_len = math.hypot(tn.x - hn.x, tn.y - hn.y)
                if direct_len <= max(NODE_TOL * 2.0, 5.0):
                    continue
                if not self.preview._edge_angle_is_canonical(hn.x, hn.y, tn.x, tn.y, tol_deg=4.0):
                    continue
                branch_ang = self._angle_to_main_axis_for_candidate(host, terminal, mid)
                if branch_ang == 999.0:
                    continue
                if abs(branch_ang - 90.0) <= 18.0:
                    new_kind = classify_junction_type(self.model, host, self.cmb_main_size.currentText().strip())
                    if new_kind == "Y":
                        new_kind = "LT"
                    desc_key = "smart_drag_desc_90"
                elif abs(branch_ang - 45.0) <= 18.0:
                    new_kind = "Y"
                    desc_key = "smart_drag_desc_45"
                else:
                    continue
                return {
                    "mid": mid, "host": host, "terminal": terminal,
                    "new_kind": new_kind, "desc_key": desc_key,
                    "branch_angle": branch_ang, "mid_code": mid_code,
                }
        return None

    def smart_drag_optimize_after_pipe_move(self, moved_edge_key: str) -> bool:
        """Ask the user before changing graph topology after a pipe drag."""
        try:
            cand = self._find_smart_drag_simplify_candidate(moved_edge_key)
        except Exception:
            cand = None
        if not cand:
            return False
        mid = int(cand["mid"]); host = int(cand["host"]); terminal = int(cand["terminal"])
        fit_host = self.model.fittings.get(host)
        fit_mid = self.model.fittings.get(mid)
        fit_term = self.model.fittings.get(terminal)
        old_route = f"{getattr(fit_host, 'ftype', '')} → {getattr(fit_mid, 'ftype', '45°')} → {getattr(fit_term, 'ftype', '')}"
        desc = self.tr(str(cand.get("desc_key") or "smart_drag_desc_45"))
        msg = self.tr("smart_drag_msg").format(old=old_route, desc=desc)
        ret = QMessageBox.question(self, self.tr("smart_drag_title"), msg, QMessageBox.Yes | QMessageBox.No, QMessageBox.Yes)
        if ret != QMessageBox.Yes:
            self.lbl_status.setText(self.tr("smart_drag_keep"))
            return False

        # Keep the original undo snapshot if pipe dragging already saved one;
        # otherwise save before topology edit.
        if not getattr(self, "undo_snapshot", None):
            self.save_undo_snapshot("smart_drag_optimize")
        # Preserve size/material from the two old pieces where possible.
        old_edges = [e for e in self.model.edges if mid in (e.a, e.b)]
        old_size = next((str(e.size) for e in old_edges if str(e.size).strip()), self.cmb_main_size.currentText().strip())
        old_mat = next((str(getattr(e, "material_override", "")) for e in old_edges if str(getattr(e, "material_override", "")).strip()), "")

        self.model.edges = [e for e in self.model.edges if e.a != mid and e.b != mid]
        if edge_obj(self.model, host, terminal) is None:
            self.model.edges.append(Edge(host, terminal, old_size, old_mat))
        self.model.nodes.pop(mid, None)
        self.model.fittings.pop(mid, None)

        # Let apply_common recalc final type/size, but put the intended host family first.
        if host in self.model.fittings:
            self.model.fittings[host].ftype = str(cand.get("new_kind") or self.model.fittings[host].ftype)
            self.model.fittings[host].manual = False
        rebuild_flow(self.model)
        self.apply_common()
        self.selected_node = None
        self.selected_edge = edge_key(host, terminal)
        self.select_edge(self.selected_edge)
        self.lbl_status.setText(self.tr("smart_drag_done"))
        return True

    def refresh_all(self):
        """Lightweight refresh entry point.

        Many controls emit several signals for one click.  The old code redrew
        the full detailed preview and rebuilt the material table immediately
        for every signal, which made checkboxes/combo boxes feel frozen.  This
        debounces them into one refresh after the UI becomes idle.
        """
        try:
            if hasattr(self, "_refresh_timer"):
                self._refresh_timer.start()
                return
        except Exception:
            pass
        self._do_refresh_all()

    def _do_refresh_all(self):
        if getattr(self, "_drawing_now", False):
            return
        self._drawing_now = True
        try:
            self.preview.draw_model()
            self.update_material_table()
            if hasattr(self, "lbl_support_hint"):
                self.update_support_controls(refresh_only=True)
        finally:
            self._drawing_now = False

    def make_fitting_label(self, nid:int) -> str:
        fit = self.model.fittings.get(nid)
        if not fit or fit.excluded:
            return ""
        prefix = self.fitting_prefix_for_node(nid)
        suffix = self.bushing_label_suffix(nid) if hasattr(self, "bushing_label_suffix") else ""
        if fit.ftype == "集合管":
            size_txt = (fit.size or "").strip()
            port_txt = self.classify_base_ports(nid)
            base = f"集合管 {port_txt}" if not size_txt else f"{size_txt} 集合管 {port_txt}"
            return base + suffix
        if fit.ftype in ["Y","LT","DT","T","SV","S"]:
            return f"{fit.size}{prefix}-{fit.ftype}" + suffix
        if fit.ftype == "45°":
            return f"{fit.size}{prefix}-45°" + suffix
        if fit.ftype == "IN":
            nums = re.findall(r"\d+", str(fit.size))
            if len(nums) >= 2:
                return f"{nums[0]}→{nums[1]} {prefix}-IN" + suffix
            return f"{fit.size}{prefix}-IN" + suffix
        return f"{fit.size}{prefix}-{fit.ftype}" + suffix

    def classify_base_ports(self, nid:int) -> str:
        """Human label for 集合管 ports based on the centerlines connected to the base node."""
        deg = self.model.degree(nid)
        if deg <= 1:
            return "1 cửa"
        if deg == 2:
            ns = self.model.neighbors(nid); n0=self.model.nodes[nid]
            v1=(self.model.nodes[ns[0]].x-n0.x,self.model.nodes[ns[0]].y-n0.y)
            v2=(self.model.nodes[ns[1]].x-n0.x,self.model.nodes[ns[1]].y-n0.y)
            ang = angle_between(v1, v2)
            # Near 180° means straight through; near 90° means perpendicular.
            return "2 cửa thẳng" if abs(180.0-ang) <= 25.0 else "2 cửa vuông góc"
        return f"{deg} cửa"

    def auto_base_fitting_size(self, nid:int) -> str:
        """Default 集合管 size. Priority is pipe size first, branch split second.

        For a 2-port base, prefer 65x75 as requested. This makes one outgoing
        branch inherit 65 and the other inherit 75 before later Y/LT/DT sizing rules.
        """
        deg = self.model.degree(nid)
        main = self.cmb_main_size.currentText().strip() if hasattr(self, "cmb_main_size") else ""
        branch = self.default_branch_size_for(main) if main else ""
        if deg <= 1:
            return main
        if deg == 2:
            return f"{main}x{branch}" if main and branch and main != branch else main
        # 3+ outlets: no fixed 65 fallback. Use current main/branch only if selected.
        if not main:
            return ""
        parts = [main] + ([branch] if branch else []) + [main] * max(0, deg-2)
        return "x".join([x for x in parts if x])

    def ordered_base_children(self, nid:int) -> List[int]:
        """Stable order for assigning 集合管 port sizes to connected branches."""
        if nid not in self.model.nodes:
            return []
        n0 = self.model.nodes[nid]
        children = []
        for nb in self.model.neighbors(nid):
            # Prefer flow children, but allow all neighbors if graph direction has not been rebuilt.
            if self.model.parent and self.model.parent.get(nb) != nid:
                continue
            n = self.model.nodes[nb]
            ang = math.degrees(math.atan2(n.y-n0.y, n.x-n0.x))
            # clockwise/stable order, starting from right/up-ish in model coordinates
            children.append((ang, nb))
        if not children:
            for nb in self.model.neighbors(nid):
                n = self.model.nodes[nb]
                ang = math.degrees(math.atan2(n.y-n0.y, n.x-n0.x))
                children.append((ang, nb))
        children.sort(key=lambda x: x[0])
        return [nb for _, nb in children]

    def base_child_size_map(self, nid:int, fallback_size: str) -> Dict[int, str]:
        """Map each outgoing branch from 集合管 to the port size it should inherit."""
        fit = self.model.fittings.get(nid)
        size_text = (fit.size if fit else "") or self.auto_base_fitting_size(nid)
        nums = re.findall(r"\d+", str(size_text))
        if not nums:
            nums = [fallback_size]
        children = self.ordered_base_children(nid)
        out: Dict[int, str] = {}
        for i, nb in enumerate(children):
            out[nb] = nums[i] if i < len(nums) else nums[-1]
        return out

    def _current_fire_limit(self) -> float:
        try:
            return float(self.edit_fire_len.text())
        except Exception:
            return 0.0

    def _fire_boundary_node_tolerance(self, nid: int) -> float:
        """Tolerance for deciding a fitting is sitting on the fire boundary.

        NEVIS rule: when a fitting/terminal is at the material border, do not draw
        a transverse cut line through/near that fitting; make the fitting itself
        fire-protection material.  Use about half the largest connected pipe OD so
        small coordinate/trim differences do not leave the fitting as normal pipe.
        """
        max_od = 0.0
        fire = self._combo_current_code(self.cmb_fire_mat) if hasattr(self, "cmb_fire_mat") else self.cmb_fire_mat.currentText()
        normal = self._combo_current_code(self.cmb_normal_mat) if hasattr(self, "cmb_normal_mat") else self.cmb_normal_mat.currentText()
        for e in getattr(self.model, "edges", []):
            if e.a == nid or e.b == nid:
                try:
                    max_od = max(max_od, self.pipe_outer_diameter(fire, e.size), self.pipe_outer_diameter(normal, e.size))
                except Exception:
                    pass
        return max(NODE_TOL * 2.0, max_od * 0.5)

    def node_is_fire_boundary_fitting(self, nid: int, fire_limit: Optional[float] = None) -> bool:
        """True when a real fitting/terminal center is on the fire boundary.

        This is intentionally limited to nodes that actually have a fitting.  A
        normal pipe split without a fitting still gets the transverse boundary cap.
        """
        if not (hasattr(self, "chk_fire") and self.chk_fire.isChecked()):
            return False
        fit = self.model.fittings.get(nid) if hasattr(self, "model") else None
        if not fit or getattr(fit, "excluded", False):
            return False
        fl = self._current_fire_limit() if fire_limit is None else fire_limit
        d = self.model.dist.get(nid, 1e100)
        if d >= 1e99:
            return False
        return abs(d - fl) <= self._fire_boundary_node_tolerance(nid)

    def normalize_fire_boundary_t_for_fitting(self, e: Edge, t: float) -> float:
        """Snap fire/normal split to a fitting center when the fitting sits on the boundary.

        Important drawing rule: if a real fitting is on the fire-protection
        boundary, the fitting itself becomes fire-protection material, but NEVIS
        must NOT draw a tiny fire-protection pipe stub immediately beside that
        fitting on the normal-pipe side.  Snapping the split to the endpoint
        removes that short leftover pipe body in both preview and JWW output.
        """
        try:
            t = max(0.0, min(1.0, float(t)))
        except Exception:
            return 0.0
        length = self.model.edge_length(e) if hasattr(self, "model") else 0.0
        if length <= EPS:
            return t
        if self.node_is_fire_boundary_fitting(e.a) and (t * length) <= self._fire_boundary_node_tolerance(e.a):
            return 0.0
        if self.node_is_fire_boundary_fitting(e.b) and ((1.0 - t) * length) <= self._fire_boundary_node_tolerance(e.b):
            return 1.0
        return t

    def edge_fire_interval_by_mouth(self, e: Edge, fire_limit: Optional[float] = None) -> Tuple[float, float]:
        """Return fire-protection interval on the REAL visible pipe body [t0,t1].

        Fire pipe length must be judged from fitting mouth to fitting mouth, not
        from fitting center to fitting center.  When a fitting sits on the
        boundary it may become fire-protection material, but the normal pipe
        leaving the far mouth must not inherit fire material just because the
        edge centerline overlaps the fitting body.
        """
        try:
            if fire_limit is None:
                fire_limit = self._current_fire_limit()
            fire_limit = float(fire_limit)
        except Exception:
            fire_limit = 0.0
        try:
            length = self.model.edge_length(e)
        except Exception:
            length = 0.0
        if length <= EPS:
            return (0.0, 0.0)
        if getattr(e, "material_override", ""):
            return (0.0, 0.0)

        normal = self._combo_current_code(self.cmb_normal_mat) if hasattr(self, "cmb_normal_mat") else self.cmb_normal_mat.currentText()
        fire = self._combo_current_code(self.cmb_fire_mat) if hasattr(self, "cmb_fire_mat") else self.cmb_fire_mat.currentText()
        # Use the larger of normal/fire trim because a boundary fitting is drawn
        # as fire but the pipe still starts/ends at the real mouth.
        try:
            trim_a = max(float(self.ruby_trim_for_fitting_side(e.a, e.b, e.size, normal)), float(self.ruby_trim_for_fitting_side(e.a, e.b, e.size, fire)), 0.0)
            trim_b = max(float(self.ruby_trim_for_fitting_side(e.b, e.a, e.size, normal)), float(self.ruby_trim_for_fitting_side(e.b, e.a, e.size, fire)), 0.0)
        except Exception:
            trim_a = trim_b = 0.0
        trim_a = min(trim_a, length * 0.49)
        trim_b = min(trim_b, length * 0.49)
        clear_a = trim_a
        clear_b = length - trim_b
        if clear_b <= clear_a + 0.001:
            return (0.0, 0.0)

        da = self.model.dist.get(e.a, 1e100)
        db = self.model.dist.get(e.b, 1e100)
        if da >= 1e99 or db >= 1e99:
            return (0.0, 0.0)
        # Convert visible pipe body mouth positions to flow-distance positions.
        if da <= db:
            flow_a = da + clear_a
            flow_b = da + clear_b
            hit0 = max(flow_a, 0.0)
            hit1 = min(flow_b, fire_limit)
            if hit1 <= hit0 + 0.001:
                return (0.0, 0.0)
            return ((hit0 - da) / length, (hit1 - da) / length)
        else:
            # Flow runs from B to A on this edge.  A param t has flow distance:
            # db + (1-t)*length.  Visible body is still [clear_a, clear_b] from A.
            flow_at_clear_b = db + (length - clear_b)
            flow_at_clear_a = db + (length - clear_a)
            hit0 = max(flow_at_clear_b, 0.0)
            hit1 = min(flow_at_clear_a, fire_limit)
            if hit1 <= hit0 + 0.001:
                return (0.0, 0.0)
            # hit0 is nearer to B -> larger t; hit1 is nearer to A -> smaller t.
            t_high = 1.0 - (hit0 - db) / length
            t_low = 1.0 - (hit1 - db) / length
            return (max(0.0, min(1.0, t_low)), max(0.0, min(1.0, t_high)))

    def edge_fire_fraction_by_mouth(self, e: Edge, fire_limit: Optional[float] = None) -> float:
        t0, t1 = self.edge_fire_interval_by_mouth(e, fire_limit)
        return max(0.0, min(1.0, t1 - t0))

    def effective_fire_fraction_for_edge(self, e: Edge, raw_frac: float) -> float:
        """Fire length ratio after boundary-fitting stub suppression."""
        try:
            frac = max(0.0, min(1.0, float(raw_frac)))
        except Exception:
            return 0.0
        if frac <= 0.001 or frac >= 0.999:
            return frac
        da = self.model.dist.get(e.a, 1e100)
        db = self.model.dist.get(e.b, 1e100)
        split_t = frac if da <= db else 1.0 - frac
        split_t = self.normalize_fire_boundary_t_for_fitting(e, split_t)
        return split_t if da <= db else 1.0 - split_t

    def should_draw_fire_boundary_cap(self, e: Edge, t: float) -> bool:
        """Draw cap only on open pipe, not through a boundary fitting.

        If the split point is at/very close to a node that has a fitting, the
        fitting is switched to TMP/耐火VP by fitting_prefix_for_node(), and the cap
        is suppressed to keep the drawing clean.
        """
        try:
            t = max(0.0, min(1.0, float(t)))
        except Exception:
            return True
        t = self.normalize_fire_boundary_t_for_fitting(e, t)
        if t <= 0.001 or t >= 0.999:
            return False
        length = self.model.edge_length(e) if hasattr(self, "model") else 0.0
        if length <= EPS:
            return False
        if self.node_is_fire_boundary_fitting(e.a) and (t * length) <= self._fire_boundary_node_tolerance(e.a):
            return False
        if self.node_is_fire_boundary_fitting(e.b) and ((1.0 - t) * length) <= self._fire_boundary_node_tolerance(e.b):
            return False
        return True

    def fitting_prefix_for_node(self, nid:int) -> str:
        """Return the material folder prefix used for this fitting library.

        Step 8 fix:
        Do not decide branch fittings (Y/LT/DT/T) by the *whole edge* material
        ratio.  When an edge crosses the fire-protection boundary, edge_material()
        can return TMP because more than 50% of the edge is inside the fire zone,
        even though the fitting node itself is outside.  That was why outside-area
        branch fittings were displayed as DV on the drawing but detailed preview/JWW
        still loaded TMP libraries.

        Correct rule:
        - Manual/special fitting override wins.
        - Connected edge material_override wins for special branches.
        - Otherwise fitting material is decided locally at the fitting node:
          inside fire range = fire material, outside = normal material.
        """
        fit = self.model.fittings.get(nid)
        forced = getattr(fit, "material_override", "") if fit else ""
        if forced:
            return self.pipe_prefix(forced)

        # Special branch material override on any connected pipe should win.
        for e in self.model.edges:
            if e.a == nid or e.b == nid:
                ov = getattr(e, "material_override", "")
                if ov:
                    return self.pipe_prefix(ov)

        if self.chk_fire.isChecked():
            try:
                fl = float(self.edit_fire_len.text())
            except Exception:
                fl = 0.0
            # Boundary rule: a fitting exactly on the fire/non-fire border is
            # treated as fire-protection fitting, so the joint at the split is safe.
            d = self.model.dist.get(nid, 1e100)
            if d <= fl + 1e-6 or self.node_is_fire_boundary_fitting(nid, fl):
                return self.pipe_prefix(self._combo_current_code(self.cmb_fire_mat) if hasattr(self, "cmb_fire_mat") else self.cmb_fire_mat.currentText())

        return self.pipe_prefix(self._combo_current_code(self.cmb_normal_mat) if hasattr(self, "cmb_normal_mat") else self.cmb_normal_mat.currentText())

    def pipe_prefix(self, mat: str) -> str:
        if mat in ["VP/VU","VP","VU","DV"]: return "DV"
        if mat in ["TMP","トミジ"]: return "TMP"
        if mat == "耐火VP": return "耐火VP"
        if mat in ["HTVP", "HIVP", "TS"]: return "HT" if mat == "HTVP" else mat
        return mat

    def current_pipe_for_node(self, nid: Optional[int]) -> str:
        if nid is None:
            return "DV"
        prefix = self.fitting_prefix_for_node(nid)
        if prefix == "HT":
            return "HTVP"
        if prefix == "DV":
            return "DV"
        return prefix

    def normalize_lib_type(self, t: str) -> str:
        t = (t or "").strip()
        if t in ["45", "45°", "45度"]:
            return "45°"
        if t in ["S管", "集合管"]:
            return "集合管"
        return t

    def pipe_aliases(self, pipe: str, ftype: str = "") -> Set[str]:
        """Return material/folder aliases for library lookup.
        Library is folder-first: library/<pipe>/<fitting>/<txt>.
        集合管 is special and may live in library/集合管, not under DV/TMP.
        """
        pipe = (pipe or "").strip()
        ftype = self.normalize_lib_type(ftype)
        aliases = {pipe} if pipe else set()
        if ftype == "集合管":
            aliases.update(["集合管", "S", "SV", "S3"])
            return aliases
        if pipe in ["DV", "VP", "VU", "VP/VU"]:
            aliases.update(["DV", "VP", "VU", "VP/VU"])
        if pipe in ["TMP", "トミジ", "耐火二層管"]:
            aliases.update(["TMP", "トミジ", "耐火二層管"])
        if pipe in ["HT", "HTVP", "HIVP", "TS"]:
            aliases.update(["HT", "HTVP", "HIVP", "TS"])
        if pipe in ["耐火VP", "TaikaVP"]:
            aliases.update(["耐火VP", "TaikaVP"])
        return aliases

    def type_aliases(self, ftype: str) -> Set[str]:
        ftype = self.normalize_lib_type(ftype)
        if ftype == "集合管":
            return {"集合管", "S", "SV"}
        if ftype == "45°":
            return {"45°", "45"}
        if ftype == "LL":
            return {"LL", "L"}
        return {ftype}

    def library_sizes(self, pipe: str, ftype: str) -> List[str]:
        ftype = self.normalize_lib_type(ftype)
        out = []
        aliases = self.pipe_aliases(pipe, ftype)
        type_alias = self.type_aliases(ftype)
        for item in self.library_index:
            if not isinstance(item, dict):
                continue
            it_pipe = str(item.get("pipe", ""))
            it_type = self.normalize_lib_type(str(item.get("type", "")))
            sz = str(item.get("size", "")).strip()
            if sz and it_pipe in aliases and it_type in type_alias:
                out.append(sz)
        # Natural sort by numeric parts, then unique.
        def sort_key(v):
            nums = [int(x) for x in re.findall(r"\d+", v)]
            return (nums, v)
        out = sorted(out, key=sort_key)
        seen = set(); uniq = []
        for x in out:
            if x not in seen:
                uniq.append(x); seen.add(x)
        return uniq


    def current_material_code(self) -> str:
        """Return current material code without relying on visible bilingual label."""
        try:
            code = self._combo_current_code(self.cmb_normal_mat)
            if code:
                return str(code).strip()
        except Exception:
            pass
        try:
            txt = self.cmb_normal_mat.currentText().strip()
            # labels may be like "排水 — Thoát nước"; keep the code side when possible.
            return txt.split("—", 1)[0].strip()
        except Exception:
            return ""

    def library_pipe_sizes_for_material(self, pipe: str = "") -> List[str]:
        """Build pipe-size list from the actual library/index, not hard-coded PIPE_SIZE_ORDER.

        The list is intentionally material-scoped.  VP/DV/TMP/HIVP/STPG can each
        have a different size family.  If nothing is found, return [] so the UI
        stays blank instead of falling back to 65.
        """
        pipe = self.pipe_prefix(pipe or self.current_material_code())
        aliases = self.pipe_aliases(pipe, "配管") | self.pipe_aliases(pipe, "LL") | {pipe}
        out: List[str] = []
        for item in getattr(self, "library_index", []) or []:
            if not isinstance(item, dict):
                continue
            it_pipe = str(item.get("pipe", "")).strip()
            if it_pipe not in aliases:
                continue
            sz = str(item.get("size", "")).strip()
            nums = re.findall(r"\d+", sz)
            # For 65x50 fittings, both sizes are useful as available pipe sizes.
            for n in nums:
                if n and n not in out:
                    out.append(n)
            # Some pipe JSON/TXT may have blank size in metadata; recover from filename.
            if not nums:
                pth = str(item.get("path", ""))
                for n in re.findall(r"\d+", Path(pth).stem):
                    if n and n not in out:
                        out.append(n)
        def sort_key(v: str):
            try:
                return (int(v), v)
            except Exception:
                return (10**9, v)
        return sorted(out, key=sort_key)

    def dynamic_lower_pipe_size(self, size: str) -> str:
        """One-size-down using the current material's real size list."""
        size = str(size or "").strip().split("x")[0]
        if not size:
            return ""
        sizes = self.library_pipe_sizes_for_material()
        if not sizes:
            return lower_pipe_size(size) if size else ""
        if size in sizes:
            i = sizes.index(size)
            return sizes[max(0, i - 1)]
        try:
            v = int(float(size))
            smaller = [s for s in sizes if int(float(s)) < v]
            return smaller[-1] if smaller else ""
        except Exception:
            return ""

    def terminal_options_from_library(self, pipe: str = "", current_size: str = "") -> List[str]:
        """Return LL/DL/脚部 variants existing in the selected material library.

        Examples shown in combo: LL, LL_U, LL_D, DL, DL_U, DL_D.  If a current
        main size is selected, prefer terminal files containing that size but
        still keep other variants available when the size-specific file is absent.
        """
        pipe = self.pipe_prefix(pipe or self.current_material_code())
        aliases = self.pipe_aliases(pipe, "LL") | self.pipe_aliases(pipe, "DL") | {pipe}
        cur_nums = re.findall(r"\d+", str(current_size or ""))
        cur_base = cur_nums[0] if cur_nums else ""
        exact: List[str] = []
        loose: List[str] = []
        for item in getattr(self, "library_index", []) or []:
            if not isinstance(item, dict):
                continue
            it_pipe = str(item.get("pipe", "")).strip()
            if it_pipe not in aliases:
                continue
            ftype = self.normalize_lib_type(str(item.get("type", "")))
            if ftype not in {"LL", "DL", "脚部"}:
                continue
            pth = str(item.get("path", ""))
            mode = self._path_terminal_mode(pth) or self._terminal_size_mode(str(item.get("size", "")))
            label = ftype + (f"_{mode}" if mode else "")
            fnums = re.findall(r"\d+", str(item.get("size", "")) + "_" + Path(pth).stem)
            bucket = exact if (cur_base and cur_base in fnums) else loose
            if label and label not in bucket:
                bucket.append(label)
        out: List[str] = []
        for arr in (exact, loose):
            for x in arr:
                if x not in out:
                    out.append(x)
        def key(v: str):
            order = {"DL": 0, "DL_U": 1, "DL_D": 2, "LL": 3, "LL_U": 4, "LL_D": 5, "脚部": 6, "脚部_U": 7}
            return (order.get(v, 99), v)
        return sorted(out, key=key)

    def refresh_size_and_terminal_from_library(self):
        """Refresh main/branch size and terminal options from material/library data."""
        if not hasattr(self, "cmb_main_size") or not hasattr(self, "cmb_branch_size"):
            return
        pipe = self.current_material_code()
        cur_main = self.cmb_main_size.currentText().strip()
        cur_branch = self.cmb_branch_size.currentText().strip()
        sizes = self.library_pipe_sizes_for_material(pipe)
        if sizes:
            self.cmb_main_size.blockSignals(True)
            self.cmb_main_size.clear(); self.cmb_main_size.addItems([""] + sizes)
            self.cmb_main_size.setCurrentText(cur_main if cur_main in sizes else "")
            self.cmb_main_size.blockSignals(False)
            self.cmb_branch_size.blockSignals(True)
            self.cmb_branch_size.clear(); self.cmb_branch_size.addItems([""] + sizes)
            self.cmb_branch_size.setCurrentText(cur_branch if cur_branch in sizes else "")
            self.cmb_branch_size.blockSignals(False)
        if hasattr(self, "cmb_terminal"):
            cur_term = self.cmb_terminal.currentText().strip()
            terms = self.terminal_options_from_library(pipe, self.cmb_main_size.currentText().strip())
            if terms:
                self.cmb_terminal.blockSignals(True)
                self.cmb_terminal.clear(); self.cmb_terminal.addItems(terms)
                self.cmb_terminal.setCurrentText(cur_term if cur_term in terms else terms[0])
                self.cmb_terminal.blockSignals(False)
        self.sync_branch_size_from_rule()

    def fallback_sizes_for_type(self, ftype: str, current_size: str = "") -> List[str]:
        ftype = self.normalize_lib_type(ftype)
        if ftype == "集合管":
            return ["65x75", "75x65", "65x50", "50x65", "65", "75", "100x65x50"]
        if ftype in ["Y", "LT", "DT", "T", "SV", "S"]:
            main = parse_fitting_size_pair(current_size, self.cmb_main_size.currentText())[0]
            if not main:
                return []
            down = self.dynamic_lower_pipe_size(main)
            vals = [f"{main}x{down}" if down else "", f"{main}x{main}"]
            return [x for x in vals if x]
        if ftype in ["DL", "LL", "脚部"]:
            base = (current_size.split("x")[0] if current_size else self.cmb_main_size.currentText()).strip()
            if not base:
                return []
            return [f"{base}xU", base]
        base = (current_size.split("x")[0] if current_size else self.cmb_main_size.currentText()).strip()
        return [base] if base else []

    def update_size_choices_for_selected(self):
        ftype = self.cmb_fit_type.currentText()
        nid = self.selected_node
        current = self.cmb_fit_size.currentText().strip()
        pipe = self.current_pipe_for_node(nid)
        sizes = self.library_sizes(pipe, ftype)
        if not sizes:
            sizes = self.fallback_sizes_for_type(ftype, current or self.cmb_main_size.currentText())
        self.cmb_fit_size.blockSignals(True)
        self.cmb_fit_size.clear()
        self.cmb_fit_size.addItems(sizes)
        if current and current in sizes:
            self.cmb_fit_size.setCurrentText(current)
        elif current:
            self.cmb_fit_size.setEditText(current)
        self.cmb_fit_size.blockSignals(False)
        self.update_selected_library_preview()

    def _size_tokens_match(self, lib_size: str, requested_size: str, up: bool = False, ftype: str = "") -> bool:
        lib_size = (lib_size or "").strip()
        requested_size = (requested_size or "").strip()
        if not requested_size:
            return False
        if lib_size == requested_size:
            return True
        a = lib_size.replace("_", "x").upper()
        b = requested_size.replace("_", "x").upper()
        if a == b:
            return True

        # Branch fittings: main and branch are separate identity fields.
        # Example: requested 65x50 must not match stored 65x65.
        if self.normalize_lib_type(ftype) in STRICT_BRANCH_SIZE_FITTINGS:
            return _strict_fitting_size_match(ftype, lib_size, requested_size)

        # Terminal UP/U files can have names like LL_30_U or DL_30_30_U.
        # Both should match requested size 30xU and base size 30.
        if up and ("U" in b or "UP" in b):
            bnums = re.findall(r"\d+", b)
            anums = re.findall(r"\d+", a)
            if bnums and anums and bnums[0] == anums[0]:
                return True
        return False

    def _terminal_size_mode(self, size: str) -> str:
        """Return terminal direction marker from a fitting size/name: U=up, D=down, N=neutral/none."""
        txt = str(size or "").upper().replace(" ", "")
        if re.search(r"(^|[X_\-])U(P)?($|[X_\-])", txt):
            return "U"
        if re.search(r"(^|[X_\-])D(OWN)?($|[X_\-])", txt):
            return "D"
        if re.search(r"(^|[X_\-])N($|[X_\-])", txt):
            return "N"
        return ""

    def _path_terminal_mode(self, path: str) -> str:
        stem = Path(str(path or "")).stem.upper()
        if re.search(r"(^|[_\-])U(P)?($|[_\-])", stem):
            return "U"
        if re.search(r"(^|[_\-])D(OWN)?($|[_\-])", stem):
            return "D"
        if re.search(r"(^|[_\-])N($|[_\-])", stem):
            return "N"
        return ""

    def _is_marked_y_centerline_file(self, path: str) -> bool:
        """Return True when a Y TXT contains the NEVIS explicit centerline rule.

        Required convention:
        - lc8 line starts at 0,0 and points downstream to 集合管, usually 130mm.
        - another origin line (often lc2) points to the branch, usually about 200mm.
        This lets Y be placed by center vectors, not by guessed mouth geometry.
        """
        if not path or not is_y_library_name(path):
            return False
        try:
            current_lc = ""
            has_lc8_origin = False
            has_other_origin = False
            num = r"-?\d+(?:\.\d+)?(?:e[-+]?\d+)?"
            line_re = re.compile(rf"^\s*({num})\s+({num})\s+({num})\s+({num})\s*$", re.I)
            for raw in _read_library_lines(path):
                line = str(raw).strip()
                low = line.lower()
                if low.startswith("lc"):
                    current_lc = low[2:].strip()
                    continue
                m = line_re.match(line)
                if not m:
                    continue
                x1, y1, x2, y2 = map(float, m.groups())
                starts_origin = math.hypot(x1, y1) <= 2.5 or math.hypot(x2, y2) <= 2.5
                if not starts_origin:
                    continue
                L = math.hypot(x2-x1, y2-y1)
                if current_lc == "8" and 80.0 <= L <= 180.0:
                    has_lc8_origin = True
                elif current_lc != "8" and 120.0 <= L <= 260.0:
                    has_other_origin = True
                if has_lc8_origin and has_other_origin:
                    return True
        except Exception:
            return False
        return False

    def current_system_folder_aliases(self) -> List[str]:
        """Folder aliases for selected system. Example: 排水 -> Thoat nuoc / 排水."""
        try:
            data = getattr(self, "_nevis_master_data", None) or self.load_nevis_master_data()
            code = self._combo_current_code(self.cmb_system) if hasattr(self, "cmb_system") else "排水"
            item = self._find_master_item(data, "systems", code)
            return system_folder_aliases_from_code(code, item)
        except Exception:
            return ["Thoat nuoc", "Thoát nước", "排水"]

    def direct_library_path_from_folder(self, pipe: str, ftype: str, size: str) -> str:
        """Find library directly from Library/<system>/<pipe>/<type>/ first.

        Supports new structure: library/Thoat nuoc/DV/Y/Y_65_50.json,
        with old structure library/DV/Y/Y_65_50.json kept as compatibility.
        Terminal U/D suffix remains strict.
        """
        pipe = self.pipe_prefix(pipe)
        ftype = self.normalize_lib_type(ftype)
        try:
            lib_count = len(getattr(self, "library_index", []) or [])
        except Exception:
            lib_count = 0
        cache_key = ("|".join(self.current_system_folder_aliases()), str(pipe), str(ftype), str(size), lib_count)
        cached_path = _LIB_PATH_CACHE.get(cache_key)
        if cached_path and Path(cached_path).exists():
            return cached_path
        nums = re.findall(r"\d+", str(size or ""))
        base = nums[0] if nums else str(size or "").split("x")[0]
        req_main, req_branch, req_note = _nevis_size_identity(size)
        strict_branch = self.normalize_lib_type(ftype) in STRICT_BRANCH_SIZE_FITTINGS
        mode = self._terminal_size_mode(size)
        pipe_aliases = self.pipe_aliases(pipe, ftype)
        type_aliases = list(self.type_aliases(ftype))
        # Folder aliases for terminal fittings.  Python set + list caused a crash here.
        # Keep order strict so DL_50_50_U.json is checked before normal DL folder fallback.
        if mode == "U":
            type_aliases += [ftype + " Up", ftype + " UP", ftype + "Up", ftype + "_U"]
        elif mode == "D":
            type_aliases += [ftype + " Down", ftype + " DOWN", ftype + "Down", ftype + "_D"]
        roots = []
        for base_dir in [Path.cwd(), Path(__file__).resolve().parent]:
            for libname in ["library", "Library"]:
                d = base_dir / libname
                if d.exists():
                    roots.append(d)
        exts = [".json", ".txt"]
        scored = []
        search_roots = []
        for root in roots:
            for sd in self.current_system_folder_aliases():
                d = root / sd
                if d.exists() and d.is_dir():
                    search_roots.append(d)
            search_roots.append(root)  # old library/DV/Y compatibility
        seen_roots = set(); search_roots2 = []
        for r in search_roots:
            k = str(r.resolve()).lower()
            if k not in seen_roots:
                seen_roots.add(k); search_roots2.append(r)
        def candidate_type_dirs(root: Path):
            # Normal: library/<system>/<material>/<group>/file
            for pp in pipe_aliases:
                pipe_dir = root / pp
                if not pipe_dir.exists():
                    continue
                for tt in type_aliases:
                    yield pipe_dir / tt
            # Special role libraries may live directly under the system folder:
            # library/<system>/集合管/... or library/<system>/脚部/...
            if ftype in {"集合管", "脚部", "配管"}:
                for tt in type_aliases:
                    yield root / tt

        for root in search_roots2:
            for tdir in candidate_type_dirs(root):
                if not tdir.exists():
                    continue
                for f in list(tdir.glob("*.json")) + list(tdir.glob("*.txt")):
                    stem = f.stem.upper()
                    item_mode = self._path_terminal_mode(str(f))
                    if mode == "U" and item_mode != "U":
                        continue
                    if mode == "D" and item_mode != "D":
                        continue
                    if not mode and item_mode in {"U", "D"}:
                        continue
                    fnums = re.findall(r"\d+", stem)
                    # 45° files may have a leading 45 token from the group name.
                    fnums_for_size = list(fnums)
                    if self.normalize_lib_type(ftype) == "45°" and fnums_for_size and fnums_for_size[0] == "45":
                        fnums_for_size = fnums_for_size[1:]
                    # 集合管 1 cửa: request size is only "65".  Do not accept
                    # S_65_50 / SV_65_50 because those are multi-mouth libraries
                    # and produce the wrong preview/JWW even when the label says 1 cửa.
                    if self.normalize_lib_type(ftype) == "集合管" and _collection_requested_single_port(size):
                        if not _collection_candidate_is_single_port(str(f)):
                            continue
                    if strict_branch:
                        if req_main and (not fnums_for_size or fnums_for_size[0] != req_main):
                            continue
                        if req_branch and (len(fnums_for_size) < 2 or fnums_for_size[1] != req_branch):
                            continue
                        if req_note:
                            token_text = "_" + stem + "_"
                            if ("_" + req_note.upper() + "_") not in token_text:
                                continue
                    else:
                        if base and (not fnums_for_size or fnums_for_size[0] != base):
                            continue
                    score = 0
                    if f.suffix.lower() == ".json": score += 100
                    if strict_branch and req_branch and len(fnums_for_size) >= 2 and fnums_for_size[1] == req_branch:
                        score += 80
                    if strict_branch and req_note and ("_" + req_note.upper() + "_") in ("_" + stem + "_"):
                        score += 30
                    if mode == "U" and stem.endswith("_U"): score += 40
                    if mode == "D" and stem.endswith("_D"): score += 40
                    if f"_{base}_{base}" in stem: score += 10
                    scored.append((score, str(f)))
        scored.sort(key=lambda x: x[0], reverse=True)
        result = scored[0][1] if scored else ""
        # Cache only positive hits.  A negative hit becomes stale immediately if
        # the user moves/rebuilds the library while NEVIS is open.  Caching ""
        # was the reason Y/LT/DT/T preview kept saying no library until the
        # system/material combo was changed several times.
        if result and Path(result).exists():
            _LIB_PATH_CACHE[cache_key] = result
            if len(_LIB_PATH_CACHE) > 2000:
                _LIB_PATH_CACHE.clear()
        return result

    def matching_library_path(self, nid: Optional[int], ftype: str, size: str) -> str:
        pipe = self.current_pipe_for_node(nid)
        ftype = self.normalize_lib_type(ftype)

        # Step 8: new structured database must win over stale index/Ruby fallback.
        # Example: library/Thoat nuoc/DV/Y/Y_65_50.json must be selected before
        # any old indexed TMP/Y/Y_65_50.json with the same size.
        direct_first = self.direct_library_path_from_folder(pipe, ftype, size)
        if direct_first:
            return direct_first

        aliases = self.pipe_aliases(pipe, ftype)
        type_alias = self.type_aliases(ftype)
        sys_alias = {x.lower() for x in self.current_system_folder_aliases()}
        sys_code_alias = {infer_system_code_from_folder(x) for x in self.current_system_folder_aliases()}
        exact = []
        loose = []
        for item in self.library_index:
            if not isinstance(item, dict):
                continue
            it_system = str(item.get("system", ""))
            if it_system and it_system.lower() not in sys_alias and infer_system_code_from_folder(it_system) not in sys_code_alias:
                continue
            it_pipe = str(item.get("pipe", ""))
            it_type = self.normalize_lib_type(str(item.get("type", "")))
            it_size = str(item.get("size", ""))
            if it_pipe in aliases and it_type in type_alias:
                pth = str(item.get("path", ""))
                if ftype == "集合管" and _collection_requested_single_port(size):
                    # Keep 集合管 1 cửa strict.  Old index search previously accepted
                    # S_65_50/SV_65_50 because only the first size matched.
                    if not _collection_candidate_is_single_port(pth or str(item.get("size", ""))):
                        continue
                item_mode = self._path_terminal_mode(pth)
                req_mode = self._terminal_size_mode(size)
                up = bool(item.get("up")) or item_mode == "U"

                # Very important: terminal direction is strict.
                # 50xU must use only *_U.json/txt; it must NEVER fall back to normal DL/LL
                # or to *_D / *_N.  Down/normal endpoints are also kept separate.
                if req_mode == "U":
                    if item_mode != "U" and not up:
                        continue
                elif req_mode == "D":
                    if item_mode != "D":
                        continue
                else:
                    if item_mode in {"U", "D"}:
                        continue

                if self._size_tokens_match(it_size, size, up or req_mode == "U", ftype):
                    if req_mode == "U" and (item_mode == "U" or up):
                        exact.insert(0, pth)
                    else:
                        exact.append(pth)
                elif (self.normalize_lib_type(ftype) not in STRICT_BRANCH_SIZE_FITTINGS) and (not req_mode) and size and it_size and re.findall(r"\d+", it_size)[:1] == re.findall(r"\d+", size)[:1]:
                    loose.append(pth)
        candidates = [p for p in (exact + loose) if p and Path(p).exists()]
        if ftype == "Y" and candidates:
            # v46: if both old Y_65_50.txt and new DV_Y_65_50.txt exist, use the
            # marked centerline file.  This was the reason v45 behaved like v37.
            marked = [p for p in candidates if self._is_marked_y_centerline_file(p)]
            if marked:
                # Prefer current material family prefix when available.
                fam = self.material_family_for_size_tables(nid)
                if fam == "TMP":
                    pref = [p for p in marked if Path(p).stem.upper().startswith("TMP_Y")]
                else:
                    pref = [p for p in marked if Path(p).stem.upper().startswith(("DV_Y", "VP_Y", "VU_Y"))]
                return pref[0] if pref else marked[0]
        for p in candidates:
            return p

        # Direct fallback from current folder structure.  This catches freshly edited
        # JSON files even when the cache/index has stale metadata.
        direct = self.direct_library_path_from_folder(pipe, ftype, size)
        if direct:
            return direct
        return ""

    def update_selected_library_preview(self):
        if not hasattr(self, "fit_preview_scene"):
            return
        path = self.matching_library_path(self.selected_node, self.cmb_fit_type.currentText(), self.cmb_fit_size.currentText().strip())
        self.draw_library_preview(path)


    def pipe_library_path(self, mat: str, size: str) -> str:
        """Find a straight-pipe TXT template under library/配管.

        Supported examples:
            library/配管/TMP_20.txt
            library/配管/VP_20.txt
        The selected edge still controls the real length; the TXT is only a
        shape template for preview/drawing style.
        """
        size = str(size or "").split("x")[0].strip()
        mat = self.pipe_prefix(mat)
        candidates = []
        if mat in ["DV", "VP", "VU", "VP/VU"]:
            candidates = ["VP", "DV", "VU", "VP/VU"]
        elif mat in ["TMP", "トミジ"]:
            candidates = ["TMP", "トミジ"]
        elif mat in ["HT", "HTVP"]:
            candidates = ["HTVP", "HT"]
        elif mat in ["耐火VP", "TaikaVP"]:
            candidates = ["耐火VP", "TaikaVP", "VP"]
        else:
            candidates = [mat]

        # Prefer indexed library entries.
        for item in self.library_index:
            if not isinstance(item, dict):
                continue
            if self.normalize_lib_type(str(item.get("type", ""))) != "配管":
                continue
            if str(item.get("pipe", "")) in candidates and str(item.get("size", "")) == size:
                p = str(item.get("path", ""))
                if p and Path(p).exists():
                    return p

        # Fallback direct search in common folders.
        names = []
        for c in candidates:
            names.append(f"{c}_{size}.json")
            names.append(f"{c}-{size}.json")
            names.append(f"{c}_{size}.txt")
            names.append(f"{c}-{size}.txt")
        for base in [Path.cwd(), Path(__file__).resolve().parent]:
            sys_roots = []
            for sd in self.current_system_folder_aliases():
                sys_roots.append(base / "library" / sd / "配管")
                for c in candidates:
                    sys_roots.append(base / "library" / sd / c / "配管")
            for root in sys_roots + [base / "library" / "配管", base / "配管"]:
                if not root.exists():
                    continue
                for name in names:
                    p = root / name
                    if p.exists():
                        return str(p)
        return ""

    def _scaled_pipe_entities(self, ents, target_len_mm: float):
        """Stretch the pipe TXT along its long direction to match selected edge length."""
        if not ents:
            return ents
        xs, ys = [], []
        for e in ents:
            if e.get("type") == "line":
                xs += [e["x1"], e["x2"]]
                ys += [e["y1"], e["y2"]]
            elif e.get("type") in ["circle", "arc"]:
                xs += [e["cx"] - e["r"], e["cx"] + e["r"]]
                ys += [e["cy"] - e["r"], e["cy"] + e["r"]]
        if not xs or not ys:
            return ents
        minx, maxx = min(xs), max(xs)
        miny, maxy = min(ys), max(ys)
        w, h = max(maxx-minx, 1.0), max(maxy-miny, 1.0)
        # Most pipe TXT is horizontal. If a future template is vertical, stretch Y instead.
        stretch_x = w >= h
        scale = max(float(target_len_mm), 1.0) / (w if stretch_x else h)
        out = []
        for e in ents:
            ne = dict(e)
            if e.get("type") == "line":
                if stretch_x:
                    ne["x1"] = minx + (e["x1"] - minx) * scale
                    ne["x2"] = minx + (e["x2"] - minx) * scale
                else:
                    ne["y1"] = miny + (e["y1"] - miny) * scale
                    ne["y2"] = miny + (e["y2"] - miny) * scale
            elif e.get("type") in ["circle", "arc"]:
                if stretch_x:
                    ne["cx"] = minx + (e["cx"] - minx) * scale
                else:
                    ne["cy"] = miny + (e["cy"] - miny) * scale
            out.append(ne)
        return out

    def draw_pipe_preview(self, e: Edge):
        """Show selected pipe information and optional pipe TXT template in the fitting preview box."""
        sc = self.fit_preview_scene
        sc.clear()
        mat = self.edge_material(e)
        prefix = self.pipe_prefix(mat)
        label = f"{e.size}{prefix}"
        length_m = self.model.edge_length(e) / 1000.0
        path = self.pipe_library_path(mat, e.size)

        title = sc.addText(f"{label}\n{length_m:.3f} m", QFont("Segoe UI", 10, QFont.Bold))
        title.setDefaultTextColor(QColor(30, 80, 120))
        title.setZValue(20)

        if path:
            try:
                ents = parse_jww_library_geometry(path)
                ents = self._scaled_pipe_entities(ents, self.model.edge_length(e))
            except Exception:
                ents = []
            pen = QPen(QColor(0, 88, 125), 1.7)
            pen.setCosmetic(True)
            for ent in ents[:1200]:
                typ = ent.get("type")
                if typ == "line":
                    sx1, sy1 = display_point(ent["x1"], ent["y1"])
                    sx2, sy2 = display_point(ent["x2"], ent["y2"])
                    sc.addLine(sx1, sy1, sx2, sy2, pen)
                elif typ == "circle":
                    sx, sy = display_point(ent["cx"], ent["cy"]); r = ent["r"]
                    sc.addEllipse(sx-r, sy-r, r*2, r*2, pen)
                elif typ == "arc":
                    pts = arc_points(ent["cx"], ent["cy"], ent["r"], ent["a1"], ent["a2"], ent.get("rot", 0.0))
                    for (x1,y1),(x2,y2) in zip(pts, pts[1:]):
                        sx1, sy1 = display_point(x1, y1)
                        sx2, sy2 = display_point(x2, y2)
                        sc.addLine(sx1, sy1, sx2, sy2, pen)
            note = sc.addText(f"LIB: {Path(path).name}", QFont("Segoe UI", 8))
            note.setDefaultTextColor(QColor(110, 110, 110))
            note.setPos(0, 32)
            note.setFlag(QGraphicsItem.ItemIgnoresTransformations, True)
        else:
            note = sc.addText("Không tìm thấy JSON/TXT ống trong thư viện 配管", QFont("Segoe UI", 8))
            note.setDefaultTextColor(QColor(150, 90, 60))
            note.setPos(0, 38)

        # Show the resolved library file/folder directly in the preview box.
        # This is a practical check line so a wrong DL/LL/U/D selection is visible immediately.
        try:
            lib_note = sc.addText("LIB: " + str(Path(path).parent.name) + "/" + str(Path(path).name), QFont("Segoe UI", 7))
            lib_note.setDefaultTextColor(QColor(120, 120, 120))
            lib_note.setPos(0, -28)
            lib_note.setFlag(QGraphicsItem.ItemIgnoresTransformations, True)
        except Exception:
            pass

        # Show the resolved library file/folder directly in the preview box.
        # This is a practical check line so a wrong DL/LL/U/D selection is visible immediately.
        try:
            lib_note = sc.addText("LIB: " + str(Path(path).parent.name) + "/" + str(Path(path).name), QFont("Segoe UI", 7))
            lib_note.setDefaultTextColor(QColor(120, 120, 120))
            lib_note.setPos(0, -28)
            lib_note.setFlag(QGraphicsItem.ItemIgnoresTransformations, True)
        except Exception:
            pass

        try:
            note = sc.addText("LIB: " + str(Path(path).parent.name) + "/" + str(Path(path).name), QFont("Segoe UI", 7))
            note.setDefaultTextColor(QColor(120, 120, 120))
            note.setPos(0, -28)
            note.setFlag(QGraphicsItem.ItemIgnoresTransformations, True)
        except Exception:
            pass

        if sc.items():
            rect = sc.itemsBoundingRect()
            pad = max(8.0, max(rect.width(), rect.height()) * 0.04)
            rect = rect.adjusted(-pad, -pad, pad, pad)
            sc.setSceneRect(rect)
            self.fit_preview.resetTransform()
            self.fit_preview.fitInView(rect, Qt.KeepAspectRatio)

    def expected_library_name_for_selection(self) -> str:
        try:
            ftype = self.normalize_lib_type(self.cmb_fit_type.currentText())
            size = self.cmb_fit_size.currentText().strip()
            main, branch, note = _nevis_size_identity(size)
            if self.normalize_lib_type(ftype) in STRICT_BRANCH_SIZE_FITTINGS and main and branch:
                name = f"{ftype}_{main}_{branch}"
            elif main:
                name = f"{ftype}_{main}"
            else:
                name = f"{ftype}_{size}"
            if note:
                name += f"_{note}"
            return name + ".json"
        except Exception:
            return ""

    def searched_library_dirs_for_selection(self) -> str:
        try:
            pipe = self.pipe_prefix(self.current_pipe_for_node(self.selected_node))
            ftype = self.normalize_lib_type(self.cmb_fit_type.currentText())
            roots = []
            for base in [Path.cwd(), Path(__file__).resolve().parent]:
                for libname in ["library", "Library"]:
                    d = base / libname
                    if d.exists():
                        for sysdir in self.current_system_folder_aliases():
                            roots.append(str(d / sysdir / pipe / ftype))
                        roots.append(str(d / pipe / ftype))
            return "\n".join(roots[:8]) if roots else "library"
        except Exception:
            return "library"

    def draw_library_preview(self, path: str):
        sc = self.fit_preview_scene
        sc.clear()
        if not path or not Path(path).exists():
            try:
                msg = self.tr("missing_library_detail").format(
                    system=self.cmb_system.currentText() if hasattr(self, "cmb_system") else "",
                    material=self.current_pipe_for_node(self.selected_node),
                    group=self.cmb_fit_type.currentText() if hasattr(self, "cmb_fit_type") else "",
                    name=self.expected_library_name_for_selection(),
                    paths=self.searched_library_dirs_for_selection(),
                )
            except Exception:
                msg = self.tr("no_lib_txt")
            sc.addText(msg, QFont("Segoe UI", 8)).setDefaultTextColor(QColor(130,90,60))
            return
        try:
            ents = parse_jww_library_geometry(path)
        except Exception:
            sc.addText(self.tr("cant_read_txt"), QFont("Segoe UI", 9)).setDefaultTextColor(QColor(180,60,60))
            return
        if not ents:
            sc.addText(self.tr("cant_read_txt"), QFont("Segoe UI", 9)).setDefaultTextColor(QColor(180,60,60))
            return

        # Keep the original JWW geometry but use display_point only for screen orientation.
        line_pen = QPen(QColor(0, 88, 125), 1.8); line_pen.setCosmetic(True)
        circle_pen = QPen(QColor(0, 88, 125), 1.8); circle_pen.setCosmetic(True)
        arc_pen = QPen(QColor(0, 88, 125), 1.8); arc_pen.setCosmetic(True)

        def add_polyline(points, pen):
            if len(points) < 2:
                return
            for (x1,y1),(x2,y2) in zip(points, points[1:]):
                sx1,sy1 = display_point(x1,y1); sx2,sy2 = display_point(x2,y2)
                sc.addLine(sx1, sy1, sx2, sy2, pen)

        for e in ents[:1400]:
            typ = e.get("type")
            if typ == "line":
                sx1,sy1 = display_point(e["x1"], e["y1"]); sx2,sy2 = display_point(e["x2"], e["y2"])
                sc.addLine(sx1, sy1, sx2, sy2, line_pen)
            elif typ == "circle":
                # Ellipse rect also needs orientation conversion. Radius is unchanged.
                sx,sy = display_point(e["cx"], e["cy"]); r = e["r"]
                sc.addEllipse(sx-r, sy-r, r*2, r*2, circle_pen)
            elif typ == "arc":
                pts = arc_points(e["cx"], e["cy"], e["r"], e["a1"], e["a2"], e.get("rot", 0.0))
                add_polyline(pts, arc_pen)

        # JSON debug overlay: show real connector direction and FLOW in the library
        # preview.  This is intentionally drawn in the preview itself so Đại ca can
        # immediately see whether the JSON library is correct before NEVIS places it.
        try:
            if Path(path).suffix.lower() == ".json":
                anchor, ports, meta = _json_connector_objects(path)
                red_pen = QPen(QColor(210, 40, 40), 1.2); red_pen.setCosmetic(True)
                green_pen = QPen(QColor(0, 150, 60), 1.8); green_pen.setCosmetic(True)
                blue_pen = QPen(QColor(0, 70, 190), 1.4); blue_pen.setCosmetic(True)
                ax, ay = display_point(anchor[0], anchor[1])
                sc.addLine(ax-10, ay, ax+10, ay, red_pen); sc.addLine(ax, ay-10, ax, ay+10, red_pen)
                txtc = sc.addText("CENTER", QFont("Segoe UI", 8, QFont.Bold)); txtc.setDefaultTextColor(QColor(190,40,40)); txtc.setPos(ax+8, ay+4)
                def draw_arrow(x, y, ang, pen, length=46.0):
                    x2, y2 = x + math.cos(ang)*length, y + math.sin(ang)*length
                    sx1, sy1 = display_point(x, y); sx2, sy2 = display_point(x2, y2)
                    sc.addLine(sx1, sy1, sx2, sy2, pen)
                    aa = math.atan2(sy2-sy1, sx2-sx1)
                    for off in (2.55, -2.55):
                        hx = sx2 + math.cos(aa+off)*11; hy = sy2 + math.sin(aa+off)*11
                        sc.addLine(sx2, sy2, hx, hy, pen)
                for po in ports:
                    xy = po.get('point') or anchor
                    px, py = float(xy[0]), float(xy[1])
                    spx, spy = display_point(px, py)
                    sc.addEllipse(spx-5, spy-5, 10, 10, blue_pen)
                    draw_arrow(px, py, float(po.get('axis',0.0)), blue_pen, 34.0)
                    t = sc.addText(str(po.get('name','P')), QFont("Segoe UI", 9, QFont.Bold)); t.setDefaultTextColor(QColor(0,70,190)); t.setPos(spx+8, spy+8)
                # FLOW: P1 -> P2 by convention, or explicit standard/downstream port if present.
                if len(ports) >= 2:
                    p1 = next((po for po in ports if str(po.get('name','')).upper().endswith('P1')), ports[0])
                    p2name = str(meta.get('standard_port') or meta.get('downstream_port') or meta.get('out_port') or 'P2').upper()
                    p2 = next((po for po in ports if str(po.get('name','')).upper() == p2name or str(po.get('name','')).upper().endswith(p2name)), ports[1])
                    xy1 = p1.get('point') or anchor; xy2 = p2.get('point') or anchor
                    x1,y1 = display_point(float(xy1[0]), float(xy1[1])); x2,y2 = display_point(float(xy2[0]), float(xy2[1]))
                    sc.addLine(x1, y1, x2, y2, green_pen)
                    aa = math.atan2(y2-y1, x2-x1)
                    for off in (2.55, -2.55):
                        sc.addLine(x2, y2, x2 + math.cos(aa+off)*14, y2 + math.sin(aa+off)*14, green_pen)
                    ft = sc.addText("FLOW", QFont("Segoe UI", 10, QFont.Bold)); ft.setDefaultTextColor(QColor(0,145,55)); ft.setPos((x1+x2)/2+8, (y1+y2)/2+8)
        except Exception as ex:
            try:
                sc.addText(f"JSON port preview error: {ex}", QFont("Segoe UI", 7)).setDefaultTextColor(QColor(180,60,60))
            except Exception:
                pass

        if sc.items():
            rect = sc.itemsBoundingRect()
            pad = max(4.0, max(rect.width(), rect.height()) * 0.025)
            rect = rect.adjusted(-pad, -pad, pad, pad)
            sc.setSceneRect(rect)
            self.fit_preview.resetTransform()
            self.fit_preview.centerOn(rect.center())
            self.fit_preview.fitInView(rect, Qt.KeepAspectRatio)

    def update_support_kind_items(self):
        """Cùm ống của 排水転がし配管 chỉ dùng レベル, không cho chọn loại khác."""
        self.support_kind = "レベル"
        if hasattr(self, "cmb_support_kind"):
            self.cmb_support_kind.blockSignals(True)
            self.cmb_support_kind.clear()
            self.cmb_support_kind.addItem("レベル")
            self.cmb_support_kind.setCurrentText("レベル")
            self.cmb_support_kind.setVisible(False)
            self.cmb_support_kind.blockSignals(False)
        if hasattr(self, "lbl_support_kind"):
            self.lbl_support_kind.setVisible(False)

    def update_support_controls(self, refresh_only: bool = False):
        """Enable support inputs without recalculating immediately.

        The first checkbox means "calculate support bands".  It must be light:
        checking it only enables controls.  Real calculation happens only when
        the user presses Apply.  The second checkbox only toggles drawing of the
        already-calculated bands, so the material table can still count them.
        """
        if not hasattr(self, "chk_support_band"):
            return
        enabled = self.chk_support_band.isChecked()
        self.support_enabled = bool(enabled)
        for w in [self.lbl_support_spacing, self.edit_support_spacing, self.lbl_support_kind, self.cmb_support_kind, self.btn_apply_support]:
            w.setEnabled(enabled)
        cache_ready = bool(enabled and getattr(self, "_support_cache", []))
        if hasattr(self, "chk_show_support_band"):
            self.chk_show_support_band.setEnabled(cache_ready)
            if not enabled:
                self.chk_show_support_band.blockSignals(True)
                self.chk_show_support_band.setChecked(False)
                self.chk_show_support_band.blockSignals(False)
                self.support_visible = False
        if enabled:
            self.lbl_support_hint.setText(self.tr("support_hint_on"))
        else:
            self.lbl_support_hint.setText(self.tr("support_hint_off"))
            self._support_cache = []
            self._support_cache_key = None
        # Do not call refresh_all here.  This function is triggered by checkbox
        # state changes, and recalculating/redrawing here caused visible lag.
        if not refresh_only and hasattr(self, "preview"):
            self.preview.draw_model()

    def toggle_support_visibility(self):
        if not hasattr(self, "chk_show_support_band"):
            return
        if not getattr(self, "support_enabled", False) or not getattr(self, "_support_cache", []):
            self.support_visible = False
            self.chk_show_support_band.blockSignals(True)
            self.chk_show_support_band.setChecked(False)
            self.chk_show_support_band.blockSignals(False)
            return
        self.support_visible = bool(self.chk_show_support_band.isChecked())
        if hasattr(self, "preview"):
            self.preview.draw_model()

    def _support_signature(self) -> Tuple[object, ...]:
        """Small cache key for support-band calculation."""
        edge_sig = []
        try:
            for e in self.model.edges:
                edge_sig.append((e.key, e.a, e.b, str(e.size), str(getattr(e, "material_override", ""))))
        except Exception:
            pass
        fit_sig = []
        try:
            for nid, f in sorted(self.model.fittings.items()):
                fit_sig.append((nid, str(f.ftype), str(f.size), bool(f.excluded), str(getattr(f, "material_override", ""))))
        except Exception:
            pass
        return (round(float(getattr(self, "support_spacing", 900.0)), 3), str(getattr(self, "support_kind", "レベル")), tuple(edge_sig), tuple(fit_sig))

    def invalidate_support_cache(self):
        self._support_cache_key = None
        self._support_cache = []
        if hasattr(self, "chk_show_support_band"):
            self.chk_show_support_band.setEnabled(False)
            self.chk_show_support_band.blockSignals(True)
            self.chk_show_support_band.setChecked(False)
            self.chk_show_support_band.blockSignals(False)
        self.support_visible = False

    def apply_support_settings(self):
        try:
            spacing = float(self.edit_support_spacing.text().strip())
        except Exception:
            QMessageBox.warning(self, "NEVIS", self.tr("support_invalid"))
            return
        if spacing <= 0:
            QMessageBox.warning(self, "NEVIS", self.tr("support_positive"))
            return
        self.support_spacing = spacing
        self.support_kind = "レベル"
        self.support_enabled = self.chk_support_band.isChecked()
        if self.support_enabled:
            self._support_cache_key = None
            bands = self.compute_support_bands(force=True)
            if hasattr(self, "chk_show_support_band"):
                self.chk_show_support_band.setEnabled(bool(bands))
                self.chk_show_support_band.blockSignals(True)
                # After applying, show it once for visual checking. User can hide it.
                self.chk_show_support_band.setChecked(bool(bands))
                self.chk_show_support_band.blockSignals(False)
            self.support_visible = bool(bands)
            count = len(bands)
        else:
            self.invalidate_support_cache()
            count = 0
        self.refresh_all()
        self.lbl_status.setText(self.tr("support_status").format(count=count, spacing=spacing))

    def band_pipe_name_for_material(self, mat: str) -> str:
        p = self.pipe_prefix(mat)
        # For normal drainage/supply pipes, VP bands are shared. Tomiji/TMP uses TMP.
        if p in ["TMP", "トミジ"]:
            return "TMP"
        return "VP"

    def support_band_label(self, size: str, mat: str, kind: Optional[str] = None) -> str:
        k = (kind if kind is not None else getattr(self, "support_kind", "レベル")) or "レベル"
        pipe = f"{size}{self.band_pipe_name_for_material(mat)}"
        if getattr(self, "lang", "vi") == "jp":
            return f"{pipe}用{k}バンド"
        return f"Cùm ống {pipe} - {k}"

    def support_half_len_for_edge(self, e: Edge) -> float:
        nums = re.findall(r"\d+", str(e.size))
        nominal = float(nums[0]) if nums else 50.0
        return max(14.0, min(90.0, nominal * 0.75))  # half length; shortened to 1/2 of previous symbol

    def compute_support_bands(self, force: bool = False) -> List[Dict[str, object]]:
        """Compute pipe clamps between the *real fitting mouths* only.

        Rule requested by Đại ca:
        - one pipe interval between two fitting mouths gets at least one clamp;
        - clamp positions are distributed inside the clear pipe body so no gap
          exceeds the configured spacing;
        - use the same trim/mouth distance as detailed pipe drawing;
        - if the clear space between two fitting mouths is under 35mm, skip it
          because a clamp cannot realistically be installed there.
        """
        if not getattr(self, "support_enabled", False) or not self.model.nodes:
            return []
        sig = self._support_signature() if hasattr(self, "_support_signature") else None
        if not force and sig is not None and sig == getattr(self, "_support_cache_key", None):
            return list(getattr(self, "_support_cache", []))
        try:
            spacing = float(getattr(self, "support_spacing", 900.0))
        except Exception:
            spacing = 900.0
        spacing = max(1.0, spacing)
        min_clear = 35.0
        max_bands_total = 1200
        entries: List[Dict[str, object]] = []
        seen = set()

        def add_band(x, y, nx, ny, e: Edge):
            if len(entries) >= max_bands_total:
                return
            key = (round(x, 2), round(y, 2), e.key)
            if key in seen:
                return
            seen.add(key)
            entries.append({
                "x": x, "y": y, "nx": nx, "ny": ny,
                "size": e.size, "mat": self.edge_material(e),
                "kind": getattr(self, "support_kind", "レベル"),
                "half": self.support_half_len_for_edge(e),
            })

        for e in self.model.edges:
            n1, n2 = self.model.nodes[e.a], self.model.nodes[e.b]
            dx, dy = n2.x - n1.x, n2.y - n1.y
            full_len = math.hypot(dx, dy)
            if full_len <= EPS:
                continue

            mat = self.edge_material(e)
            trim_a = max(0.0, float(self.ruby_trim_for_fitting_side(e.a, e.b, e.size, mat)))
            trim_b = max(0.0, float(self.ruby_trim_for_fitting_side(e.b, e.a, e.size, mat)))
            # Keep a tiny valid interval even if a bad library trim is too large.
            if trim_a + trim_b >= full_len:
                continue

            ta = trim_a / full_len
            tb = 1.0 - trim_b / full_len
            clear_len = full_len * (tb - ta)
            if clear_len < min_clear:
                continue

            ax, ay = n1.x + dx * ta, n1.y + dy * ta
            bx, by = n1.x + dx * tb, n1.y + dy * tb
            cdx, cdy = bx - ax, by - ay
            L = math.hypot(cdx, cdy)
            if L < min_clear:
                continue

            # Perpendicular unit vector for the clamp symbol.
            nx, ny = -cdy / L, cdx / L

            # L <= spacing -> 1 clamp at the middle between fitting mouths.
            # Larger intervals are split so no clear gap exceeds spacing.
            band_count = max(1, int(math.ceil(L / spacing)) - 1)
            band_count = min(band_count, max(0, max_bands_total - len(entries)))
            for i in range(1, band_count + 1):
                t = i / (band_count + 1)
                x = ax + cdx * t
                y = ay + cdy * t
                add_band(x, y, nx, ny, e)
                if len(entries) >= max_bands_total:
                    break
            if len(entries) >= max_bands_total:
                break
        if sig is not None:
            self._support_cache_key = sig
            self._support_cache = list(entries)
        return entries

    def _force_combo_text_visible(self, combo: QComboBox, text: str):
        """Set combo text even when the current master/filter list does not contain it.

        NEVIS dùng CSDL vật tư động theo folder. Khi một node đổi vai trò
        bằng Mặc định/Đặt đầu nhánh, loại cút có thể chuyển sang 集合管, 脚部,
        要確認... nhưng combobox đang bị lọc theo danh sách cũ. Qt setCurrentText
        sẽ im lặng thất bại nếu text không có trong list, làm màn hình vẫn hiện
        DL UP/LL Down cũ dù model đã đổi đúng. Hàm này đảm bảo UI luôn phản ánh
        đúng model, tránh người dùng tưởng phần mềm không đổi.
        """
        text = str(text or "")
        combo.blockSignals(True)
        try:
            idx = combo.findText(text)
            if idx < 0 and text:
                combo.insertItem(0, text, text)
                idx = 0
            if idx >= 0:
                combo.setCurrentIndex(idx)
            elif combo.isEditable():
                combo.setEditText(text)
        finally:
            combo.blockSignals(False)

    def select_node(self, nid:int):
        _prev_edge = self.selected_edge  # NEVIS perf: chỉ redraw nếu có edge highlight cần xóa
        self.selected_node = nid; self.selected_edge = None; self.selected_bushing_id = None
        fit = self.model.fittings.get(nid)
        n = self.model.nodes[nid]
        if fit:
            if hasattr(self, "cmb_branch_material") and getattr(fit, "material_override", ""):
                self.cmb_branch_material.setCurrentText(fit.material_override)

            # Cực quan trọng: combo phải ăn theo dữ liệu model, không được giữ
            # hiển thị cũ. Trước đây label đã đổi thành 集合管 nhưng combo vẫn hiện
            # DL UP, khiến Apply/preview tiếp tục tra thư viện sai.
            self._force_combo_text_visible(self.cmb_fit_type, fit.ftype)
            if self.cmb_fit_size.findText(str(fit.size or "")) < 0 and str(fit.size or ""):
                self.cmb_fit_size.insertItem(0, str(fit.size), str(fit.size))
            self.cmb_fit_size.blockSignals(True)
            try:
                self.cmb_fit_size.setEditText(str(fit.size or ""))
            finally:
                self.cmb_fit_size.blockSignals(False)

            self.update_size_choices_for_selected()
            # update_size_choices_for_selected() có thể rebuild list size; set lại
            # một lần nữa để không mất size hiện tại.
            if str(fit.size or ""):
                self.cmb_fit_size.blockSignals(True)
                try:
                    if self.cmb_fit_size.findText(str(fit.size)) < 0:
                        self.cmb_fit_size.insertItem(0, str(fit.size), str(fit.size))
                    self.cmb_fit_size.setEditText(str(fit.size))
                finally:
                    self.cmb_fit_size.blockSignals(False)
            self.lbl_selected.setText(f"Node {nid} / {self.make_fitting_label(nid)}")
            self.update_selected_library_preview()
        else:
            self.fit_preview_scene.clear()
            self.lbl_selected.setText(f"Node {nid} / {self.tr("pass_node")}")
        self.lbl_detail.setText(self.tr("coord_degree_fmt").format(x=n.x, y=n.y, deg=self.model.degree(nid)))
        self.lbl_status.setText(self.tr("node_selected_status").format(nid=nid))
        self.pending_reducer = None
        self.update_reducer_buttons()
        self.update_branch_material_buttons()
        # NEVIS perf: nếu không có edge nào đang được chọn thì không cần xóa highlight.
        # Khi có edge được chọn trước đó, vẫn phải redraw để bỏ highlight màu vàng.
        if _prev_edge is not None:
            self.preview.draw_model()

    def select_edge(self, key:str):
        self.selected_edge = key
        self.selected_node = None
        self.selected_bushing_id = None
        e = next((x for x in self.model.edges if x.key==key), None)
        if not e:
            return
        length = self.model.edge_length(e)/1000.0
        mat = self.edge_material(e)
        prefix = self.pipe_prefix(mat)
        pipe_name = f"{e.size}{prefix}"
        self.lbl_selected.setText(self.tr("pipe_selected"))
        self.lbl_detail.setText(f"{pipe_name}   |   {length:.3f} m")
        self.lbl_status.setText(self.tr("pipe_selected_status").format(key=key, name=pipe_name, length=length))
        self.pending_reducer = None
        self.draw_pipe_preview(e)
        self.update_reducer_buttons()
        self.update_branch_material_buttons()
        self.preview.draw_model()


    def save_undo_snapshot(self, action: str = ""):
        """Save one-step undo snapshot before changing the pipe graph."""
        self.undo_snapshot = {
            "action": action,
            "model": copy.deepcopy(self.model),
            "selected_node": self.selected_node,
            "selected_edge": self.selected_edge,
            "selected_bushing_id": self.selected_bushing_id,
        }
        self.update_reducer_buttons()

    def undo_last_action(self):
        """Undo real graph/edit operations only. Detail preview exits by the same toggle button."""
        if getattr(self, "preview_detail_mode", False):
            # In read-only detail mode, Undo is locked; this guard prevents shortcut surprises.
            return

        snap = getattr(self, "undo_snapshot", None)
        if not snap:
            return
        self.model = snap["model"]
        self.selected_node = snap.get("selected_node")
        self.selected_edge = snap.get("selected_edge")
        self.selected_bushing_id = snap.get("selected_bushing_id")
        self.pending_reducer = None
        self.undo_snapshot = None
        rebuild_flow(self.model)
        self.apply_common()
        if self.selected_bushing_id and any(int(b.get("id", -1)) == int(self.selected_bushing_id) for b in getattr(self.model, "bushings", [])):
            self.select_bushing(self.selected_bushing_id)
        elif self.selected_node and self.selected_node in self.model.nodes:
            self.select_node(self.selected_node)
        elif self.selected_edge and any(e.key == self.selected_edge for e in self.model.edges):
            self.select_edge(self.selected_edge)
        else:
            self.selected_node = None
            self.selected_edge = None
            self.refresh_all()
            self.update_reducer_buttons()
            self.update_branch_material_buttons()
        self.lbl_status.setText(self.tr("undo_done"))

    def update_reducer_buttons(self):
        """Update 異径ソケット button states by selection context."""
        if not hasattr(self, "btn_insert_reducer"):
            return
        fit = self.model.fittings.get(self.selected_node) if self.selected_node else None
        has_pipe = bool(self.selected_edge)
        pending = bool(getattr(self, "pending_reducer", None))
        is_in = bool(fit and fit.ftype == "IN" and not fit.excluded)
        is_bushing = bool(self.selected_bushing_id and any(int(b.get("id", -1)) == int(self.selected_bushing_id) for b in getattr(self.model, "bushings", [])))
        self.btn_insert_reducer.setEnabled(has_pipe and not pending)
        self.btn_confirm_reducer.setEnabled(pending)
        self.btn_cancel_reducer.setEnabled(pending)
        self.btn_delete_reducer.setEnabled((is_in or is_bushing) and not pending)
        can_undo = bool(getattr(self, "undo_snapshot", None)) and (not pending) and (not bool(getattr(self, "preview_detail_mode", False)))
        if hasattr(self, "btn_undo"):
            self.btn_undo.setEnabled(can_undo)
        if hasattr(self, "btn_center_undo"):
            self.btn_center_undo.setEnabled(can_undo)
        if hasattr(self, "act_undo"):
            self.act_undo.setEnabled(can_undo)
        if pending:
            self.lbl_reducer_hint.setText(self.tr("reducer_hint_pending"))
        elif has_pipe:
            self.lbl_reducer_hint.setText(self.tr("pipe_hint_selected"))
        elif is_in:
            self.lbl_reducer_hint.setText(self.tr("in_hint_selected"))
        else:
            self.lbl_reducer_hint.setText(self.tr("reducer_hint_normal"))

    def reducer_size_options_for_edge(self, e: Edge) -> List[str]:
        """Find IN size options from library, preferring current pipe material and current edge size."""
        current = str(e.size).split("x")[0].strip()
        mat = self.edge_material(e)
        pipe = self.pipe_prefix(mat)
        if pipe == "HT":
            pipe = "HTVP"
        aliases = self.pipe_aliases(pipe, "IN")
        opts = []
        for item in self.library_index:
            if not isinstance(item, dict):
                continue
            if self.normalize_lib_type(str(item.get("type", ""))) != "IN":
                continue
            it_pipe = str(item.get("pipe", ""))
            if it_pipe and it_pipe not in aliases:
                # Also accept generic libraries in IN/配管-less folders.
                pass
            sz = str(item.get("size", "")).strip()
            nums = re.findall(r"\d+", sz)
            if len(nums) >= 2 and nums[0] == current and nums[1] != nums[0]:
                label = f"{nums[0]}x{nums[1]}"
                if label not in opts:
                    opts.append(label)
        def sort_key(v):
            nums = [int(x) for x in re.findall(r"\d+", v)]
            # larger-to-smaller reduction choices: 65x50 before 65x40
            return (nums[0] if nums else 0, -(nums[1] if len(nums)>1 else 0), v)
        opts = sorted(opts, key=sort_key, reverse=False)
        if not opts:
            # Fallback: one-step and smaller-step reductions when TXT cache is not scanned yet.
            if current in PIPE_SIZE_ORDER:
                i = PIPE_SIZE_ORDER.index(current)
                for j in range(i-1, -1, -1):
                    opts.append(f"{current}x{PIPE_SIZE_ORDER[j]}")
            else:
                low = lower_pipe_size(current)
                if low != current:
                    opts.append(f"{current}x{low}")
        return opts


    def _collect_bushing_downstream(self, host: int, other: int) -> Tuple[Set[int], Set[str]]:
        """Collect the pipe side controlled by one ブッシング.

        host = large fitting mouth.  other = first node/pipe on the small side.
        Everything reachable from other without crossing host or another bushing host
        is considered the small-side run.  This is intentionally geometry/network
        based, not only normal flow-parent based, so it also works when the selected
        pipe is not perfectly aligned with the current 集合管 flow tree.
        """
        nodes: Set[int] = set()
        edges: Set[str] = set()
        try:
            host = int(host); other = int(other)
        except Exception:
            return nodes, edges
        if host not in self.model.nodes or other not in self.model.nodes:
            return nodes, edges
        stop_hosts = {int(b.get("host_node", -1)) for b in getattr(self.model, "bushings", []) if str(b.get("host_node", "")).strip()}
        stop_hosts.add(host)
        q = [other]
        blocked = {host}
        while q:
            nid = q.pop(0)
            if nid in blocked or nid in nodes or nid not in self.model.nodes:
                continue
            nodes.add(nid)
            for nb in self.model.neighbors(nid):
                ed = edge_obj(self.model, nid, nb)
                if ed is not None:
                    # Include the immediate host-other edge too: that pipe starts small
                    # right at the large fitting mouth.
                    if nb != host or nid == other:
                        edges.add(ed.key)
                if nb in blocked:
                    continue
                # Do not push through the large mouth of another bushing.
                if nb in stop_hosts and nb != other:
                    continue
                if nb not in nodes:
                    q.append(nb)
        return nodes, edges

    def _force_fit_to_small_side(self, fit: Fitting, small: str):
        """Force a downstream fitting size after ブッシング.

        V17 important fix:
        When a bushing shrinks the downstream pipe, terminal DL/LL/脚部 fittings
        must keep their U/D identity.  The old logic changed a terminal like
        DL 75xU -> DL 50, so preview/detail loaded the normal DL_50 library even
        though the common terminal setting still said U.  Keep 50xU / 50xD on
        real endpoints, while route bends still stay normal single-size LL/DL.
        """
        if not fit or fit.excluded:
            return
        fbase = self._safe_group_code(getattr(fit, "ftype", ""))

        def _terminal_mode_for_fit() -> str:
            # First trust the fitting's current size, because it is the actual
            # model state before the bushing resize.
            mode = self._terminal_size_mode(str(getattr(fit, "size", ""))) if hasattr(self, "_terminal_size_mode") else ""
            if mode:
                return mode
            # If the size was already damaged by an older run, recover U/D from
            # the common terminal combo, but only for true endpoints of the same
            # family.  Never apply U/D to route bends.
            try:
                nid = int(getattr(fit, "node_id", -1))
                if getattr(self, "model", None) and self.model.degree(nid) == 1 and hasattr(self, "cmb_terminal"):
                    term = str(self.cmb_terminal.currentText() or "")
                    tbase, tsize = self.normalize_terminal_type_size(term, small)
                    if self._safe_group_code(tbase) == fbase:
                        return self._terminal_size_mode(tsize)
            except Exception:
                pass
            return ""

        if fbase in ["LL", "DL", "脚部"]:
            try:
                is_endpoint = getattr(self, "model", None) is not None and self.model.degree(int(getattr(fit, "node_id", -1))) == 1
            except Exception:
                is_endpoint = False
            mode = _terminal_mode_for_fit() if is_endpoint else ""
            fit.size = f"{small}x{mode}" if mode in {"U", "D"} else small
        elif fbase in ["45°", "集合管", "S", "SV"]:
            fit.size = small
        elif fbase in ["Y", "LT", "DT", "T", "HTVP"]:
            # Keep the same fitting family, but its main pipe becomes the small side.
            old_nums = re.findall(r"\d+", str(getattr(fit, "size", "")))
            branch = old_nums[1] if len(old_nums) >= 2 and old_nums[1] != old_nums[0] else self.default_branch_size_for(small)
            # Branch must not be larger than the new main size.  If uncertain, use one size down.
            try:
                if branch in PIPE_SIZE_ORDER and small in PIPE_SIZE_ORDER and PIPE_SIZE_ORDER.index(branch) > PIPE_SIZE_ORDER.index(small):
                    branch = self.default_branch_size_for(small)
            except Exception:
                pass
            fit.size = f"{small}x{branch}"
        elif fbase == "IN":
            nums2 = re.findall(r"\d+", str(getattr(fit, "size", "")))
            out_small = nums2[1] if len(nums2) >= 2 else self.default_branch_size_for(small)
            fit.size = f"{small}x{out_small}"
        elif fbase and fbase != "要確認":
            fit.size = small

    def _apply_bushing_small_side_now(self, host: int, other: int, small: str):
        """Immediately apply small size to all pipe/fittings after a bushing."""
        nodes, edges = self._collect_bushing_downstream(host, other)
        for ed in self.model.edges:
            if ed.key in edges:
                ed.size = small
        for nid in nodes:
            # Do not change the host fitting.  Its label gets the bushing suffix instead.
            if nid == int(host):
                continue
            fit = self.model.fittings.get(nid)
            if fit:
                self._force_fit_to_small_side(fit, small)

    def _preview_apply_bushing_small_side(self, info: Dict[str, object]):
        """Live preview: while IN is dragged into the mouth, shrink the small side immediately.

        The previous patch only drew a symbol.  This one temporarily changes model sizes
        so the existing detailed preview/JWW-style drawing naturally uses the smaller
        pipe diameter and smaller downstream fitting libraries.
        """
        data = getattr(self, "pending_reducer", None)
        if not data or not isinstance(info, dict):
            return
        backup = data.setdefault("bushing_size_backup", {"edges": {}, "fits": {}})
        try:
            host = int(info.get("host")); other = int(info.get("other"))
            nums = re.findall(r"\d+", str(info.get("size", "")))
            if len(nums) < 2:
                return
            small = nums[1]
        except Exception:
            return
        nodes, edges = self._collect_bushing_downstream(host, other)
        for ed in self.model.edges:
            if ed.key in edges:
                backup["edges"].setdefault(ed.key, ed.size)
        for nid in nodes:
            fit = self.model.fittings.get(nid)
            if fit:
                backup["fits"].setdefault(str(nid), {"ftype": fit.ftype, "size": fit.size, "manual": fit.manual})
        data["bushing_size_backup"] = backup
        self.pending_reducer = data
        self._apply_bushing_small_side_now(host, other, small)

    def _preview_restore_bushing_small_side(self):
        """Restore sizes changed only for live bushing preview."""
        data = getattr(self, "pending_reducer", None)
        if not data:
            return
        backup = data.pop("bushing_size_backup", None)
        if not isinstance(backup, dict):
            self.pending_reducer = data
            return
        try:
            for k, val in (backup.get("edges") or {}).items():
                for ed in self.model.edges:
                    if ed.key == k:
                        ed.size = val
                        break
            for nid_s, rec in (backup.get("fits") or {}).items():
                nid = int(nid_s)
                fit = self.model.fittings.get(nid)
                if fit and isinstance(rec, dict):
                    fit.ftype = rec.get("ftype", fit.ftype)
                    fit.size = rec.get("size", fit.size)
                    fit.manual = bool(rec.get("manual", fit.manual))
        except Exception:
            pass
        self.pending_reducer = data

    def _next_bushing_id(self) -> int:
        vals = []
        for b in getattr(self.model, "bushings", []):
            try:
                vals.append(int(b.get("id", 0)))
            except Exception:
                pass
        return (max(vals) + 1) if vals else 1

    def reducer_near_bushing_end(self, e: Edge, t: float, size: str = "") -> Optional[Dict[str, object]]:
        """Return endpoint info when pending IN is close enough to become ブッシング.

        A bushing is only offered at a real fitting mouth, not a pass-through point.
        The selected IN size big side must match the pipe/end size as much as possible.
        """
        try:
            nums = re.findall(r"\d+", str(size or ""))
            big = nums[0] if nums else str(e.size or "").split("x")[0]
            small = nums[1] if len(nums) >= 2 else lower_pipe_size(big)
            length = max(self.model.edge_length(e), EPS)
            end_candidates = []
            for endpoint, other, dist_t in ((e.a, e.b, t), (e.b, e.a, 1.0 - t)):
                if dist_t * length > max(35.0, length * 0.08):
                    continue
                fit = self.model.fittings.get(endpoint)
                if not fit or fit.excluded or fit.ftype in {"IN", "要確認"}:
                    continue
                # Prefer the end whose fitting/edge is the large side.  Empty fitting
                # size is still accepted because many 集合管 sizes are auto labels.
                fnums = re.findall(r"\d+", str(fit.size or ""))
                if fnums and big not in fnums[:2]:
                    # Still allow when the selected edge itself is the big pipe.
                    edge_nums = re.findall(r"\d+", str(e.size or ""))
                    if not edge_nums or edge_nums[0] != big:
                        continue
                end_candidates.append({"host": endpoint, "other": other, "big": big, "small": small, "size": f"{big}x{small}", "edge_key": e.key})
            if not end_candidates:
                return None
            # Pick the truly closest end if both are within tolerance.
            return end_candidates[0] if t <= 0.5 else end_candidates[-1]
        except Exception:
            return None

    def bushings_for_node(self, nid: int) -> List[Dict[str, object]]:
        return [b for b in getattr(self.model, "bushings", []) if int(b.get("host_node", -1)) == int(nid)]

    def bushing_small_for_side(self, host: int, other: int) -> str:
        for b in getattr(self.model, "bushings", []):
            try:
                h = int(b.get("host_node", -1)); o = int(b.get("other_node", -1))
                # For sizing, the whole connected pipe run becomes the small size.
                # Accept either direction because flow parent direction may be opposite
                # to the large fitting mouth in some networks.
                if (h == int(host) and o == int(other)) or (h == int(other) and o == int(host)):
                    nums = re.findall(r"\d+", str(b.get("size", "")))
                    if len(nums) >= 2:
                        return nums[1]
            except Exception:
                continue
        return ""

    def bushing_label_suffix(self, nid: int) -> str:
        bs = self.bushings_for_node(nid)
        if not bs:
            return ""
        labels = []
        for b in bs:
            size = str(b.get("size", "")).strip()
            item_name = self.bushing_item_name(str(b.get("material", ""))) if hasattr(self, "bushing_item_name") else "ブッシング"
            labels.append(f"{size}_{item_name}" if size else item_name)
        return " + " + " + ".join(labels)

    def ask_live_bushing_conversion(self, edge_key_value: str, offer_key: str):
        """Show the bushing question immediately while dragging IN near a large fitting mouth."""
        data = getattr(self, "pending_reducer", None)
        if not data or str(data.get("edge_key", "")) != str(edge_key_value):
            return
        info = data.get("bushing_preview") if isinstance(data.get("bushing_preview"), dict) else None
        if not info:
            return
        current_key = f"{info.get('host')}-{info.get('other')}-{info.get('size')}"
        if current_key != offer_key:
            return
        e = next((x for x in self.model.edges if x.key == str(edge_key_value)), None)
        if not e:
            return
        ret = QMessageBox.question(
            self,
            self.tr("bushing_confirm_title"),
            self.tr("bushing_live_msg"),
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.Yes,
        )
        data = getattr(self, "pending_reducer", None)
        if not data:
            return
        if ret == QMessageBox.Yes:
            info = data.get("bushing_preview") if isinstance(data.get("bushing_preview"), dict) else info
            e = next((x for x in self.model.edges if x.key == str(edge_key_value)), None)
            if e and info:
                self.create_bushing_from_pending(e, info)
            return
        # User declined: undo the live size preview and go back to normal IN.
        self._preview_restore_bushing_small_side()
        data = getattr(self, "pending_reducer", data)
        data["bushing_declined_key"] = offer_key
        data.pop("bushing_preview", None)
        self.pending_reducer = data
        self.preview.draw_model()

    def create_bushing_from_pending(self, e: Edge, info: Dict[str, object]) -> bool:
        """Convert pending IN at a large fitting mouth into a bushing object.

        The IN body disappears.  The pipe connected to that fitting starts as the
        small size right at the mouth, and material summary counts one bushing.
        """
        size = str(info.get("size", ""))
        nums = re.findall(r"\d+", size)
        if len(nums) < 2:
            return False
        host = int(info.get("host"))
        other = int(info.get("other"))
        small = nums[1]
        self.save_undo_snapshot("insert_bushing")
        # Live preview may already have shrunk the model.  Do not restore it;
        # clear the backup and commit the same small-side sizing as real data.
        try:
            if isinstance(getattr(self, "pending_reducer", None), dict):
                self.pending_reducer.pop("bushing_size_backup", None)
        except Exception:
            pass
        self._apply_bushing_small_side_now(host, other, small)
        mat = self.edge_material(e)
        # Avoid double-counting when the same pipe mouth is converted again.
        self.model.bushings = [
            x for x in getattr(self.model, "bushings", [])
            if not (int(x.get("host_node", -1)) == host and int(x.get("other_node", -1)) == other)
        ]
        b = {
            "id": self._next_bushing_id(),
            "host_node": host,
            "other_node": other,
            "edge_key": edge_key(host, other),
            "size": f"{nums[0]}x{nums[1]}",
            "material": mat,
            "quantity": 1,
        }
        self.model.bushings.append(b)
        self.pending_reducer = None
        rebuild_flow(self.model)
        self.apply_common()
        # apply_common recalculates normal pipe sizes first; enforce bushing after it too.
        self.force_bushing_downstream_sizes()
        self.select_bushing(b["id"])
        self.lbl_status.setText(self.tr("bushing_done").format(size=b["size"]))
        return True

    def get_bushing_by_id(self, bid) -> Optional[Dict[str, object]]:
        try:
            bid = int(bid)
        except Exception:
            return None
        for b in getattr(self.model, "bushings", []) or []:
            try:
                if int(b.get("id", -1)) == bid:
                    return b
            except Exception:
                continue
        return None

    def bushing_size_options(self, b: Dict[str, object]) -> List[str]:
        """Editable size list for a selected ブッシング. 100x75 can be changed to 100x65 etc."""
        nums = re.findall(r"\d+", str(b.get("size", "")))
        if not nums:
            return []
        big = nums[0]
        opts: List[str] = []
        if big in PIPE_SIZE_ORDER:
            bi = PIPE_SIZE_ORDER.index(big)
            # Show smaller sizes from nearest downward.  Do not include the same size.
            for small in reversed(PIPE_SIZE_ORDER[:bi]):
                opts.append(f"{big}x{small}")
        else:
            cur = nums[1] if len(nums) >= 2 else lower_pipe_size(big)
            opts.append(f"{big}x{cur}")
        cur_size = str(b.get("size", "")).strip()
        if cur_size and cur_size not in opts:
            opts.insert(0, cur_size)
        return opts[:20]

    def select_bushing(self, bid):
        """Select ブッシング as a real reducer object, not just as the host fitting."""
        b = self.get_bushing_by_id(bid)
        if not b:
            return
        self.selected_bushing_id = int(b.get("id"))
        self.selected_node = None
        self.selected_edge = None
        self.pending_reducer = None
        size = str(b.get("size", "")).strip()
        host = int(b.get("host_node", -1)); other = int(b.get("other_node", -1))
        item_name = self.bushing_item_name(str(b.get("material", ""))) if hasattr(self, "bushing_item_name") else "ブッシング"
        self._force_combo_text_visible(self.cmb_fit_type, item_name)
        self.cmb_fit_size.blockSignals(True)
        try:
            self.cmb_fit_size.clear()
            for opt in self.bushing_size_options(b):
                self.cmb_fit_size.addItem(opt, opt)
            if size and self.cmb_fit_size.findText(size) < 0:
                self.cmb_fit_size.insertItem(0, size, size)
            if size:
                self.cmb_fit_size.setEditText(size)
        finally:
            self.cmb_fit_size.blockSignals(False)
        self.fit_preview_scene.clear()
        self.lbl_selected.setText(f"{item_name} / {size}")
        self.lbl_detail.setText(f"Host Node {host} → Small side Node {other} | {size}")
        self.lbl_status.setText(f"Đã chọn {item_name} {size}: có thể sửa size hoặc xóa như cút thu IN.")
        self.update_reducer_buttons()
        self.update_branch_material_buttons()
        self.preview.draw_model()

    def apply_selected_bushing(self) -> bool:
        """Apply edited size to selected ブッシング and re-force all downstream pipe/fitting sizes."""
        b = self.get_bushing_by_id(getattr(self, "selected_bushing_id", None))
        if not b:
            return False
        size = self.cmb_fit_size.currentText().strip()
        nums = re.findall(r"\d+", size)
        if len(nums) < 2:
            QMessageBox.warning(self, "NEVIS", "Size ブッシング không hợp lệ. Ví dụ: 100x65")
            return True
        self.save_undo_snapshot("edit_bushing")
        b["size"] = f"{nums[0]}x{nums[1]}"
        try:
            host = int(b.get("host_node")); other = int(b.get("other_node"))
            self._apply_bushing_small_side_now(host, other, nums[1])
        except Exception:
            pass
        rebuild_flow(self.model)
        self.apply_common()
        self.force_bushing_downstream_sizes()
        self.select_bushing(b.get("id"))
        self.lbl_status.setText(f"Đã sửa ブッシング thành {b['size']} và ép tuyến sau về {nums[1]}.")
        return True

    def delete_selected_bushing(self) -> bool:
        """Delete selected ブッシング; normal auto-sizing will restore the pipe sizes."""
        bid = getattr(self, "selected_bushing_id", None)
        b = self.get_bushing_by_id(bid)
        if not b:
            return False
        self.save_undo_snapshot("delete_bushing")
        old_size = str(b.get("size", ""))
        self.model.bushings = [x for x in getattr(self.model, "bushings", []) if int(x.get("id", -1)) != int(bid)]
        self.selected_bushing_id = None
        self.selected_node = None
        self.selected_edge = str(b.get("edge_key", "")) or edge_key(int(b.get("host_node", 0)), int(b.get("other_node", 0)))
        rebuild_flow(self.model)
        self.apply_common()
        if self.selected_edge and any(e.key == self.selected_edge for e in self.model.edges):
            self.select_edge(self.selected_edge)
        else:
            self.refresh_all()
        self.lbl_status.setText(f"Đã xóa ブッシング {old_size}; size ống đã tính lại theo hệ thống.")
        return True

    def start_insert_reducer(self):
        """Start pending IN insertion on the selected pipe."""
        if not self.selected_edge:
            QMessageBox.information(self, "NEVIS", self.tr("reducer_hint_select_pipe"))
            return
        e = next((x for x in self.model.edges if x.key == self.selected_edge), None)
        if not e:
            QMessageBox.warning(self, "NEVIS", "Ống đang chọn không còn tồn tại.")
            return
        opts = self.reducer_size_options_for_edge(e)
        if not opts:
            QMessageBox.warning(self, "NEVIS", f"Không tìm thấy thư viện IN phù hợp cho size {e.size}.")
            return
        choice, ok = QInputDialog.getItem(self, "異径ソケット / Cút thu IN", "Chọn size / サイズ", opts, 0, False)
        if not ok or not choice:
            return
        # Place at midpoint first; user can click/drag on this pipe to move before 確定.
        self.pending_reducer = {"edge_key": e.key, "size": choice, "t": 0.5}
        self.lbl_reducer_hint.setText(f"IN {choice}: click/kéo trên ống rồi bấm 確定")
        self.update_reducer_buttons()
        self.preview.draw_model()

    def confirm_insert_reducer(self):
        data = getattr(self, "pending_reducer", None)
        if not data:
            return
        key = str(data.get("edge_key", ""))
        size = str(data.get("size", ""))
        try:
            t = float(data.get("t", 0.5))
        except Exception:
            t = 0.5
        e = next((x for x in self.model.edges if x.key == key), None)
        if not e:
            QMessageBox.warning(self, "NEVIS", "Ống chèn IN không còn tồn tại.")
            self.pending_reducer = None
            self.update_reducer_buttons()
            return
        nums = re.findall(r"\d+", size)
        if len(nums) < 2:
            QMessageBox.warning(self, "NEVIS", "Size IN không hợp lệ.")
            return
        bushing_info = self.reducer_near_bushing_end(e, t, size)
        if bushing_info:
            offer_key = f"{bushing_info.get('host')}-{bushing_info.get('other')}-{bushing_info.get('size')}"
            if data.get("bushing_declined_key") != offer_key:
                ret = QMessageBox.question(self, self.tr("bushing_confirm_title"), self.tr("bushing_confirm_msg"), QMessageBox.Yes | QMessageBox.No, QMessageBox.Yes)
                if ret == QMessageBox.Yes:
                    self.create_bushing_from_pending(e, bushing_info)
                    return
        self.save_undo_snapshot("insert_in")
        a, b = e.a, e.b
        n1, n2 = self.model.nodes[a], self.model.nodes[b]
        t = max(0.05, min(0.95, t))
        x = n1.x + (n2.x - n1.x) * t
        y = n1.y + (n2.y - n1.y) * t
        new_id = (max(self.model.nodes.keys()) + 1) if self.model.nodes else 1
        old_size = e.size
        # Remove selected edge and insert A-IN-B.
        self.model.edges = [ed for ed in self.model.edges if ed.key != key]
        self.model.nodes[new_id] = Node(new_id, x, y)
        self.model.edges.append(Edge(a, new_id, old_size))
        self.model.edges.append(Edge(new_id, b, old_size))
        self.model.fittings[new_id] = Fitting(new_id, "IN", f"{nums[0]}x{nums[1]}", manual=True)
        self.pending_reducer = None
        rebuild_flow(self.model)
        self.apply_common()
        self.select_node(new_id)
        self.lbl_status.setText(f"Đã chèn IN {nums[0]}→{nums[1]}")

    def cancel_insert_reducer(self):
        self.pending_reducer = None
        self.update_reducer_buttons()
        self.lbl_reducer_hint.setText(self.tr("reducer_hint_normal"))
        self.preview.draw_model()

    def delete_selected_reducer(self):
        """Delete selected IN or ブッシング reducer."""
        if getattr(self, "selected_bushing_id", None):
            if self.delete_selected_bushing():
                return
        nid = self.selected_node
        fit = self.model.fittings.get(nid) if nid else None
        if not nid or not fit or fit.ftype != "IN":
            return
        ns = self.model.neighbors(nid)
        if len(ns) != 2:
            QMessageBox.warning(self, "NEVIS", "Chỉ xóa IN khi nó nằm giữa đúng 2 đoạn ống.")
            return
        self.save_undo_snapshot("delete_in")
        a, b = ns[0], ns[1]
        # Remove all edges touching IN, then reconnect neighbors.
        self.model.edges = [e for e in self.model.edges if e.a != nid and e.b != nid]
        if edge_obj(self.model, a, b) is None:
            self.model.edges.append(Edge(a, b, self.cmb_main_size.currentText()))
        self.model.nodes.pop(nid, None)
        self.model.fittings.pop(nid, None)
        self.selected_node = None
        self.selected_edge = edge_key(a, b)
        rebuild_flow(self.model)
        self.apply_common()
        self.select_edge(self.selected_edge)
        self.lbl_status.setText("Đã xóa IN")

    def branch_start_child_for_node(self, nid: int) -> Optional[int]:
        """Return the child node where a branch-material override should start.

        For Y/LT/DT/T this is the side branch. For a normal two-way fitting or IN,
        it is the downstream child away from 集合管.
        """
        if not nid or nid not in self.model.nodes:
            return None
        children = [nb for nb in self.model.neighbors(nid) if self.model.parent.get(nb) == nid]
        if not children:
            return None
        if self.model.degree(nid) >= 3:
            info = junction_axis_info(self.model, nid)
            if info:
                b = info.get("branch")
                if b in children:
                    return b
        return children[0] if len(children) == 1 else children[-1]

    def update_branch_material_buttons(self):
        if not hasattr(self, "btn_apply_branch_material"):
            return
        fit = self.model.fittings.get(self.selected_node) if self.selected_node else None
        can_apply = bool(fit and not fit.excluded and self.branch_start_child_for_node(self.selected_node) is not None)
        self.btn_apply_branch_material.setEnabled(can_apply)
        self.btn_clear_branch_material.setEnabled(can_apply or bool(fit and getattr(fit, "material_override", "")))
        if can_apply and fit:
            mat = getattr(fit, "material_override", "") or ""
            extra = f" / hiện tại: {mat}" if mat else ""
            self.lbl_branch_mat_hint.setText(f"{fit.ftype} " + ("nhánh đặc biệt" if self.lang == "vi" else "の枝へ材質指定") + f"{extra}")
        else:
            self.lbl_branch_mat_hint.setText(self.tr("branch_mat_hint_normal"))

    def _walk_downstream_edges(self, start_parent: int, start_child: int):
        """Yield (parent, child, edge) from start_child to all descendants."""
        stack = [(start_parent, start_child)]
        seen = set()
        while stack:
            p, c = stack.pop()
            k = edge_key(p, c)
            if k in seen:
                continue
            seen.add(k)
            e = edge_obj(self.model, p, c)
            if e is not None:
                yield p, c, e
            for nb in self.model.neighbors(c):
                if self.model.parent.get(nb) == c:
                    stack.append((c, nb))

    def apply_branch_material_override(self):
        """Force material from selected fitting's side branch downstream.

        Example: select DT at dishwasher drainage branch, choose HTVP, then the DT
        and all pipes/fittings away from 集合管 on that branch use HTVP.
        """
        nid = self.selected_node
        fit = self.model.fittings.get(nid) if nid else None
        child = self.branch_start_child_for_node(nid) if nid else None
        if not fit or child is None:
            QMessageBox.information(self, "NEVIS", self.tr("branch_mat_hint_normal"))
            return
        mat = self.cmb_branch_material.currentText().strip() or "HTVP"
        self.save_undo_snapshot("branch_material")
        fit.material_override = mat
        for p, c, e in self._walk_downstream_edges(nid, child):
            e.material_override = mat
            cf = self.model.fittings.get(c)
            if cf and not cf.excluded:
                cf.material_override = mat
        self.refresh_all()
        self.select_node(nid)
        self.lbl_status.setText(self.tr("branch_applied").format(mat=mat))

    def clear_branch_material_override(self):
        nid = self.selected_node
        fit = self.model.fittings.get(nid) if nid else None
        child = self.branch_start_child_for_node(nid) if nid else None
        if not fit:
            return
        self.save_undo_snapshot("clear_branch_material")
        fit.material_override = ""
        if child is not None:
            for p, c, e in self._walk_downstream_edges(nid, child):
                e.material_override = ""
                cf = self.model.fittings.get(c)
                if cf:
                    cf.material_override = ""
        self.refresh_all()
        self.select_node(nid)
        self.lbl_status.setText(self.tr("branch_cleared"))

    def update_fire_controls(self, refresh_only: bool = False):
        """Hiển thị thiết lập chống cháy đơn giản cho 排水転がし配管.

        - Không tích: toàn hệ thống dùng vật liệu ống thường.
        - Có tích: trong phạm vi dùng vật liệu chống cháy, ngoài phạm vi dùng vật liệu thường.
        Không còn lựa chọn "ngoài phạm vi" để tránh hiểu nhầm.
        """
        active = bool(self.chk_fire.isChecked()) if hasattr(self, "chk_fire") else False
        for w in [getattr(self, "lbl_fire_len", None), getattr(self, "edit_fire_len", None), getattr(self, "lbl_fire_unit", None),
                  getattr(self, "lbl_inside", None), getattr(self, "cmb_fire_mat", None)]:
            if w is not None:
                w.setVisible(active)
                w.setEnabled(active)
        # Vật liệu ống thường luôn cần hiển thị: khi tắt chống cháy dùng cho toàn hệ,
        # khi bật chống cháy dùng cho phần ngoài phạm vi.
        for w in [getattr(self, "lbl_outside", None), getattr(self, "cmb_normal_mat", None)]:
            if w is not None:
                w.setVisible(True)
                w.setEnabled(True)
        if hasattr(self, "chk_fire_outside_keep"):
            self.chk_fire_outside_keep.setChecked(True)
            self.chk_fire_outside_keep.setVisible(False)
        if not refresh_only:
            try:
                self.refresh_all()
            except Exception:
                pass

    def edge_material(self, e: Edge) -> str:
        forced = getattr(e, "material_override", "")
        if forced:
            return forced
        normal = self._combo_current_code(self.cmb_normal_mat) if hasattr(self, "cmb_normal_mat") else self.cmb_normal_mat.currentText()
        fire = self._combo_current_code(self.cmb_fire_mat) if hasattr(self, "cmb_fire_mat") else self.cmb_fire_mat.currentText()
        if hasattr(self, "chk_fire") and self.chk_fire.isChecked():
            try:
                fl = float(self.edit_fire_len.text())
            except Exception:
                fl = 0.0
            # Strict fire rule on the VISIBLE pipe body only: mouth-to-mouth,
            # not fitting-center to fitting-center.  This prevents a normal pipe
            # leaving a boundary fitting from being counted as fire material.
            if self.edge_fire_fraction_by_mouth(e, fl) > 0.0:
                return fire
        return normal

    def apply_node(self):
        if getattr(self, "selected_bushing_id", None):
            if self.apply_selected_bushing():
                return
        if not self.selected_node:
            return
        ftype = self._combo_current_code(self.cmb_fit_type) if hasattr(self, '_combo_current_code') else self.cmb_fit_type.currentText()
        ftype = ftype or self.cmb_fit_type.currentText()
        size = self.cmb_fit_size.currentText().strip()
        old_fit = self.model.fittings.get(self.selected_node)
        old_mat = getattr(old_fit, "material_override", "") if old_fit else ""
        self.model.fittings[self.selected_node] = Fitting(self.selected_node, ftype, size, manual=True, material_override=old_mat)
        if ftype == "集合管":
            self.model.base_nodes = set(getattr(self.model, "base_nodes", set()) or [])
            self.model.base_nodes.add(self.selected_node)
            if self.model.base_node is None or self.model.base_node not in self.model.nodes:
                self.model.base_node = self.selected_node
            rebuild_flow(self.model)
        # Recalculate branch pipe sizes after manual fitting/size change.
        # Example: 65x40 Y/LT/DT makes the side branch and its downstream fittings 40.
        self.apply_common()
        self.select_node(self.selected_node)

    def default_node(self):
        if not self.selected_node:
            return
        # Mặc định = bỏ sửa tay và trả node về đúng thiết lập chung + hình học hiện tại.
        self.model.fittings[self.selected_node] = self._auto_default_fitting_for_node(self.selected_node)
        self.apply_common()
        self.select_node(self.selected_node)

    def delete_node(self):
        if not self.selected_node: return
        if self.selected_node in self.model.fittings:
            self.model.fittings[self.selected_node].excluded = True
        self.refresh_all(); self.select_node(self.selected_node)

    def set_selected_as_base(self):
        if self._block_if_detail_readonly():
            return
        if not self.selected_node:
            return
        self.model.base_nodes = set(getattr(self.model, "base_nodes", set()) or [])
        self.model.base_nodes.add(self.selected_node)
        if self.model.base_node is None or self.model.base_node not in self.model.nodes:
            self.model.base_node = self.selected_node
        # Đặt đầu nhánh = THÊM một điểm khởi đầu/cụm mới, không xóa các cụm đã đặt.
        # Loại cút ăn theo ô Đầu nhánh trong Thiết lập chung.
        self.model.fittings[self.selected_node] = self._auto_default_fitting_for_node(self.selected_node)
        rebuild_flow(self.model)
        self.apply_common()
        self.select_node(self.selected_node)


    def edge_material_for_node(self, nid: int) -> str:
        """Material used for quantity add-ons around a node."""
        if self.chk_fire.isChecked():
            try:
                fl = float(self.edit_fire_len.text())
            except Exception:
                fl = 0.0
            d = self.model.dist.get(nid, 1e100)
            if d <= fl + 1e-6 or self.node_is_fire_boundary_fitting(nid, fl):
                return self._combo_current_code(self.cmb_fire_mat) if hasattr(self, "cmb_fire_mat") else self.cmb_fire_mat.currentText()
        return self._combo_current_code(self.cmb_normal_mat) if hasattr(self, "cmb_normal_mat") else self.cmb_normal_mat.currentText()

    def material_kind_name(self, ftype: str) -> str:
        """Japanese material item name used for UI/Excel aggregation."""
        ftype = str(ftype or "")
        if ftype in ["45", "45°", "45度"]:
            return "45°エルボ"
        if ftype == "LL":
            return "LL継手"
        if ftype == "DL":
            return "DL立上り"
        if ftype == "Y":
            return "Y継手"
        if ftype == "LT":
            return "LT継手"
        if ftype == "DT":
            return "DT継手"
        if ftype == "T":
            return "T継手"
        if ftype == "IN":
            return "異径ソケット"
        if ftype in {"BUSHING", "ブッシング"}:
            return "ブッシング"
        if ftype == "脚部":
            return "脚部継手"
        if ftype == "集合管":
            return "集合管"
        return ftype

    def material_kind_label(self, mat: str) -> str:
        """Normalize pipe/fitting material names so total aggregation does not split similar names."""
        mat = str(mat or "")
        if mat in ["VP/VU", "VP", "VU", "DV"]:
            return "DV" if mat == "DV" else "VP"
        if mat in ["TMP", "トミジ", "耐火二層管"]:
            return "TMP"
        if mat in ["HT", "HTVP"]:
            return "HTVP"
        if mat in ["耐火VP", "TaikaVP"]:
            return "耐火VP"
        return mat

    def pipe_item_name(self, mat: str) -> str:
        mat2 = self.material_kind_label(mat)
        if mat2 == "TMP":
            return "トミジパイプ"
        if mat2 == "HTVP":
            return "HTVPパイプ"
        if mat2 == "耐火VP":
            return "耐火VPパイプ"
        return f"{mat2}パイプ"

    def build_material_rows(self, sheet_type: str = "") -> List[List[object]]:
        """Return canonical rows: [種類, サイズ, 品名, 単位, 数量, 備考].

        `sheet_type` is kept only for backward-compatible callers; the UI/export
        no longer uses the タイプ column because 排水転がし配管 has only one system.
        """
        rows: List[List[object]] = []
        counts: Dict[Tuple[str,str,str], int] = {}

        for nid, fit in self.model.fittings.items():
            if fit.excluded:
                continue
            mat = self.material_kind_label(self.fitting_prefix_for_node(nid))
            size = str(fit.size or "")
            item_name = self.material_kind_name(fit.ftype)
            counts[(mat, size, item_name)] = counts.get((mat, size, item_name), 0) + 1

        for b in getattr(self.model, "bushings", []):
            mat = self.material_kind_label(str(b.get("material", "") or self.cmb_normal_mat.currentText()))
            size = str(b.get("size", ""))
            item_name = self.bushing_item_name(mat) if hasattr(self, "bushing_item_name") else "ブッシング"
            counts[(mat, size, item_name)] = counts.get((mat, size, item_name), 0) + int(b.get("quantity", 1) or 1)

        for (mat, size, item_name), cnt in sorted(counts.items()):
            rows.append([mat, size, item_name, "個", cnt, ""])

        pipe_len: Dict[Tuple[str,str], float] = {}
        try:
            fire_len = float(self.edit_fire_len.text())
        except Exception:
            fire_len = 0.0

        for e in self.model.edges:
            total = self.model.edge_length(e)
            if getattr(e, "material_override", ""):
                k = (self.material_kind_label(e.material_override), e.size)
                pipe_len[k] = pipe_len.get(k, 0.0) + total
                continue
            if self.chk_fire.isChecked():
                frac = self.edge_fire_fraction_by_mouth(e, fire_len)
            else:
                frac = 0.0
            if frac > 0:
                k = (self.material_kind_label(self.cmb_fire_mat.currentText()), e.size)
                pipe_len[k] = pipe_len.get(k, 0.0) + total * frac
            if frac < 1:
                k = (self.material_kind_label(self.cmb_normal_mat.currentText()), e.size)
                pipe_len[k] = pipe_len.get(k, 0.0) + total * (1 - frac)

        # Optional drainage vertical riser allowance: add 500mm for each real terminal UP point.
        # 排水転がし配管: every branch-end Up fitting (DL_UP / LL_UP, stored as size like 50xU)
        # needs an extra 500mm vertical pipe in material quantity.  Use the connected pipe
        # size/material, not the fitting name, because some projects use LL_UP at terminal ends.
        if getattr(self, "chk_riser_500", None) is not None and self.chk_riser_500.isChecked():
            base_nodes = set(getattr(self.model, "base_nodes", set()) or [])
            if getattr(self.model, "base_node", None) is not None:
                base_nodes.add(self.model.base_node)
            for nid, fit in self.model.fittings.items():
                if fit.excluded or nid in base_nodes:
                    continue
                if self.model.degree(nid) != 1:
                    continue

                ftxt = f"{getattr(fit, 'ftype', '')} {getattr(fit, 'size', '')} {self.material_kind_name(getattr(fit, 'ftype', ''))}".upper()
                # Count only terminal UP fittings.  This catches both DL_UP and LL_UP even when
                # the internal fitting type is simply DL/LL and the UP mark is stored in size (50xU).
                is_up_terminal = ("UP" in ftxt) or bool(re.search(r"(^|X|[_\-\s])U($|[_\-\s])", ftxt))
                if not is_up_terminal:
                    continue

                nbs = self.model.neighbors(nid)
                if not nbs:
                    continue
                e = edge_obj(self.model, nid, nbs[0])
                if not e:
                    continue

                nums = re.findall(r"\d+", str(e.size or fit.size or ""))
                size = nums[0] if nums else str(e.size or fit.size or "")

                if getattr(e, "material_override", ""):
                    mat = e.material_override
                elif self.chk_fire.isChecked():
                    try:
                        fire_limit = float(self.edit_fire_len.text())
                    except Exception:
                        fire_limit = 0.0
                    # Use the terminal node distance to decide the 500mm vertical pipe material.
                    mat = self.cmb_fire_mat.currentText() if (self.model.dist.get(nid, 1e100) <= fire_limit + 1e-6 or self.node_is_fire_boundary_fitting(nid, fire_limit)) else self.cmb_normal_mat.currentText()
                else:
                    mat = self.cmb_normal_mat.currentText()

                k = (self.material_kind_label(mat), size)
                pipe_len[k] = pipe_len.get(k, 0.0) + 500.0

        try:
            unit_len = float(self.edit_pipe_unit.text())
        except Exception:
            unit_len = 4.0
        for (mat, size), mm in sorted(pipe_len.items()):
            m = round(mm / 1000.0, 2)
            pcs = max(1, math.ceil((mm / 1000.0) / unit_len)) if mm > 0 else 0
            rows.append([mat, size, self.pipe_item_name(mat), "m", m, f"{unit_len:g}m管 × {pcs}本"])

        # 支持バンド count by size/material/kind.
        if getattr(self, "support_enabled", False):
            band_counts: Dict[Tuple[str,str,str], int] = {}
            for b in self.compute_support_bands():
                mat = self.material_kind_label(str(b.get("mat", "")))
                size = str(b.get("size", ""))
                kind = str(b.get("kind", ""))
                name = self.support_band_label(size, mat, kind)
                band_counts[(mat, size, name)] = band_counts.get((mat, size, name), 0) + 1
            for (mat, size, name), cnt in sorted(band_counts.items()):
                rows.append([mat, size, name, "個", cnt, ""])

        return rows

    def _autosize_material_table(self):
        """Fit material-table columns to the longest visible text.

        QHeaderView.Stretch makes the name/remarks columns shrink unpredictably
        when the right panel is narrow.  NEVIS material rows often contain long
        Japanese item names, so calculate widths from header + cell text and
        allow a horizontal scrollbar only when the content is genuinely wider
        than the panel.
        """
        if not hasattr(self, "table_mat") or self.table_mat is None:
            return
        try:
            table = self.table_mat
            header = table.horizontalHeader()
            header.setStretchLastSection(False)
            header.setSectionResizeMode(QHeaderView.Interactive)
            fm = table.fontMetrics()
            labels = ["種類", "サイズ", "品名", "単位", "数量", "備考"]
            min_w = [62, 76, 160, 48, 62, 95]
            max_w = [150, 150, 520, 80, 100, 420]
            pad = 28
            for c in range(min(table.columnCount(), 6)):
                label = labels[c] if c < len(labels) else ""
                best = fm.horizontalAdvance(label) + pad
                for r in range(table.rowCount()):
                    item = table.item(r, c)
                    if item is not None:
                        best = max(best, fm.horizontalAdvance(item.text()) + pad)
                table.setColumnWidth(c, max(min_w[c], min(best, max_w[c])))

            # If there is still free space, give it to 品名 first, then 備考.
            viewport_w = max(0, table.viewport().width() - 4)
            total_w = sum(table.columnWidth(c) for c in range(table.columnCount()))
            extra = viewport_w - total_w
            if extra > 0 and table.columnCount() >= 6:
                add_name = min(extra, max_w[2] - table.columnWidth(2))
                if add_name > 0:
                    table.setColumnWidth(2, table.columnWidth(2) + add_name)
                    extra -= add_name
                add_note = min(extra, max_w[5] - table.columnWidth(5))
                if add_note > 0:
                    table.setColumnWidth(5, table.columnWidth(5) + add_note)
        except Exception:
            pass

    def update_material_table(self):
        rows = self.build_material_rows("")
        self.table_mat.setRowCount(len(rows))
        self.table_mat.setColumnCount(6)
        self.table_mat.setHorizontalHeaderLabels(["種類", "サイズ", "品名", "単位", "数量", "備考"])
        try:
            self.table_mat.verticalHeader().setVisible(False)
            self.table_mat.setWordWrap(False)
            self.table_mat.setHorizontalScrollMode(QTableWidget.ScrollPerPixel)
            self.table_mat.horizontalHeader().setSectionResizeMode(QHeaderView.Interactive)
            self.table_mat.horizontalHeader().setStretchLastSection(False)
        except Exception:
            pass
        for i, row in enumerate(rows):
            for c, v in enumerate(row[:6]):
                item = QTableWidgetItem(str(v))
                item.setToolTip(str(v))
                self.table_mat.setItem(i, c, item)
        self._autosize_material_table()
        try:
            QTimer.singleShot(0, self._autosize_material_table)
        except Exception:
            pass


    # =============================================================
    # JWW OUTPUT: style panel + completed pipe edges + fittings
    # =============================================================
    def clean_jww_no(self, value: str, default: str = "1") -> str:
        m = re.search(r"\d+", str(value or ""))
        if m:
            n = int(m.group(0))
            if 1 <= n <= 8:
                return str(n)
        return default

    def clean_jww_layer(self, value: str, default: str = "0") -> str:
        v = str(value or "").strip().lower()[:1]
        return v if re.match(r"^[0-9a-f]$", v) else default

    def jww_line_pattern_text(self, no: int) -> str:
        return {
            1: "━━━━", 2: "･･････", 3: "- - -", 4: "-- --",
            5: "-･-･", 6: "--･--", 7: "-･･-", 8: "--･･",
        }.get(int(no), "--･･")

    def load_jww_colors_for_style(self, jwf_path: str = r"C:\JWW\Jw_win.jwf") -> Dict[int, str]:
        colors = {1:"00C0C0", 2:"000000", 3:"00C000", 4:"C0C000", 5:"C000C0", 6:"0000FF", 7:"008080", 8:"FF0080"}
        p = Path(jwf_path)
        if not p.exists():
            # Some installations use a lower-case/shorter folder spelling.
            for alt in [Path(r"C:\jww\jw_win.jwf"), Path(r"C:\JWW\jw_win.jwf")]:
                if alt.exists():
                    p = alt
                    break
            else:
                return colors
        try:
            txt = p.read_text(encoding="cp932", errors="ignore")
        except Exception:
            return colors
        for line in txt.splitlines():
            m = re.match(r"^LCOLLOR_(\d)\s*=\s*(-?\d+)\s+(-?\d+)\s+(-?\d+)", line.strip(), re.I)
            if not m:
                continue
            no = int(m.group(1))
            r = max(0, min(255, int(m.group(2))))
            g = max(0, min(255, int(m.group(3))))
            b = max(0, min(255, int(m.group(4))))
            colors[no] = f"{r:02X}{g:02X}{b:02X}"
        return colors

    def apply_jww_style_from_ui(self):
        e = getattr(self, "jww_edits", {})
        self.jww_pipe_color = self.clean_jww_no(e.get("pipe_color", QLineEdit(self.jww_pipe_color)).text(), self.jww_pipe_color)
        self.jww_pipe_line = self.clean_jww_no(e.get("pipe_line", QLineEdit(self.jww_pipe_line)).text(), self.jww_pipe_line)
        self.jww_pipe_lg = self.clean_jww_layer(e.get("pipe_lg", QLineEdit(self.jww_pipe_lg)).text(), self.jww_pipe_lg)
        self.jww_pipe_ly = self.clean_jww_layer(e.get("pipe_ly", QLineEdit(self.jww_pipe_ly)).text(), self.jww_pipe_ly)
        self.jww_center_color = self.clean_jww_no(e.get("center_color", QLineEdit(self.jww_center_color)).text(), self.jww_center_color)
        self.jww_center_line = self.clean_jww_no(e.get("center_line", QLineEdit(self.jww_center_line)).text(), self.jww_center_line)
        self.jww_center_lg = self.clean_jww_layer(e.get("center_lg", QLineEdit(self.jww_center_lg)).text(), self.jww_center_lg)
        self.jww_center_ly = self.clean_jww_layer(e.get("center_ly", QLineEdit(self.jww_center_ly)).text(), self.jww_center_ly)
        self.jww_joint_color = self.clean_jww_no(e.get("joint_color", QLineEdit(self.jww_joint_color)).text(), self.jww_joint_color)
        self.jww_joint_line = self.clean_jww_no(e.get("joint_line", QLineEdit(self.jww_joint_line)).text(), self.jww_joint_line)
        self.jww_joint_lg = self.clean_jww_layer(e.get("joint_lg", QLineEdit(self.jww_joint_lg)).text(), self.jww_joint_lg)
        self.jww_joint_ly = self.clean_jww_layer(e.get("joint_ly", QLineEdit(self.jww_joint_ly)).text(), self.jww_joint_ly)
        vals = {
            "pipe_color": self.jww_pipe_color, "pipe_line": self.jww_pipe_line, "pipe_lg": self.jww_pipe_lg, "pipe_ly": self.jww_pipe_ly,
            "center_color": self.jww_center_color, "center_line": self.jww_center_line, "center_lg": self.jww_center_lg, "center_ly": self.jww_center_ly,
            "joint_color": self.jww_joint_color, "joint_line": self.jww_joint_line, "joint_lg": self.jww_joint_lg, "joint_ly": self.jww_joint_ly,
        }
        for k, v in vals.items():
            if k in e:
                e[k].setText(v)

    def jww_attr(self, lg: str, ly: str, lc: str, lt: str) -> str:
        return f"lg{lg}\nly{ly}\nlc{lc}\nlt{lt}\n"

    def pipe_geometry_family(self, mat: str) -> str:
        """Two pipe-body geometry systems for now.

        VP geometry includes DV, VP, VU, 耐火VP, HTVP, HIVP, DVLP, AW, VB, VD.
        TMP geometry is separate.  Fitting libraries are still resolved separately.
        """
        p = self.pipe_prefix(mat)
        u = str(mat or p or "").upper()
        if p in {"TMP", "トミジ"} or "TMP" in u or "TOMI" in u:
            return "TMP"
        return "VP"

    def pipe_outer_diameter(self, mat: str, size: str) -> float:
        base = str(size or "").split("x")[0]
        dv = {"20":26.0, "25":32.0, "30":38.0, "40":48.0, "50":60.0, "65":76.0, "75":89.0, "100":114.0, "125":140.0, "150":165.0, "200":216.0}
        tmp = {"30":43.7,"40":55.2,"50":69.0,"65":87.4,"75":102.2,"100":131.0,"125":161.0,"150":189.6}
        p = self.pipe_prefix(mat)
        table = tmp if p in {"TMP", "トミジ"} else dv
        return table.get(base, float(re.findall(r"\d+", base)[0]) if re.findall(r"\d+", base) else 60.0)

    def pipe_label_for_jww(self, mat: str, size: str) -> str:
        p = self.pipe_prefix(mat)
        if p == "DV":
            return f"VP{size}"
        if p == "HT":
            return f"HTVP {size}"
        return f"{p}{size}"

    def material_family_for_size_tables(self, nid: Optional[int] = None, mat: str = "") -> str:
        """Classify output material for Ruby-compatible geometry tables.

        DV and 耐火VP share DV geometry. TMP/トミジ uses 3-layer pipe geometry.
        TS/HTVP/HIVP use small-diameter TS-style tables.
        """
        if nid is not None:
            p = self.current_pipe_for_node(nid)
        else:
            p = self.pipe_prefix(mat)
        pu = str(p or mat or "").upper()
        if p in ["TMP", "トミジ"] or "TMP" in pu or "TOMI" in pu:
            return "TMP"
        if p in ["HT", "HTVP", "HIVP", "TS"] or "HT" in pu or "HIVP" in pu or pu == "TS":
            return "TS"
        return "DV"

    def _size_key(self, size: str) -> str:
        nums = re.findall(r"\d+", str(size or ""))
        if len(nums) >= 2:
            return f"{nums[0]}x{nums[1]}"
        if len(nums) == 1:
            return nums[0]
        return "65"

