def _v13_components_without_base(model: PipeModel) -> int:
    try:
        bases = set(getattr(model, 'base_nodes', set()) or [])
        if getattr(model, 'base_node', None) is not None:
            bases.add(model.base_node)
        bases = {b for b in bases if b in model.nodes}
        cnt = 0
        for comp in _v12_component_nodes(model):
            if not (comp & bases):
                cnt += 1
        return cnt
    except Exception:
        return 0

