# -----------------------------------------------------------------------------
# NEVIS V14 patch - exact library file matching for reducer / multi-size fittings
# -----------------------------------------------------------------------------
def _v14_size_tokens(size: str) -> List[str]:
    return re.findall(r'\d+', str(size or ''))

def _v14_norm_name(s: str) -> str:
    return re.sub(r'[^0-9A-Za-z一-龥ぁ-んァ-ヶー]+', '_', str(s or '').upper()).strip('_')

def _v14_file_score_for_fit(path: str, group: str, size: str) -> int:
    """Higher score = safer match.

    Critical fix: for IN_65_50 the candidate file must contain BOTH 65 and 50
    in order. Old loose matching could pick IN_65 / 65x65 because it only saw 65.
    """
    stem = Path(str(path)).stem
    n = _v14_norm_name(stem)
    g = _v14_norm_name(group)
    nums = _v14_size_tokens(size)

    score = 0
    if g:
        parts = set(n.split('_'))
        if g in parts or n.startswith(g + '_') or ('_' + g + '_') in ('_' + n + '_'):
            score += 1000
        elif g in n:
            score += 250
        else:
            score -= 5000

    if len(nums) >= 2:
        a, b = nums[0], nums[1]
        exact_patterns = [
            f'{g}_{a}_{b}' if g else f'{a}_{b}',
            f'{g}_{a}X{b}' if g else f'{a}X{b}',
            f'{a}_{b}',
            f'{a}X{b}',
        ]
        if any(p and p in n for p in exact_patterns):
            score += 10000

        file_nums = _v14_size_tokens(stem)
        # Must contain the ordered pair for reducer/multi-size fittings.
        ordered = False
        for i in range(len(file_nums) - 1):
            if file_nums[i] == a and file_nums[i+1] == b:
                ordered = True
                break
        if ordered:
            score += 8000
        else:
            # Strongly reject files that do not contain full pair.
            score -= 20000

        # Penalize wrong second size, especially 65x65 when asking 65x50.
        if len(file_nums) >= 2 and not ordered:
            score -= 5000

    elif len(nums) == 1:
        a = nums[0]
        file_nums = _v14_size_tokens(stem)
        if a in file_nums:
            score += 4000
        else:
            score -= 8000

    # Prefer JSON over TXT when both exist.
    try:
        if Path(str(path)).suffix.lower() == '.json':
            score += 50
    except Exception:
        pass
    # Prefer shorter exact names, avoid random debug/backup.
    low = str(path).lower()
    if '.bak' in low or 'debug' in low:
        score -= 3000
    score -= min(len(stem), 200)
    return score

def _v14_pick_exact_library(candidates, group: str, size: str):
    if not candidates:
        return ''
    scored = []
    for p in candidates:
        try:
            scored.append((_v14_file_score_for_fit(str(p), group, size), str(p)))
        except Exception:
            pass
    if not scored:
        return ''
    scored.sort(reverse=True, key=lambda x: x[0])
    best_score, best_path = scored[0]
    # For multi-size fitting, do not accept bad loose match.
    if len(_v14_size_tokens(size)) >= 2 and best_score < 5000:
        return ''
    return best_path

def _v14_find_library_path(self, material: str, group: str, size: str):
    """Strict wrapper over existing library search.

    It first scans known library roots/folders and picks an exact file by group+size.
    If no exact multi-size match exists, it returns empty so preview shows missing
    library instead of silently showing the wrong fitting.
    """
    roots = []
    for attr in ('library_root', 'lib_root', 'root_library', 'library_dir'):
        v = getattr(self, attr, None)
        if v:
            roots.append(Path(str(v)))
    try:
        roots.append(app_base_dir() / 'Library')
        roots.append(app_base_dir() / 'library')
    except Exception:
        pass
    try:
        roots.append(Path.cwd() / 'Library')
        roots.append(Path.cwd() / 'library')
    except Exception:
        pass

    material_u = _v14_norm_name(material)
    group_u = _v14_norm_name(group)
    candidates = []
    seen = set()
    for root in roots:
        if not root.exists():
            continue
        for p in root.rglob('*'):
            if not p.is_file() or p.suffix.lower() not in ('.json', '.txt'):
                continue
            s = str(p)
            key = s.lower()
            if key in seen:
                continue
            seen.add(key)
            ns = _v14_norm_name(s)
            if group_u and group_u not in ns:
                continue
            if material_u and material_u not in ns:
                # Do not reject too hard, because some folders use DV group under VP/VU.
                pass
            candidates.append(p)

    exact = _v14_pick_exact_library(candidates, group, size)
    if exact:
        return exact

    # For reducer/multi-size: never fallback to a single-size wrong file.
    if len(_v14_size_tokens(size)) >= 2:
        return ''

    # Single-size may use old search if available.
    return None

# Patch common library path methods if they exist. Keep original as fallback for single-size only.
