# =============================================================================
# NEVIS CUSTOM LAYOUT (from "📋 Xuất code" in Edit Mode)
# =============================================================================
def _nevis_deep_remove_widget(root_layout, widget):
    """Recursively find and remove `widget` from `root_layout` or any of its
    nested sub-layouts (op_grid, type_row, bm_row, ...). Plain
    layout.removeWidget() only checks direct items, so widgets placed inside
    a nested row would otherwise stay claimed by that row and keep getting
    re-positioned by it."""
    if root_layout is None:
        return False
    try:
        if root_layout.indexOf(widget) != -1:
            root_layout.removeWidget(widget)
            return True
    except Exception:
        pass
    try:
        for i in range(root_layout.count()):
            item = root_layout.itemAt(i)
            sub = item.layout() if item is not None else None
            if sub is not None:
                if _nevis_deep_remove_widget(sub, widget):
                    return True
    except Exception:
        pass
    return False


# === NEVIS Edit Mode - layout tùy chỉnh ===
# Dán hàm này vào CUỐI file (trước def main()), rồi thêm 1 dòng
# gọi nó sau _build_ui(), ví dụ trong _v98_build_ui:
#     apply_custom_layout(self)
#
# LƯU Ý: nếu widget thuộc g_common, mỗi lần đổi ngôn ngữ
# (_v98_order_common_panel chạy lại) sẽ RESET vị trí về mặc định.
# Nếu cần giữ khi đổi ngôn ngữ, gọi apply_custom_layout(self) lại
# ngay sau self.refresh_language_texts(), hoặc copy thủ công các
# số row/col/span dưới đây vào trong _v98_order_common_panel().
def apply_custom_layout(self):
    """NEVIS left common panel layout patch: fixed 450px left panel.

    共通設定 dùng 4 cột thật + 3 cột đệm:
    C1 nhỏ, C2/C3 rộng hơn, C4 đủ cho size/DL UP.
    Chỉ thay đổi bố cục UI, không đụng thuật toán.
    """
    try:
        lay = self.g_common.layout()

        # 4 cột thật + 3 cột đệm. Tổng chiều rộng nằm gọn trong panel 450.
        COL1 = 90
        COL2 = 110
        COL3 = 105
        COL4 = 80
        GAP = 8
        H = 30
        H_MAX = 34
        REAL_COLS = [0, 2, 4, 6]
        SPACER_COLS = [1, 3, 5]
        COL_W = [COL1, COL2, COL3, COL4]

        try:
            lay.setContentsMargins(10, 18, 10, 10)
            lay.setHorizontalSpacing(0)   # khoảng hở dùng bằng cột đệm GAP
            lay.setVerticalSpacing(8)

            for c in range(8):
                lay.setColumnStretch(c, 0)
                lay.setColumnMinimumWidth(c, 0)

            lay.setColumnMinimumWidth(0, COL1)
            lay.setColumnMinimumWidth(2, COL2)
            lay.setColumnMinimumWidth(4, COL3)
            lay.setColumnMinimumWidth(6, COL4)

            for c in SPACER_COLS:
                lay.setColumnMinimumWidth(c, GAP)

            lay.setColumnStretch(7, 1)
        except Exception:
            pass

        def _deep_remove(w):
            try:
                _nevis_deep_remove_widget(lay, w)
            except Exception:
                try:
                    lay.removeWidget(w)
                except Exception:
                    pass

        def span_width(logical_col, colspan_real):
            """Tính width theo cột thật + cột đệm giữa các cột."""
            logical_col = max(0, min(3, int(logical_col)))
            colspan_real = max(1, int(colspan_real))
            widths = COL_W[logical_col:logical_col + colspan_real]
            return sum(widths) + GAP * max(0, len(widths) - 1)

        def put(name, row, logical_col, rowspan=1, colspan_real=1, width=None, maxw=None, align=Qt.AlignCenter):
            w = getattr(self, name, None)
            if w is None:
                return None

            _deep_remove(w)

            try:
                grid_col = REAL_COLS[int(logical_col)]
                grid_span = max(1, int(colspan_real) * 2 - 1)
                lay.addWidget(w, row, grid_col, rowspan, grid_span)
            except Exception:
                return w

            ww = int(width if width is not None else span_width(logical_col, colspan_real))
            mw = int(maxw if maxw is not None else ww)

            try:
                w.setMinimumWidth(ww)
                w.setMaximumWidth(mw)
                w.setMinimumHeight(H)
                w.setMaximumHeight(H_MAX)
                w.setSizePolicy(QSizePolicy.Fixed, QSizePolicy.Fixed)
            except Exception:
                pass

            if align is not None:
                try:
                    lay.setAlignment(w, align)
                except Exception:
                    pass

            return w

        # Row 0: 工事名 + project name. Label 1 cột, input 3 cột.
        put('lbl_project', 0, 0)
        put('edit_project', 0, 1, 1, 3, align=Qt.AlignLeft | Qt.AlignVCenter)

        # Row 1: 系統 cố định 2 cột + 主管サイズ + combobox.
        put('lbl_fixed_system', 1, 0, 1, 2)
        put('lbl_main_size', 1, 2)
        put('cmb_main_size', 1, 3)

        # Row 2: 主管サイズ / 1サイズ下げる / 枝サイズ / size.
        put('lbl_branch_rule', 2, 0)
        put('cmb_branch_rule', 2, 1)
        put('lbl_branch_size_v98', 2, 2)
        put('cmb_branch_size', 2, 3)

        # Row 3: 枝始点 / 集合管 / 枝端部 / DL UP.
        put('lbl_start_fitting', 3, 0)
        put('cmb_start_fitting', 3, 1)
        put('lbl_terminal', 3, 2)
        put('cmb_terminal', 3, 3)

        # Row 4: 防火適用 / 範囲 / 1200 / mm.
        put('chk_fire', 4, 0)
        put('lbl_fire_len', 4, 1)
        put('edit_fire_len', 4, 2, align=Qt.AlignLeft | Qt.AlignVCenter)
        put('lbl_fire_unit', 4, 3, align=Qt.AlignLeft | Qt.AlignVCenter)

        # Row 5: 範囲内 / TMP / 範囲外 / DV.
        put('lbl_inside', 5, 0)
        put('cmb_fire_mat', 5, 1)
        put('lbl_outside', 5, 2)
        put('cmb_normal_mat', 5, 3)

        # Row 6: Material DB + Apply, mỗi nút 2 cột.
        put('btn_common_list', 6, 0, 1, 2)
        put('btn_apply_common', 6, 2, 1, 2)

        # Style/align giữ đồng nhất, tránh chữ bị dồn về mép.
        for name in (
            'lbl_project', 'lbl_fixed_system', 'lbl_main_size',
            'lbl_branch_rule', 'lbl_branch_size_v98', 'lbl_start_fitting',
            'lbl_terminal', 'lbl_fire_len', 'lbl_inside', 'lbl_outside',
            'chk_fire', 'btn_common_list', 'btn_apply_common'
        ):
            w = getattr(self, name, None)
            if w is not None:
                try:
                    w.setAlignment(Qt.AlignCenter)
                except Exception:
                    pass

        # Ẩn combo hệ thống cũ nếu còn tồn tại.
        try:
            if hasattr(self, 'lbl_system'):
                self.lbl_system.setVisible(False)
            if hasattr(self, 'cmb_system'):
                self.cmb_system.setVisible(False)
        except Exception:
            pass

        # Khóa các group bên trái theo panel 450, không để ruột tự bung.
        for gname in ('g_common', 'g_sel', 'g_branch_mat', 'g_support'):
            g = getattr(self, gname, None)
            if g is not None:
                try:
                    g.setMinimumWidth(450)
                    g.setMaximumWidth(450)
                    g.setSizePolicy(QSizePolicy.Fixed, QSizePolicy.Maximum)
                except Exception:
                    pass

        # Các hint dài ở vùng dưới không ép bung panel.
        for name, group_name, args in (
            ('lbl_branch_mat_hint', 'g_branch_mat', ('insert', 1)),
            ('lbl_support_hint', 'g_support', ('grid', 2, 0, 1, 5)),
        ):
            w = getattr(self, name, None)
            group = getattr(self, group_name, None)
            if w is None or group is None:
                continue
            glay = group.layout()
            try:
                _nevis_deep_remove_widget(glay, w)
            except Exception:
                pass
            try:
                if args[0] == 'insert':
                    glay.insertWidget(args[1], w)
                else:
                    glay.addWidget(w, args[1], args[2], args[3], args[4])
                w.setMinimumWidth(0)
                w.setMaximumWidth(420)
            except Exception:
                pass

        # Một vài control vùng support giữ kích thước hợp lý.
        w = getattr(self, 'edit_support_spacing', None)
        if w is not None:
            try:
                glay = self.g_support.layout()
                _nevis_deep_remove_widget(glay, w)
                glay.addWidget(w, 1, 1, 1, 1)
                w.setMinimumWidth(60)
                w.setMaximumWidth(70)
                w.setMinimumHeight(26)
                w.setMaximumHeight(30)
            except Exception:
                pass

        w = getattr(self, 'btn_apply_support', None)
        if w is not None:
            try:
                glay = self.g_support.layout()
                _nevis_deep_remove_widget(glay, w)
                glay.addWidget(w, 0, 3, 2, 1)
                w.setMinimumWidth(130)
                w.setMaximumWidth(150)
                w.setMinimumHeight(26)
                w.setMaximumHeight(34)
            except Exception:
                pass

        w = getattr(self, 'lbl_selected', None)
        if w is not None:
            try:
                glay = self.g_sel.layout()
                _nevis_deep_remove_widget(glay, w)
                glay.addWidget(w, 0, 0, 1, 3)
                w.setMinimumWidth(0)
                w.setMaximumWidth(430)
            except Exception:
                pass

    except Exception as ex:
        print('CUSTOM_LAYOUT_ERROR', ex)




# =============================================================================
# NEVIS 2.02 V102 - Quick replace branch-start choices
# =============================================================================
# Branch start must not be locked to 集合管 only.  When right-double-clicking a
# branch-start node, show four selectable groups: 集合管 / DL_D / LL_D / 特.
# 集合管 files are grouped by actual port count/shape so repeated size names are
# readable: 1 cửa, 2 cửa thẳng, 2 cửa vuông góc, 3 cửa.
try:
    if '_NevisV82QuickReplaceDialog' in globals():
        _NEVIS_V102_OLD_QUICK_POPULATE = getattr(_NevisV82QuickReplaceDialog, '_populate', None)

        def _nevis_v102_combo_code(mw, combo_name: str, fallback: str = '') -> str:
            try:
                combo = getattr(mw, combo_name, None)
                if combo is not None and hasattr(mw, '_combo_current_code'):
                    v = mw._combo_current_code(combo)
                    if v:
                        return str(v).strip()
                if combo is not None:
                    return str(combo.currentText() or '').strip()
            except Exception:
                pass
            return fallback

        def _nevis_v102_node_pipe_material(mw, nid: int) -> str:
            """Material used to find DL_D/LL_D alternatives at a start node.

            集合管 itself is material-independent, but DL/LL_D alternatives still
            belong to the nearby pipe material.  Do not reuse _v82_material_for_node
            when it returns 集合管.
            """
            try:
                for nb in mw.model.neighbors(int(nid)):
                    e = edge_obj(mw.model, int(nid), nb)
                    if e is not None:
                        mat = str(mw.edge_material(e) if hasattr(mw, 'edge_material') else '').strip()
                        if mat and mat != '集合管':
                            return mat
            except Exception:
                pass
            try:
                mat = str(mw.edge_material_for_node(int(nid)) or '').strip()
                if mat and mat != '集合管':
                    return mat
            except Exception:
                pass
            return _nevis_v102_combo_code(mw, 'cmb_normal_mat', 'DV') or 'DV'

        def _nevis_v102_lang(mw) -> str:
            try:
                return 'jp' if getattr(mw, 'lang', 'vi') == 'jp' else 'vi'
            except Exception:
                return 'vi'

        def _nevis_v102_label(mw, key: str) -> str:
            lang = _nevis_v102_lang(mw)
            labels = {
                'vi': {
                    'collection': '集合管',
                    'one': '1 cửa',
                    'straight2': '2 cửa thẳng',
                    'corner2': '2 cửa vuông góc',
                    'review2': '2 cửa / cần xem preview',
                    'three': '3 cửa',
                    'hint': 'Mở nhóm bên trái để chọn thư viện.',
                },
                'jp': {
                    'collection': '集合管',
                    'one': '1口',
                    'straight2': '2口・直線',
                    'corner2': '2口・直角',
                    'review2': '2口・要確認',
                    'three': '3口',
                    'hint': '左のグループを開いてライブラリを選択してください。',
                },
            }
            return labels.get(lang, labels['vi']).get(key, key)

        def _nevis_v102_is_branch_start_node(mw, nid: int, ftype: str) -> bool:
            try:
                if int(nid) == getattr(mw.model, 'base_node', None):
                    return True
                if int(nid) in (getattr(mw.model, 'base_nodes', set()) or set()):
                    return True
            except Exception:
                pass
            return _v82_norm_ftype(ftype) == '集合管'

        def _nevis_v102_collection_info(path: Path, mw=None):
            """Return (group_label, size_label, port_count) for a 集合管 file.

            Library naming rule used by NEVIS drainage:
            - S_65          : 1口 / 1 cửa
            - S_65_50       : 2口直線 / 2 cửa thẳng
            - SV_65_50      : 2口直角 / 2 cửa vuông góc
            - S3_65_50_75   : 3口 / 3 cửa

            JSON port count is used as extra confirmation, but SV is never 3 cửa.
            """
            stem = Path(path).stem
            up = stem.upper()
            nums = re.findall(r'\d+', stem)

            if up.startswith('S3'):
                size_label = 'x'.join(nums[-3:]) if len(nums) >= 3 else ('x'.join(nums) if nums else stem)
            elif len(nums) >= 2:
                size_label = 'x'.join(nums[-2:])
            elif nums:
                size_label = nums[-1]
            else:
                size_label = stem

            port_count = 0
            angle_label = ''
            try:
                if path.suffix.lower() == '.json' and '_json_connector_objects' in globals():
                    anchor, ports, meta = _json_connector_objects(str(path))
                    port_count = len(ports or [])
                    if port_count == 2:
                        pts = []
                        for po in ports:
                            xy = po.get('point') or anchor
                            pts.append((float(xy[0]) - float(anchor[0]), float(xy[1]) - float(anchor[1])))
                        if len(pts) >= 2:
                            ang = angle_between(pts[0], pts[1])
                            angle_label = _nevis_v102_label(mw, 'straight2') if abs(180.0 - ang) <= 25.0 else _nevis_v102_label(mw, 'corner2')
            except Exception:
                pass

            # Filename has priority because old JSON libraries sometimes expose
            # center + 2 ports for SV, which previously made SV look like 3 cửa.
            if up.startswith('SV'):
                group = _nevis_v102_label(mw, 'corner2')
            elif up.startswith('S3') or (port_count >= 3 and not up.startswith('SV')):
                group = _nevis_v102_label(mw, 'three')
            elif port_count == 2:
                group = angle_label or _nevis_v102_label(mw, 'review2')
            elif len(nums) <= 1:
                group = _nevis_v102_label(mw, 'one')
            else:
                group = _nevis_v102_label(mw, 'straight2')
            return group, size_label, port_count

        def _nevis_v102_unique_title(used: set, base: str, path: Path) -> str:
            title = base
            # Avoid unreadable duplicate rows like 50x50, 50x50, 50x50.
            if title in used:
                title = f'{base}  [{path.stem}]'
            k = 2
            orig = title
            while title in used:
                title = f'{orig} ({k})'; k += 1
            used.add(title)
            return title

        def _nevis_v102_sort_key_from_title(title_path):
            title, p = title_path
            nums = [int(n) for n in re.findall(r'\d+', str(title))]
            return (nums[0] if nums else 9999, nums[1] if len(nums) > 1 else -1, str(title), Path(p).stem)

        def _nevis_v102_add_collection_group(tree, files, mw=None):
            root = QTreeWidgetItem(tree, [_nevis_v102_label(mw, 'collection')])
            group_order = [
                _nevis_v102_label(mw, 'one'),
                _nevis_v102_label(mw, 'straight2'),
                _nevis_v102_label(mw, 'corner2'),
                _nevis_v102_label(mw, 'review2'),
                _nevis_v102_label(mw, 'three'),
            ]
            buckets = {g: [] for g in group_order}
            for p in files:
                try:
                    if _v82_is_tokushu(p):
                        continue
                    if not _v82_is_current_type_file(p, '集合管'):
                        continue
                    group, size_label, _pc = _nevis_v102_collection_info(p, mw)
                    buckets.setdefault(group, []).append((size_label, p))
                except Exception:
                    pass
            for group in group_order + [g for g in buckets.keys() if g not in group_order]:
                vals = buckets.get(group) or []
                if not vals:
                    continue
                gr = QTreeWidgetItem(root, [group])
                used = set()
                for size_label, p in sorted(vals, key=_nevis_v102_sort_key_from_title):
                    title = _nevis_v102_unique_title(used, size_label or Path(p).stem, Path(p))
                    _v82_add_file_item(gr, title, Path(p), 'apply_same_type', size_label, '集合管')
            return root

        def _nevis_v102_add_down_group(tree, files, label: str, base_type: str, mat: str):
            root = QTreeWidgetItem(tree, [label])
            vals = []
            for p in files:
                try:
                    if _v82_is_tokushu(p):
                        continue
                    if not _v82_is_current_type_file(p, base_type):
                        continue
                    if not _v82_path_has_material(p, mat):
                        continue
                    # Prefer explicitly marked Down/D files.  If helper exists,
                    # use it; otherwise check path/stem text.
                    mode = ''
                    try:
                        mode = _nevis_v94_path_ud_subtype(p)
                    except Exception:
                        txt = (str(p.parent) + '_' + p.stem).upper()
                        if re.search(r'(^|[_\-\s])D(OWN)?($|[_\-\s])', txt):
                            mode = 'D'
                    if mode != 'D':
                        continue
                    sz = _v82_nums_size_from_name(p.stem, base_type)
                    vals.append((sz or p.stem, p))
                except Exception:
                    pass
            used = set()
            for sz, p in sorted(vals, key=_nevis_v102_sort_key_from_title):
                title = _nevis_v102_unique_title(used, sz or Path(p).stem, Path(p))
                _v82_add_file_item(root, title, Path(p), 'apply_same_type', sz, base_type)
            return root

        def _nevis_v102_add_special_group(tree, files):
            root = QTreeWidgetItem(tree, ['特'])
            vals = [p for p in files if _v82_is_tokushu(p)]
            used = set()
            for p in sorted(vals, key=lambda x: (str(x.parent), x.stem)):
                title = _nevis_v102_unique_title(used, p.stem, Path(p))
                _v82_add_file_item(root, title, Path(p), 'special_node', '', '特')
            return root

        def _nevis_v102_quick_populate(self):
            try:
                # Only replace branch-start node behavior.  Other node/edge quick
                # replace dialogs keep all previous V95/V94 behavior.
                if self.target_kind != 'node':
                    if _NEVIS_V102_OLD_QUICK_POPULATE:
                        return _NEVIS_V102_OLD_QUICK_POPULATE(self)
                    return
                mw = self.mw
                nid = int(self.target_val)
                fit = mw.model.fittings.get(nid)
                ftype = _v82_norm_ftype(getattr(fit, 'ftype', ''))
                if not _nevis_v102_is_branch_start_node(mw, nid, ftype):
                    if _NEVIS_V102_OLD_QUICK_POPULATE:
                        return _NEVIS_V102_OLD_QUICK_POPULATE(self)
                    return

                self.tree.clear()
                files = _v82_scan_library_files(mw)
                pipe_mat = _nevis_v102_node_pipe_material(mw, nid)
                _nevis_v102_add_collection_group(self.tree, files, mw)
                _nevis_v102_add_down_group(self.tree, files, 'DL_D', 'DL', pipe_mat)
                _nevis_v102_add_down_group(self.tree, files, 'LL_D', 'LL', pipe_mat)
                _nevis_v102_add_special_group(self.tree, files)

                self.tree.collapseAll()
                self.tree.setCurrentItem(None)
                self.preview_scene.clear()
                try:
                    self.info.setText(mw.tr('quick_open_group_hint'))
                except Exception:
                    self.info.setText(_nevis_v102_label(mw, 'hint'))
            except Exception as ex:
                try:
                    self.info.setText(f'Lỗi đọc thư viện: {ex}')
                except Exception:
                    pass
                try:
                    print('NEVIS_V102_START_OPTIONS_POPULATE_ERROR', ex)
                except Exception:
                    pass

        _NevisV82QuickReplaceDialog._populate = _nevis_v102_quick_populate
    print('NEVIS_202_V102_START_OPTIONS_GROUPED_READY')
except Exception as _nevis_v102_err:
    print('NEVIS_V102_PATCH_ERROR', _nevis_v102_err)




# =============================================================================
# NEVIS 2.02 V103 - Remember exact quick-selected library file
# =============================================================================
# Fix: Quick replace selected the correct DL_D / DL_U / LL_D / LL_U JSON, but
# after pressing OK NEVIS only saved ftype + size (e.g. DL + 65).  Later preview,
# detail preview and JWW export searched again and often picked the normal DL
# library instead of the exact D/U file selected by the user.
try:
    def _nevis_v103_stored_library_path_from_fit(fit) -> str:
        for attr in ('quick_library_path', 'library_path', 'selected_library_path', 'exact_library_path'):
            try:
                p = str(getattr(fit, attr, '') or '').strip()
                if p and Path(p).exists():
                    return p
            except Exception:
                pass
        return ''

    def _nevis_v103_path_matches_request(path: str, ftype: str, size: str) -> bool:
        try:
            p = Path(str(path or ''))
            if not p.exists():
                return False
            ft = _v82_norm_ftype(ftype) if '_v82_norm_ftype' in globals() else str(ftype or '').strip()
            if ft and '_v82_is_current_type_file' in globals() and not _v82_is_current_type_file(p, ft):
                return False
            req_nums = re.findall(r'\d+', str(size or ''))
            if req_nums:
                stem_nums = re.findall(r'\d+', p.stem)
                # Every requested size token must exist in the selected stem.
                # DL_65_65_D matches size 65; S_65_50 matches 65x50.
                for n in req_nums:
                    if n not in stem_nums:
                        return False
            return True
        except Exception:
            return False

    def _nevis_v103_store_payload_path_on_fit(mw, nid: int, payload: dict) -> None:
        try:
            path = str((payload or {}).get('path', '') or '').strip()
            if not path or not Path(path).exists():
                return
            fit = mw.model.fittings.get(int(nid))
            if fit is None:
                return
            setattr(fit, 'quick_library_path', path)
            setattr(fit, 'library_path', path)
            setattr(fit, 'selected_library_path', path)
            setattr(fit, 'exact_library_path', path)
            setattr(fit, 'library_name', Path(path).stem)
            try:
                setattr(fit, 'library_variant', _nevis_v94_path_ud_subtype(Path(path)))
            except Exception:
                pass
        except Exception as ex:
            try: print('NEVIS_V103_STORE_EXACT_LIBRARY_PATH_ERROR', ex)
            except Exception: pass

    _NEVIS_V103_PREV_APPLY_PAYLOAD = globals().get('_v82_apply_payload', None)

    def _nevis_v103_apply_payload(mw, target_kind, target_val, payload):
        act = str((payload or {}).get('action', '') or '')
        if str(target_kind) == 'node' and act == 'apply_same_type':
            ok = False
            if _NEVIS_V103_PREV_APPLY_PAYLOAD:
                ok = bool(_NEVIS_V103_PREV_APPLY_PAYLOAD(mw, target_kind, target_val, payload))
            # Store after the previous apply path because apply_node() may replace
            # the Fitting object.  The exact path then becomes the source of truth.
            _nevis_v103_store_payload_path_on_fit(mw, int(target_val), payload or {})
            try:
                mw.select_node(int(target_val))
            except Exception:
                try:
                    mw.update_selected_library_preview()
                    mw.preview.draw_model()
                except Exception:
                    pass
            return ok
        if _NEVIS_V103_PREV_APPLY_PAYLOAD:
            return _NEVIS_V103_PREV_APPLY_PAYLOAD(mw, target_kind, target_val, payload)
        return False

    globals()['_v82_apply_payload'] = _nevis_v103_apply_payload

    _NEVIS_V103_PREV_MATCHING_LIBRARY_PATH = getattr(MainWindow, 'matching_library_path', None)

    def _nevis_v103_matching_library_path(self, nid, ftype, size):
        try:
            if nid is not None:
                fit = self.model.fittings.get(int(nid))
                p = _nevis_v103_stored_library_path_from_fit(fit)
                if p and _nevis_v103_path_matches_request(p, ftype, size):
                    return p
        except Exception:
            pass
        if _NEVIS_V103_PREV_MATCHING_LIBRARY_PATH:
            return _NEVIS_V103_PREV_MATCHING_LIBRARY_PATH(self, nid, ftype, size)
        return ''

    MainWindow.matching_library_path = _nevis_v103_matching_library_path

    _NEVIS_V103_PREV_RESOLVE_FITTING_LIBRARY_PATH = getattr(MainWindow, 'resolve_fitting_library_path_for_jww', None)

    def _nevis_v103_resolve_fitting_library_path_for_jww(self, nid, fit):
        try:
            p = _nevis_v103_stored_library_path_from_fit(fit)
            if p:
                return p
        except Exception:
            pass
        if _NEVIS_V103_PREV_RESOLVE_FITTING_LIBRARY_PATH:
            return _NEVIS_V103_PREV_RESOLVE_FITTING_LIBRARY_PATH(self, nid, fit)
        return ''

    MainWindow.resolve_fitting_library_path_for_jww = _nevis_v103_resolve_fitting_library_path_for_jww

    print('NEVIS_202_V103_EXACT_QUICK_LIBRARY_PATH_READY')
except Exception as _nevis_v103_err:
    print('NEVIS_V103_PATCH_ERROR', _nevis_v103_err)


# =============================================================================
# NEVIS 2.02 V107S - safe startup + lightweight selection cache
# =============================================================================
# Patch này chỉ giảm lag khi chọn đối tượng/preview thư viện.  Nó không đổi thuật
# toán tính tuyến, tính size, trim miệng cút hay xuất JWW.
try:
    def _nevis_v107s_lower_size(mw, size: str) -> str:
        size = str(size or '').strip().split('x')[0]
        if not size:
            return ''
        try:
            sizes = mw.library_pipe_sizes_for_material() if hasattr(mw, 'library_pipe_sizes_for_material') else []
        except Exception:
            sizes = []
        try:
            if sizes and size in sizes:
                i = sizes.index(size)
                return sizes[max(0, i - 1)]
            if sizes:
                v = int(float(size))
                smaller = [s for s in sizes if int(float(s)) < v]
                if smaller:
                    return smaller[-1]
        except Exception:
            pass
        try:
            return lower_pipe_size(size)
        except Exception:
            return size

    # Startup guard: some patched builds call sync_branch_size_from_rule() during
    # __init__ before every later hotfix has attached helper methods.
    if not hasattr(MainWindow, 'dynamic_lower_pipe_size'):
        def _nevis_v107s_dynamic_lower_pipe_size(self, size: str) -> str:
            return _nevis_v107s_lower_size(self, size)
        MainWindow.dynamic_lower_pipe_size = _nevis_v107s_dynamic_lower_pipe_size

    _NEVIS_V107S_PREV_SYNC_BRANCH = getattr(MainWindow, 'sync_branch_size_from_rule', None)
    if _NEVIS_V107S_PREV_SYNC_BRANCH:
        def _nevis_v107s_sync_branch_size_from_rule(self):
            try:
                return _NEVIS_V107S_PREV_SYNC_BRANCH(self)
            except AttributeError as ex:
                if 'dynamic_lower_pipe_size' not in str(ex):
                    raise
                if not hasattr(self, 'cmb_branch_rule') or not hasattr(self, 'cmb_branch_size'):
                    return
                code = self.cmb_branch_rule.currentData() or self._branch_rule_code_from_text()
                main = self.cmb_main_size.currentText().strip() if hasattr(self, 'cmb_main_size') else ''
                fixed = (code == 'fixed')
                self.cmb_branch_size.setEnabled(fixed)
                if not main:
                    if not fixed:
                        self.cmb_branch_size.setCurrentText('')
                    return
                if code == 'same':
                    self.cmb_branch_size.setCurrentText(main)
                elif not fixed:
                    self.cmb_branch_size.setCurrentText(_nevis_v107s_lower_size(self, main))
        MainWindow.sync_branch_size_from_rule = _nevis_v107s_sync_branch_size_from_rule

    _NEVIS_V107S_PREV_MATCHING_LIBRARY_PATH = getattr(MainWindow, 'matching_library_path', None)
    _NEVIS_V107S_PREV_UPDATE_SELECTED_LIBRARY_PREVIEW = getattr(MainWindow, 'update_selected_library_preview', None)
    _NEVIS_V107S_PREV_PIPE_LIBRARY_PATH = getattr(MainWindow, 'pipe_library_path', None)
    _NEVIS_V107S_PREV_SELECT_NODE = getattr(MainWindow, 'select_node', None)

    def _nevis_v107s_index_token(mw):
        try:
            return (len(getattr(mw, 'library_index', []) or []), id(getattr(mw, '_lib_lookup', None)))
        except Exception:
            return (0, 0)

    def _nevis_v107s_norm_ftype(mw, ftype: str) -> str:
        try:
            if '_nvs_role_clean' in globals():
                ftype = _nvs_role_clean(ftype)
        except Exception:
            pass
        try:
            return mw.normalize_lib_type(str(ftype or ''))
        except Exception:
            return str(ftype or '').strip()

    def _nevis_v107s_matching_library_path(self, nid, ftype, size):
        if not _NEVIS_V107S_PREV_MATCHING_LIBRARY_PATH:
            return ''
        try:
            pipe = self.current_pipe_for_node(nid) if hasattr(self, 'current_pipe_for_node') else ''
            key = (nid, pipe, _nevis_v107s_norm_ftype(self, ftype), str(size or '').strip(), _nevis_v107s_index_token(self))
            cache = getattr(self, '_nevis_v107s_path_cache', None)
            if not isinstance(cache, dict):
                cache = {}
                self._nevis_v107s_path_cache = cache
            hit = cache.get(key, None)
            if hit is not None:
                return hit if (not hit or Path(str(hit)).exists()) else ''
            out = str(_NEVIS_V107S_PREV_MATCHING_LIBRARY_PATH(self, nid, ftype, size) or '')
            if len(cache) > 1000:
                cache.clear()
            cache[key] = out
            return out
        except Exception:
            return _NEVIS_V107S_PREV_MATCHING_LIBRARY_PATH(self, nid, ftype, size)

    def _nevis_v107s_update_selected_library_preview(self):
        if getattr(self, '_nevis_v107s_suppress_preview', False):
            return
        if not _NEVIS_V107S_PREV_UPDATE_SELECTED_LIBRARY_PREVIEW:
            return
        try:
            if not hasattr(self, 'fit_preview_scene'):
                return
            ftype = self.cmb_fit_type.currentText() if hasattr(self, 'cmb_fit_type') else ''
            size = self.cmb_fit_size.currentText().strip() if hasattr(self, 'cmb_fit_size') else ''
            path = self.matching_library_path(getattr(self, 'selected_node', None), ftype, size)
            try:
                st = Path(path).stat() if path else None
                psig = (str(Path(path).resolve()), float(st.st_mtime), int(st.st_size)) if st else ('', 0.0, 0)
            except Exception:
                psig = (str(path or ''), 0.0, 0)
            sig = (getattr(self, 'selected_node', None), _nevis_v107s_norm_ftype(self, ftype), size, psig)
            if getattr(self, '_nevis_v107s_preview_sig', None) == sig:
                return
            self._nevis_v107s_preview_sig = sig
            self.draw_library_preview(path)
        except Exception:
            return _NEVIS_V107S_PREV_UPDATE_SELECTED_LIBRARY_PREVIEW(self)

    def _nevis_v107s_pipe_library_path(self, mat: str, size: str) -> str:
        if not _NEVIS_V107S_PREV_PIPE_LIBRARY_PATH:
            return ''
        try:
            key = (str(mat or ''), str(size or '').split('x')[0].strip(), _nevis_v107s_index_token(self))
            cache = getattr(self, '_nevis_v107s_pipe_cache', None)
            if not isinstance(cache, dict):
                cache = {}
                self._nevis_v107s_pipe_cache = cache
            hit = cache.get(key, None)
            if hit is not None:
                return hit if (not hit or Path(str(hit)).exists()) else ''
            out = str(_NEVIS_V107S_PREV_PIPE_LIBRARY_PATH(self, mat, size) or '')
            if len(cache) > 500:
                cache.clear()
            cache[key] = out
            return out
        except Exception:
            return _NEVIS_V107S_PREV_PIPE_LIBRARY_PATH(self, mat, size)

    def _nevis_v107s_select_node(self, nid: int):
        try:
            if nid not in self.model.nodes:
                return
            fit = self.model.fittings.get(nid)
            if fit:
                self._nevis_v107s_suppress_preview = True
                try:
                    ret = _NEVIS_V107S_PREV_SELECT_NODE(self, nid)
                finally:
                    self._nevis_v107s_suppress_preview = False
                self.update_selected_library_preview()
                return ret
            return _NEVIS_V107S_PREV_SELECT_NODE(self, nid)
        except Exception:
            return _NEVIS_V107S_PREV_SELECT_NODE(self, nid)

    MainWindow.matching_library_path = _nevis_v107s_matching_library_path
    MainWindow.update_selected_library_preview = _nevis_v107s_update_selected_library_preview
    MainWindow.pipe_library_path = _nevis_v107s_pipe_library_path
    if _NEVIS_V107S_PREV_SELECT_NODE:
        MainWindow.select_node = _nevis_v107s_select_node

    print('NEVIS_202_V107S_SAFE_SELECTION_CACHE_READY')
except Exception as _nevis_v107s_err:
    print('NEVIS_V107S_PATCH_ERROR', _nevis_v107s_err)


# =============================================================================
# NEVIS 2.02 V108 - collection fitting BOM is material-independent
# =============================================================================
# 集合管 is a special device.  Even when it is located inside the fire-protection
# range, it must not be listed as TMP/DV/VP-VU in the material table.  Keep size,
# name, unit and quantity, but leave 種類 blank.
try:
    _NEVIS_V108_PREV_BUILD_MATERIAL_ROWS = getattr(MainWindow, 'build_material_rows', None)

    def _nevis_v108_is_collection_bom_row(row) -> bool:
        try:
            vals = list(row) + [''] * 6
            mat = str(vals[0] or '').strip()
            size = str(vals[1] or '').strip()
            name = str(vals[2] or '').strip()
            note = str(vals[5] or '').strip()
            blob = f'{mat} {size} {name} {note}'.upper()
            if '集合管' in blob:
                return True
            # Library names for 集合管 are commonly S_*, SV_* or S3_*.
            # Keep this narrow so normal pipe/fitting rows are not affected.
            name2 = name.upper().replace('-', '_').replace(' ', '_')
            return bool(re.search(r'(^|_)S3?(_|$)', name2) or re.search(r'(^|_)SV(_|$)', name2))
        except Exception:
            return False

    def _nevis_v108_build_material_rows(self, sheet_type: str = ''):
        rows = _NEVIS_V108_PREV_BUILD_MATERIAL_ROWS(self, sheet_type) if _NEVIS_V108_PREV_BUILD_MATERIAL_ROWS else []
        out = []
        for r in rows or []:
            try:
                row = list(r)
                while len(row) < 6:
                    row.append('')
                if _nevis_v108_is_collection_bom_row(row):
                    row[0] = ''
                    # 集合管 is counted as an individual fitting/device.
                    if not str(row[3] or '').strip():
                        row[3] = '個'
                out.append(row)
            except Exception:
                out.append(r)
        return out

    MainWindow.build_material_rows = _nevis_v108_build_material_rows
    print('NEVIS_202_V108_COLLECTION_BOM_NO_MATERIAL_READY')
except Exception as _nevis_v108_err:
    print('NEVIS_V108_PATCH_ERROR', _nevis_v108_err)


# =============================================================================
# NEVIS 2.02 V109 - clearer drainage-only badge in common settings
# =============================================================================
# The current release supports only drainage horizontal/rolling pipe layouts.
# Show that limitation as a short orange badge, localized by current UI language.
try:
    APP_TEXT.setdefault('vi', {}).update({
        'fixed_system': 'Đường ống thoát dưới sàn cho căn hộ',
    })
    APP_TEXT.setdefault('jp', {}).update({
        'fixed_system': '住宅排水転がし配管専用',
    })

    def _nevis_v109_fixed_system_text(mw) -> str:
        try:
            return mw.tr('fixed_system')
        except Exception:
            return '住宅排水転がし配管専用'

    def _nevis_v109_style_fixed_system(mw):
        try:
            w = getattr(mw, 'lbl_fixed_system', None)
            if w is None:
                return
            w.setText(_nevis_v109_fixed_system_text(mw))
            w.setAlignment(Qt.AlignCenter)
            w.setMinimumHeight(30)
            w.setMaximumHeight(34)
            w.setStyleSheet(
                'color:#C55A00; font-weight:800; background:#FFF2DF; '
                'border:1px solid #F0A34A; border-radius:6px; padding:3px 7px;'
            )
            try:
                w.setToolTip('住宅排水転がし配管専用' if getattr(mw, 'lang', 'jp') != 'vi' else 'Đường ống thoát dưới sàn cho căn hộ.')
            except Exception:
                pass
        except Exception:
            pass

    _NEVIS_V109_PREV_BUILD_UI = getattr(MainWindow, '_build_ui', None)
    if _NEVIS_V109_PREV_BUILD_UI:
        def _nevis_v109_build_ui(self, *args, **kwargs):
            ret = _NEVIS_V109_PREV_BUILD_UI(self, *args, **kwargs)
            _nevis_v109_style_fixed_system(self)
            return ret
        MainWindow._build_ui = _nevis_v109_build_ui

    _NEVIS_V109_PREV_REFRESH_LANGUAGE_TEXTS = getattr(MainWindow, 'refresh_language_texts', None)
    if _NEVIS_V109_PREV_REFRESH_LANGUAGE_TEXTS:
        def _nevis_v109_refresh_language_texts(self, *args, **kwargs):
            ret = _NEVIS_V109_PREV_REFRESH_LANGUAGE_TEXTS(self, *args, **kwargs)
            _nevis_v109_style_fixed_system(self)
            return ret
        MainWindow.refresh_language_texts = _nevis_v109_refresh_language_texts

    print('NEVIS_202_V109_DRAINAGE_ONLY_ORANGE_BADGE_READY')
except Exception as _nevis_v109_err:
    print('NEVIS_V109_PATCH_ERROR', _nevis_v109_err)


# =============================================================================
# NEVIS 2.02 V110 - packaged library editor launcher
# =============================================================================
# In a PyInstaller build, sys.executable is Nevis.exe, not a Python interpreter.
# Prefer the bundled editor EXE, and keep the old .py path for source testing.
try:
    _NEVIS_V110_PREV_LAUNCH_LIBRARY_EDITOR = getattr(MainWindow, 'launch_library_editor', None)

    def _nevis_v110_launch_library_editor(self):
        try:
            base = app_base_dir()
        except Exception:
            base = Path(sys.executable).resolve().parent if getattr(sys, 'frozen', False) else Path.cwd()
        env = os.environ.copy()
        env["NEVIS_LANG"] = getattr(self, "lang", "vi")
        env["NEVIS_LIBRARY_ROOT"] = str((base / "library") if (base / "library").exists() else ((base / "Library") if (base / "Library").exists() else base))
        exe_candidates = [
            base / "Nevis_Library_Editor.exe",
            base / "Nevis_JSON_Library_Editor_FINAL_i18n.exe",
        ]
        exe = next((x for x in exe_candidates if x.exists()), None)
        if exe is not None:
            try:
                subprocess.Popen([str(exe)], cwd=str(base), env=env)
                return
            except Exception as e:
                QMessageBox.warning(self, "NEVIS", str(e))
                return
        if _NEVIS_V110_PREV_LAUNCH_LIBRARY_EDITOR:
            return _NEVIS_V110_PREV_LAUNCH_LIBRARY_EDITOR(self)
        QMessageBox.warning(self, "NEVIS", self.tr("library_editor_not_found") + "\nNevis_Library_Editor.exe")

    MainWindow.launch_library_editor = _nevis_v110_launch_library_editor
    print('NEVIS_202_V110_PACKAGED_EDITOR_LAUNCHER_READY')
except Exception as _nevis_v110_err:
    print('NEVIS_V110_PATCH_ERROR', _nevis_v110_err)


# =============================================================================
# NEVIS 2.02 V111 - special library material definition map
# =============================================================================
# 特 libraries are not always one new item.  A file like 45°+45° may need to be
# counted as two standard elbows, while another 特 file may be a new material
# name.  Store the user's definition in library/Settings/special_material_map.json.
try:
    APP_TEXT.setdefault('vi', {}).update({
        'special_bom_editor': 'Định danh vật tư 特',
    })
    APP_TEXT.setdefault('jp', {}).update({
        'special_bom_editor': '特 材料定義',
    })

    def _nevis_v111_settings_dir() -> Path:
        try:
            base = app_base_dir()
        except Exception:
            base = Path.cwd()
        for name in ('library', 'Library'):
            p = base / name / 'Settings'
            if p.exists() or (base / name).exists():
                p.mkdir(parents=True, exist_ok=True)
                return p
        p = base / 'library' / 'Settings'
        p.mkdir(parents=True, exist_ok=True)
        return p

    def _nevis_v111_map_path() -> Path:
        return _nevis_v111_settings_dir() / 'special_material_map.json'

    def _nevis_v111_load_map() -> dict:
        p = _nevis_v111_map_path()
        try:
            data = json.loads(p.read_text(encoding='utf-8-sig'))
            if isinstance(data, dict):
                defs = data.get('definitions', data)
                return dict(defs) if isinstance(defs, dict) else {}
        except Exception:
            pass
        return {}

    def _nevis_v111_save_map(defs: dict) -> Path:
        p = _nevis_v111_map_path()
        p.parent.mkdir(parents=True, exist_ok=True)
        data = {
            'schema': 'NEVIS_SPECIAL_MATERIAL_MAP_V1',
            'description': 'Key = special library relative path or file stem. Rows = material/size/item/unit/qty/note counted for one placed 特.',
            'definitions': defs or {},
        }
        p.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding='utf-8')
        return p

    def _nevis_v111_rel_key(path: str) -> str:
        try:
            p = Path(str(path)).resolve()
            base = app_base_dir().resolve()
            return str(p.relative_to(base)).replace('\\', '/')
        except Exception:
            try:
                return str(Path(str(path)).name)
            except Exception:
                return str(path or '')

    def _nevis_v111_keys_for_special(sp: dict) -> List[str]:
        out = []
        path = str(sp.get('path', '') or '')
        if path:
            out.append(_nevis_v111_rel_key(path))
            out.append(Path(path).name)
            out.append(Path(path).stem)
        name = str(sp.get('name', '') or '').strip()
        mat = str(sp.get('mat', '') or '').strip()
        size = str(sp.get('size', '') or '').strip()
        if name:
            out.append(name)
        if mat and size and name:
            out.append(f'{mat}_{size}_{name}')
        seen = set()
        uniq = []
        for k in out:
            k = str(k or '').strip()
            if k and k not in seen:
                seen.add(k); uniq.append(k)
        return uniq

    def _nevis_v111_definition_for_special(defs: dict, sp: dict):
        for k in _nevis_v111_keys_for_special(sp):
            rec = defs.get(k)
            if isinstance(rec, dict):
                return rec
        return None

    def _nevis_v111_special_old_rows(mw, sp: dict) -> List[List[object]]:
        rows = []
        try:
            mat = mw.material_kind_label(str(sp.get('mat','') or mw.cmb_normal_mat.currentText()))
            size = _sp_v1_base_size(str(sp.get('size',''))) if '_sp_v1_base_size' in globals() else str(sp.get('size',''))
            name = str(sp.get('name','')).strip()
            qty = float(sp.get('quantity', 1) or 1)
            parts = _sp_v1_combo_parts(name) if '_sp_v1_combo_parts' in globals() else []
            if parts:
                for part in parts:
                    item_name = mw.material_kind_name(part) if hasattr(mw, 'material_kind_name') else part
                    rows.append([mat, size, item_name, '個', qty, ''])
            else:
                rows.append([mat, size, name, '個', qty, '特'])
        except Exception:
            pass
        return rows

    def _nevis_v111_row_key(row) -> Tuple[str, str, str, str]:
        vals = list(row) + [''] * 6
        return (str(vals[0]), str(vals[1]), str(vals[2]), str(vals[3]))

    def _nevis_v111_subtract_rows(rows: List[List[object]], remove_rows: List[List[object]]) -> List[List[object]]:
        out = [list(r) for r in rows]
        for rr in remove_rows:
            rkey = _nevis_v111_row_key(rr)
            try:
                rq = float((list(rr) + [''] * 6)[4] or 0)
            except Exception:
                rq = 0
            if rq <= 0:
                continue
            for row in out:
                if _nevis_v111_row_key(row) != rkey:
                    continue
                try:
                    row[4] = float(row[4] or 0) - rq
                    if abs(row[4] - round(row[4])) < 1e-9:
                        row[4] = int(round(row[4]))
                except Exception:
                    pass
                break
        cleaned = []
        for row in out:
            try:
                if float(row[4] or 0) <= 1e-9:
                    continue
            except Exception:
                pass
            cleaned.append(row)
        return cleaned

    def _nevis_v111_definition_rows(mw, sp: dict, rec: dict) -> List[List[object]]:
        mult = 1.0
        try:
            mult = float(sp.get('quantity', 1) or 1)
        except Exception:
            pass
        rows = []
        for r in rec.get('rows', []) if isinstance(rec, dict) else []:
            if not isinstance(r, dict):
                continue
            mat = str(r.get('mat', sp.get('mat', '')) or '').strip()
            size = str(r.get('size', sp.get('size', '')) or '').strip()
            name = str(r.get('name', '') or '').strip()
            unit = str(r.get('unit', '個') or '個').strip()
            note = str(r.get('note', '特') or '').strip()
            try:
                qty = float(r.get('qty', 1) or 1) * mult
            except Exception:
                qty = mult
            if name:
                rows.append([mat, size, name, unit, int(qty) if abs(qty - round(qty)) < 1e-9 else round(qty, 3), note])
        return rows

    def _nevis_v111_merge_rows(rows: List[List[object]], add_rows: List[List[object]]) -> List[List[object]]:
        out = [list(r) for r in rows]
        for ar in add_rows:
            ar = list(ar) + [''] * 6
            key = _nevis_v111_row_key(ar)
            done = False
            for row in out:
                if _nevis_v111_row_key(row) == key:
                    try:
                        q = float(row[4] or 0) + float(ar[4] or 0)
                        row[4] = int(q) if abs(q - round(q)) < 1e-9 else round(q, 3)
                        note = str(ar[5] or '')
                        if note and note not in str(row[5]):
                            row[5] = (str(row[5]) + ' / ' + note).strip(' /')
                    except Exception:
                        pass
                    done = True
                    break
            if not done:
                out.append(ar[:6])
        return out

    def _nevis_v111_special_files(mw) -> List[dict]:
        files = []
        try:
            if '_sp_v1_scan_special_devices' in globals():
                files = list(_sp_v1_scan_special_devices(mw) or [])
        except Exception:
            files = []
        if not files:
            try:
                base = app_base_dir()
                for root in (base / 'library' / '特', base / 'Library' / '特'):
                    if root.exists():
                        for p in root.rglob('*'):
                            if p.is_file() and p.suffix.lower() in {'.json', '.txt'}:
                                files.append({'mat':'', 'size':'', 'name':p.stem, 'path':str(p)})
            except Exception:
                pass
        return files

    class _NevisV111SpecialBomDialog(QDialog):
        def __init__(self, mw):
            super().__init__(mw)
            self.mw = mw
            self.defs = _nevis_v111_load_map()
            self.files = _nevis_v111_special_files(mw)
            self.current_key = ''
            self.setWindowTitle(mw.tr('special_bom_editor') if hasattr(mw, 'tr') else '特 material definition')
            self.resize(980, 620)
            root = QHBoxLayout(self)

            left = QVBoxLayout()
            self.tree = QTreeWidget()
            self.tree.setHeaderLabels(['特 Library'])
            left.addWidget(self.tree, 1)
            root.addLayout(left, 1)

            right = QVBoxLayout()
            self.preview = QGraphicsView()
            self.preview_scene = QGraphicsScene(self.preview)
            self.preview.setScene(self.preview_scene)
            self.preview.setRenderHint(QPainter.Antialiasing)
            self.preview.setMinimumHeight(210)
            right.addWidget(self.preview)

            self.info = QLabel('')
            self.info.setStyleSheet('color:#526174; padding:4px;')
            right.addWidget(self.info)

            self.table = QTableWidget(0, 6)
            self.table.setHorizontalHeaderLabels(['種類', 'サイズ', '品名', '単位', '数量', '備考'])
            self.table.horizontalHeader().setStretchLastSection(True)
            right.addWidget(self.table, 1)

            btns = QHBoxLayout()
            self.btn_new = QPushButton('新規/1行')
            self.btn_combo = QPushButton('45°+45° mẫu')
            self.btn_add = QPushButton('+ 行')
            self.btn_del = QPushButton('- 行')
            self.btn_save = QPushButton('保存')
            self.btn_close = QPushButton('閉じる')
            for b in (self.btn_new, self.btn_combo, self.btn_add, self.btn_del, self.btn_save, self.btn_close):
                btns.addWidget(b)
            right.addLayout(btns)
            root.addLayout(right, 2)

            self.btn_new.clicked.connect(self._default_one_row)
            self.btn_combo.clicked.connect(self._default_combo_rows)
            self.btn_add.clicked.connect(lambda: self._add_row('', '', '', '個', 1, '特'))
            self.btn_del.clicked.connect(self._delete_row)
            self.btn_save.clicked.connect(self._save_current)
            self.btn_close.clicked.connect(self.accept)
            self.tree.currentItemChanged.connect(self._on_current)
            self._populate()

        def _populate(self):
            self.tree.clear()
            groups = {}
            for f in self.files:
                mat = str(f.get('mat','') or '特')
                groups.setdefault(mat, []).append(f)
            for mat in sorted(groups.keys()):
                root = QTreeWidgetItem(self.tree, [mat])
                for f in sorted(groups[mat], key=lambda x: (str(x.get('size','')), str(x.get('name','')))):
                    title = f"{f.get('size','')}  {f.get('name','')}".strip()
                    it = QTreeWidgetItem(root, [title])
                    it.setData(0, Qt.UserRole, f)
                    path = str(f.get('path','') or '')
                    keys = [_nevis_v111_rel_key(path), Path(path).name if path else '', Path(path).stem if path else '']
                    if any(k in self.defs for k in keys):
                        it.setText(0, '✓ ' + title)
            self.tree.expandAll()

        def _on_current(self, cur, old=None):
            data = cur.data(0, Qt.UserRole) if cur else None
            if not isinstance(data, dict):
                return
            path = str(data.get('path','') or '')
            self.current_key = _nevis_v111_rel_key(path)
            self.info.setText(f"{self.current_key}")
            self._draw_preview(path)
            self._load_rows_for(data)

        def _draw_preview(self, path: str):
            self.preview_scene.clear()
            if not path or not Path(path).exists():
                return
            try:
                ents = parse_jww_library_geometry(path)
                pen = QPen(QColor(0, 88, 125), 1.5); pen.setCosmetic(True)
                for ent in ents[:1400]:
                    typ = ent.get('type')
                    if typ == 'line':
                        x1,y1 = display_point(ent['x1'], ent['y1']); x2,y2 = display_point(ent['x2'], ent['y2'])
                        self.preview_scene.addLine(x1,y1,x2,y2,pen)
                    elif typ == 'circle':
                        x,y = display_point(ent['cx'], ent['cy']); r = ent['r']
                        self.preview_scene.addEllipse(x-r,y-r,r*2,r*2,pen)
                    elif typ == 'arc':
                        pts = arc_points(ent['cx'], ent['cy'], ent['r'], ent['a1'], ent['a2'], ent.get('rot', 0.0))
                        for (a,b),(c,d) in zip(pts, pts[1:]):
                            x1,y1 = display_point(a,b); x2,y2 = display_point(c,d)
                            self.preview_scene.addLine(x1,y1,x2,y2,pen)
                rect = self.preview_scene.itemsBoundingRect()
                if rect.isValid():
                    rect = rect.adjusted(-20,-20,20,20)
                    self.preview_scene.setSceneRect(rect)
                    self.preview.fitInView(rect, Qt.KeepAspectRatio)
            except Exception as ex:
                self.preview_scene.addText(str(ex))

        def _load_rows_for(self, data: dict):
            self.table.setRowCount(0)
            path = str(data.get('path','') or '')
            keys = [_nevis_v111_rel_key(path), Path(path).name if path else '', Path(path).stem if path else '', str(data.get('name',''))]
            rec = next((self.defs.get(k) for k in keys if isinstance(self.defs.get(k), dict)), None)
            if rec:
                for r in rec.get('rows', []):
                    self._add_row(r.get('mat',''), r.get('size',''), r.get('name',''), r.get('unit','個'), r.get('qty',1), r.get('note','特'))
            else:
                self._default_guess_rows(data)

        def _add_row(self, mat, size, name, unit='個', qty=1, note='特'):
            row = self.table.rowCount()
            self.table.insertRow(row)
            vals = [mat, size, name, unit, qty, note]
            for c, v in enumerate(vals):
                self.table.setItem(row, c, QTableWidgetItem(str(v)))

        def _current_file_data(self):
            it = self.tree.currentItem()
            data = it.data(0, Qt.UserRole) if it else None
            return data if isinstance(data, dict) else {}

        def _default_guess_rows(self, data: dict):
            self.table.setRowCount(0)
            mat = str(data.get('mat',''))
            size = str(data.get('size',''))
            name = str(data.get('name',''))
            parts = _sp_v1_combo_parts(name) if '_sp_v1_combo_parts' in globals() else []
            if parts:
                for part in parts:
                    item = self.mw.material_kind_name(part) if hasattr(self.mw, 'material_kind_name') else part
                    self._add_row(mat, size, item, '個', 1, '特')
            else:
                self._add_row(mat, size, name, '個', 1, '特')

        def _default_one_row(self):
            data = self._current_file_data()
            self.table.setRowCount(0)
            self._add_row(data.get('mat',''), data.get('size',''), data.get('name',''), '個', 1, '特')

        def _default_combo_rows(self):
            data = self._current_file_data()
            self.table.setRowCount(0)
            mat = data.get('mat',''); size = data.get('size','')
            name45 = self.mw.material_kind_name('45°') if hasattr(self.mw, 'material_kind_name') else '45°'
            self._add_row(mat, size, name45, '個', 2, '特')

        def _delete_row(self):
            rows = sorted({i.row() for i in self.table.selectedIndexes()}, reverse=True)
            for r in rows:
                self.table.removeRow(r)

        def _save_current(self):
            data = self._current_file_data()
            path = str(data.get('path','') or '')
            if not path:
                return
            rows = []
            for r in range(self.table.rowCount()):
                vals = []
                for c in range(6):
                    it = self.table.item(r, c)
                    vals.append(it.text().strip() if it else '')
                if not vals[2]:
                    continue
                try:
                    qty = float(vals[4] or 1)
                except Exception:
                    qty = 1
                rows.append({'mat': vals[0], 'size': vals[1], 'name': vals[2], 'unit': vals[3] or '個', 'qty': qty, 'note': vals[5]})
            if not rows:
                QMessageBox.warning(self, 'NEVIS', 'Chưa có dòng vật tư.')
                return
            key = _nevis_v111_rel_key(path)
            self.defs[key] = {'path': key, 'name': data.get('name',''), 'rows': rows}
            p = _nevis_v111_save_map(self.defs)
            try:
                self.mw._nevis_v111_special_map_cache = dict(self.defs)
                self.mw.update_material_table()
            except Exception:
                pass
            self._populate()
            QMessageBox.information(self, 'NEVIS', f'Đã lưu định danh 特:\n{p}')

    _NEVIS_V111_PREV_BUILD_ROWS = getattr(MainWindow, 'build_material_rows', None)

    def _nevis_v111_build_material_rows(self, sheet_type: str = ''):
        rows = _NEVIS_V111_PREV_BUILD_ROWS(self, sheet_type) if _NEVIS_V111_PREV_BUILD_ROWS else []
        defs = getattr(self, '_nevis_v111_special_map_cache', None)
        if not isinstance(defs, dict):
            defs = _nevis_v111_load_map()
            self._nevis_v111_special_map_cache = dict(defs)
        remove = []
        add = []
        for sp in getattr(self.model, 'special_equipments', []) or []:
            rec = _nevis_v111_definition_for_special(defs, sp)
            if not rec:
                continue
            remove.extend(_nevis_v111_special_old_rows(self, sp))
            add.extend(_nevis_v111_definition_rows(self, sp, rec))
        if remove:
            rows = _nevis_v111_subtract_rows(rows, remove)
        if add:
            rows = _nevis_v111_merge_rows(rows, add)
        return rows

    def _nevis_v111_open_special_bom_editor(self):
        dlg = _NevisV111SpecialBomDialog(self)
        dlg.exec()

    MainWindow.build_material_rows = _nevis_v111_build_material_rows
    MainWindow.open_special_bom_editor = _nevis_v111_open_special_bom_editor

    _NEVIS_V111_PREV_BUILD_UI = getattr(MainWindow, '_build_ui', None)
    if _NEVIS_V111_PREV_BUILD_UI:
        def _nevis_v111_build_ui(self, *args, **kwargs):
            ret = _NEVIS_V111_PREV_BUILD_UI(self, *args, **kwargs)
            try:
                if not hasattr(self, 'act_special_bom_editor'):
                    self.act_special_bom_editor = QAction(self.tr('special_bom_editor') if hasattr(self, 'tr') else '特 material definition', self)
                    self.act_special_bom_editor.triggered.connect(self.open_special_bom_editor)
                    self.menu_lib.addAction(self.act_special_bom_editor)
            except Exception:
                pass
            return ret
        MainWindow._build_ui = _nevis_v111_build_ui

    _NEVIS_V111_PREV_REFRESH_LANG = getattr(MainWindow, 'refresh_language_texts', None)
    if _NEVIS_V111_PREV_REFRESH_LANG:
        def _nevis_v111_refresh_language_texts(self, *args, **kwargs):
            ret = _NEVIS_V111_PREV_REFRESH_LANG(self, *args, **kwargs)
            try:
                if hasattr(self, 'act_special_bom_editor'):
                    self.act_special_bom_editor.setText(self.tr('special_bom_editor'))
            except Exception:
                pass
            return ret
        MainWindow.refresh_language_texts = _nevis_v111_refresh_language_texts

    print('NEVIS_202_V111_SPECIAL_MATERIAL_MAP_READY')
except Exception as _nevis_v111_err:
    print('NEVIS_V111_PATCH_ERROR', _nevis_v111_err)


# =============================================================================
# NEVIS 2.03 BOM canonicalization - display/merge only
# =============================================================================
try:
    _NEVIS_203_BOM_CANON_PREV_BUILD_ROWS = getattr(MainWindow, 'build_material_rows', None)

    def _nevis_203_bom_is_deferred_material_row(row: object) -> bool:
        """Rows for future fire/TMP/collection rules must pass through unchanged."""
        try:
            vals = list(row) + [''] * 6
            blob = ' '.join(str(v or '') for v in vals[:6])
            deferred_tokens = ('TMP', 'トミジ', '耐火二層管', '耐火VP', '耐火DV', '集合管')
            return any(tok in blob for tok in deferred_tokens)
        except Exception:
            return True

    def _nevis_203_bom_is_pipe_item(name: object) -> bool:
        s = str(name or '').strip().upper()
        return ('パイプ' in s) or ('PIPE' in s) or ('配管' in s)

    def _nevis_203_bom_is_standard_fitting_item(name: object) -> bool:
        s = str(name or '').strip().upper()
        if not s:
            return False
        return (
            ('継手' in s) or
            ('エルボ' in s) or
            ('ソケット' in s) or
            ('ブッシング' in s) or
            s.startswith('45')
        )

    def _nevis_203_bom_clean_size(size: object) -> str:
        s = str(size or '').strip()
        if not s:
            return ''
        s2 = s.upper().replace('×', 'X').replace('*', 'X')
        nums = re.findall(r'\d+', s2)
        if len(nums) >= 2:
            return f'{nums[0]}x{nums[1]}'
        if len(nums) == 1:
            return nums[0]
        return s

    def _nevis_203_bom_normalize_row(row: object) -> List[object]:
        vals = list(row) + [''] * 6
        mat, size, item, unit, qty, note = vals[:6]
        mat_s = str(mat or '').strip()
        size_s = str(size or '').strip()
        item_s = str(item or '').strip()
        unit_s = str(unit or '').strip()

        if mat_s == '耐火VP' and unit_s == 'm' and _nevis_203_bom_is_pipe_item(item_s):
            return [mat_s, size_s, '耐火VP パイプ', unit_s, qty, note]
        if mat_s == '耐火VP' and unit_s == '個' and _nevis_203_bom_is_standard_fitting_item(item_s):
            return ['耐火DV', size_s, item_s, unit_s, qty, note]

        if _nevis_203_bom_is_deferred_material_row(vals):
            return [mat, size, item, unit, qty, note]

        normal_mats = {'', 'DV', 'VP', 'VU', 'VP/VU'}
        if mat_s in normal_mats:
            if _nevis_203_bom_is_pipe_item(item_s):
                mat_s = 'VP/VU'
                item_s = 'VP/VU パイプ'
            elif _nevis_203_bom_is_standard_fitting_item(item_s):
                mat_s = 'DV'

        up = (item_s + ' ' + size_s).upper().replace('_', ' ').replace('-', ' ')
        if 'DL' in up:
            item_s = 'DL継手'
            size_s = _nevis_203_bom_clean_size(size_s)
            if mat_s in normal_mats:
                mat_s = 'DV'
        elif 'LL' in up:
            item_s = 'LL継手'
            size_s = _nevis_203_bom_clean_size(size_s)
            if mat_s in normal_mats:
                mat_s = 'DV'

        return [mat_s, size_s, item_s, unit_s, qty, note]

    def _nevis_203_bom_merge_rows(rows: object) -> List[List[object]]:
        merged = {}
        order = []
        for r in rows or []:
            try:
                row = _nevis_203_bom_normalize_row(r)
                row = list(row) + [''] * (6 - len(row))
                mat, size, item, unit, qty, note = row[:6]
                key = (str(mat or '').strip(), str(size or '').strip(), str(item or '').strip(), str(unit or '').strip())
                if key not in merged:
                    merged[key] = [key[0], key[1], key[2], key[3], 0, str(note or '').strip()]
                    order.append(key)
                try:
                    q = float(qty)
                except Exception:
                    q = 0.0
                merged[key][4] = float(merged[key][4] or 0) + q
                note_s = str(note or '').strip()
                if note_s and note_s not in str(merged[key][5]):
                    merged[key][5] = (str(merged[key][5]) + ' / ' + note_s).strip(' /')
            except Exception:
                try:
                    key = ('__raw__', str(len(order)), '', '')
                    order.append(key)
                    merged[key] = list(r)
                except Exception:
                    pass

        out = []
        for key in order:
            row = merged.get(key)
            if not row:
                continue
            try:
                if str(row[3]) == '個' and abs(float(row[4]) - round(float(row[4]))) < 1e-9:
                    row[4] = int(round(float(row[4])))
                elif isinstance(row[4], float):
                    row[4] = round(row[4], 3)
            except Exception:
                pass
            out.append(row)
        return out

    def _nevis_203_bom_canonical_build_material_rows(self, sheet_type: str = ''):
        rows = _NEVIS_203_BOM_CANON_PREV_BUILD_ROWS(self, sheet_type) if _NEVIS_203_BOM_CANON_PREV_BUILD_ROWS else []
        return _nevis_203_bom_merge_rows(rows)

    MainWindow.build_material_rows = _nevis_203_bom_canonical_build_material_rows
    print('NEVIS_203_BOM_CANONICALIZATION_READY')
except Exception as _nevis_203_bom_canon_err:
    print('NEVIS_203_BOM_CANONICALIZATION_PATCH_ERROR', _nevis_203_bom_canon_err)


