def _nevis_perf_wrap_callable(func, name: str):
    if not callable(func) or getattr(func, "_nevis_perf_wrapped", False):
        return func

    @functools.wraps(func)
    def _nevis_perf_wrapper(*args, **kwargs):
        with nevis_perf_scope(name):
            return func(*args, **kwargs)

    _nevis_perf_wrapper._nevis_perf_wrapped = True
    return _nevis_perf_wrapper


def _nevis_install_perf_profile_wrappers() -> None:
    if not nevis_perf_enabled():
        return

    targets = [
        ("PreviewView.draw_model", PreviewView, "draw_model"),
        ("PreviewView._draw_detailed_fittings", PreviewView, "_draw_detailed_fittings"),
        ("PreviewView._draw_jww_background", PreviewView, "_draw_jww_background"),
        ("MainWindow.refresh_all", MainWindow, "refresh_all"),
        ("MainWindow._do_refresh_all", MainWindow, "_do_refresh_all"),
        ("MainWindow.load_temp", MainWindow, "load_temp"),
        ("MainWindow.load_nevis_master_data", MainWindow, "load_nevis_master_data"),
        ("MainWindow.load_common_config", MainWindow, "load_common_config"),
        ("MainWindow.build_material_rows", MainWindow, "build_material_rows"),
        ("MainWindow.update_material_table", MainWindow, "update_material_table"),
        ("MainWindow.matching_library_path", MainWindow, "matching_library_path"),
        ("MainWindow.pipe_library_path", MainWindow, "pipe_library_path"),
        ("MainWindow.scan_library_folder", MainWindow, "scan_library_folder"),
        ("MainWindow.build_jww", MainWindow, "build_jww"),
        ("MainWindow.export_jww", MainWindow, "export_jww"),
        ("MainWindow.export_debug", MainWindow, "export_debug"),
    ]
    for label, cls, attr in targets:
        current = getattr(cls, attr, None)
        if current is not None:
            setattr(cls, attr, _nevis_perf_wrap_callable(current, label))

    global_targets = [
        ("_read_jww_temp_entities", "_read_jww_temp_entities"),
        ("parse_jww_temp", "parse_jww_temp"),
        ("parse_jww_background_geometry", "parse_jww_background_geometry"),
        ("parse_jww_library_geometry", "parse_jww_library_geometry"),
        ("_sp_v1_scan_special_devices", "_sp_v1_scan_special_devices"),
        ("_sp_v11_choose_special_device", "_sp_v11_choose_special_device"),
        ("_v82_apply_payload", "_v82_apply_payload"),
        ("_v92_apply_payload", "_v92_apply_payload"),
        ("_nevis_v103_apply_payload", "_nevis_v103_apply_payload"),
        ("_v92_direct_apply_special_node", "_v92_direct_apply_special_node"),
    ]
    for label, attr in global_targets:
        current = globals().get(attr)
        if current is not None:
            globals()[attr] = _nevis_perf_wrap_callable(current, label)


_nevis_install_perf_profile_wrappers()


