    self.lbl_pipe_check_warnings = QLabel()
    self.lbl_pipe_check_errors.setStyleSheet("color:#B42318; font-weight:700;")
    self.lbl_pipe_check_warnings.setStyleSheet("color:#B26A00; font-weight:700;")
